const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, validationResult, query } = require('express-validator');

const app = express();
const PORT = process.env.PORT || 3000;

// ============================================
// MIDDLEWARE: Security Headers
// ============================================
app.use(helmet());

// ============================================
// MIDDLEWARE: Body Parser with Size Limits
// ============================================
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// ============================================
// MIDDLEWARE: Rate Limiting
// ============================================
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);

// ============================================
// MIDDLEWARE: Request Logging (basic)
// ============================================
app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    const duration = Date.now() - start;
    console.log(`${req.method} ${req.path} ${res.statusCode} ${duration}ms`);
  });
  next();
});

// ============================================
// ROUTES
// ============================================

/**
 * Health check endpoint
 */
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

/**
 * Get users endpoint with optional filtering
 * Query params: limit (1-100), offset (0+)
 */
app.get(
  '/users',
  [
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be an integer between 1 and 100'),
    query('offset')
      .optional()
      .isInt({ min: 0 })
      .withMessage('Offset must be a non-negative integer'),
  ],
  (req, res) => {
    try {
      // Check for validation errors
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({
          error: 'Invalid query parameters',
          details: errors.array(),
        });
      }

      const limit = Math.min(parseInt(req.query.limit || '10', 10), 100);
      const offset = Math.max(parseInt(req.query.offset || '0', 10), 0);

      // Sample data (in production, fetch from database)
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Apply pagination
      const paginatedUsers = users.slice(offset, offset + limit);

      res.json({
        data: paginatedUsers,
        total: users.length,
        limit,
        offset,
      });
    } catch (error) {
      console.error('Error fetching users:', error);
      res.status(500).json({ error: 'Internal server error' });
    }
  }
);

// ============================================
// 404 Handler - Must come after all routes
// ============================================
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    path: req.path,
  });
});

// ============================================
// Global Error Handler - Must come last
// ============================================
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Don't leak error details to client in production
  const isDevelopment = process.env.NODE_ENV === 'development';
  const errorResponse = {
    error: isDevelopment ? err.message : 'Internal server error',
  };

  if (isDevelopment) {
    errorResponse.stack = err.stack;
  }

  res.status(err.status || 500).json(errorResponse);
});

// ============================================
// Server Initialization with Error Handling
// ============================================
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  process.exit(1);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

# Security Review & Improvement Recommendations for app.js

## Executive Summary
The original app.js has minimal error handling and no input validation, creating security vulnerabilities. Multiple improvements are recommended.

---

## Critical Issues & Fixes

### 1. **Missing Error Handling**

**Problem:**
```javascript
app.listen(3000, () => {
  console.log('Server running on port 3000');
});
```
- No error handler for uncaught exceptions
- No 404 handler for undefined routes
- Routes have no try-catch blocks

**Solution:**
```javascript
// Global error handler (must be last middleware)
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);
  res.status(err.status || 500).json({ error: 'Internal server error' });
});

// 404 handler (before error handler)
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

// Process-level error handlers
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  process.exit(1);
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection:', reason);
  process.exit(1);
});
```

---

### 2. **No Input Validation**

**Problem:**
- `/users` endpoint accepts any query parameters without validation
- No limits on request size
- No type checking on inputs

**Solution:**
```javascript
const { query, validationResult } = require('express-validator');

app.get('/users',
  [
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be 1-100'),
    query('offset')
      .optional()
      .isInt({ min: 0 })
      .withMessage('Offset must be non-negative'),
  ],
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ error: 'Invalid parameters', details: errors.array() });
    }
    // ... process request
  }
);
```

---

### 3. **Missing Security Headers**

**Problem:**
- No protection against common web attacks (XSS, Clickjacking, MIME sniffing)
- No HSTS, CSP, or other security headers

**Solution:**
```javascript
const helmet = require('helmet');
app.use(helmet()); // Adds ~15 security headers by default
```

**Headers Added:**
- `X-Frame-Options: DENY` (prevents clickjacking)
- `X-Content-Type-Options: nosniff` (prevents MIME sniffing)
- `Strict-Transport-Security` (enforces HTTPS)
- Content Security Policy headers
- And more...

---

### 4. **No Rate Limiting**

**Problem:**
- Vulnerable to DoS attacks
- No protection against brute force or abuse

**Solution:**
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // 100 requests per window
  message: 'Too many requests',
});

app.use(limiter);
```

---

### 5. **No Request Size Limits**

**Problem:**
- Vulnerable to large payload attacks
- No protection against memory exhaustion

**Solution:**
```javascript
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));
```

---

### 6. **Hardcoded Configuration**

**Problem:**
```javascript
app.listen(3000, () => { /* ... */ });
```
- Port is hardcoded
- No environment-based configuration
- Secrets/sensitive data could be hardcoded

**Solution:**
```javascript
const PORT = process.env.PORT || 3000;
const ENV = process.env.NODE_ENV || 'development';

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
```

---

### 7. **Information Disclosure**

**Problem:**
- Error messages leak internal details to clients
- Stack traces could expose sensitive paths

**Solution:**
```javascript
const isDevelopment = process.env.NODE_ENV === 'development';
const errorResponse = {
  error: isDevelopment ? err.message : 'Internal server error',
};

if (isDevelopment) {
  errorResponse.stack = err.stack;
}

res.status(err.status || 500).json(errorResponse);
```

---

### 8. **No Request Logging**

**Problem:**
- No audit trail for debugging or security analysis
- Difficult to track malicious activity

**Solution:**
```javascript
app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    const duration = Date.now() - start;
    console.log(`${req.method} ${req.path} ${res.statusCode} ${duration}ms`);
  });
  next();
});
```

---

## Dependencies to Install

```bash
npm install express helmet express-rate-limit express-validator
```

**Why these packages:**
- **helmet**: Automatically adds 15+ security headers
- **express-rate-limit**: Prevents abuse and DoS attacks
- **express-validator**: Validates and sanitizes user input

---

## Additional Recommendations

### 1. **CORS Configuration**
```javascript
const cors = require('cors');
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
}));
```

### 2. **HTTPS Enforcement**
```javascript
if (process.env.NODE_ENV === 'production') {
  app.use((req, res, next) => {
    if (req.header('x-forwarded-proto') !== 'https') {
      res.redirect(`https://${req.header('host')}${req.url}`);
    } else {
      next();
    }
  });
}
```

### 3. **Request ID Tracking**
```javascript
const { v4: uuidv4 } = require('uuid');

app.use((req, res, next) => {
  req.id = uuidv4();
  res.set('X-Request-ID', req.id);
  next();
});
```

### 4. **Database Query Parameterization**
If using a database, always use parameterized queries:
```javascript
// BAD
db.query(`SELECT * FROM users WHERE id = ${req.query.id}`);

// GOOD
db.query('SELECT * FROM users WHERE id = ?', [req.query.id]);
```

### 5. **Authentication & Authorization**
```javascript
const authenticateToken = (req, res, next) => {
  const token = req.headers['authorization']?.split(' ')[1];
  if (!token) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  // Verify token
  next();
};

app.get('/users', authenticateToken, (req, res) => { /* ... */ });
```

---

## Testing Recommendations

### Unit Tests
```javascript
const request = require('supertest');
const app = require('./app');

describe('GET /users', () => {
  it('should validate limit parameter', async () => {
    const res = await request(app)
      .get('/users')
      .query({ limit: 999 });
    expect(res.status).toBe(400);
  });

  it('should return users with valid parameters', async () => {
    const res = await request(app)
      .get('/users')
      .query({ limit: 10, offset: 0 });
    expect(res.status).toBe(200);
    expect(res.body).toHaveProperty('data');
  });
});
```

### Security Testing
```bash
# Check dependencies for vulnerabilities
npm audit

# Test for common vulnerabilities
npm install --save-dev snyk
npx snyk test

# Use OWASP ZAP for penetration testing
```

---

## Summary of Changes

| Issue | Severity | Fix |
|-------|----------|-----|
| No error handling | High | Add try-catch, global error handler |
| No input validation | High | Use express-validator |
| Missing security headers | High | Add helmet middleware |
| No rate limiting | Medium | Add express-rate-limit |
| No request size limit | Medium | Configure express.json limits |
| Hardcoded config | Medium | Use environment variables |
| Information disclosure | Medium | Don't leak error details |
| No logging | Low | Add request logging middleware |

All of these have been implemented in `app.js.improved`.

