/**
 * Configuration Module
 * 
 * Centralized configuration management with validation
 * Environment variables are loaded via dotenv in development
 * In production, use environment-injected variables or secrets manager
 */

require('dotenv').config({
  path: process.env.NODE_ENV === 'test' ? '.env.test' : '.env'
});

// Validation helper
function getEnv(key, defaultValue = null, required = false) {
  const value = process.env[key];

  if (value) {
    return value;
  }

  if (defaultValue !== null) {
    return defaultValue;
  }

  if (required) {
    throw new Error(`Missing required environment variable: ${key}`);
  }

  return null;
}

// Configuration object with validation
const config = {
  // Application
  nodeEnv: getEnv('NODE_ENV', 'development'),
  port: parseInt(getEnv('PORT', '3000'), 10),
  isDevelopment: process.env.NODE_ENV === 'development',
  isProduction: process.env.NODE_ENV === 'production',
  isTest: process.env.NODE_ENV === 'test',

  // Database
  database: {
    url: getEnv('DATABASE_URL', null, process.env.NODE_ENV === 'production'),
  },

  // AWS Configuration
  aws: {
    accessKeyId: getEnv('AWS_ACCESS_KEY_ID', null, process.env.NODE_ENV === 'production'),
    secretAccessKey: getEnv('AWS_SECRET_ACCESS_KEY', null, process.env.NODE_ENV === 'production'),
    region: getEnv('AWS_REGION', 'us-east-1'),
  },

  // External API Keys
  apis: {
    anthropic: {
      apiKey: getEnv('ANTHROPIC_API_KEY', null, process.env.NODE_ENV === 'production'),
    },
    stripe: {
      secretKey: getEnv('STRIPE_SECRET_KEY', null, process.env.NODE_ENV === 'production'),
    },
    logfire: {
      token: getEnv('LOGFIRE_TOKEN', null, false), // Optional for now
    },
  },

  // Authentication & Security
  auth: {
    jwtSecret: getEnv('JWT_SECRET', 'dev-jwt-secret', process.env.NODE_ENV === 'production'),
    accessTokenSecret: getEnv('ACCESS_TOKEN_SECRET', 'dev-access-secret', process.env.NODE_ENV === 'production'),
    refreshTokenSecret: getEnv('REFRESH_TOKEN_SECRET', 'dev-refresh-secret', process.env.NODE_ENV === 'production'),
  },

  // CORS & Security
  cors: {
    allowedOrigins: getEnv('ALLOWED_ORIGINS', 'http://localhost:3000')
      .split(',')
      .map(origin => origin.trim()),
  },

  // Logging
  logging: {
    level: getEnv('LOG_LEVEL', 'info'),
  },
};

// Validate critical configurations on startup
function validateConfig() {
  const errors = [];

  if (config.isProduction) {
    if (!config.database.url) {
      errors.push('DATABASE_URL is required in production');
    }
    if (!config.auth.jwtSecret || config.auth.jwtSecret.startsWith('dev-')) {
      errors.push('JWT_SECRET must be set properly in production');
    }
    if (!config.auth.accessTokenSecret || config.auth.accessTokenSecret.startsWith('dev-')) {
      errors.push('ACCESS_TOKEN_SECRET must be set properly in production');
    }
  }

  if (errors.length > 0) {
    console.error('Configuration validation errors:');
    errors.forEach(error => console.error(`  - ${error}`));
    if (config.isProduction) {
      throw new Error('Invalid production configuration');
    }
  }
}

// Run validation
validateConfig();

// Freeze config to prevent accidental modifications
Object.freeze(config);

module.exports = config;

