// Improved application with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('mongo-sanitize');
const xss = require('xss-clean');
const validator = require('validator');
const app = express();

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// 1. Set security HTTP headers using Helmet
app.use(helmet());

// 2. Rate limiting - Prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// 3. Stricter rate limiting for auth endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: 'Too many login attempts, please try again later.',
  skipSuccessfulRequests: true,
});

// 4. Body parser middleware with size limits
app.use(express.json({ limit: '10kb' })); // Prevent large payload attacks
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 5. Data sanitization middleware
app.use(mongoSanitize()); // Remove NoSQL injection attempts
app.use(xss()); // Clean user input from XSS attacks

// 6. Request validation middleware
const validateQuery = (req, res, next) => {
  const query = req.query;

  // Example: Validate limit and offset parameters if provided
  if (query.limit !== undefined) {
    if (!validator.isInt(query.limit, { min: 1, max: 100 })) {
      return res.status(400).json({
        status: 'error',
        message: 'Invalid limit parameter. Must be an integer between 1 and 100.',
      });
    }
  }

  if (query.offset !== undefined) {
    if (!validator.isInt(query.offset, { min: 0 })) {
      return res.status(400).json({
        status: 'error',
        message: 'Invalid offset parameter. Must be a non-negative integer.',
      });
    }
  }

  if (query.search !== undefined) {
    // Validate search string - max 100 characters
    if (!validator.isLength(query.search, { max: 100 })) {
      return res.status(400).json({
        status: 'error',
        message: 'Search parameter exceeds maximum length of 100 characters.',
      });
    }
  }

  next();
};

// ============================================================================
// ROUTES
// ============================================================================

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    res.status(500).json({
      status: 'error',
      message: 'Health check failed',
    });
  }
});

// Users endpoint with validation
app.get('/users', validateQuery, (req, res) => {
  try {
    const limit = req.query.limit ? parseInt(req.query.limit, 10) : 10;
    const offset = req.query.offset ? parseInt(req.query.offset, 10) : 0;

    // Mock data
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination
    const paginatedUsers = allUsers.slice(offset, offset + limit);

    res.json({
      status: 'success',
      data: paginatedUsers,
      pagination: {
        limit,
        offset,
        total: allUsers.length,
      },
    });
  } catch (error) {
    return res.status(500).json({
      status: 'error',
      message: 'Failed to retrieve users',
    });
  }
});

// ============================================================================
// 404 HANDLER
// ============================================================================
app.use((req, res) => {
  res.status(404).json({
    status: 'error',
    message: 'Endpoint not found',
  });
});

// ============================================================================
// GLOBAL ERROR HANDLER
// ============================================================================
app.use((err, req, res, next) => {
  // Log error (in production, use a proper logging service)
  console.error('Error:', {
    message: err.message,
    stack: err.stack,
    timestamp: new Date().toISOString(),
  });

  // Don't expose internal error details to clients
  const status = err.status || 500;
  const message = err.status ? err.message : 'Internal server error';

  res.status(status).json({
    status: 'error',
    message,
  });
});

// ============================================================================
// SERVER STARTUP
// ============================================================================
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log('Environment:', process.env.NODE_ENV || 'development');
});

module.exports = app;

# Security Review: app.js - Comprehensive Improvements Guide

## Executive Summary
The original `app.js` lacks critical security measures for error handling and input validation. This review outlines vulnerabilities and provides best practices for hardening the application.

---

## 🚨 Critical Issues Found

### 1. **No Input Validation**
**Risk**: Injection attacks, XSS, DoS
```javascript
// VULNERABLE: No validation on query parameters
app.get('/users', (req, res) => {
  // req.query could contain malicious data
  res.json([...]);
});
```
**Fix**: Implement validator middleware and schema validation

### 2. **Missing Security Headers**
**Risk**: Clickjacking, MIME type sniffing, XSS, SSL stripping
```javascript
// SOLUTION: Use Helmet.js
app.use(helmet());
// Provides:
// - Content-Security-Policy
// - X-Frame-Options
// - X-Content-Type-Options
// - Strict-Transport-Security (HSTS)
```

### 3. **No Rate Limiting**
**Risk**: Denial of Service (DoS) attacks
```javascript
// VULNERABLE: Unlimited requests allowed
// SOLUTION: Use express-rate-limit
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100
});
app.use(limiter);
```

### 4. **No Error Handling**
**Risk**: Information disclosure, crashes
```javascript
// VULNERABLE: Unhandled errors
app.get('/users', (req, res) => {
  res.json([...]); // What if JSON.stringify fails?
});

// SOLUTION: Add try-catch and error middleware
app.get('/users', (req, res) => {
  try {
    res.json([...]);
  } catch (error) {
    res.status(500).json({ status: 'error', message: 'Internal error' });
  }
});
```

### 5. **No Input Sanitization**
**Risk**: NoSQL injection, XSS
```javascript
// SOLUTION: Use sanitization libraries
app.use(mongoSanitize());  // Prevent NoSQL injection
app.use(xss());            // Prevent XSS attacks
```

### 6. **Payload Size Not Limited**
**Risk**: Memory exhaustion, DoS
```javascript
// VULNERABLE: No limit
app.use(express.json());

// SOLUTION: Set size limits
app.use(express.json({ limit: '10kb' }));
```

---

## ✅ Recommended Improvements

### 1. **Install Required Packages**
```bash
npm install helmet express-rate-limit mongo-sanitize xss-clean validator
```

### 2. **Implement Security Headers (Helmet)**
```javascript
const helmet = require('helmet');
app.use(helmet());
```
**What it does:**
- Content-Security-Policy
- X-Frame-Options: DENY
- X-Content-Type-Options: nosniff
- Strict-Transport-Security (HSTS)
- X-XSS-Protection
- Referrer-Policy

### 3. **Add Rate Limiting**
```javascript
const rateLimit = require('express-rate-limit');

// General limiter
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,  // 15 minutes
  max: 100,                   // 100 requests per window
  message: 'Too many requests',
  standardHeaders: true,
  legacyHeaders: false
});
app.use(limiter);

// Stricter limiter for sensitive endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  skipSuccessfulRequests: true
});
app.post('/login', authLimiter, ...);
```

### 4. **Implement Input Validation**
```javascript
const validator = require('validator');

// Validation middleware
const validateQuery = (req, res, next) => {
  // Validate limit parameter
  if (req.query.limit) {
    if (!validator.isInt(req.query.limit, { min: 1, max: 100 })) {
      return res.status(400).json({
        status: 'error',
        message: 'Invalid limit parameter'
      });
    }
  }

