// Improved Express application with security best practices
// Includes error handling, input validation, and security headers

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');

const app = express();

// ==================== MIDDLEWARE SETUP ====================

// Security: Add security headers
app.use(helmet());

// Rate limiting to prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

app.use(limiter);

// Parse JSON bodies with size limit
app.use(express.json({ limit: '10kb' }));

// Parse URL-encoded bodies with size limit
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// Request logging middleware
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.path}`);
  next();
});

// ==================== ROUTES ====================

/**
 * Health check endpoint
 * GET /health
 */
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    handleError(error, res, 'Health check failed');
  }
});

/**
 * Get users endpoint
 * GET /users
 * Query parameters:
 *   - limit: number (1-100, default 10)
 *   - offset: number (default 0)
 */
app.get('/users', 
  // Input validation for query parameters
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Offset must be a non-negative integer'),
  (req, res) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        error: 'Validation failed',
        details: errors.array() 
      });
    }

    try {
      const limit = Math.min(parseInt(req.query.limit) || 10, 100);
      const offset = parseInt(req.query.offset) || 0;

      // Mock user database
      const allUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
        { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      ];

      // Apply pagination
      const users = allUsers.slice(offset, offset + limit);

      res.json({
        data: users,
        pagination: {
          limit,
          offset,
          total: allUsers.length
        }
      });
    } catch (error) {
      handleError(error, res, 'Failed to fetch users');
    }
  }
);

/**
 * Create user endpoint (example with POST)
 * POST /users
 */
app.post('/users',
  // Input validation for request body
  body('name')
    .trim()
    .notEmpty()
    .withMessage('Name is required')
    .isLength({ min: 2, max: 50 })
    .withMessage('Name must be between 2 and 50 characters'),
  body('email')
    .trim()
    .isEmail()
    .withMessage('Valid email is required')
    .normalizeEmail(),
  (req, res) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        error: 'Validation failed',
        details: errors.array() 
      });
    }

    try {
      const { name, email } = req.body;

      // Mock create user (in production, save to database)
      const newUser = {
        id: Math.floor(Math.random() * 10000),
        name,
        email
      };

      res.status(201).json({
        success: true,
        data: newUser
      });
    } catch (error) {
      handleError(error, res, 'Failed to create user');
    }
  }
);

// ==================== ERROR HANDLING ====================

/**
 * 404 Not Found handler
 */
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    message: `Route ${req.method} ${req.path} does not exist`
  });
});

/**
 * Global error handler
 */
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Don't expose internal error details to client
  const statusCode = err.statusCode || 500;
  const isProduction = process.env.NODE_ENV === 'production';

  res.status(statusCode).json({
    error: 'Internal server error',
    message: isProduction ? 'An unexpected error occurred' : err.message,
    ...(process.env.DEBUG && { stack: err.stack })
  });
});

/**
 * Helper function for consistent error handling
 */
function handleError(error, res, message) {
  console.error(message, error);
  res.status(500).json({
    error: message,
    details: process.env.NODE_ENV !== 'production' ? error.message : undefined
  });
}

// ==================== SERVER STARTUP ====================

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';

const server = app.listen(PORT, HOST, () => {
  console.log(`[${new Date().toISOString()}] Server running on http://${HOST}:${PORT}`);
  console.log(`Node environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

const request = require('supertest');
const app = require('./app_improved.js');

describe('Security & Input Validation Tests', () => {

  // ============ HEALTH ENDPOINT TESTS ============

  describe('GET /health', () => {
    test('should return 200 with ok status', async () => {
      const res = await request(app).get('/health');
      expect(res.statusCode).toBe(200);
      expect(res.body.status).toBe('ok');
      expect(res.body.timestamp).toBeDefined();
      expect(res.body.uptime).toBeDefined();
    });

    test('should not expose sensitive information', async () => {
      const res = await request(app).get('/health');
      expect(res.body).not.toHaveProperty('password');
      expect(res.body).not.toHaveProperty('secret');
    });
  });

  // ============ USERS ENDPOINT - VALIDATION TESTS ============

  describe('GET /users', () => {
    test('should return users successfully', async () => {
      const res = await request(app).get('/users');
      expect(res.statusCode).toBe(200);
      expect(res.body).toHaveProperty('data');
      expect(res.body).toHaveProperty('pagination');
      expect(Array.isArray(res.body.data)).toBe(true);
    });

