      const res = await request(app).get('/users?limit=101');
      expect(res.statusCode).toBe(400);
      expect(res.body).toHaveProperty('error');
      expect(res.body).toHaveProperty('details');
    });

    test('should reject negative limit', async () => {
      const res = await request(app).get('/users?limit=-1');
      expect(res.statusCode).toBe(400);
    });

    test('should reject non-numeric limit', async () => {
      const res = await request(app).get('/users?limit=abc');
      expect(res.statusCode).toBe(400);
    });

    test('should validate offset parameter', async () => {
      const res = await request(app).get('/users?offset=-1');
      expect(res.statusCode).toBe(400);
    });

    test('should handle valid pagination', async () => {
      const res = await request(app).get('/users?limit=10&offset=0');
      expect(res.statusCode).toBe(200);
      expect(res.body.pagination.limit).toBe(10);
      expect(res.body.pagination.offset).toBe(0);
    });

    test('should use default pagination when not specified', async () => {
      const res = await request(app).get('/users');
      expect(res.statusCode).toBe(200);
      expect(res.body.pagination.limit).toBe(10);
      expect(res.body.pagination.offset).toBe(0);
    });

    test('should not expose sensitive user fields', async () => {
      const res = await request(app).get('/users');
      if (res.body.data.length > 0) {
        expect(res.body.data[0]).not.toHaveProperty('password');
        expect(res.body.data[0]).not.toHaveProperty('ssn');
      }
    });
  });

  // ============ CREATE USER ENDPOINT - VALIDATION TESTS ============

  describe('POST /users', () => {
    test('should create user with valid data', async () => {
      const res = await request(app)
        .post('/users')
        .send({
          name: 'John Doe',
          email: 'john@example.com'
        });
      expect(res.statusCode).toBe(201);
      expect(res.body.success).toBe(true);
      expect(res.body.data).toHaveProperty('id');
      expect(res.body.data.name).toBe('John Doe');
    });

    test('should reject missing name', async () => {
      const res = await request(app)
        .post('/users')
        .send({
          email: 'john@example.com'
        });
      expect(res.statusCode).toBe(400);
      expect(res.body.error).toBe('Validation failed');
    });

    test('should reject missing email', async () => {
      const res = await request(app)
        .post('/users')
        .send({
          name: 'John Doe'
        });
      expect(res.statusCode).toBe(400);
    });

    test('should reject invalid email format', async () => {
      const res = await request(app)
        .post('/users')
        .send({
          name: 'John Doe',
          email: 'invalid-email'
        });
      expect(res.statusCode).toBe(400);
      expect(res.body.details[0].msg).toContain('email');
    });

    test('should reject name shorter than 2 characters', async () => {
      const res = await request(app)
        .post('/users')
        .send({
          name: 'J',
          email: 'john@example.com'
        });
      expect(res.statusCode).toBe(400);
    });

    test('should reject name longer than 50 characters', async () => {
      const res = await request(app)
        .post('/users')
        .send({
          name: 'A'.repeat(51),
          email: 'john@example.com'
        });
      expect(res.statusCode).toBe(400);
    });

    test('should trim whitespace from name and email', async () => {
      const res = await request(app)
        .post('/users')
        .send({
          name: '  John Doe  ',
          email: '  john@example.com  '
        });
      expect(res.statusCode).toBe(201);
      expect(res.body.data.name).toBe('John Doe');
      expect(res.body.data.email).toBe('john@example.com');
    });

    test('should reject XSS attempt in name', async () => {
      const res = await request(app)
        .post('/users')
        .send({
          name: '<script>alert("xss")</script>',
          email: 'john@example.com'
        });
      // Should still validate as name length, but won't execute
      expect(res.statusCode).toBe(201); // Passes validation but data is stored as-is
      expect(typeof res.body.data.name).toBe('string'); // Name stored as string, not executed
