});
```

**AFTER** ✅
```javascript
app.get('/users', (req, res) => {
  try {
    const users = getUsers();
    res.json(users);
  } catch (error) {
    handleError(error, res, 'Failed to fetch users');
  }
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);
