// Improved application with security best practices
// Error handling, input validation, and security headers

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// Set security HTTP headers
app.use(helmet());

// Rate limiting middleware
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

// Apply rate limiting to all requests
app.use(limiter);

// Logging middleware
app.use(morgan('combined'));

// Body parser middleware with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// ============================================
// REQUEST VALIDATION MIDDLEWARE
// ============================================

/**
 * Validates and sanitizes query parameters
 */
const validateQueryParams = (req, res, next) => {
  try {
    const allowedParams = ['sort', 'filter', 'limit', 'offset'];

    // Check for unexpected parameters
    const invalidParams = Object.keys(req.query).filter(
      param => !allowedParams.includes(param)
    );

    if (invalidParams.length > 0) {
      return res.status(400).json({
        error: 'Invalid query parameters',
        invalid: invalidParams,
        allowed: allowedParams,
      });
    }

    // Validate and sanitize limit parameter
    if (req.query.limit) {
      const limit = parseInt(req.query.limit, 10);
      if (isNaN(limit) || limit < 1 || limit > 1000) {
        return res.status(400).json({
          error: 'Invalid limit parameter. Must be a number between 1 and 1000.',
        });
      }
      req.query.limit = limit;
    }

    // Validate offset parameter
    if (req.query.offset) {
      const offset = parseInt(req.query.offset, 10);
      if (isNaN(offset) || offset < 0) {
        return res.status(400).json({
          error: 'Invalid offset parameter. Must be a non-negative number.',
        });
      }
      req.query.offset = offset;
    }

    next();
  } catch (error) {
    return res.status(400).json({
      error: 'Error validating query parameters',
      message: error.message,
    });
  }
};

// ============================================
// ROUTES WITH ERROR HANDLING
// ============================================

/**
 * Health check endpoint
 */
app.get('/health', (req, res) => {
  try {
    res.status(200).json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    });
  } catch (error) {
    res.status(500).json({
      error: 'Health check failed',
      message: process.env.NODE_ENV === 'production' ? 'Internal server error' : error.message,
    });
  }
});

/**
 * Get users endpoint with validation
 */
app.get('/users', validateQueryParams, (req, res) => {
  try {
    const limit = req.query.limit ? parseInt(req.query.limit, 10) : 10;
    const offset = req.query.offset ? parseInt(req.query.offset, 10) : 0;

    // Mock user data
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination
    const paginatedUsers = allUsers.slice(offset, offset + limit);

    // Return data without exposing sensitive information
    const safeUsers = paginatedUsers.map(({ id, name }) => ({
      id,
      name,
      // Email intentionally excluded unless specifically authorized
    }));

    res.status(200).json({
      data: safeUsers,
      pagination: {
        offset,
        limit,
        total: allUsers.length,
      },
    });
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({
      error: 'Failed to fetch users',
      message: process.env.NODE_ENV === 'production' ? 'Internal server error' : error.message,
    });
  }
});

// ============================================
// 404 HANDLER
// ============================================

app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    path: req.path,
    method: req.method,
  });
});

// ============================================
// GLOBAL ERROR HANDLER (must be last)
// ============================================

app.use((err, req, res, next) => {
  const status = err.status || err.statusCode || 500;
  const message = err.message || 'Internal Server Error';

  // Log error details (in production, use proper logging service)
  console.error({
    timestamp: new Date().toISOString(),
    status,
    message,
    path: req.path,
    method: req.method,
    ip: req.ip,
    error: process.env.NODE_ENV === 'production' ? undefined : err,
  });

  // Don't expose sensitive error details in production
  res.status(status).json({
    error: message,
    ...(process.env.NODE_ENV !== 'production' && { details: err.stack }),
  });
});

// ============================================
// SERVER STARTUP
// ============================================

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // In production, alert monitoring service
  process.exit(1);
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  // In production, alert monitoring service
  process.exit(1);
});

module.exports = app;

# Security Review and Improvements for app.js

## Executive Summary
The original app.js lacks essential security measures, error handling, and input validation. This document outlines critical vulnerabilities and recommended improvements.

---

## Critical Issues Found

### 1. ❌ No Error Handling
**Risk**: Unhandled exceptions can crash the server or expose sensitive information.

**Original Code**:
```javascript
app.get('/users', (req, res) => {
  res.json([...]);  // No try-catch or error handling
});
```

**Improved**:
```javascript
app.get('/users', validateQueryParams, (req, res) => {
  try {
    // ... code ...
    res.status(200).json({ data: safeUsers });
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({ error: 'Failed to fetch users' });
  }
});
```

**Best Practices Applied**:
- ✅ Try-catch blocks for all routes
- ✅ Global error handler middleware
- ✅ Appropriate HTTP status codes
- ✅ Environment-aware error messages (no details in production)

---

### 2. ❌ No Input Validation
**Risk**: Malformed or malicious input could cause unexpected behavior.

**Improvements**:
```javascript
const validateQueryParams = (req, res, next) => {
  try {
    // Whitelist allowed parameters
    const allowedParams = ['sort', 'filter', 'limit', 'offset'];

    // Validate each parameter
    const limit = parseInt(req.query.limit, 10);
    if (isNaN(limit) || limit < 1 || limit > 1000) {
      return res.status(400).json({ error: 'Invalid limit parameter' });
    }

    next();
  } catch (error) {
    res.status(400).json({ error: 'Error validating query parameters' });
  }
};
```

**Security Measures**:
- ✅ Whitelist allowed parameters
- ✅ Type validation and range checking
- ✅ Prevents injection attacks
- ✅ Clear error messages to users

---

### 3. ❌ Missing Security Headers
**Risk**: Vulnerable to various attacks (XSS, clickjacking, etc.)

**Solution**: Use `helmet.js`
```javascript
const helmet = require('helmet');
app.use(helmet()); // Adds 15+ security headers
```

**Headers Added**:
- Content-Security-Policy
- X-Content-Type-Options
- X-Frame-Options
- X-XSS-Protection
- Strict-Transport-Security
- And more...

---

### 4. ❌ No Rate Limiting
**Risk**: Vulnerable to DoS attacks and brute force attempts.

**Solution**: Use `express-rate-limit`
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                  // 100 requests per IP
  message: 'Too many requests from this IP',
});

app.use(limiter);
```

**Benefits**:
- ✅ Prevents DoS attacks
- ✅ Protects brute force attacks
- ✅ Configurable per endpoint

---

### 5. ❌ Sensitive Data Exposure
**Risk**: Exposing unnecessary data (emails, passwords, etc.)

**Original Code**:
```javascript
{ id: 1, name: 'Alice', email: 'alice@example.com' }  // Email exposed
```

**Improved**:
```javascript
const safeUsers = paginatedUsers.map(({ id, name }) => ({
  id,
  name,
  // email excluded unless specifically authorized
}));
```

**Best Practices**:
- ✅ Return only necessary data
- ✅ Implement role-based access control
- ✅ Audit what data is exposed

---

### 6. ❌ No Logging or Monitoring
**Risk**: Cannot detect security incidents or debug issues.

**Solution**:
```javascript
const morgan = require('morgan');
app.use(morgan('combined')); // HTTP request logging

// Also log errors
console.error({
  timestamp: new Date().toISOString(),
  status,
  path: req.path,
  ip: req.ip,
  error: err.message,
});
```

**Logging Best Practices**:
- ✅ Log all requests
- ✅ Log all errors with context
- ✅ Include timestamps and request IDs
- ✅ Store logs securely
- ✅ Never log sensitive data (passwords, tokens)

---

### 7. ❌ No Request Size Limits
**Risk**: Vulnerable to payload attacks and memory exhaustion.

**Solution**:
```javascript
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));
```

**Benefits**:
- ✅ Prevents memory exhaustion
- ✅ Blocks oversized payloads
- ✅ Configurable per application

---

### 8. ❌ No Graceful Shutdown Handling
**Risk**: Data loss or incomplete transactions during shutdown.

**Solution**:
```javascript
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection:', reason);
  process.exit(1);
});

process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  process.exit(1);
});
```

---

## Recommended Package.json Dependencies

```json
{
  "dependencies": {
    "express": "^4.18.0",
    "helmet": "^7.0.0",
    "express-rate-limit": "^6.7.0",
    "morgan": "^1.10.0",
    "dotenv": "^16.0.0"
  },
  "devDependencies": {
    "jest": "^29.0.0",
    "supertest": "^6.3.0"
  }
}
```

---

## Environment Configuration

Create a `.env` file for sensitive configuration:

```env
NODE_ENV=production
PORT=3000
LOG_LEVEL=info
RATE_LIMIT_WINDOW_MS=900000
RATE_LIMIT_MAX_REQUESTS=100
```

Use in code:
```javascript
require('dotenv').config();
const PORT = process.env.PORT || 3000;
```

---

## Additional Security Recommendations

### 1. **Authentication & Authorization**
- Implement JWT or session-based authentication
- Add role-based access control (RBAC)
- Validate tokens on protected routes

### 2. **HTTPS/TLS**
- Always use HTTPS in production
- Use secure cookies with `httpOnly` and `secure` flags
- Implement HSTS

### 3. **Database Security**
- Use parameterized queries
- Never concatenate user input
- Encrypt sensitive data at rest

### 4. **Validation & Sanitization**
- Use libraries like `joi` or `yup` for schema validation
- Sanitize HTML input with `xss`
- Validate all inputs on both client and server

### 5. **Testing**
- Write security-focused unit tests
- Perform penetration testing
- Use OWASP ZAP or Burp Suite for security scanning

### 6. **Monitoring & Alerts**
- Set up log aggregation (ELK, Datadog, etc.)
- Configure alerts for anomalies
- Monitor error rates and response times

