/**
 * Centralized Configuration Module
 * 
 * This module loads and validates environment variables from .env files
 * and provides a single source of truth for application configuration.
 * 
 * Usage:
 *   const config = require('./config');
 *   const port = config.port;
 *   const dbUrl = config.database.url;
 */

require('dotenv').config();

// Configuration object with environment variables
const config = {
  // Application settings
  nodeEnv: process.env.NODE_ENV || 'development',
  port: parseInt(process.env.PORT, 10) || 3000,
  isDevelopment: process.env.NODE_ENV !== 'production',
  isProduction: process.env.NODE_ENV === 'production',
  isTest: process.env.NODE_ENV === 'test',

  // Database
  database: {
    url: process.env.DATABASE_URL,
  },

  // AWS
  aws: {
    accessKeyId: process.env.AWS_ACCESS_KEY_ID,
    secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
    region: process.env.AWS_REGION || 'us-east-1',
  },

  // API Keys
  anthropic: {
    apiKey: process.env.ANTHROPIC_API_KEY,
  },

  // Stripe
  stripe: {
    secretKey: process.env.STRIPE_SECRET_KEY,
  },

  // Logging
  logfire: {
    token: process.env.LOGFIRE_TOKEN,
  },
};

/**
 * Validates environment configuration
 * Throws an error if required variables are missing or invalid
 */
function validate() {
  const errors = [];

  // Validate required variables by environment
  if (config.isProduction) {
    // Production requires more strict validation
    const requiredProd = [
      'DATABASE_URL',
      'STRIPE_SECRET_KEY',
    ];

    requiredProd.forEach(varName => {
      if (!process.env[varName]) {
        errors.push(`Missing required environment variable for production: ${varName}`);
      }
    });

    // Validate Stripe is using live keys in production
    if (process.env.STRIPE_SECRET_KEY && !process.env.STRIPE_SECRET_KEY.startsWith('sk_live_')) {
      errors.push('STRIPE_SECRET_KEY must use live key (sk_live_) in production');
    }
  }

  // Development/Test validation
  if (config.isDevelopment || config.isTest) {
    // Validate Stripe is using test keys (not live)
    if (process.env.STRIPE_SECRET_KEY && process.env.STRIPE_SECRET_KEY.startsWith('sk_live_')) {
      errors.push('STRIPE_SECRET_KEY must use test key (sk_test_) in development/test, not live keys');
    }

    // Warn if database points to production
    if (process.env.DATABASE_URL && process.env.DATABASE_URL.includes('production')) {
      errors.push('DATABASE_URL should not reference production database in development/test');
    }
  }

  // Validate port is valid
  if (isNaN(config.port) || config.port < 1 || config.port > 65535) {
    errors.push('PORT must be a number between 1 and 65535');
  }

  // If there are errors, throw them all at once
  if (errors.length > 0) {
    const errorMessage = 'Configuration validation failed:\n' + 
      errors.map((err, i) => `  ${i + 1}. ${err}`).join('\n');
    throw new Error(errorMessage);
  }
}

/**
 * Checks for deprecated or suspicious environment variable patterns
 * Returns warnings that should be addressed but don't prevent startup
 */
function getWarnings() {
  const warnings = [];

  // Warn if AWS keys are hardcoded in test/dev
  if (!config.isProduction && process.env.AWS_ACCESS_KEY_ID) {
    warnings.push('AWS credentials are hardcoded - consider using IAM roles instead');
  }

  // Warn if running in development
  if (config.isDevelopment) {
    warnings.push('Running in DEVELOPMENT mode - DO NOT use production credentials');
  }

  // Warn if .env file doesn't exist and not in CI
  if (!process.env.CI && !process.env.GITHUB_ACTIONS) {
    const fs = require('fs');
    const envFile = config.isTest ? '.env.test' : '.env';
    if (!fs.existsSync(envFile)) {
      warnings.push(`No ${envFile} file found - using default values`);
    }
  }

  return warnings;
}

/**
 * Displays configuration info (for debugging)
 * IMPORTANT: Does NOT output sensitive values
 */
function logConfiguration() {
  const logConfig = {
    nodeEnv: config.nodeEnv,
    port: config.port,
    isDevelopment: config.isDevelopment,
    isProduction: config.isProduction,
    isTest: config.isTest,
    database: {
      url: config.database.url ? '***' : 'not configured',
    },
    aws: {
      accessKeyId: process.env.AWS_ACCESS_KEY_ID ? '***' : 'not configured',
      region: config.aws.region,
    },
    stripe: {
      secretKey: config.stripe.secretKey ? (
        config.stripe.secretKey.startsWith('sk_live_') ? '***LIVE***' : '***TEST***'
      ) : 'not configured',
    },
  };

  console.log('\n=== Application Configuration ===');
  console.log(JSON.stringify(logConfig, null, 2));
  console.log('==================================\n');
}

// Validate on module load
try {
  validate();
} catch (error) {
  console.error('❌ Configuration Error:', error.message);
  process.exit(1);
}

// Log warnings if any
const warnings = getWarnings();
if (warnings.length > 0) {
  console.warn('\n⚠️  Configuration Warnings:');
  warnings.forEach((warning, i) => {
    console.warn(`  ${i + 1}. ${warning}`);
  });
  console.warn('');
}

// Export configuration
module.exports = {
  ...config,
  validate,
  getWarnings,
  logConfiguration,
};

// Improved application with security best practices and configuration management
// Error handling, input validation, security headers, and proper environment config

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');

// Load and validate configuration
const config = require('./config');

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// Set security HTTP headers
app.use(helmet());

// Rate limiting middleware
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

// Apply rate limiting to all requests
app.use(limiter);

// Logging middleware
app.use(morgan('combined'));

// Body parser middleware with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// ============================================
// REQUEST VALIDATION MIDDLEWARE
// ============================================

/**
 * Validates and sanitizes query parameters
 */
const validateQueryParams = (req, res, next) => {
  try {
    const allowedParams = ['sort', 'filter', 'limit', 'offset'];

    // Check for unexpected parameters
    const invalidParams = Object.keys(req.query).filter(
      param => !allowedParams.includes(param)
    );

    if (invalidParams.length > 0) {
      return res.status(400).json({
        error: 'Invalid query parameters',
        invalid: invalidParams,
        allowed: allowedParams,
      });
    }

    // Validate and sanitize limit parameter
    if (req.query.limit) {
      const limit = parseInt(req.query.limit, 10);
      if (isNaN(limit) || limit < 1 || limit > 1000) {
        return res.status(400).json({
          error: 'Invalid limit parameter. Must be a number between 1 and 1000.',
        });
      }
      req.query.limit = limit;
    }

    // Validate offset parameter
    if (req.query.offset) {
      const offset = parseInt(req.query.offset, 10);
      if (isNaN(offset) || offset < 0) {
        return res.status(400).json({
          error: 'Invalid offset parameter. Must be a non-negative number.',
        });
      }
      req.query.offset = offset;
    }

    next();
  } catch (error) {
    return res.status(400).json({
      error: 'Error validating query parameters',
      message: config.isDevelopment ? error.message : undefined,
    });
  }
};

// ============================================
// ROUTES WITH ERROR HANDLING
// ============================================

/**
 * Health check endpoint
 */
app.get('/health', (req, res) => {
  try {
    res.status(200).json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      environment: config.nodeEnv,
    });
  } catch (error) {
    res.status(500).json({
      error: 'Health check failed',
      message: config.isDevelopment ? error.message : 'Internal server error',
    });
  }
});

/**
 * Get users endpoint with validation
 */
app.get('/users', validateQueryParams, (req, res) => {
  try {
    const limit = req.query.limit ? parseInt(req.query.limit, 10) : 10;
    const offset = req.query.offset ? parseInt(req.query.offset, 10) : 0;

    // Mock user data
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination
    const paginatedUsers = allUsers.slice(offset, offset + limit);

    // Return data without exposing sensitive information
    const safeUsers = paginatedUsers.map(({ id, name }) => ({
      id,
      name,
      // Email intentionally excluded unless specifically authorized
    }));

    res.status(200).json({
      data: safeUsers,
      pagination: {
        offset,
        limit,
        total: allUsers.length,
      },
    });
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({
      error: 'Failed to fetch users',
      message: config.isDevelopment ? error.message : 'Internal server error',
    });
  }
});

// ============================================
// 404 HANDLER
// ============================================

app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    path: req.path,
    method: req.method,
  });
});

// ============================================
// GLOBAL ERROR HANDLER (must be last)
// ============================================

app.use((err, req, res, next) => {
  const status = err.status || err.statusCode || 500;
  const message = err.message || 'Internal Server Error';

  // Log error details (in production, use proper logging service)
  console.error({
    timestamp: new Date().toISOString(),
    status,
    message,
    path: req.path,
    method: req.method,
    ip: req.ip,
    error: config.isDevelopment ? err : undefined,
  });

  // Don't expose sensitive error details in production
  res.status(status).json({
    error: message,
    ...(config.isDevelopment && { details: err.stack }),
  });
});

// ============================================
// SERVER STARTUP
// ============================================

const server = app.listen(config.port, () => {
  console.log(`✓ Server running on port ${config.port}`);
  console.log(`✓ Environment: ${config.nodeEnv}`);

  // Log configuration info (excludes sensitive values)
  if (config.isDevelopment) {
    config.logConfiguration();
  }
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('❌ Unhandled Rejection at:', promise, 'reason:', reason);
  // In production, alert monitoring service
  server.close(() => process.exit(1));
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('❌ Uncaught Exception:', error);
  // In production, alert monitoring service
  server.close(() => process.exit(1));
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

