// Improved application with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');
const morgan = require('morgan');
const dotenv = require('dotenv');

// Load environment variables
dotenv.config();

const app = express();
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// ============================================
// Middleware - Security & Logging
// ============================================

// Security headers
app.use(helmet());

// Request logging
app.use(morgan(NODE_ENV === 'production' ? 'combined' : 'dev'));

// Body parser with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Rate limiting - prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Stricter rate limit for authentication endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  skipSuccessfulRequests: true,
});

// ============================================
// Middleware - Error Handler
// ============================================

// Express validation error handler middleware
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      success: false,
      errors: errors.array().map(err => ({
        field: err.param,
        message: err.msg
      }))
    });
  }
  next();
};

// ============================================
// Routes - Health Check
// ============================================

app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      environment: NODE_ENV
    });
  } catch (error) {
    console.error('Error in /health endpoint:', error);
    res.status(500).json({
      success: false,
      message: 'Internal server error'
    });
  }
});

// ============================================
// Routes - Users (with validation & pagination)
// ============================================

// Mock database
const users = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
  { id: 3, name: 'Charlie', email: 'charlie@example.com' },
  { id: 4, name: 'Diana', email: 'diana@example.com' },
];

/**
 * GET /users
 * Query Parameters:
 *   - page (optional): page number (default: 1)
 *   - limit (optional): items per page (default: 10, max: 100)
 */
app.get('/users',
  query('page')
    .optional()
    .isInt({ min: 1 })
    .toInt()
    .withMessage('Page must be a positive integer'),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .toInt()
    .withMessage('Limit must be between 1 and 100'),
  handleValidationErrors,
  (req, res) => {
    try {
      const page = req.query.page || 1;
      const limit = Math.min(req.query.limit || 10, 100); // Cap at 100

      const startIndex = (page - 1) * limit;
      const endIndex = startIndex + limit;

      const paginatedUsers = users.slice(startIndex, endIndex);

      res.json({
        success: true,
        data: paginatedUsers,
        pagination: {
          page,
          limit,
          total: users.length,
          pages: Math.ceil(users.length / limit)
        }
      });
    } catch (error) {
      console.error('Error in /users endpoint:', error);
      res.status(500).json({
        success: false,
        message: 'Internal server error'
      });
    }
  }
);

/**
 * GET /users/:id
 * Get a specific user by ID with validation
 */
app.get('/users/:id',
  query('id')
    .isInt({ min: 1 })
    .withMessage('User ID must be a positive integer'),
  (req, res) => {
    try {
      const userId = parseInt(req.params.id, 10);

      // Validate userId
      if (isNaN(userId) || userId <= 0) {
        return res.status(400).json({
          success: false,
          message: 'Invalid user ID format'
        });
      }

      const user = users.find(u => u.id === userId);

      if (!user) {
        return res.status(404).json({
          success: false,
          message: 'User not found'
        });
      }

      res.json({
        success: true,
        data: user
      });
    } catch (error) {
      console.error('Error in GET /users/:id endpoint:', error);
      res.status(500).json({
        success: false,
        message: 'Internal server error'
      });
    }
  }
);

// ============================================
// Error Handling Middleware
// ============================================

// 404 handler - must be after all other routes
app.use((req, res) => {
  res.status(404).json({
    success: false,
    message: 'Endpoint not found',
    path: req.path
  });
});

// Global error handler - must be last middleware
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  const status = err.status || err.statusCode || 500;
  const message = NODE_ENV === 'production'
    ? 'Internal server error'
    : err.message;

  res.status(status).json({
    success: false,
    message,
    ...(NODE_ENV === 'development' && { stack: err.stack })
  });
});

// ============================================
// Server Startup & Shutdown
// ============================================

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} (${NODE_ENV})`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

// Catch unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

module.exports = app;

# Security & Best Practices Review: app.js

## Executive Summary
The current `app.js` has significant security and reliability gaps. This document outlines the issues and provides implementation recommendations.

---

## 🚨 Critical Issues

### 1. **No Error Handling**
**Risk Level:** HIGH

**Issues:**
- No try-catch blocks in route handlers
- No global error handler middleware
- Unhandled promise rejections will crash the server
- No logging of errors

**Recommendation:**
```javascript
// Add global error handler (must be last middleware)
app.use((err, req, res, next) => {
  console.error('Error:', err);
  res.status(err.status || 500).json({
    success: false,
    message: process.env.NODE_ENV === 'production' 
      ? 'Internal server error' 
      : err.message
  });
});

// Handle unhandled rejections
process.on('unhandledRejection', (reason) => {
  console.error('Unhandled Rejection:', reason);
  process.exit(1);
});
```

---

### 2. **No Input Validation**
**Risk Level:** HIGH

**Issues:**
- Query parameters are not validated
- No type checking on incoming data
- Vulnerable to injection attacks
- No protection against malformed requests

**Recommendation:**
Use `express-validator`:
```javascript
npm install express-validator
```

```javascript
const { query, param, validationResult } = require('express-validator');

app.get('/users/:id',
  param('id')
    .isInt({ min: 1 })
    .withMessage('User ID must be a positive integer'),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    // Process valid data
  }
);
```

---

### 3. **Missing Security Headers**
**Risk Level:** MEDIUM

**Issues:**
- No HTTP security headers (X-Frame-Options, X-Content-Type-Options, etc.)
- Vulnerable to clickjacking, MIME-type sniffing
- No CSP (Content Security Policy) headers

**Recommendation:**
```javascript
npm install helmet
```

```javascript
const helmet = require('helmet');
app.use(helmet());
```

---

### 4. **No Rate Limiting**
**Risk Level:** MEDIUM

**Issues:**
- Vulnerable to brute force attacks
- No protection against DoS attacks
- Endpoints can be abused without limits

**Recommendation:**
```javascript
npm install express-rate-limit
```

```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
});

app.use(limiter);
```

---

### 5. **Unsafe Data Exposure**
**Risk Level:** MEDIUM

**Issues:**
- All user data exposed without authentication
- Email addresses exposed in /users endpoint
- No access control checks
- No pagination (could expose unbounded data)

**Recommendation:**
- Implement authentication/authorization
- Add pagination with reasonable limits
- Control which fields are exposed
- Use role-based access control (RBAC)

```javascript
app.get('/users',
  query('page').optional().isInt({ min: 1 }).toInt(),
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  (req, res) => {
    const page = req.query.page || 1;
    const limit = Math.min(req.query.limit || 10, 100);

    // Pagination logic
    const startIndex = (page - 1) * limit;
    res.json({
      data: users.slice(startIndex, startIndex + limit),
      pagination: { page, limit, total: users.length }
    });
  }
);
```

---

### 6. **No Request Body Size Limits**
**Risk Level:** MEDIUM

**Issues:**
- Vulnerable to large payload attacks
- Could cause memory exhaustion
- No protection against slowloris attacks

**Recommendation:**
```javascript
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));
```

---

### 7. **Hardcoded Configuration**
**Risk Level:** LOW

**Issues:**
- Port hardcoded to 3000
- No environment-specific configuration
- Difficult to deploy across environments

**Recommendation:**
```javascript
npm install dotenv
```

Create `.env` file:
```
PORT=3000
NODE_ENV=development
```

```javascript
require('dotenv').config();
const PORT = process.env.PORT || 3000;
```

---

### 8. **No Logging**
**Risk Level:** LOW

**Issues:**
- No request logging
- Difficult to debug issues
- No audit trail

**Recommendation:**
```javascript
npm install morgan
```

```javascript
const morgan = require('morgan');
app.use(morgan('dev'));
```

---

### 9. **No Graceful Shutdown**
**Risk Level:** LOW

**Issues:**
- In-flight requests may be cut off
- No cleanup on server termination
- Connections not properly closed

**Recommendation:**
```javascript
const server = app.listen(3000, () => {
  console.log('Server running');
});

process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});
```

