// Improved application with security best practices
// Includes environment variable validation
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');
const morgan = require('morgan');
const dotenv = require('dotenv');

// Load environment variables
dotenv.config();

// ============================================
// Configuration & Validation
// ============================================

const config = {
  // Server
  port: parseInt(process.env.PORT, 10) || 3000,
  nodeEnv: process.env.NODE_ENV || 'development',

  // Security
  corsOrigin: process.env.CORS_ORIGIN || 'http://localhost:3000',
  jwtSecret: process.env.JWT_SECRET,

  // Database (when implemented)
  databaseUrl: process.env.DATABASE_URL,

  // External Services (when implemented)
  awsAccessKeyId: process.env.AWS_ACCESS_KEY_ID,
  awsSecretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
  anthropicApiKey: process.env.ANTHROPIC_API_KEY,
  stripeSecretKey: process.env.STRIPE_SECRET_KEY,
  logfireToken: process.env.LOGFIRE_TOKEN,
};

/**
 * Validate required environment variables
 * Throws error if critical variables are missing in production
 */
function validateConfig() {
  const requiredInProduction = ['jwtSecret'];
  const recommendedInProduction = ['databaseUrl'];

  const isProd = config.nodeEnv === 'production';

  if (isProd) {
    const missing = requiredInProduction.filter(key => !config[key]);
    if (missing.length > 0) {
      throw new Error(
        `Missing required environment variables in production: ${missing.join(', ')}\n` +
        `Please set: ${missing.map(key => {
          const varName = {
            jwtSecret: 'JWT_SECRET',
            databaseUrl: 'DATABASE_URL'
          }[key];
          return varName;
        }).join(', ')}`
      );
    }

    const notSet = recommendedInProduction.filter(key => !config[key]);
    if (notSet.length > 0) {
      console.warn(
        `⚠️  Warning: These environment variables are recommended in production but not set: ${notSet.join(', ')}`
      );
    }
  }

  // Warn about unused but configured variables
  const unusedVars = {
    awsAccessKeyId: 'AWS_ACCESS_KEY_ID',
    awsSecretAccessKey: 'AWS_SECRET_ACCESS_KEY',
    anthropicApiKey: 'ANTHROPIC_API_KEY',
    stripeSecretKey: 'STRIPE_SECRET_KEY',
    logfireToken: 'LOGFIRE_TOKEN',
    databaseUrl: 'DATABASE_URL' // Only warn if not in production
  };

  Object.entries(unusedVars).forEach(([key, envVar]) => {
    if (config[key]) {
      if (key === 'databaseUrl' && isProd) return; // Don't warn if using in prod
      console.info(
        `ℹ️  Info: Environment variable ${envVar} is configured but not currently used by the application`
      );
    }
  });

  console.log(`✓ Configuration validated (Environment: ${config.nodeEnv})`);
}

// Validate configuration on startup
try {
  validateConfig();
} catch (error) {
  console.error('❌ Configuration Error:', error.message);
  process.exit(1);
}

const app = express();

// ============================================
// Middleware - Security & Logging
// ============================================

// Security headers
app.use(helmet());

// Request logging
app.use(morgan(config.nodeEnv === 'production' ? 'combined' : 'dev'));

// Body parser with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Rate limiting - prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Stricter rate limit for authentication endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  skipSuccessfulRequests: true,
});

// ============================================
// Middleware - Error Handler
// ============================================

// Express validation error handler middleware
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      success: false,
      errors: errors.array().map(err => ({
        field: err.param,
        message: err.msg
      }))
    });
  }
  next();
};

// ============================================
// Routes - Configuration Info (Debug Only)
// ============================================

// Debug endpoint - show configuration (dev only)
app.get('/config', (req, res) => {
  if (config.nodeEnv !== 'development') {
    return res.status(403).json({
      success: false,
      message: 'Configuration endpoint only available in development'
    });
  }

  try {
    // Only show safe configuration info, never show secrets
    res.json({
      success: true,
      config: {
        port: config.port,
        nodeEnv: config.nodeEnv,
        corsOrigin: config.corsOrigin,
        // Don't expose secrets, just show if they're set
        secrets: {
          jwtSecret: !!config.jwtSecret ? 'SET' : 'NOT SET',
          databaseUrl: !!config.databaseUrl ? 'SET' : 'NOT SET',
          awsAccessKeyId: !!config.awsAccessKeyId ? 'SET' : 'NOT SET',
          awsSecretAccessKey: !!config.awsSecretAccessKey ? 'SET' : 'NOT SET',
          anthropicApiKey: !!config.anthropicApiKey ? 'SET' : 'NOT SET',
          stripeSecretKey: !!config.stripeSecretKey ? 'SET' : 'NOT SET',
          logfireToken: !!config.logfireToken ? 'SET' : 'NOT SET',
        }
      }
    });
  } catch (error) {
    console.error('Error in /config endpoint:', error);
    res.status(500).json({
      success: false,
      message: 'Internal server error'
    });
  }
});

// ============================================
// Routes - Health Check
// ============================================

app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      environment: config.nodeEnv
    });
  } catch (error) {
    console.error('Error in /health endpoint:', error);
    res.status(500).json({
      success: false,
      message: 'Internal server error'
    });
  }
});

// ============================================
// Routes - Users (with validation & pagination)
// ============================================

// Mock database
const users = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
  { id: 3, name: 'Charlie', email: 'charlie@example.com' },
  { id: 4, name: 'Diana', email: 'diana@example.com' },
];

/**
 * GET /users
 * Query Parameters:
 *   - page (optional): page number (default: 1)
 *   - limit (optional): items per page (default: 10, max: 100)
 */
app.get('/users',
  query('page')
    .optional()
    .isInt({ min: 1 })
    .toInt()
    .withMessage('Page must be a positive integer'),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .toInt()
    .withMessage('Limit must be between 1 and 100'),
  handleValidationErrors,
  (req, res) => {
    try {
      const page = req.query.page || 1;
      const limit = Math.min(req.query.limit || 10, 100); // Cap at 100

      const startIndex = (page - 1) * limit;
      const endIndex = startIndex + limit;

      const paginatedUsers = users.slice(startIndex, endIndex);

      res.json({
        success: true,
        data: paginatedUsers,
        pagination: {
          page,
          limit,
          total: users.length,
          pages: Math.ceil(users.length / limit)
        }
      });
    } catch (error) {
      console.error('Error in /users endpoint:', error);
      res.status(500).json({
        success: false,
        message: 'Internal server error'
      });
    }
  }
);

/**
 * GET /users/:id
 * Get a specific user by ID with validation
 */
app.get('/users/:id',
  (req, res) => {
    try {
      const userId = parseInt(req.params.id, 10);

      // Validate userId
      if (isNaN(userId) || userId <= 0) {
        return res.status(400).json({
          success: false,
          message: 'Invalid user ID format'
        });
      }

      const user = users.find(u => u.id === userId);

      if (!user) {
        return res.status(404).json({
          success: false,
          message: 'User not found'
        });
      }

      res.json({
        success: true,
        data: user
      });
    } catch (error) {
      console.error('Error in GET /users/:id endpoint:', error);
      res.status(500).json({
        success: false,
        message: 'Internal server error'
      });
    }
  }
);

// ============================================
// Error Handling Middleware
// ============================================

// 404 handler - must be after all other routes
app.use((req, res) => {
  res.status(404).json({
    success: false,
    message: 'Endpoint not found',
    path: req.path
  });
});

// Global error handler - must be last middleware
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  const status = err.status || err.statusCode || 500;
  const message = config.nodeEnv === 'production'
    ? 'Internal server error'
    : err.message;

  res.status(status).json({
    success: false,
    message,
    ...(config.nodeEnv === 'development' && { stack: err.stack })
  });
});

// ============================================
// Server Startup & Shutdown
// ============================================

const server = app.listen(config.port, () => {
  console.log(`
╭─────────────────────────────────────────╮
│  Server Running                         │
├─────────────────────────────────────────┤
│  Port: ${config.port}
│  Environment: ${config.nodeEnv}
│  URL: http://localhost:${config.port}
│  Health: http://localhost:${config.port}/health
│  Users: http://localhost:${config.port}/users
╰─────────────────────────────────────────╯
  `);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

// Catch unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

module.exports = app;
module.exports.config = config; // Export for testing

