  const { page, limit } = req.query;

  // Set defaults
  req.validatedParams = {
    page: 1,
    limit: 10,
  };

  if (page !== undefined) {
    const pageNum = parseInt(page, 10);
    if (isNaN(pageNum) || pageNum < 1) {
      return res.status(400).json({
        error: 'Invalid request',
        message: 'Parameter "page" must be a positive integer',
