// Improved Express application with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const validator = require('validator');

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// Set security HTTP headers
app.use(helmet());

// Trust proxy for rate limiting behind reverse proxy
app.set('trust proxy', 1);

// Rate limiting - prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
});

app.use(limiter);

// ============================================
// MIDDLEWARE
// ============================================

// Parse JSON with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Request logging middleware
app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    const duration = Date.now() - start;
    console.log(`[${new Date().toISOString()}] ${req.method} ${req.path} - ${res.statusCode} - ${duration}ms`);
  });
  next();
});

// ============================================
// ROUTES
// ============================================

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.status(200).json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ error: 'Health check failed' });
  }
});

// Users endpoint with input validation
app.get('/users', (req, res) => {
  try {
    // Validate query parameters
    const { limit, offset } = req.query;

    // Validate limit parameter
    if (limit !== undefined) {
      if (!validator.isInt(limit, { min: 1, max: 100 })) {
        return res.status(400).json({
          error: 'Invalid limit parameter. Must be an integer between 1 and 100.',
        });
      }
    }

    // Validate offset parameter
    if (offset !== undefined) {
      if (!validator.isInt(offset, { min: 0 })) {
        return res.status(400).json({
          error: 'Invalid offset parameter. Must be a non-negative integer.',
        });
      }
    }

    // Mock data - in production, this would come from a database
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination
    const limitNum = Math.min(parseInt(limit, 10) || 10, 100);
    const offsetNum = Math.max(parseInt(offset, 10) || 0, 0);
    const paginatedUsers = allUsers.slice(offsetNum, offsetNum + limitNum);

    res.status(200).json({
      data: paginatedUsers,
      total: allUsers.length,
      limit: limitNum,
      offset: offsetNum,
    });
  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({
      error: 'Failed to retrieve users. Please try again later.',
    });
  }
});

// ============================================
// ERROR HANDLING MIDDLEWARE
// ============================================

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: 'The requested resource does not exist.',
  });
});

// Global error handler (must be last)
app.use((err, req, res, next) => {
  console.error('Unhandled error:', {
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
  });

  // Don't leak error details to client in production
  const isDevelopment = process.env.NODE_ENV === 'development';
  const status = err.status || err.statusCode || 500;

  res.status(status).json({
    error: 'Internal Server Error',
    message: isDevelopment ? err.message : 'An unexpected error occurred.',
    ...(isDevelopment && { stack: err.stack }),
  });
});

// ============================================
// SERVER STARTUP
// ============================================

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';

let server;

const startServer = () => {
  server = app.listen(PORT, HOST, () => {
    console.log(`✓ Server running on http://${HOST}:${PORT}`);
    console.log(`✓ Environment: ${process.env.NODE_ENV || 'development'}`);
  });

  // Set timeouts
  server.keepAliveTimeout = 65000;
  server.headersTimeout = 66000;
};

// Graceful shutdown
const gracefulShutdown = (signal) => {
  console.log(`\n✓ Received ${signal}, shutting down gracefully...`);

  if (server) {
    server.close(() => {
      console.log('✓ Server closed');
      process.exit(0);
    });

    // Force shutdown after timeout
    setTimeout(() => {
      console.error('✗ Could not close connections in time, forcefully shutting down');
      process.exit(1);
    }, 10000);
  } else {
    process.exit(0);
  }
};

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  process.exit(1);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

startServer();

module.exports = app;

# Security Review: app.js - Improvement Recommendations

## Executive Summary
The original `app.js` is a basic Express application that lacks critical security measures, input validation, and error handling. This review identifies vulnerabilities and provides recommendations to harden the application.

---

## Critical Issues

### 1. **Missing Error Handling** ⚠️ HIGH PRIORITY
**Problem:**
- No try-catch blocks in route handlers
- No global error handler middleware
- No error logging
- Unhandled promise rejections could crash the app

**Impact:**
- Application crashes on errors
- Poor debugging capability
- Potential information disclosure

**Solution:**
```javascript
// Add global error handler
app.use((err, req, res, next) => {
  console.error('Error:', err);
  const status = err.status || 500;
  res.status(status).json({ 
    error: 'Internal Server Error',
    message: process.env.NODE_ENV === 'production' 
      ? 'An error occurred' 
      : err.message 
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  process.exit(1);
});
```

---

### 2. **No Input Validation** ⚠️ HIGH PRIORITY
**Problem:**
- Query parameters are not validated
- No type checking
- No sanitization
- No validation of request size

**Impact:**
- Injection attacks
- Denial of Service (DoS) via large payloads
- Invalid data processing

**Solution:**
```javascript
// Validate query parameters
app.use(express.json({ limit: '10kb' }));

app.get('/users', (req, res) => {
  const { limit, offset } = req.query;

  if (limit && !validator.isInt(limit, { min: 1, max: 100 })) {
    return res.status(400).json({ error: 'Invalid limit' });
  }

  if (offset && !validator.isInt(offset, { min: 0 })) {
    return res.status(400).json({ error: 'Invalid offset' });
  }
  // ... rest of handler
});
```

---

### 3. **Missing Security Headers** ⚠️ HIGH PRIORITY
**Problem:**
- No helmet.js protection
- No CORS configuration
- No Content Security Policy
- No X-Frame-Options headers

**Impact:**
- Vulnerable to clickjacking
- Missing XSS protection
- Exposed to CORS attacks

**Solution:**
```javascript
const helmet = require('helmet');
app.use(helmet()); // Sets 16+ security headers
```

---

### 4. **No Rate Limiting** ⚠️ MEDIUM PRIORITY
**Problem:**
- No protection against brute force attacks
- No DoS protection
- Unlimited requests allowed

**Impact:**
- Application resource exhaustion
- Service degradation
- Brute force vulnerabilities

**Solution:**
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100, // 100 requests per 15 minutes
  message: 'Too many requests'
});

app.use(limiter);
```

---

### 5. **No Authentication/Authorization** ⚠️ MEDIUM PRIORITY
**Problem:**
- Public endpoints without access control
- Sensitive user data exposed
- No user identification

**Impact:**
- Unauthorized data access
- Privacy concerns
- GDPR/compliance violations

**Solution:**
```javascript
const authenticateToken = (req, res, next) => {
  const token = req.headers['authorization']?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (error) {
    res.status(403).json({ error: 'Invalid or expired token' });
  }
};

app.get('/users', authenticateToken, (req, res) => {
  // ... only authenticated users can access
});
```

---

### 6. **Missing Request Logging** ⚠️ MEDIUM PRIORITY
**Problem:**
- No audit trail
- No request tracking
- Difficult to debug issues
- No security monitoring

**Impact:**
- Cannot investigate security incidents
- Poor observability
- Compliance violations

**Solution:**
```javascript
app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    console.log(`[${new Date().toISOString()}] ${req.method} ${req.path} - ${res.statusCode} - ${Date.now() - start}ms`);
  });
  next();
});
```

---

### 7. **Hardcoded Configuration** ⚠️ MEDIUM PRIORITY
**Problem:**
- Port is hardcoded
- No environment variable support
- Cannot configure for different environments

**Impact:**
- Not production-ready
- Security issues with deployments
- Configuration management problems

**Solution:**
```javascript
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';
const NODE_ENV = process.env.NODE_ENV || 'development';

app.listen(PORT, HOST, () => {
  console.log(`Server running on ${HOST}:${PORT}`);
});
```

---

### 8. **No Graceful Shutdown** ⚠️ LOW PRIORITY
**Problem:**
- No signal handlers
- Abrupt server termination
- Potential data loss
- In-flight requests are killed

**Impact:**
- Failed requests
- Incomplete operations
- Poor deployment experience

**Solution:**
```javascript
const gracefulShutdown = (signal) => {
  console.log(`Received ${signal}, shutting down gracefully...`);

  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });

  // Force shutdown after timeout
  setTimeout(() => {
    console.error('Forced shutdown');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));
```

---

## Additional Security Recommendations

### 1. **Dependency Management**
```bash
# Check for vulnerable dependencies
npm audit
npm audit fix

# Use lock file
npm ci instead of npm install
```

### 2. **Data Protection**
- Encrypt sensitive data at rest and in transit
- Use HTTPS in production
- Hash passwords with bcrypt
- Implement proper session management

### 3. **Monitoring & Logging**
```javascript
// Use structured logging
const logger = require('winston');

logger.error('Error occurred:', {
  message: err.message,
  stack: err.stack,
  userId: req.user?.id,
  path: req.path
});
```

### 4. **Environment-Specific Configuration**
```javascript
// .env file
PORT=3000
HOST=localhost
NODE_ENV=development
JWT_SECRET=your-secret-key
LOG_LEVEL=debug
```

### 5. **CORS Configuration**
```javascript
const cors = require('cors');

app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  optionsSuccessStatus: 200
}));
```

### 6. **SQL Injection Prevention** (if using databases)
```javascript
// ✗ DON'T DO THIS
db.query(`SELECT * FROM users WHERE id = ${userId}`);

// ✓ DO THIS (parameterized queries)
db.query('SELECT * FROM users WHERE id = ?', [userId]);
```

### 7. **Data Validation Library**
```javascript
// Use joi for schema validation
const schema = joi.object({
  limit: joi.number().integer().min(1).max(100),
  offset: joi.number().integer().min(0)
});

const { error, value } = schema.validate(req.query);
if (error) return res.status(400).json({ error: error.details });
```

