// Enhanced application with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const validator = require('validator');
const app = express();

// ============================================
// 1. SECURITY MIDDLEWARE
// ============================================

// Apply security headers
app.use(helmet());

// Body parsing with size limits to prevent DoS
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Rate limiting - prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
});

app.use(limiter);

// Request logging middleware (audit trail)
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.path} - IP: ${req.ip}`);
  next();
});

// ============================================
// 2. INPUT VALIDATION & SANITIZATION
// ============================================

const validateQueryParams = (req, res, next) => {
  // Validate and sanitize query parameters
  for (const [key, value] of Object.entries(req.query)) {
    if (typeof value === 'string') {
      // Validate it's a string and not excessively long
      if (value.length > 100) {
        return res.status(400).json({ 
          error: 'Query parameter too long',
          field: key 
        });
      }
      // Basic XSS prevention
      if (!validator.isAscii(value)) {
        return res.status(400).json({ 
          error: 'Invalid characters in query parameter',
          field: key 
        });
      }
    }
  }
  next();
};

// ============================================
// 3. AUTHENTICATION MIDDLEWARE (Mock)
// ============================================

const authenticate = (req, res, next) => {
  const authHeader = req.headers.authorization;

  if (!authHeader) {
    return res.status(401).json({ error: 'Missing authorization header' });
  }

  try {
    const token = authHeader.split(' ')[1];
    if (!token) {
      return res.status(401).json({ error: 'Invalid token format' });
    }
    // In production: verify JWT with secret
    // const decoded = jwt.verify(token, process.env.JWT_SECRET);
    // req.user = decoded;

    // Mock authentication (remove in production)
    req.user = { id: 1, role: 'user' };
    next();
  } catch (error) {
    return res.status(401).json({ error: 'Invalid token' });
  }
};

// ============================================
// 4. ROUTES WITH PROPER ERROR HANDLING
// ============================================

app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      version: process.env.APP_VERSION || '1.0.0'
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Protected endpoint with validation
app.get('/users', validateQueryParams, authenticate, (req, res) => {
  try {
    // Validate optional query parameters
    const { limit = 10, offset = 0 } = req.query;

    const parsedLimit = parseInt(limit, 10);
    const parsedOffset = parseInt(offset, 10);

    // Validate parsed values
    if (isNaN(parsedLimit) || isNaN(parsedOffset)) {
      return res.status(400).json({ 
        error: 'Invalid query parameters',
        details: 'limit and offset must be valid integers'
      });
    }

    if (parsedLimit < 1 || parsedLimit > 100) {
      return res.status(400).json({ 
        error: 'Invalid limit',
        details: 'limit must be between 1 and 100'
      });
    }

    if (parsedOffset < 0) {
      return res.status(400).json({ 
        error: 'Invalid offset',
        details: 'offset must be non-negative'
      });
    }

    // Sample data (in production: fetch from database)
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination
    const users = allUsers.slice(parsedOffset, parsedOffset + parsedLimit);

    res.json({
      data: users,
      total: allUsers.length,
      limit: parsedLimit,
      offset: parsedOffset
    });
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// ============================================
// 5. ERROR HANDLING MIDDLEWARE
// ============================================

// 404 handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not found',
    path: req.path
  });
});

// Global error handler (must be last)
app.use((err, req, res, next) => {
  console.error('Unhandled error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'production' ? undefined : err.stack,
    timestamp: new Date().toISOString()
  });

  // Don't expose sensitive error details in production
  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal server error' 
    : err.message;

  res.status(statusCode).json({ error: message });
});

// ============================================
// 6. GRACEFUL SHUTDOWN
// ============================================

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // In production: send to error tracking service (e.g., Sentry)
});

process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  // Gracefully shutdown
  process.exit(1);
});

// ============================================
// 7. SERVER START WITH ERROR HANDLING
// ============================================

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

server.on('error', (error) => {
  if (error.code === 'EADDRINUSE') {
    console.error(`Port ${PORT} is already in use`);
  } else {
    console.error('Server error:', error);
  }
  process.exit(1);
});

// Graceful shutdown on SIGTERM
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

