// Enhanced application with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const xss = require('xss-clean');
const app = express();

// ============ SECURITY MIDDLEWARE ============

// 1. Use Helmet to set various HTTP headers for security
app.use(helmet());

// 2. Data sanitization against NoSQL query injection
app.use(mongoSanitize());

// 3. Data sanitization against XSS
app.use(xss());

// 4. Rate limiting - prevent brute force and DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

// Apply rate limiting to all requests
app.use(limiter);

// 5. Body parser with size limits to prevent payload attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// ============ INPUT VALIDATION HELPER ============

/**
 * Validates and sanitizes string input
 * @param {string} input - Input to validate
 * @param {string} fieldName - Field name for error message
 * @param {object} options - Validation options
 * @returns {string} - Sanitized input or throws error
 */
function validateStringInput(input, fieldName, options = {}) {
  const { minLength = 0, maxLength = 255, pattern = null } = options;

  // Type check
  if (typeof input !== 'string') {
    throw new Error(`${fieldName} must be a string`);
  }

  // Length validation
  if (input.length < minLength || input.length > maxLength) {
    throw new Error(
      `${fieldName} must be between ${minLength} and ${maxLength} characters`
    );
  }

  // Pattern validation (regex)
  if (pattern && !pattern.test(input)) {
    throw new Error(`${fieldName} format is invalid`);
  }

  return input.trim();
}

/**
 * Validates numeric ID
 * @param {*} id - ID to validate
 * @returns {number} - Validated ID or throws error
 */
function validateId(id) {
  const numId = parseInt(id, 10);
  if (!Number.isInteger(numId) || numId <= 0) {
    throw new Error('Invalid ID format');
  }
  return numId;
}

// ============ ROUTES WITH VALIDATION & ERROR HANDLING ============

/**
 * Health check endpoint
 */
app.get('/health', (req, res) => {
  try {
    res.status(200).json({
      status: 'ok',
      timestamp: new Date().toISOString(),
    });
  } catch (err) {
    res.status(500).json({ error: 'Internal server error' });
  }
});

/**
 * Get all users
 * Note: In production, add authentication and authorization
 */
app.get('/users', (req, res) => {
  try {
    // Validate query parameters if any are expected
    const { limit = 10, offset = 0 } = req.query;

    // Validate pagination parameters
    const validatedLimit = Math.min(Math.max(parseInt(limit, 10) || 10, 1), 100);
    const validatedOffset = Math.max(parseInt(offset, 10) || 0, 0);

    if (!Number.isInteger(validatedLimit) || !Number.isInteger(validatedOffset)) {
      return res.status(400).json({
        error: 'Invalid pagination parameters',
      });
    }

    // Mock data (in production, fetch from database with proper auth)
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const users = allUsers.slice(validatedOffset, validatedOffset + validatedLimit);

    res.status(200).json({
      data: users,
      pagination: {
        limit: validatedLimit,
        offset: validatedOffset,
        total: allUsers.length,
      },
    });
  } catch (err) {
    res.status(500).json({ error: 'Internal server error' });
  }
});

/**
 * Get user by ID
 */
app.get('/users/:id', (req, res) => {
  try {
    // Validate and sanitize ID parameter
    const userId = validateId(req.params.id);

    // Mock data
    const mockUsers = {
      1: { id: 1, name: 'Alice' },
      2: { id: 2, name: 'Bob' },
    };

    const user = mockUsers[userId];

    if (!user) {
      return res.status(404).json({
        error: 'User not found',
      });
    }

    res.status(200).json({ data: user });
  } catch (err) {
    if (err.message === 'Invalid ID format') {
      return res.status(400).json({ error: err.message });
    }
    res.status(500).json({ error: 'Internal server error' });
  }
});

// ============ 404 HANDLER ============

app.use((req, res) => {
  res.status(404).json({
    error: 'Endpoint not found',
    method: req.method,
    path: req.path,
  });
});

// ============ GLOBAL ERROR HANDLER ============

/**
 * Global error handling middleware
 * Must be defined last, after all other middleware and routes
 */
app.use((err, req, res, next) => {
  // Log error (in production, use a proper logger like Winston or Pino)
  console.error({
    timestamp: new Date().toISOString(),
    error: err.message,
    stack: err.stack,
    method: req.method,
    path: req.path,
  });

  // Send generic error response (don't leak stack traces to client)
  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal server error' 
    : err.message;

  res.status(statusCode).json({
    error: message,
    requestId: req.id, // Add request tracking if available
  });
});

// ============ UNHANDLED ERROR HANDLERS ============

// Handle unhandled promise rejections
process.on('unhandledRejection', (err) => {
  console.error('UNHANDLED REJECTION:', err);
  // In production, you might want to restart the process or alert
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('UNCAUGHT EXCEPTION:', err);
  // In production, gracefully shutdown and restart
  process.exit(1);
});

// ============ SERVER START ============

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

