const request = require('supertest');
const app = require('../app.js.improved');

describe('Input Validation & Security', () => {

  // ============ Error Handling Tests ============

  describe('Error Handling', () => {

    test('should handle non-existent routes gracefully', async () => {
      const response = await request(app)
        .get('/nonexistent')
        .expect(404);

      expect(response.body).toHaveProperty('error');
      expect(response.body.error).toBe('Endpoint not found');
      expect(response.body.stack).toBeUndefined(); // No stack trace leak
    });

    test('should not expose stack traces in production', async () => {
      process.env.NODE_ENV = 'production';

      const response = await request(app)
        .get('/users/invalid-id')
        .expect(400);

      // In production, should not show internal details
      expect(response.body.error).toBeDefined();
      expect(response.body.error).not.toContain('at');
    });
  });

  // ============ Input Validation Tests ============

  describe('ID Parameter Validation', () => {

    test('should accept valid numeric ID', async () => {
      const response = await request(app)
        .get('/users/1')
        .expect(200);

      expect(response.body.data).toBeDefined();
      expect(response.body.data.id).toBe(1);
    });

    test('should reject non-numeric ID', async () => {
      const response = await request(app)
        .get('/users/abc')
        .expect(400);

      expect(response.body.error).toBe('Invalid ID format');
    });

    test('should reject negative ID', async () => {
      const response = await request(app)
        .get('/users/-1')
        .expect(400);

      expect(response.body.error).toBe('Invalid ID format');
    });

    test('should reject ID with special characters', async () => {
      const response = await request(app)
        .get('/users/1;DROP TABLE users')
        .expect(400);

      expect(response.body.error).toBe('Invalid ID format');
    });

    test('should reject float ID', async () => {
      const response = await request(app)
        .get('/users/1.5')
        .expect(400);

      expect(response.body.error).toBe('Invalid ID format');
    });

    test('should reject zero ID', async () => {
      const response = await request(app)
        .get('/users/0')
        .expect(400);

      expect(response.body.error).toBe('Invalid ID format');
    });
  });

  // ============ Query Parameter Validation Tests ============

  describe('Query Parameter Validation', () => {

    test('should accept valid pagination parameters', async () => {
      const response = await request(app)
        .get('/users?limit=10&offset=0')
        .expect(200);

      expect(response.body.pagination.limit).toBe(10);
      expect(response.body.pagination.offset).toBe(0);
    });

    test('should enforce maximum limit', async () => {
      const response = await request(app)
        .get('/users?limit=500')
        .expect(200);

      // Should be capped at 100
      expect(response.body.pagination.limit).toBeLessThanOrEqual(100);
    });

    test('should enforce minimum limit', async () => {
      const response = await request(app)
        .get('/users?limit=-1')
        .expect(200);

      // Should be at least 1
      expect(response.body.pagination.limit).toBeGreaterThanOrEqual(1);
    });

    test('should handle non-numeric limit gracefully', async () => {
      const response = await request(app)
        .get('/users?limit=abc')
        .expect(200);

      // Should use default or fallback value
      expect(response.body.pagination.limit).toBeDefined();
    });

    test('should handle negative offset', async () => {
      const response = await request(app)
        .get('/users?offset=-5')
        .expect(200);

      // Should be zero or positive
      expect(response.body.pagination.offset).toBeGreaterThanOrEqual(0);
    });

    test('should support default pagination', async () => {
      const response = await request(app)
        .get('/users')
        .expect(200);

      expect(response.body.pagination.limit).toBeDefined();
      expect(response.body.pagination.offset).toBeDefined();
    });
  });

  // ============ Security Header Tests ============

  describe('Security Headers', () => {

    test('should include Content-Security-Policy header', async () => {
      const response = await request(app)
        .get('/health')
        .expect(200);

      expect(response.headers['content-security-policy']).toBeDefined();
    });

    test('should include X-Frame-Options header', async () => {
      const response = await request(app)
        .get('/health')
        .expect(200);

      expect(response.headers['x-frame-options']).toBe('DENY');
    });

    test('should include X-Content-Type-Options header', async () => {
      const response = await request(app)
        .get('/health')
        .expect(200);

      expect(response.headers['x-content-type-options']).toBe('nosniff');
    });

    test('should include Strict-Transport-Security header', async () => {
      const response = await request(app)
        .get('/health')
        .expect(200);

      expect(response.headers['strict-transport-security']).toBeDefined();
    });

    test('should not expose server information', async () => {
      const response = await request(app)
        .get('/health')
        .expect(200);

      // Server header should be removed by Helmet
      expect(response.headers['server']).toBeUndefined();
    });
