describe('Edge Cases', () => {

  test('should handle empty path segments', async () => {
    const response = await request(app)
      .get('//health')
      .expect(404); // Express normalizes to /health but router might return 404

    expect(response.status).toBeDefined();
  });

  test('should handle very long path', async () => {
    const longPath = '/users/' + 'a'.repeat(5000);

    const response = await request(app)
      .get(longPath)
      .expect(404);

    expect(response.status).toBeDefined();
  });

  test('should handle null bytes in path', async () => {
    const response = await request(app)
      .get('/users/1%00')
      .expect(404);

    expect(response.status).toBeDefined();
  });

  test('should handle unicode characters', async () => {
    const response = await request(app)
      .get('/users/1?search=こんにちは')
      .expect(200); // Should handle gracefully

    expect(response.status).toBeDefined();
  });

  test('should handle concurrent requests', async () => {
    const promises = [];

    for (let i = 0; i < 10; i++) {
      promises.push(
        request(app)
          .get('/users/1')
          .expect(200)
      );
    }

    const results = await Promise.all(promises);

    expect(results).toHaveLength(10);
    expect(results.every(r => r.status === 200)).toBe(true);
  });
});

