# Security Review: app.js

## Current Issues & Recommendations

### 1. **Missing Error Handling** (Critical)
**Issue:** No error handling middleware or try-catch blocks
- Routes don't handle potential errors
- No proper HTTP error responses
- Server crashes on unexpected errors would be unhandled

**Recommendation:**
```javascript
// Add error handling middleware
app.use((err, req, res, next) => {
  console.error('Error:', err);
  res.status(err.status || 500).json({
    error: process.env.NODE_ENV === 'production' ? 'Internal Server Error' : err.message
  });
});

// Add 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});
```

### 2. **Missing Input Validation** (High)
**Issue:** Routes accept requests without validating input
- Query parameters not validated
- Request body not validated
- No content-type checking

**Recommendation:**
- Use middleware like `express-validator` or `joi`
- Validate and sanitize all inputs
- Example:
```javascript
const { query, validationResult } = require('express-validator');

app.get('/users', 
  query('limit').optional().isInt({ min: 1, max: 100 }),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    // ... handle request
  }
);
```

### 3. **Missing Security Headers** (High)
**Issue:** No security headers configured
- No helmet.js protection
- Vulnerable to common attacks (XSS, clickjacking, etc.)

**Recommendation:**
```javascript
const helmet = require('helmet');
app.use(helmet());
```

### 4. **No Request Size Limits** (Medium)
**Issue:** Potential for Denial of Service attacks
- No limit on request payload size
- No timeout settings

**Recommendation:**
```javascript
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb' }));

// Add request timeout
app.use((req, res, next) => {
  req.setTimeout(5000);
  next();
});
```

### 5. **No CORS Configuration** (Medium)
**Issue:** CORS not properly configured
- Could allow unauthorized cross-origin requests
- Or block legitimate requests

**Recommendation:**
```javascript
const cors = require('cors');
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST'],
  maxAge: 3600
}));
```

### 6. **Sensitive Data Exposure** (Medium)
**Issue:** Exposing user emails in `/users` endpoint
- No authentication/authorization
- Returns all user data without filtering
- Endpoint accessible to anyone

**Recommendation:**
```javascript
// Add authentication middleware
const authenticate = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];
  if (!token) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  // Verify token...
  next();
};

// Protect sensitive endpoints
app.get('/users', authenticate, (req, res) => {
  // Filter sensitive data
  res.json([
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
  ]);
});
```

### 7. **Missing Logging & Monitoring** (Medium)
**Issue:** No request logging or error tracking
- Difficult to debug issues
- Cannot track security incidents

**Recommendation:**
```javascript
const morgan = require('morgan');
app.use(morgan('combined')); // or custom format for production

// Log errors with context
app.use((err, req, res, next) => {
  console.error({
    timestamp: new Date().toISOString(),
    method: req.method,
    path: req.path,
    statusCode: err.status || 500,
    error: err.message
  });
  // ... send response
});
```

### 8. **No Environment Configuration** (Medium)
**Issue:** Hard-coded port and no env-based configuration
- Not portable
- No way to configure for different environments

**Recommendation:**
```javascript
require('dotenv').config();
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
```

### 9. **Missing HTTP Method Validation** (Low)
**Issue:** Only GET routes defined, but no explicit method restrictions
- HEAD requests might be unintended
- No OPTIONS support for CORS preflight

**Recommendation:**
```javascript
// Handle OPTIONS automatically with cors middleware
// Or explicitly for manual control
app.options('/users', cors());
```

### 10. **No Rate Limiting** (Low-Medium)
**Issue:** No protection against brute force or DoS attacks
- Anyone can make unlimited requests

**Recommendation:**
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests, please try again later.'
});

app.use(limiter);
```

## Summary of Recommended Changes

| Issue | Severity | Category |
|-------|----------|----------|
| Error handling middleware | Critical | Error Handling |
| Input validation | High | Input Validation |
| Security headers (helmet) | High | Security |
| CORS configuration | Medium | Security |
| Request size limits | Medium | Security |
| Sensitive data exposure | Medium | Security/Privacy |
| Logging/Monitoring | Medium | Observability |
| Environment configuration | Medium | Configuration |
| Rate limiting | Low-Medium | Security |

## Recommended npm Dependencies
```json
{
  "dependencies": {
    "express": "^4.18.2",
    "helmet": "^7.0.0",
    "cors": "^2.8.5",
    "express-validator": "^7.0.0",
    "express-rate-limit": "^7.0.0",
    "morgan": "^1.10.0",
    "dotenv": "^16.3.1"
  }
}
```

// Improved Express application with security best practices
require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const { query, validationResult } = require('express-validator');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');

const app = express();
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// ==================== SECURITY MIDDLEWARE ====================

// Security headers
app.use(helmet());

// Request logging
app.use(morgan(NODE_ENV === 'production' ? 'combined' : 'dev'));

// CORS configuration
app.use(cors({
  origin: (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(','),
  credentials: true,
  methods: ['GET', 'OPTIONS'],
  optionsSuccessStatus: 200,
  maxAge: 3600
}));

// Body parser with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
});

app.use(limiter);

// Request timeout
app.use((req, res, next) => {
  req.setTimeout(5000);
  next();
});

// ==================== MIDDLEWARE ====================

// Simple authentication middleware (replace with real JWT validation in production)
const authenticate = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];

  if (!token && NODE_ENV === 'production') {
    return res.status(401).json({ error: 'Unauthorized - Missing token' });
  }

  // In development, allow requests without token
  // In production, validate the token
  if (token && NODE_ENV === 'production') {
    try {
      // TODO: Implement proper JWT verification
      // const decoded = verifyToken(token);
      // req.user = decoded;
    } catch (error) {
      return res.status(401).json({ error: 'Unauthorized - Invalid token' });
    }
  }

  next();
};

// ==================== ROUTES ====================

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      environment: NODE_ENV
    });
  } catch (error) {
    res.status(500).json({
      error: NODE_ENV === 'production' ? 'Internal Server Error' : error.message
    });
  }
});

// Get users endpoint with validation and authentication
app.get('/users',
  authenticate,
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be an integer between 1 and 100'),
  (req, res) => {
    try {
      // Validate query parameters
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({
          error: 'Validation failed',
          details: errors.array()
        });
      }

      const limit = Math.min(req.query.limit ? parseInt(req.query.limit) : 10, 100);

      // Mock user data (in production, this would come from a database)
      const users = [
        { id: 1, name: 'Alice' },
        { id: 2, name: 'Bob' },
      ].slice(0, limit);

      res.json({
        data: users,
        count: users.length,
        timestamp: new Date().toISOString()
      });
    } catch (error) {
      console.error('Error in /users:', error);
      res.status(500).json({
        error: NODE_ENV === 'production' ? 'Internal Server Error' : error.message
      });
    }
  }
);

// ==================== ERROR HANDLING ====================

// 404 Not Found handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    path: req.path,
    method: req.method
  });
});

// Global error handling middleware (must be last)
app.use((err, req, res, next) => {
  // Log error
  console.error({
    timestamp: new Date().toISOString(),
    method: req.method,
    path: req.path,
    statusCode: err.status || 500,
    error: err.message,
    stack: NODE_ENV === 'development' ? err.stack : undefined
  });

  // Send error response
  res.status(err.status || 500).json({
    error: err.message || 'Internal Server Error',
    ...(NODE_ENV === 'development' && { stack: err.stack })
  });
});

// ==================== SERVER STARTUP ====================

// Only start server if this file is run directly (not imported as module)
if (require.main === module) {
  const server = app.listen(PORT, () => {
    console.log(`Server running on port ${PORT} (Environment: ${NODE_ENV})`);
  });

  // Graceful shutdown
  process.on('SIGTERM', () => {
    console.log('SIGTERM signal received: closing HTTP server');
    server.close(() => {
      console.log('HTTP server closed');
      process.exit(0);
    });
  });

  process.on('SIGINT', () => {
    console.log('SIGINT signal received: closing HTTP server');
    server.close(() => {
      console.log('HTTP server closed');
      process.exit(0);
    });
  });
}

module.exports = app;

