# Common Vulnerabilities & How to Fix Them

## 1. SQL Injection

### ❌ VULNERABLE
```javascript
const userId = req.query.id;
db.query(`SELECT * FROM users WHERE id = ${userId}`, (err, result) => {
  // If userId = "1 OR 1=1" - ENTIRE TABLE EXPOSED!
});
```

### ✅ SECURE
```javascript
const userId = req.query.id;
// Use parameterized queries
db.query('SELECT * FROM users WHERE id = ?', [userId], (err, result) => {
  // Safe - userId is treated as data, not code
});
```

---

## 2. Cross-Site Scripting (XSS)

### ❌ VULNERABLE
```javascript
app.get('/search', (req, res) => {
  const query = req.query.q;
  // User input directly in response
  res.send(`<h1>Results for: ${query}</h1>`);
  // If query = "<script>alert('hacked')</script>" - EXECUTES!
});
```

### ✅ SECURE - Option 1: Escape HTML
```javascript
const xss = require('xss');

app.get('/search', (req, res) => {
  const query = xss(req.query.q);
  res.send(`<h1>Results for: ${query}</h1>`);
  // HTML entities escaped
});
```

### ✅ SECURE - Option 2: Use JSON
```javascript
app.get('/search', (req, res) => {
  const query = req.query.q;
  res.json({ query: query }); // Safe - JSON, not HTML
});
```

---

## 3. Command Injection

### ❌ VULNERABLE
```javascript
const filename = req.query.file;
exec(`ls ${filename}`, (error, stdout) => {
  // If filename = "'; rm -rf /" - DISASTER!
});
```

### ✅ SECURE
```javascript
const { execFile } = require('child_process');
const filename = req.query.file;

// Use execFile with array, not shell string
execFile('ls', [filename], (error, stdout) => {
  // filename treated as argument, not shell command
});
```

---

## 4. Cross-Site Request Forgery (CSRF)

### ❌ VULNERABLE
```javascript
app.post('/transfer-money', (req, res) => {
  const amount = req.body.amount;
  // No CSRF token verification
  // Attacker website can make this request on behalf of user
  transferMoney(amount);
});
```

### ✅ SECURE
```javascript
const csrf = require('csurf');
const csrfProtection = csrf({ cookie: false });

app.post('/transfer-money', csrfProtection, (req, res) => {
  const amount = req.body.amount;
  // CSRF token automatically verified by middleware
  transferMoney(amount);
});
```

---

## 5. Authentication Bypass

### ❌ VULNERABLE
```javascript
app.get('/admin', (req, res) => {
  // No authentication check
  res.json({ admin: 'data' });
});
```

### ✅ SECURE
```javascript
const authenticate = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];
  try {
    const user = jwt.verify(token, process.env.JWT_SECRET);
    req.user = user;
    next();
  } catch (error) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
};

app.get('/admin', authenticate, (req, res) => {
  res.json({ admin: 'data' });
});
```

