## 10. XML External Entity (XXE)

### ❌ VULNERABLE
```javascript
const xml2js = require('xml2js');

app.post('/upload-xml', (req, res) => {
  const parser = new xml2js.Parser();
  // Default parser processes external entities
  parser.parseString(req.body, (err, result) => {
    // Can read files from server!
  });
});
```

### ✅ SECURE
```javascript
const xml2js = require('xml2js');

app.post('/upload-xml', (req, res) => {
  const parser = new xml2js.Parser({
    // Disable XXE processing
    strict: false,
    features: {
      nonvalidating: true,
      external: false  // Don't allow external entities
    }
  });
  parser.parseString(req.body, (err, result) => {
    // Safe - external entities blocked
  });
});
```

