## 11. Insecure Deserialization

### ❌ VULNERABLE
```javascript
// User-provided JSON
const data = JSON.parse(req.body);
// If attacker provides: {"constructor":{"prototype":{"isAdmin":true}}}
// Prototype pollution attack possible!
```

### ✅ SECURE
```javascript
const { body, validationResult } = require('express-validator');

app.post('/data', 
  body('field1').isString().trim(),
  body('field2').isInt(),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    // Only validated data is used
    const data = {
      field1: req.body.field1,
      field2: req.body.field2
    };
  }
);
```

---

## 12. Server-Side Template Injection

### ❌ VULNERABLE
```javascript
const template = req.query.template;
const compiled = ejs.render(template); // Compiles user input!
// If template = "<%=require('child_process').execSync('rm -rf /')%>"
// DESTROYED!
```

### ✅ SECURE - Use Pre-compiled Templates
```javascript
// Load templates from files, not user input
app.get('/page', (req, res) => {
  res.render('template.ejs', { 
    data: req.query.data // Only pass data
  });
});
```

