## 13. Denial of Service (ReDoS)

### ❌ VULNERABLE
```javascript
const email = req.body.email;
// Complex regex with backtracking
if (/^([a-zA-Z0-9]+)*@/.test(email)) {
  // If email = "aaaa...aaa" with 50+ a's - HANG!
}
```

### ✅ SECURE
```javascript
const { body, validationResult } = require('express-validator');

app.post('/user',
  body('email').isEmail(), // Simple, safe validation
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
  }
);
```

---

## 14. Path Traversal

### ❌ VULNERABLE
```javascript
const filename = req.query.file;
res.download(`./files/${filename}`);
// If filename = "../../../etc/passwd" - EXPOSED!
```

### ✅ SECURE
```javascript
const path = require('path');

app.get('/download', (req, res) => {
  const filename = req.query.file;
  // Resolve path and verify it's within allowed directory
  const filePath = path.resolve('./files', filename);
  const basePath = path.resolve('./files');

  if (!filePath.startsWith(basePath)) {
    return res.status(403).json({ error: 'Access denied' });
  }

  res.download(filePath);
});
```

---

## 15. Insecure Cryptography

### ❌ VULNERABLE
```javascript
const crypto = require('crypto');
// MD5 is broken!
const hash = crypto.createHash('md5').update(password).digest('hex');
```

### ✅ SECURE
```javascript
const bcrypt = require('bcrypt');
// Use bcrypt for passwords
const hash = await bcrypt.hash(password, 10);

// For general hashing, use SHA-256
const crypto = require('crypto');
const hash = crypto.createHash('sha256').update(data).digest('hex');

// For encryption, use AES
const cipher = crypto.createCipher('aes-256-cbc', key);
```

