// Improved application with security best practices
// Enhanced error handling, input validation, and security headers

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const app = express();

// ==================== Configuration ====================
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// ==================== Security Middleware ====================

// Set security HTTP headers
app.use(helmet());

// Request logging
app.use(morgan('combined'));

// Rate limiting to prevent brute force and DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
});

// Apply rate limiting to all routes
app.use(limiter);

// Parse JSON with size limits to prevent large payload attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// ==================== Input Validation Helpers ====================

/**
 * Validate query parameters
 */
const validateQueryParams = (req, allowedParams) => {
  const errors = [];
  for (const key of Object.keys(req.query)) {
    if (!allowedParams.includes(key)) {
      errors.push(`Invalid query parameter: ${key}`);
    }
  }
  return errors;
};

/**
 * Sanitize user data for safe output
 */
const sanitizeUser = (user) => {
  return {
    id: user.id,
    name: user.name,
    // Don't expose email unless authenticated
  };
};

// ==================== Routes ====================

/**
 * Health check endpoint
 * GET /health
 */
app.get('/health', (req, res, next) => {
  try {
    // Validate query parameters
    const errors = validateQueryParams(req, ['format']);
    if (errors.length > 0) {
      return res.status(400).json({ 
        error: 'Invalid request parameters',
        details: errors 
      });
    }

    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      environment: NODE_ENV 
    });
  } catch (error) {
    next(error);
  }
});

/**
 * Get users endpoint
 * GET /users
 * Query params: ?limit=10&offset=0
 */
app.get('/users', (req, res, next) => {
  try {
    // Validate query parameters
    const errors = validateQueryParams(req, ['limit', 'offset']);
    if (errors.length > 0) {
      return res.status(400).json({ 
        error: 'Invalid request parameters',
        details: errors 
      });
    }

    // Validate and sanitize limit parameter
    let limit = 10; // Default
    if (req.query.limit) {
      limit = parseInt(req.query.limit, 10);
      if (isNaN(limit) || limit < 1 || limit > 100) {
        return res.status(400).json({ 
          error: 'Invalid limit parameter. Must be a number between 1 and 100.' 
        });
      }
    }

    // Validate and sanitize offset parameter
    let offset = 0; // Default
    if (req.query.offset) {
      offset = parseInt(req.query.offset, 10);
      if (isNaN(offset) || offset < 0) {
        return res.status(400).json({ 
          error: 'Invalid offset parameter. Must be a non-negative number.' 
        });
      }
    }

    // Mock user data
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination
    const paginatedUsers = allUsers
      .slice(offset, offset + limit)
      .map(sanitizeUser);

    res.json({ 
      data: paginatedUsers,
      pagination: {
        limit,
        offset,
        total: allUsers.length
      }
    });
  } catch (error) {
    next(error);
  }
});

// ==================== 404 Handler ====================
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not Found',
    path: req.path,
    method: req.method 
  });
});

// ==================== Global Error Handler ====================
app.use((err, req, res, next) => {
  // Log error (in production, use a proper logging service)
  console.error({
    timestamp: new Date().toISOString(),
    error: err.message,
    stack: NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method,
  });

  // Determine status code
  const status = err.status || err.statusCode || 500;

  // Don't expose internal error details in production
  const message = NODE_ENV === 'production' 
    ? 'Internal Server Error' 
    : err.message;

  res.status(status).json({ 
    error: message,
    ...(NODE_ENV === 'development' && { stack: err.stack })
  });
});

// ==================== Unhandled Rejection Handler ====================
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // In production, you should log this and potentially restart the process
});

// ==================== Server Startup ====================
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${NODE_ENV} mode`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
  });
});

module.exports = app;

