### 2. Comprehensive Input Validator
```javascript
class InputValidator {
  static validateString(value, min = 1, max = 255, fieldName = 'Field') {
    if (typeof value !== 'string') {
      throw new Error(`${fieldName} must be a string`);
    }

    if (value.trim().length < min) {
      throw new Error(`${fieldName} must be at least ${min} characters`);
    }

    if (value.length > max) {
      throw new Error(`${fieldName} must not exceed ${max} characters`);
    }

    return value.trim();
  }

  static validateInteger(value, min, max, fieldName = 'Field') {
    const num = parseInt(value, 10);

    if (isNaN(num)) {
      throw new Error(`${fieldName} must be a valid integer`);
    }

    if (num < min) {
      throw new Error(`${fieldName} must be at least ${min}`);
    }

    if (num > max) {
      throw new Error(`${fieldName} must not exceed ${max}`);
    }

    return num;
  }

  static validateEnum(value, allowedValues, fieldName = 'Field') {
    if (!allowedValues.includes(value)) {
      throw new Error(
        `${fieldName} must be one of: ${allowedValues.join(', ')}`
      );
    }

    return value;
  }
}

// Usage
try {
  const name = InputValidator.validateString(req.body.name, 1, 100, 'Name');
  const page = InputValidator.validateInteger(req.query.page, 1, 10000, 'Page');
  const role = InputValidator.validateEnum(req.body.role, ['user', 'admin'], 'Role');
} catch (error) {
  return res.status(400).json({ error: error.message });
}
