// Production-ready application with security best practices
// Error handling, input validation, and security hardening

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');

const app = express();

// ============================================================
// SECURITY MIDDLEWARE
// ============================================================

// 1. Security Headers - Helmet.js protects against common vulnerabilities
app.use(helmet());

// 2. CORS Configuration - Control cross-origin requests
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  optionsSuccessStatus: 200,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
};
app.use(cors(corsOptions));

// 3. Request Body Parsing with Size Limits
app.use(express.json({ limit: '10kb' })); // Prevent payload DoS attacks
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 4. Rate Limiting - Prevent brute force and DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
  skip: (req) => process.env.NODE_ENV === 'test',
});

app.use(limiter);

// ============================================================
// REQUEST VALIDATION & SANITIZATION MIDDLEWARE
// ============================================================

// Validate and sanitize query parameters
const validateQueryParams = (req, res, next) => {
  try {
    const allowedParams = new Set(['limit', 'offset', 'sort']);

    for (const param in req.query) {
      if (!allowedParams.has(param)) {
        return res.status(400).json({
          error: 'Invalid query parameter',
          message: `Parameter '${param}' is not allowed`,
          code: 'INVALID_PARAM',
        });
      }
    }

    // Validate limit parameter
    if (req.query.limit) {
      const limit = parseInt(req.query.limit, 10);
      if (isNaN(limit) || limit < 1 || limit > 100) {
        return res.status(400).json({
          error: 'Invalid limit parameter',
          message: 'Limit must be a number between 1 and 100',
          code: 'INVALID_LIMIT',
        });
      }
    }

    // Validate offset parameter
    if (req.query.offset) {
      const offset = parseInt(req.query.offset, 10);
      if (isNaN(offset) || offset < 0) {
        return res.status(400).json({
          error: 'Invalid offset parameter',
          message: 'Offset must be a non-negative number',
          code: 'INVALID_OFFSET',
        });
      }
    }

    next();
  } catch (error) {
    logger.error('Query validation error', { error, query: req.query });
    res.status(400).json({
      error: 'Invalid request',
      code: 'VALIDATION_ERROR',
    });
  }
};

// ============================================================
// LOGGING (Simple implementation - consider using Winston/Bunyan)
// ============================================================

const logger = {
  info: (message, data) => console.log(`[INFO] ${message}`, data || ''),
  error: (message, data) => console.error(`[ERROR] ${message}`, data || ''),
  warn: (message, data) => console.warn(`[WARN] ${message}`, data || ''),
};

// Request logging middleware
app.use((req, res, next) => {
  const startTime = Date.now();

  res.on('finish', () => {
    const duration = Date.now() - startTime;
    logger.info('Request completed', {
      method: req.method,
      path: req.path,
      status: res.statusCode,
      duration: `${duration}ms`,
      ip: req.ip,
    });
  });

  next();
});

// ============================================================
// ROUTES
// ============================================================

// Health check endpoint (no sensitive data exposed)
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    });
  } catch (error) {
    logger.error('Health check error', error);
    res.status(500).json({
      error: 'Internal server error',
      code: 'HEALTH_CHECK_FAILED',
    });
  }
});

// Get users endpoint with input validation
app.get('/users', validateQueryParams, (req, res, next) => {
  try {
    const limit = Math.min(parseInt(req.query.limit, 10) || 10, 100);
    const offset = parseInt(req.query.offset, 10) || 0;

    // Mock data - in production, this would come from a database
    const allUsers = [
      { id: 1, name: 'Alice' }, // Email removed - don't expose sensitive data
      { id: 2, name: 'Bob' },
    ];

    // Pagination
    const paginatedUsers = allUsers.slice(offset, offset + limit);

    res.json({
      data: paginatedUsers,
      pagination: {
        limit,
        offset,
        total: allUsers.length,
      },
    });
  } catch (error) {
    logger.error('Users endpoint error', error);
    next(error); // Pass to error handler
  }
});

// ============================================================
// ERROR HANDLING MIDDLEWARE
// ============================================================

// 404 Handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Route ${req.method} ${req.path} not found`,
    code: 'NOT_FOUND',
  });
});

// Global Error Handler (must be defined last)
app.use((error, req, res, next) => {
  const status = error.status || error.statusCode || 500;
  const isDevelopment = process.env.NODE_ENV === 'development';

  logger.error('Unhandled error', {
    message: error.message,
    status,
    path: req.path,
    method: req.method,
    stack: isDevelopment ? error.stack : undefined,
  });

  res.status(status).json({
    error: 'Internal server error',
    message: isDevelopment ? error.message : 'An unexpected error occurred',
    code: error.code || 'INTERNAL_ERROR',
    requestId: req.id, // Could use UUID library in production
  });
});

// ============================================================
// SERVER STARTUP
// ============================================================

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '127.0.0.1';

const server = app.listen(PORT, HOST, () => {
  logger.info(`Server running on http://${HOST}:${PORT}`);
  logger.info(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.warn('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    logger.info('HTTP server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  logger.warn('SIGINT signal received: closing HTTP server');
  server.close(() => {
    logger.info('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

# Security Review & Improvement Recommendations for app.js

## Executive Summary

The current `app.js` is a basic skeleton that lacks critical security features, input validation, error handling, and production-readiness. Below are detailed recommendations organized by priority.

---

## 🔴 CRITICAL ISSUES (Must Fix)

### 1. No Error Handling
**Problem:** No error middleware or try-catch blocks. Unhandled exceptions crash the server.

**Solution:**
```javascript
// Add global error handler
app.use((error, req, res, next) => {
  logger.error('Unhandled error', error);
  res.status(500).json({ error: 'Internal server error' });
});

// Wrap route handlers in try-catch
app.get('/users', (req, res) => {
  try {
    // Route logic
  } catch (error) {
    logger.error('Route error', error);
    next(error);
  }
});
```

### 2. No Input Validation
**Problem:** Query parameters, body data, and route parameters are never validated. Enables injection attacks.

**Solution:**
```javascript
// Validate query parameters
const validateQueryParams = (req, res, next) => {
  const allowedParams = new Set(['limit', 'offset']);

  for (const param in req.query) {
    if (!allowedParams.has(param)) {
      return res.status(400).json({ error: 'Invalid parameter' });
    }
  }
  next();
};
```

### 3. Missing Security Headers
**Problem:** No protection against common attacks (XSS, Clickjacking, etc.)

**Solution:**
```javascript
const helmet = require('helmet');
app.use(helmet());
```

### 4. No Request Size Limits
**Problem:** Attackers can send huge payloads causing DoS/memory exhaustion

**Solution:**
```javascript
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));
```

### 5. Sensitive Data Exposure
**Problem:** Email addresses exposed in `/users` endpoint without authentication

**Solution:**
- Implement authentication (JWT, OAuth2)
- Remove sensitive fields from responses
- Add authorization checks
- Implement role-based access control (RBAC)

---

## 🟠 HIGH PRIORITY ISSUES

### 6. No Rate Limiting
**Problem:** Vulnerable to brute force and DoS attacks

**Solution:**
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
});

app.use(limiter);
```

### 7. No CORS Configuration
**Problem:** Either allows all origins (security risk) or causes legitimate requests to fail

**Solution:**
```javascript
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(','),
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
};
app.use(cors(corsOptions));
```

### 8. No Logging
**Problem:** Cannot track errors, security events, or debugging information

**Solution:**
```javascript
const logger = {
  info: (msg, data) => console.log(`[INFO] ${msg}`, data),
  error: (msg, data) => console.error(`[ERROR] ${msg}`, data),
  warn: (msg, data) => console.warn(`[WARN] ${msg}`, data),
};

app.use((req, res, next) => {
  logger.info(`${req.method} ${req.path}`);
  next();
});
```

### 9. No Graceful Shutdown
**Problem:** Server abruptly terminates, potentially losing requests

**Solution:**
```javascript
const server = app.listen(PORT);

process.on('SIGTERM', () => {
  server.close(() => process.exit(0));
});
```

### 10. Hardcoded Configuration
**Problem:** Port, host, and other config hardcoded. Not environment-aware.

**Solution:**
```javascript
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '127.0.0.1';
const NODE_ENV = process.env.NODE_ENV || 'development';
```

---

## 🟡 MEDIUM PRIORITY ISSUES

### 11. No 404 Handler
**Problem:** No response for undefined routes

**Solution:**
```javascript
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    code: 'NOT_FOUND',
  });
});
```

### 12. No Request ID for Tracing
**Problem:** Cannot correlate logs from a single request

**Solution:**
```javascript
const { v4: uuidv4 } = require('uuid');

app.use((req, res, next) => {
  req.id = uuidv4();
  res.setHeader('X-Request-ID', req.id);
  next();
});
```

### 13. No Content-Type Validation
**Problem:** Could accept invalid content types

**Solution:**
```javascript
app.post('/data', express.json(), (req, res) => {
  // Body will be validated by express.json()
});
```

### 14. Console Logging Only
**Problem:** Not suitable for production. Hard to parse, no log levels

**Solution:** Use Winston, Bunyan, or Pino
```javascript
const winston = require('winston');
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});
```

### 15. No API Documentation
**Problem:** Unclear what endpoints do, what parameters they accept

**Solution:** Add OpenAPI/Swagger documentation
```javascript
const swaggerUi = require('swagger-ui-express');
const swaggerDocument = require('./swagger.json');

app.use('/api-docs', swaggerUi.serve, swaggerUi.setup(swaggerDocument));
```

---

## 🟢 LOW PRIORITY ISSUES (Nice to Have)

### 16. No Compression
**Problem:** Responses not compressed, wasting bandwidth

**Solution:**
```javascript
const compression = require('compression');
app.use(compression());
```

### 17. No Request Timeout
**Problem:** Hanging requests consume resources

**Solution:**
```javascript
app.use((req, res, next) => {
  req.setTimeout(30000); // 30 seconds
  next();
});
```

### 18. No Monitoring/Metrics
**Problem:** Cannot observe system health

**Solution:** Use Prometheus, New Relic, or DataDog
```javascript
const promClient = require('prom-client');
const httpRequestDurationMicroseconds = new promClient.Histogram({
  name: 'http_request_duration_ms',
  help: 'Duration of HTTP requests in ms',
});
```

### 19. No API Versioning
**Problem:** Hard to maintain backward compatibility

**Solution:**
```javascript
app.get('/api/v1/users', (req, res) => { /* ... */ });
app.get('/api/v2/users', (req, res) => { /* ... */ });
```

### 20. No Input Sanitization
**Problem:** Even validated input might contain malicious content

**Solution:** Use xss or sanitize-html
```javascript
const xss = require('xss');
const sanitized = xss(userInput);
```

