## Common Vulnerabilities Addressed

### 1. Injection Attacks
```javascript
// VULNERABLE
const query = `SELECT * FROM users WHERE email = '${email}'`;
db.query(query); // SQL Injection!

// SECURE
db.query('SELECT * FROM users WHERE email = ?', [email]);
```

### 2. Broken Authentication
```javascript
// VULNERABLE
app.get('/admin', (req, res) => {
  // No auth check!
});

// SECURE
app.get('/admin', authenticateJWT, authorizeRole('admin'), (req, res) => {
  // Auth and authorization checked
});
```

### 3. Sensitive Data Exposure
```javascript
// VULNERABLE
app.get('/users', (req, res) => {
  res.json(users); // Includes passwords, emails, etc.
});

// SECURE
app.get('/users', (req, res) => {
  const sanitized = users.map(u => ({ id: u.id, name: u.name }));
  res.json(sanitized);
});
```

### 4. XML External Entity (XXE)
```javascript
// VULNERABLE
app.post('/upload', (req, res) => {
  const xml = req.body; // Parsed without protection
});

// SECURE - disable XXE in XML parsers
const parser = require('xml2js').Parser();
parser.parseString(xml, { xmlMode: false }, ...);
```

### 5. Cross-Site Scripting (XSS)
```javascript
// VULNERABLE
app.get('/search', (req, res) => {
  const query = req.query.q;
  res.send(`<h1>Results for: ${query}</h1>`); // XSS!
});

// SECURE
const xss = require('xss');
const sanitized = xss(req.query.q);
res.send(`<h1>Results for: ${sanitized}</h1>`);
```

### 6. Broken Access Control
```javascript
// VULNERABLE
app.get('/users/:id', (req, res) => {
  res.json(User.findById(req.params.id)); // Any user can access any data
});

// SECURE
app.get('/users/:id', authenticateJWT, (req, res) => {
  if (req.user.id !== req.params.id && !req.user.isAdmin) {
    return res.status(403).json({ error: 'Forbidden' });
  }
  res.json(User.findById(req.params.id));
});
```

### 7. Security Misconfiguration
```javascript
// VULNERABLE
console.log('DB Password:', process.env.DB_PASSWORD); // In logs!
throw error; // Exposes stack trace to client

// SECURE
logger.debug('DB connection attempt', { host: dbHost });
res.status(500).json({ error: 'Internal server error' });
```

### 8. Insecure Deserialization
```javascript
// VULNERABLE
