  dangerousOperation();
} catch(e) {
  // Silent failure
}

// SECURE - comprehensive logging
try {
  dangerousOperation();
} catch(e) {
  logger.error('Critical operation failed', {
    error: e.message,
    stack: e.stack,
    timestamp: new Date(),
    userId: req.user.id,
  });
  // Alert should be triggered
  alerting.sendAlert('Critical error in dangerousOperation');
}
```

