// Improved application with security best practices and error handling

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');
const winston = require('winston');

const app = express();

// ==================== LOGGER SETUP ====================
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
    new winston.transports.Console({
      format: winston.format.simple(),
    }),
  ],
});

// ==================== MIDDLEWARE ====================

// Security headers
app.use(helmet());

// Body parser with size limits
app.use(express.json({ limit: '10mb' }));
app.use(express.urlencoded({ limit: '10mb', extended: true }));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
  handler: (req, res) => {
    logger.warn(`Rate limit exceeded for IP: ${req.ip}`);
    res.status(429).json({
      success: false,
      message: 'Too many requests, please try again later.',
      error: 'RATE_LIMIT_EXCEEDED',
    });
  },
});

app.use(limiter);

// Request logging middleware
app.use((req, res, next) => {
  logger.info(`${req.method} ${req.path} - IP: ${req.ip}`);
  next();
});

// ==================== ROUTES ====================

/**
 * Health check endpoint
 */
app.get('/health', (req, res) => {
  try {
    res.json({
      success: true,
      status: 'ok',
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    logger.error('Error in /health endpoint:', error);
    res.status(500).json({
      success: false,
      message: 'Internal server error',
      error: 'HEALTH_CHECK_FAILED',
    });
  }
});

/**
 * Get users endpoint
 * Supports optional limit query parameter
 */
app.get(
  '/users',
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be an integer between 1 and 100'),
  (req, res) => {
    try {
      // Check for validation errors
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        logger.warn(`Validation failed for /users: ${JSON.stringify(errors.array())}`);
        return res.status(400).json({
          success: false,
          message: 'Validation failed',
          errors: errors.array().map((err) => ({
            field: err.param,
            message: err.msg,
          })),
        });
      }

      const allUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      const limit = parseInt(req.query.limit, 10) || allUsers.length;
      const users = allUsers.slice(0, limit);

      res.json({
        success: true,
        data: users,
        count: users.length,
      });
    } catch (error) {
      logger.error('Error in /users endpoint:', error);
      res.status(500).json({
        success: false,
        message: 'Internal server error',
        error: 'FETCH_USERS_FAILED',
      });
    }
  }
);

// ==================== 404 HANDLER ====================
app.use((req, res) => {
  logger.warn(`404 Not Found: ${req.method} ${req.path}`);
  res.status(404).json({
    success: false,
    message: 'Endpoint not found',
    error: 'NOT_FOUND',
  });
});

// ==================== GLOBAL ERROR HANDLER ====================
app.use((error, req, res, next) => {
  logger.error('Unhandled error:', {
    message: error.message,
    stack: error.stack,
    path: req.path,
    method: req.method,
    ip: req.ip,
  });

  // Don't leak stack traces to clients in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(error.status || 500).json({
    success: false,
    message: error.message || 'Internal server error',
    error: error.code || 'INTERNAL_SERVER_ERROR',
    ...(isDevelopment && { stack: error.stack }),
  });
});

// ==================== SERVER STARTUP ====================
const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT}`);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  logger.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // Gracefully shutdown or restart the server
  server.close(() => {
    process.exit(1);
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  logger.error('Uncaught Exception:', error);
  // Gracefully shutdown or restart the server
  server.close(() => {
    process.exit(1);
  });
});

module.exports = app;

# Security Review: app.js - Detailed Improvements Report

## Executive Summary
The current app.js has minimal security protections and lacks proper error handling. This report outlines critical improvements needed for production-readiness.

---

## CRITICAL ISSUES

### 1. ❌ NO GLOBAL ERROR HANDLER
**Risk Level:** CRITICAL

**Current Code:**
```javascript
app.listen(3000, () => {
  console.log('Server running on port 3000');
});
```

**Problem:** 
- Unhandled errors crash the server
- No error logging
- Stack traces might leak sensitive info

**Solution:**
```javascript
// Global error handler (must be last middleware)
app.use((error, req, res, next) => {
  logger.error('Unhandled error:', error);
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(error.status || 500).json({
    success: false,
    message: 'Internal server error',
    ...(isDevelopment && { stack: error.stack }),
  });
});

// Handle process-level errors
process.on('unhandledRejection', (reason, promise) => {
  logger.error('Unhandled Rejection:', reason);
  server.close(() => process.exit(1));
});

process.on('uncaughtException', (error) => {
  logger.error('Uncaught Exception:', error);
  server.close(() => process.exit(1));
});
```

---

### 2. ❌ NO INPUT VALIDATION
**Risk Level:** CRITICAL

**Current Code:**
```javascript
app.get('/users', (req, res) => {
  res.json([...]);
});
```

**Problems:**
- Query parameters not validated
- Vulnerable to injection attacks
- No type checking

**Solution:**
```javascript
const { query, validationResult } = require('express-validator');

app.get(
  '/users',
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be an integer between 1 and 100'),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        success: false,
        errors: errors.array(),
      });
    }
    // Process request...
  }
);
```

---

### 3. ❌ MISSING SECURITY HEADERS
**Risk Level:** HIGH

**Current Code:** No security middleware

**Problems:**
- Vulnerable to XSS, Clickjacking, MIME-type sniffing
- Missing HSTS, CSP headers
- No CORS protection

**Solution:**
```javascript
const helmet = require('helmet');
app.use(helmet()); // Adds ~15 security headers
```

**Alternatively (manual):**
```javascript
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
  res.setHeader('Content-Security-Policy', "default-src 'self'");
  next();
});
```

---

### 4. ❌ NO RATE LIMITING
**Risk Level:** HIGH

**Current Code:** No rate limiting

**Problems:**
- Vulnerable to DoS attacks
- No protection against brute force
- Resource exhaustion attacks possible

**Solution:**
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests
  message: 'Too many requests, try again later.',
});

app.use(limiter);

// Or specific endpoints:
app.get('/users', limiter, (req, res) => { ... });
```

---

### 5. ❌ NO REQUEST SIZE LIMITS
**Risk Level:** MEDIUM

**Current Code:**
```javascript
app.use(express.json()); // No limit!
```

**Problems:**
- Vulnerable to buffer overflow attacks
- Memory exhaustion possible
- Large payload processing DoS

**Solution:**
```javascript
app.use(express.json({ limit: '10mb' }));
app.use(express.urlencoded({ limit: '10mb', extended: true }));
```

---

### 6. ❌ EXPOSED ERROR DETAILS
**Risk Level:** MEDIUM

**Current Code:**
```javascript
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});
```

**Problems:**
- No error handling - unhandled errors leak stack traces
- No distinction between development and production

**Solution:**
```javascript
const isDevelopment = process.env.NODE_ENV === 'development';

res.status(error.status || 500).json({
  success: false,
  message: 'Internal server error',
  error: 'INTERNAL_SERVER_ERROR',
  ...(isDevelopment && { stack: error.stack }), // Only in dev
});
```

---

### 7. ❌ NO LOGGING
**Risk Level:** MEDIUM

**Current Code:**
```javascript
app.listen(3000, () => {
  console.log('Server running on port 3000');
});
```

**Problems:**
- No audit trail
- Difficult debugging
- Security incident investigation impossible

**Solution:**
```javascript
const winston = require('winston');

const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
    new winston.transports.Console(),
  ],
});

// Log all requests
app.use((req, res, next) => {
  logger.info(`${req.method} ${req.path} - IP: ${req.ip}`);
  next();
});

// Log errors
logger.error('Error occurred:', error);
```

---

### 8. ❌ NO 404 HANDLER
**Risk Level:** LOW

**Current Code:** No catch-all for undefined routes

**Problems:**
- Express default 404 response might leak information
- No logging of 404 attempts

**Solution:**
```javascript
app.use((req, res) => {
  logger.warn(`404 Not Found: ${req.method} ${req.path}`);
  res.status(404).json({
    success: false,
    message: 'Endpoint not found',
    error: 'NOT_FOUND',
  });
});
```

