// Improved application with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const validator = require('express-validator');
const morgan = require('morgan');

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// Set security HTTP headers
app.use(helmet());

// Rate limiting to prevent DoS/brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

// Apply the rate limiting middleware to all requests
app.use(limiter);

// Logging middleware (morgan)
app.use(morgan('combined'));

// Parse JSON bodies with size limit to prevent large payload attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// ============================================
// INPUT VALIDATION MIDDLEWARE
// ============================================

// Validate and sanitize query parameters
const validateUserQuery = [
  validator.query('id')
    .optional()
    .isInt({ min: 1 })
    .withMessage('ID must be a positive integer'),
  validator.query('email')
    .optional()
    .isEmail()
    .normalizeEmail()
    .withMessage('Invalid email format'),
  validator.query('search')
    .optional()
    .trim()
    .isLength({ min: 1, max: 50 })
    .withMessage('Search must be between 1 and 50 characters')
    .matches(/^[a-zA-Z0-9\s@.-]*$/)
    .withMessage('Search contains invalid characters'),
];

// ============================================
// ROUTES
// ============================================

app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString() 
    });
  } catch (error) {
    res.status(500).json({ 
      error: 'Internal server error' 
    });
  }
});

app.get('/users', validateUserQuery, (req, res) => {
  try {
    // Handle validation errors
    const errors = validator.validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        error: 'Validation failed',
        details: errors.array() 
      });
    }

    // Mock user data (in production, fetch from secure database)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Filter by ID if provided
    if (req.query.id) {
      const id = parseInt(req.query.id, 10);
      const user = users.find(u => u.id === id);

      if (!user) {
        return res.status(404).json({ error: 'User not found' });
      }

      return res.json(user);
    }

    // Filter by email if provided
    if (req.query.email) {
      const user = users.find(u => u.email === req.query.email);

      if (!user) {
        return res.status(404).json({ error: 'User not found' });
      }

      return res.json(user);
    }

    // Filter by search term if provided
    if (req.query.search) {
      const searchLower = req.query.search.toLowerCase();
      const filtered = users.filter(u => 
        u.name.toLowerCase().includes(searchLower) ||
        u.email.toLowerCase().includes(searchLower)
      );

      return res.json(filtered);
    }

    // Return all users
    res.json(users);

  } catch (error) {
    console.error('Error in /users route:', error);
    res.status(500).json({ 
      error: 'Internal server error' 
    });
  }
});

// ============================================
// ERROR HANDLING
// ============================================

// 404 handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Endpoint not found',
    path: req.path 
  });
});

// Global error handler (must be last)
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Don't leak error details in production
  const isDevelopment = process.env.NODE_ENV === 'development';
  const errorResponse = {
    error: 'Internal server error'
  };

  if (isDevelopment) {
    errorResponse.details = err.message;
    errorResponse.stack = err.stack;
  }

  res.status(err.status || 500).json(errorResponse);
});

// ============================================
// SERVER STARTUP
// ============================================

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';

const server = app.listen(PORT, HOST, () => {
  console.log(`Server running on http://${HOST}:${PORT}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

