/**
 * List of required environment variables
 * The application will fail to start if any of these are missing
 */
const REQUIRED_ENV_VARS = [];

/**
 * List of optional environment variables with defaults
 */
const OPTIONAL_ENV_VARS = {
  PORT: { default: 3000, type: 'number' },
  NODE_ENV: { default: 'development', type: 'string' },
  LOG_LEVEL: { default: 'info', type: 'string' },
  RATE_LIMIT_ENABLED: { default: 'true', type: 'boolean' },
  DEBUG: { default: 'false', type: 'boolean' }
};

/**
 * Validates required environment variables
 * @throws {Error} If any required variables are missing
 */
function validateRequired() {
  const missing = REQUIRED_ENV_VARS.filter(
    varName => !process.env[varName]
  );

  if (missing.length > 0) {
    const message = `Missing required environment variables: ${missing.join(', ')}`;
    console.error(`\n❌ ${message}\n`);
    throw new Error(message);
  }
}

/**
 * Parse type-safe environment variable
 * @param {string} varName - Environment variable name
 * @param {string} type - Expected type ('string', 'number', 'boolean')
 * @param {*} defaultValue - Default value if not set
 * @returns {*} Parsed value
 */
function parseEnvVar(varName, type, defaultValue) {
  const value = process.env[varName];

  if (!value) {
    return defaultValue;
  }

  switch (type) {
    case 'number':
      const num = parseInt(value, 10);
      if (isNaN(num)) {
        throw new Error(
          `Invalid value for ${varName}: "${value}" is not a valid number`
        );
      }
      return num;

    case 'boolean':
      if (!['true', 'false', '1', '0', 'yes', 'no'].includes(value.toLowerCase())) {
        throw new Error(
          `Invalid value for ${varName}: "${value}" is not a valid boolean`
        );
      }
      return ['true', '1', 'yes'].includes(value.toLowerCase());

    case 'string':
    default:
      return value;
  }
}

/**
 * Initialize and validate configuration
 */
function initConfig() {
  // Validate required variables
  validateRequired();

  // Parse and validate optional variables
  const config = {};
  for (const [varName, { type, default: defaultValue }] of Object.entries(OPTIONAL_ENV_VARS)) {
    config[varName.toLowerCase()] = parseEnvVar(varName, type, defaultValue);
  }

  return config;
}

// Initialize configuration
let config;
try {
  config = initConfig();
} catch (error) {
  console.error('Failed to initialize configuration:', error.message);
  process.exit(1);
}

/**
 * Export configuration object
 */
module.exports = {
  // Server
  port: config.port,
  nodeEnv: config.nodeenv,
  isDevelopment: config.nodeenv === 'development',
  isProduction: config.nodeenv === 'production',
  isTest: config.nodeenv === 'test',

  // Logging
  logLevel: config.log_level,
  debug: config.debug,

  // Features
  rateLimitEnabled: config.rate_limit_enabled,

