```javascript
app.get('/users', (req, res) => {
  // Validate and sanitize query parameters
  const limit = parseInt(req.query.limit, 10) || 10;
  const offset = parseInt(req.query.offset, 10) || 0;

  // Add bounds checking
  if (limit < 1 || limit > 100) {
    return res.status(400).json({ error: 'Invalid limit parameter' });
  }
  if (offset < 0) {
    return res.status(400).json({ error: 'Invalid offset parameter' });
  }

  res.json([...]);
});
```

#### 2. **Missing Error Handling**
**Risk**: Unhandled errors could expose stack traces or cause server crashes.

**Recommendation**:
```javascript
// Add centralized error handling middleware
app.use((err, req, res, next) => {
  console.error('Error:', err);
  res.status(500).json({
    error: 'Internal Server Error',
    // Don't expose stack trace in production
    ...(process.env.NODE_ENV === 'development' && { message: err.message })
  });
});
```

#### 3. **Missing Security Headers**
**Risk**: No HSTS, X-Frame-Options, or other security headers.

**Recommendation**:
```javascript
const helmet = require('helmet');
app.use(helmet());
```

#### 4. **No CORS Configuration**
**Risk**: Either too permissive or default restrictive CORS could cause issues.

**Recommendation**:
```javascript
const cors = require('cors');
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || 'http://localhost:3000',
  credentials: true,
  methods: ['GET', 'POST'],
  allowedHeaders: ['Content-Type']
}));
```

#### 5. **Missing Rate Limiting**
**Risk**: No protection against brute force or DoS attacks.

**Recommendation**:
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP'
});

app.use(limiter);
```

#### 6. **No Request Size Limits**
**Risk**: Could allow memory exhaustion attacks.

**Recommendation**:
```javascript
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));
```

#### 7. **Missing 404 Handler**
**Risk**: Unhandled routes return confusing responses.

**Recommendation**:
```javascript
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});
```

#### 8. **Insufficient Logging**
**Risk**: Can't track security events or debug issues.

**Recommendation**:
```javascript
const morgan = require('morgan');
app.use(morgan('combined'));
```

#### 9. **No Input Sanitization**
**Risk**: Potential for XSS if data is returned and displayed.

**Recommendation**: Sanitize all user inputs and use parameterized queries if database queries are involved.

#### 10. **Hardcoded Port Number**
**Risk**: Not configurable for different environments.

**Recommendation**:
```javascript
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
```

---

### Improved Version:

```javascript
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');

const app = express();

// Security middleware
app.use(helmet());
app.use(morgan('combined'));

// CORS configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET'],
  allowedHeaders: ['Content-Type']
}));

// Request size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  } catch (err) {
    res.status(500).json({ error: 'Health check failed' });
  }
});

// Users endpoint with validation
app.get('/users', (req, res) => {
  try {
    const limit = Math.min(parseInt(req.query.limit, 10) || 10, 100);
    const offset = Math.max(parseInt(req.query.offset, 10) || 0, 0);

    if (isNaN(limit) || isNaN(offset) || limit < 1) {
      return res.status(400).json({ 
        error: 'Invalid pagination parameters' 
      });
    }

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    res.json(users.slice(offset, offset + limit));
  } catch (err) {
    console.error('Error fetching users:', err);
    res.status(500).json({ error: 'Failed to fetch users' });
  }
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

// Central error handler
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);
  res.status(err.status || 500).json({
    error: process.env.NODE_ENV === 'production' 
      ? 'Internal Server Error' 
      : err.message
  });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

