// Improved application with security best practices
// Error handling, input validation, and security middleware

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');
const morgan = require('morgan');

const app = express();
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// ============================================================================
// 1. SECURITY MIDDLEWARE
// ============================================================================

// Add security headers
app.use(helmet());

// CORS configuration (restrict to trusted origins in production)
app.use((req, res, next) => {
  const allowedOrigins = (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(',');
  const origin = req.headers.origin;

  if (allowedOrigins.includes(origin) || NODE_ENV === 'development') {
    res.header('Access-Control-Allow-Origin', origin);
    res.header('Access-Control-Allow-Methods', 'GET, OPTIONS');
    res.header('Access-Control-Allow-Headers', 'Content-Type');
  }

  if (req.method === 'OPTIONS') {
    return res.sendStatus(200);
  }
  next();
});

// Request size limiting
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// Rate limiting - adjust limits based on your needs
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
});

const strictLimiter = rateLimit({
  windowMs: 60 * 1000, // 1 minute
  max: 10, // stricter limit for sensitive endpoints
  skipSuccessfulRequests: true,
});

app.use(limiter);

// Request logging
app.use(morgan(NODE_ENV === 'production' ? 'combined' : 'dev'));

// ============================================================================
// 2. INPUT VALIDATION MIDDLEWARE
// ============================================================================

/**
 * Validation result handler
 * Checks for validation errors and sends appropriate response
 */
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      success: false,
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.param,
        message: err.msg
      }))
    });
  }
  next();
};

// ============================================================================
// 3. MOCK DATA (in production, use a database)
// ============================================================================

const USERS_DB = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
];

// ============================================================================
// 4. ROUTES
// ============================================================================

/**
 * GET /health
 * Health check endpoint
 */
app.get('/health', (req, res) => {
  try {
    res.json({
      success: true,
      status: 'ok',
      timestamp: new Date().toISOString(),
      environment: NODE_ENV
    });
  } catch (error) {
    res.status(500).json({
      success: false,
      error: 'Health check failed',
      ...(NODE_ENV === 'development' && { details: error.message })
    });
  }
});

/**
 * GET /users
 * Retrieve all users with optional filtering
 * Query Parameters:
 *   - limit: maximum number of results (1-100, default: 10)
 *   - offset: pagination offset (default: 0)
 */
app.get('/users',
  [
    // Validate query parameters
    body('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
    body('offset').optional().isInt({ min: 0 }).toInt(),
  ],
  handleValidationErrors,
  (req, res) => {
    try {
      const limit = Math.min(req.query.limit || 10, 100);
      const offset = req.query.offset || 0;

      // Validate pagination parameters
      if (offset < 0 || limit < 1) {
        return res.status(400).json({
          success: false,
          error: 'Invalid pagination parameters'
        });
      }

      // Apply pagination
      const paginatedUsers = USERS_DB.slice(offset, offset + limit);

      res.json({
        success: true,
        data: paginatedUsers,
        pagination: {
          limit,
          offset,
          total: USERS_DB.length,
          hasMore: offset + limit < USERS_DB.length
        }
      });
    } catch (error) {
      console.error('Error fetching users:', error);
      res.status(500).json({
        success: false,
        error: 'Failed to fetch users',
        ...(NODE_ENV === 'development' && { details: error.message })
      });
    }
  }
);

/**
 * GET /users/:id
 * Retrieve a specific user by ID
 */
app.get('/users/:id',
  [
    body('id').isInt({ min: 1 }).toInt(),
  ],
  handleValidationErrors,
  (req, res) => {
    try {
      const userId = parseInt(req.params.id, 10);

      // Validate ID format
      if (isNaN(userId) || userId < 1) {
        return res.status(400).json({
          success: false,
          error: 'Invalid user ID'
        });
      }

      const user = USERS_DB.find(u => u.id === userId);

      if (!user) {
        return res.status(404).json({
          success: false,
          error: 'User not found'
        });
      }

      res.json({
        success: true,
        data: user
      });
    } catch (error) {
      console.error('Error fetching user:', error);
      res.status(500).json({
        success: false,
        error: 'Failed to fetch user',
        ...(NODE_ENV === 'development' && { details: error.message })
      });
    }
  }
);

// ============================================================================
// 5. ERROR HANDLING MIDDLEWARE
// ============================================================================

/**
 * 404 Not Found handler
 */
app.use((req, res) => {
  res.status(404).json({
    success: false,
    error: 'Endpoint not found',
    path: req.path,
    method: req.method
  });
});

/**
 * Global error handler
 * Must be last middleware
 */
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Default error response
  const statusCode = err.statusCode || 500;
  const response = {
    success: false,
    error: err.message || 'Internal server error'
  };

  // Include stack trace only in development
  if (NODE_ENV === 'development') {
    response.stack = err.stack;
  }

  res.status(statusCode).json(response);
});

// ============================================================================
// 6. SERVER STARTUP
// ============================================================================

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${NODE_ENV}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

# Security Review: app.js

## Executive Summary
The original app.js has critical security gaps in error handling, input validation, and security headers. This document outlines the issues found and recommendations for improvement.

---

## Critical Issues Found

### 1. ❌ No Input Validation
**Severity: HIGH**

**Problem:**
- Query parameters are not validated
- No limits on parameter values
- No type checking
- Vulnerable to injection attacks and malformed data

**Example Vulnerability:**
```javascript
// Original endpoint - no validation
app.get('/users', (req, res) => {
  res.json([...]); // accepts any query params
});
```

**Solution:**
```javascript
app.get('/users',
  [
    body('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
    body('offset').optional().isInt({ min: 0 }).toInt(),
  ],
  handleValidationErrors,
  (req, res) => { /* ... */ }
);
```

---

### 2. ❌ No Error Handling
**Severity: HIGH**

**Problem:**
- No try-catch blocks
- No global error handler
- Unhandled errors will crash the application
- No error logging
- Stack traces could leak sensitive information

**Example Vulnerability:**
```javascript
// Original - any error crashes the app
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});
```

**Solution:**
```javascript
app.get('/health', (req, res) => {
  try {
    res.json({
      success: true,
      status: 'ok',
      timestamp: new Date().toISOString()
    });
  } catch (error) {
    console.error('Health check failed:', error);
    res.status(500).json({
      success: false,
      error: 'Health check failed'
    });
  }
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Error:', err);
  res.status(500).json({ 
    success: false, 
    error: 'Internal server error' 
  });
});
```

---

### 3. ❌ Missing Security Headers
**Severity: HIGH**

**Problem:**
- No helmet.js for security headers
- Vulnerable to:
  - XSS attacks
  - Clickjacking
  - MIME sniffing
  - Content Security Policy bypass

**Solution:**
```javascript
const helmet = require('helmet');
app.use(helmet());
```

---

### 4. ❌ No Rate Limiting
**Severity: MEDIUM**

**Problem:**
- Vulnerable to Denial of Service (DoS) attacks
- No protection against brute force attacks
- No request throttling

**Solution:**
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests
});

app.use(limiter);
```

---

### 5. ❌ No CORS Configuration
**Severity: MEDIUM**

**Problem:**
- Allows requests from any origin
- Vulnerable to Cross-Origin attacks
- No control over allowed methods and headers

**Solution:**
```javascript
app.use((req, res, next) => {
  const allowedOrigins = (process.env.ALLOWED_ORIGINS || 
    'http://localhost:3000').split(',');
  const origin = req.headers.origin;

  if (allowedOrigins.includes(origin)) {
    res.header('Access-Control-Allow-Origin', origin);
    res.header('Access-Control-Allow-Methods', 'GET, OPTIONS');
    res.header('Access-Control-Allow-Headers', 'Content-Type');
  }

  if (req.method === 'OPTIONS') return res.sendStatus(200);
  next();
});
```

---

### 6. ❌ No Request Size Limits
**Severity: MEDIUM**

**Problem:**
- Accepts unlimited payload sizes
- Vulnerable to memory exhaustion attacks
- Can crash the server

**Solution:**
```javascript
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));
```

---

### 7. ❌ Hardcoded Configuration
**Severity: MEDIUM**

**Problem:**
- Port is hardcoded (3000)
- No environment-based configuration
- Sensitive data could be hardcoded in production

**Solution:**
```javascript
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
```

---

### 8. ❌ Information Disclosure
**Severity: MEDIUM**

**Problem:**
- Stack traces exposed in error responses
- Could leak sensitive implementation details
- Helps attackers understand the system

**Solution:**
```javascript
const response = {
  success: false,
  error: 'Internal server error'
};

// Only include stack in development
if (NODE_ENV === 'development') {
  response.stack = err.stack;
}
```

---

### 9. ❌ No Request Logging
**Severity: LOW**

**Problem:**
- No audit trail
- Cannot track requests or debug issues
- Security incidents cannot be traced

**Solution:**
```javascript
const morgan = require('morgan');
app.use(morgan(NODE_ENV === 'production' ? 'combined' : 'dev'));
```

---

### 10. ❌ No Graceful Shutdown
**Severity: LOW**

**Problem:**
- Server doesn't handle shutdown signals
- Could lose in-flight requests
- May not release resources properly

**Solution:**
```javascript
process.on('SIGTERM', () => {
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});
```

---

## Security Best Practices Implemented

### ✅ Input Validation
- Validate all user inputs
- Use whitelisting over blacklisting
- Validate data types, lengths, and formats
- Use libraries like `express-validator`

### ✅ Error Handling
- Try-catch blocks for all operations
- Global error handler middleware
- Proper HTTP status codes
- Environment-aware error messages

### ✅ Security Headers
- Use helmet.js for standard headers
- Content-Security-Policy
- X-Frame-Options
- X-Content-Type-Options

### ✅ Rate Limiting
- Prevent DoS attacks
- Implement per-IP limits
- Different limits for sensitive endpoints

### ✅ CORS
- Restrict to trusted origins
- Validate origin headers
- Limit allowed methods and headers

### ✅ Request Limits
- Limit payload sizes
- Prevent memory exhaustion
- Configure appropriate limits

### ✅ Logging & Monitoring
- Log all requests (morgan)
- Log errors with context
- Include timestamps
- Track suspicious patterns

---

## Dependencies to Add

