const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const validator = require('validator');
const app = express();

// ==================== SECURITY MIDDLEWARE ====================

// Set security HTTP headers
app.use(helmet());

// Body parser with size limits to prevent DoS attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Data sanitization against NoSQL injection
app.use(mongoSanitize());

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply rate limiting to all routes
app.use(limiter);

// ==================== CUSTOM ERROR HANDLING ====================

// Request logging middleware
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.path} - IP: ${req.ip}`);
  next();
});

// ==================== ROUTES ====================

/**
 * Health check endpoint - no sensitive data
 */
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

/**
 * Get users with optional filtering
 * Validation: page and limit query parameters
 */
app.get('/users', (req, res) => {
  try {
    // Input validation
    let page = parseInt(req.query.page, 10) || 1;
    let limit = parseInt(req.query.limit, 10) || 10;
    const sortBy = req.query.sortBy || 'id';

    // Validate pagination parameters
    if (!Number.isInteger(page) || page < 1) {
      return res.status(400).json({ 
        error: 'Invalid page parameter. Must be a positive integer.' 
      });
    }

    if (!Number.isInteger(limit) || limit < 1 || limit > 100) {
      return res.status(400).json({ 
        error: 'Invalid limit parameter. Must be between 1 and 100.' 
      });
    }

    // Validate sort parameter (whitelist approach)
    const allowedSortFields = ['id', 'name'];
    if (!allowedSortFields.includes(sortBy)) {
      return res.status(400).json({ 
        error: `Invalid sortBy parameter. Allowed values: ${allowedSortFields.join(', ')}` 
      });
    }

    // Mock database data
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Pagination logic
    const startIndex = (page - 1) * limit;
    const endIndex = page * limit;
    const users = allUsers.slice(startIndex, endIndex);

    res.json({
      data: users,
      pagination: {
        page,
        limit,
        total: allUsers.length,
        pages: Math.ceil(allUsers.length / limit)
      }
    });
  } catch (error) {
    console.error('Get users error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

/**
 * Get user by ID
 * Validation: id parameter must be numeric
 */
app.get('/users/:id', (req, res) => {
  try {
    const userId = req.params.id;

    // Validate ID format (must be numeric)
    if (!validator.isNumeric(userId)) {
      return res.status(400).json({ 
        error: 'Invalid user ID. Must be a numeric value.' 
      });
    }

    const id = parseInt(userId, 10);

    // Mock database lookup
    const users = [
      { id: 1, name: 'Alice' },
      { id: 2, name: 'Bob' },
    ];

    const user = users.find(u => u.id === id);

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    res.json({ data: user });
  } catch (error) {
