const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const validator = require('validator');

// Load environment variables from .env file
require('dotenv').config();

const app = express();

// ==================== ENVIRONMENT VALIDATION ====================

function validateEnvironment() {
  const requiredVars = [];
  const optionalVars = [
    'NODE_ENV',
    'PORT',
    'HOST',
    'ALLOWED_ORIGINS',
    'RATE_LIMIT_WINDOW_MS',
    'RATE_LIMIT_MAX_REQUESTS'
  ];

  const missing = requiredVars.filter(v => !process.env[v]);
  if (missing.length > 0) {
    throw new Error(`Missing required environment variables: ${missing.join(', ')}`);
  }

  console.log('✓ Environment variables validated');
  console.log(`  NODE_ENV: ${process.env.NODE_ENV || 'development'}`);
  console.log(`  PORT: ${process.env.PORT || 3000}`);
  console.log(`  HOST: ${process.env.HOST || 'localhost'}`);
}

// Validate environment on startup
try {
  validateEnvironment();
} catch (error) {
  console.error('❌ Environment validation failed:', error.message);
  process.exit(1);
}

// ==================== CONFIGURATION ====================

const NODE_ENV = process.env.NODE_ENV || 'development';
const PORT = parseInt(process.env.PORT || 3000, 10);
const HOST = process.env.HOST || 'localhost';
const RATE_LIMIT_WINDOW_MS = parseInt(process.env.RATE_LIMIT_WINDOW_MS || 900000, 10);
const RATE_LIMIT_MAX_REQUESTS = parseInt(process.env.RATE_LIMIT_MAX_REQUESTS || 100, 10);
const ALLOWED_ORIGINS = (process.env.ALLOWED_ORIGINS || 'http://localhost:3000')
  .split(',')
  .map(origin => origin.trim());

// Validate configuration values
if (!Number.isInteger(PORT) || PORT < 1 || PORT > 65535) {
  throw new Error('PORT must be a valid integer between 1 and 65535');
}

if (!Number.isInteger(RATE_LIMIT_MAX_REQUESTS) || RATE_LIMIT_MAX_REQUESTS < 1) {
  throw new Error('RATE_LIMIT_MAX_REQUESTS must be a positive integer');
}

// ==================== SECURITY MIDDLEWARE ====================

// Set security HTTP headers
app.use(helmet());

// Body parser with size limits to prevent DoS attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Data sanitization against NoSQL injection
app.use(mongoSanitize());

// Rate limiting configuration
const limiter = rateLimit({
  windowMs: RATE_LIMIT_WINDOW_MS,
  max: RATE_LIMIT_MAX_REQUESTS,
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  skip: (req) => {
    // Don't rate limit health checks in development
    return NODE_ENV === 'development' && req.path === '/health';
  }
});

// Apply rate limiting to all routes
app.use(limiter);

// ==================== CUSTOM MIDDLEWARE ====================

// Request logging middleware
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.path} - IP: ${req.ip}`);
  next();
});

// ==================== ROUTES ====================

/**
 * Health check endpoint - no sensitive data
 */
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      environment: NODE_ENV
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

/**
 * Get users with optional filtering
 * Validation: page and limit query parameters
 */
app.get('/users', (req, res) => {
  try {
    // Input validation
    let page = parseInt(req.query.page, 10) || 1;
    let limit = parseInt(req.query.limit, 10) || 10;
    const sortBy = req.query.sortBy || 'id';

    // Validate pagination parameters
    if (!Number.isInteger(page) || page < 1) {
      return res.status(400).json({
        error: 'Invalid page parameter. Must be a positive integer.'
      });
    }

    if (!Number.isInteger(limit) || limit < 1 || limit > 100) {
      return res.status(400).json({
        error: 'Invalid limit parameter. Must be between 1 and 100.'
      });
    }

    // Validate sort parameter (whitelist approach)
    const allowedSortFields = ['id', 'name'];
    if (!allowedSortFields.includes(sortBy)) {
      return res.status(400).json({
        error: `Invalid sortBy parameter. Allowed values: ${allowedSortFields.join(', ')}`
      });
    }

    // Mock database data
    const allUsers = [
      { id: 1, name: 'Alice' },
      { id: 2, name: 'Bob' },
    ];

    // Pagination logic
    const startIndex = (page - 1) * limit;
    const endIndex = page * limit;
    const users = allUsers.slice(startIndex, endIndex);

    res.json({
      data: users,
      pagination: {
        page,
        limit,
        total: allUsers.length,
        pages: Math.ceil(allUsers.length / limit)
      }
    });
  } catch (error) {
    console.error('Get users error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

/**
 * Get user by ID
 * Validation: id parameter must be numeric
 */
app.get('/users/:id', (req, res) => {
  try {
    const userId = req.params.id;

    // Validate ID format (must be numeric)
    if (!validator.isNumeric(userId)) {
      return res.status(400).json({
        error: 'Invalid user ID. Must be a numeric value.'
      });
    }

    const id = parseInt(userId, 10);

    // Mock database lookup
    const users = [
      { id: 1, name: 'Alice' },
      { id: 2, name: 'Bob' },
    ];

    const user = users.find(u => u.id === id);

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    res.json({ data: user });
  } catch (error) {
    console.error('Get user by ID error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

/**
 * Create user with validation
 */
app.post('/users', (req, res) => {
  try {
    const { name, email } = req.body;

    // Input validation
    const errors = [];

    // Validate name
    if (!name || typeof name !== 'string') {
      errors.push('Name is required and must be a string');
    } else if (name.length < 2 || name.length > 100) {
      errors.push('Name must be between 2 and 100 characters');
    } else if (!validator.matches(name, /^[a-zA-Z\s'-]+$/)) {
      errors.push('Name contains invalid characters');
    }

    // Validate email
    if (!email || typeof email !== 'string') {
      errors.push('Email is required and must be a string');
    } else if (!validator.isEmail(email)) {
      errors.push('Invalid email format');
    }

    // Return validation errors
    if (errors.length > 0) {
      return res.status(400).json({
        error: 'Validation failed',
        details: errors
      });
    }

    // Sanitize inputs
    const sanitizedName = validator.escape(name.trim());
    const sanitizedEmail = validator.normalizeEmail(email);

    // Mock database create
    const newUser = {
      id: 3, // In real app, would be generated
      name: sanitizedName,
      email: sanitizedEmail,
      createdAt: new Date().toISOString()
    };

    res.status(201).json({
      data: newUser,
      message: 'User created successfully'
    });
  } catch (error) {
    console.error('Create user error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

/**
 * Configuration endpoint (only in development)
 */
if (NODE_ENV === 'development') {
  app.get('/config', (req, res) => {
    res.json({
      environment: NODE_ENV,
      port: PORT,
      host: HOST,
      allowedOrigins: ALLOWED_ORIGINS,
      rateLimiting: {
        windowMs: RATE_LIMIT_WINDOW_MS,
        maxRequests: RATE_LIMIT_MAX_REQUESTS
      }
    });
  });
}

// ==================== GLOBAL ERROR HANDLING ====================

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    path: req.path,
    method: req.method
  });
});

// Global error handler (must be last)
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Don't expose error details in production
  const isDevelopment = NODE_ENV === 'development';
  const errorResponse = {
    error: 'Internal server error',
    ...(isDevelopment && { details: err.message, stack: err.stack })
  };

  res.status(err.status || 500).json(errorResponse);
});

// ==================== SERVER STARTUP ====================

const server = app.listen(PORT, HOST, () => {
  console.log(`\n🚀 Server started`);
  console.log(`   URL: http://${HOST}:${PORT}`);
  console.log(`   Environment: ${NODE_ENV}`);
  console.log(`   Rate Limit: ${RATE_LIMIT_MAX_REQUESTS} requests per ${RATE_LIMIT_WINDOW_MS / 60000} minutes\n`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('\nSIGINT received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

