// Improved Express application with security best practices
// Includes error handling, input validation, and security headers

require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const { query, validationResult } = require('express-validator');

const app = express();

// ============================================
// SECURITY & MIDDLEWARE CONFIGURATION
// ============================================

// Set security HTTP headers
app.use(helmet());

// Enable CORS with configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  optionsSuccessStatus: 200,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

// Request logging
const morganFormat = process.env.NODE_ENV === 'production' ? 'combined' : 'dev';
app.use(morgan(morganFormat));

// Body parser with size limits (prevent large payload attacks)
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Rate limiting (prevent brute force and DDoS)
const limiter = rateLimit({
  windowMs: process.env.RATE_LIMIT_WINDOW || 15 * 60 * 1000, // 15 minutes
  max: process.env.RATE_LIMIT_MAX || 100, // 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
  skip: (req) => process.env.NODE_ENV === 'test' // Skip rate limiting in test environment
});

app.use(limiter);

// ============================================
// ROUTES
// ============================================

/**
 * Health check endpoint
 * GET /health
 */
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      environment: process.env.NODE_ENV || 'development'
    });
  } catch (error) {
    res.status(500).json({ error: 'Health check failed' });
  }
});

/**
 * Get users endpoint with optional filtering
 * GET /users?limit=10&offset=0
 * 
 * Query Parameters:
 * - limit: number of users to return (default: 10, max: 100)
 * - offset: pagination offset (default: 0)
 */
app.get('/users',
  // Input validation middleware
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be an integer between 1 and 100'),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Offset must be a non-negative integer'),
  (req, res, next) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        error: 'Invalid input',
        details: errors.array().map(err => ({
          field: err.param,
          message: err.msg
        }))
      });
    }
    next();
  },
  (req, res) => {
    try {
      const limit = parseInt(req.query.limit) || 10;
      const offset = parseInt(req.query.offset) || 0;

      // Mock user data
      const allUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Apply pagination
      const users = allUsers.slice(offset, offset + limit);

      res.json({
        data: users,
        pagination: {
          total: allUsers.length,
          limit,
          offset,
          hasMore: offset + limit < allUsers.length
        }
      });
    } catch (error) {
      next(error); // Pass to error handler
    }
  }
);

/**
 * Get a specific user by ID
 * GET /users/:id
 */
app.get('/users/:id',
  // Validate user ID parameter
  (req, res, next) => {
    const id = req.params.id;
    if (!Number.isInteger(Number(id)) || Number(id) <= 0) {
      return res.status(400).json({
        error: 'Invalid user ID',
        details: 'User ID must be a positive integer'
      });
    }
    next();
  },
  (req, res) => {
    try {
      const userId = parseInt(req.params.id);

      // Mock user data
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      const user = users.find(u => u.id === userId);

      if (!user) {
        return res.status(404).json({
          error: 'User not found'
        });
      }

      res.json({ data: user });
    } catch (error) {
      next(error); // Pass to error handler
    }
  }
);

/**
 * 404 handler
 */
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    path: req.path,
    method: req.method
  });
});

// ============================================
// ERROR HANDLING MIDDLEWARE
// ============================================

/**
 * Centralized error handler
 * Must be defined after all other middleware and routes
 */
app.use((err, req, res, next) => {
  // Log error (in production, use a proper logging service)
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    url: req.originalUrl,
    method: req.method,
    timestamp: new Date().toISOString()
  });

  // Determine status code
  const statusCode = err.statusCode || err.status || 500;

  // Send error response (don't expose internal details in production)
  res.status(statusCode).json({
    error: {
      message: process.env.NODE_ENV === 'production'
        ? 'Internal Server Error'
        : err.message,
      status: statusCode,
      ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
    }
  });
});

// ============================================
// SERVER START
// ============================================

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

const server = app.listen(PORT, () => {
  console.log(`✓ Server running on port ${PORT} in ${NODE_ENV} mode`);
  console.log(`✓ CORS enabled for: ${process.env.ALLOWED_ORIGINS || 'http://localhost:3000'}`);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  process.exit(1);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

# Testing Guide for Secure app.js

## Overview
This guide provides examples for testing the security improvements and input validation in the improved app.js.

---

## 1. Manual Testing with cURL

### Health Endpoint
```bash
# Basic health check
curl http://localhost:3000/health

# Check response headers
curl -i http://localhost:3000/health
```

### Users Endpoint - Valid Requests
```bash
# Get all users with default pagination
curl http://localhost:3000/users

# Get users with custom limit
curl "http://localhost:3000/users?limit=5"

# Get users with pagination
curl "http://localhost:3000/users?limit=10&offset=0"

# Get specific user
curl http://localhost:3000/users/1
```

### Input Validation Tests
```bash
# Invalid limit (too high)
curl "http://localhost:3000/users?limit=200"
# Expected: 400 Bad Request - "Limit must be an integer between 1 and 100"

# Invalid limit (negative)
curl "http://localhost:3000/users?limit=-5"
# Expected: 400 Bad Request

# Invalid offset (negative)
curl "http://localhost:3000/users?offset=-1"
# Expected: 400 Bad Request

# Invalid user ID (non-integer)
curl http://localhost:3000/users/abc
# Expected: 400 Bad Request - "User ID must be a positive integer"

# Invalid user ID (zero)
curl http://localhost:3000/users/0
# Expected: 400 Bad Request

# Non-existent user
curl http://localhost:3000/users/999
# Expected: 404 Not Found
```

### Security Headers Validation
```bash
# Check Helmet security headers
curl -i http://localhost:3000/health

# Should include:
# - X-Content-Type-Options: nosniff
# - X-Frame-Options: DENY
# - X-XSS-Protection: 0
# - Strict-Transport-Security (in HTTPS mode)
```

### Rate Limiting Test
```bash
# Run 101 requests quickly (should be rate limited)
for i in {1..101}; do
  curl http://localhost:3000/health
done

# After 100 requests, should receive:
# 429 Too Many Requests
```

### CORS Testing
```bash
# Test CORS headers
curl -i -H "Origin: http://localhost:3001" \
  -H "Access-Control-Request-Method: GET" \
  http://localhost:3000/users

# Check for Access-Control headers in response
```

---

## 2. Automated Testing with Jest & Supertest

### Test File Example: app.test.js

```javascript
const request = require('supertest');
const app = require('./app_improved');

describe('Express Security Tests', () => {

  // ============================================
  // SECURITY HEADERS TESTS
  // ============================================

  describe('Security Headers', () => {
    it('should set X-Content-Type-Options header', async () => {
      const response = await request(app).get('/health');
      expect(response.headers['x-content-type-options']).toBe('nosniff');
    });

    it('should set X-Frame-Options header', async () => {
      const response = await request(app).get('/health');
      expect(response.headers['x-frame-options']).toBe('DENY');
    });

    it('should set X-XSS-Protection header', async () => {
      const response = await request(app).get('/health');
      expect(response.headers['x-xss-protection']).toBeDefined();
    });
  });

  // ============================================
  // INPUT VALIDATION TESTS
  // ============================================

  describe('Input Validation - /users', () => {
    it('should accept valid limit parameter', async () => {
      const response = await request(app)
        .get('/users')
        .query({ limit: 10 })
        .expect(200);

      expect(response.body.pagination.limit).toBe(10);
    });

    it('should reject limit > 100', async () => {
      const response = await request(app)
        .get('/users')
        .query({ limit: 200 })
        .expect(400);

      expect(response.body.error).toBe('Invalid input');
      expect(response.body.details[0].message).toContain('between 1 and 100');
    });

    it('should reject negative limit', async () => {
      const response = await request(app)
        .get('/users')
        .query({ limit: -5 })
        .expect(400);

      expect(response.body.error).toBe('Invalid input');
    });

    it('should reject non-integer limit', async () => {
      const response = await request(app)
        .get('/users')
        .query({ limit: 'abc' })
        .expect(400);

      expect(response.body.error).toBe('Invalid input');
    });

    it('should reject negative offset', async () => {
      const response = await request(app)
        .get('/users')
        .query({ offset: -1 })
        .expect(400);

      expect(response.body.error).toBe('Invalid input');
    });

    it('should accept valid offset parameter', async () => {
      const response = await request(app)
        .get('/users')
        .query({ offset: 0 })
        .expect(200);

      expect(response.body.pagination.offset).toBe(0);
    });
  });

  describe('Input Validation - /users/:id', () => {
    it('should reject non-integer user ID', async () => {
      const response = await request(app)
        .get('/users/abc')
        .expect(400);

      expect(response.body.error).toBe('Invalid user ID');
    });

    it('should reject zero user ID', async () => {
      const response = await request(app)
        .get('/users/0')
        .expect(400);

      expect(response.body.error).toBe('Invalid user ID');
    });

    it('should reject negative user ID', async () => {
      const response = await request(app)
        .get('/users/-1')
        .expect(400);

      expect(response.body.error).toBe('Invalid user ID');
    });

    it('should return 404 for non-existent user', async () => {
      const response = await request(app)
        .get('/users/999')
        .expect(404);

      expect(response.body.error).toBe('User not found');
    });

    it('should return user data for valid ID', async () => {
      const response = await request(app)
        .get('/users/1')
        .expect(200);

      expect(response.body.data).toHaveProperty('id', 1);
      expect(response.body.data).toHaveProperty('name');
      expect(response.body.data).toHaveProperty('email');
    });
  });

  // ============================================
  // ENDPOINT TESTS
  // ============================================

  describe('Health Endpoint', () => {
    it('should return 200 OK', async () => {
      const response = await request(app)
        .get('/health')
        .expect(200);

      expect(response.body.status).toBe('ok');
    });

    it('should include timestamp', async () => {
      const response = await request(app).get('/health');
      expect(response.body.timestamp).toBeDefined();
      expect(new Date(response.body.timestamp)).toBeInstanceOf(Date);
    });

    it('should include uptime', async () => {
      const response = await request(app).get('/health');
      expect(typeof response.body.uptime).toBe('number');
      expect(response.body.uptime).toBeGreaterThan(0);
    });

    it('should include environment', async () => {
      const response = await request(app).get('/health');
      expect(response.body.environment).toBeDefined();
    });
  });

  describe('Users Endpoint', () => {
    it('should return user array', async () => {
      const response = await request(app)
        .get('/users')
        .expect(200);

      expect(Array.isArray(response.body.data)).toBe(true);
    });

    it('should include pagination info', async () => {
      const response = await request(app).get('/users');
      expect(response.body.pagination).toHaveProperty('total');
      expect(response.body.pagination).toHaveProperty('limit');
      expect(response.body.pagination).toHaveProperty('offset');
      expect(response.body.pagination).toHaveProperty('hasMore');
    });

    it('should respect limit parameter', async () => {
      const response = await request(app)
        .get('/users')
        .query({ limit: 1 });

      expect(response.body.data.length).toBeLessThanOrEqual(1);
    });
  });

  // ============================================
  // ERROR HANDLING TESTS
  // ============================================

  describe('Error Handling', () => {
    it('should return 404 for unknown routes', async () => {
      const response = await request(app)
        .get('/unknown')
        .expect(404);

      expect(response.body.error).toBe('Not Found');
    });

    it('should not expose internal error details in production', async () => {
      // This test assumes NODE_ENV is set to 'production'
      process.env.NODE_ENV = 'production';

      const response = await request(app)
        .get('/health')
        .expect(200);

      // Response should not contain stack traces
      expect(JSON.stringify(response.body)).not.toContain('at ');
    });
  });

  // ============================================
  // PAYLOAD SIZE TESTS
  // ============================================

  describe('Payload Size Limits', () => {
    it('should reject oversized JSON payloads', async () => {
      const largePayload = 'x'.repeat(11 * 1024); // 11KB (limit is 10KB)

      const response = await request(app)
        .post('/users') // Assuming POST endpoint exists
        .send({ data: largePayload })
        .expect(413); // Payload Too Large
    });
  });

  // ============================================
  // CORS TESTS
  // ============================================

  describe('CORS Configuration', () => {
    it('should include CORS headers for allowed origin', async () => {
      const response = await request(app)
        .get('/health')
        .set('Origin', 'http://localhost:3000');

      expect(response.headers['access-control-allow-origin']).toBeDefined();
    });

    it('should handle preflight requests', async () => {
      const response = await request(app)
        .options('/health')
        .set('Origin', 'http://localhost:3000')
        .set('Access-Control-Request-Method', 'GET');

      expect(response.status).toBeLessThan(300);
    });
  });

  // ============================================
  // RESPONSE FORMAT TESTS
  // ============================================

  describe('Response Format', () => {
    it('should return consistent JSON structure', async () => {
      const response = await request(app).get('/users');
      expect(response.headers['content-type']).toContain('application/json');
    });

    it('should include proper status codes', async () => {
      await request(app).get('/health').expect(200);
      await request(app).get('/unknown').expect(404);
      await request(app).get('/users?limit=999').expect(400);
    });
  });
});
```

### Run Tests
```bash
# Install dependencies
npm install

# Run all tests
npm test

# Run with coverage
npm test -- --coverage

# Watch mode (development)
npm test -- --watch
```

