// Improved application with security best practices
// Includes error handling, input validation, and security headers

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const validator = require('validator');
const app = express();

// ============ CONFIGURATION ============
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// ============ MIDDLEWARE ============

// Security headers
app.use(helmet());

// CORS - configure appropriately for your use case
app.use((req, res, next) => {
  res.header('Access-Control-Allow-Origin', process.env.CORS_ORIGIN || 'http://localhost:3000');
  res.header('Access-Control-Allow-Methods', 'GET, OPTIONS');
  res.header('Access-Control-Allow-Headers', 'Content-Type');
  next();
});

// Rate limiting - prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
});

app.use(limiter);

// Request parsing and sanitization
app.use(express.json({ limit: '10kb' })); // Prevent large payloads
app.use(express.urlencoded({ limit: '10kb', extended: true }));
app.use(mongoSanitize()); // Prevent NoSQL injection

// Request logging middleware
app.use((req, res, next) => {
  const timestamp = new Date().toISOString();
  console.log(`[${timestamp}] ${req.method} ${req.path} - IP: ${req.ip}`);
  next();
});

// ============ ROUTES ============

/**
 * Health check endpoint
 * No sensitive information returned
 */
app.get('/health', (req, res) => {
  try {
    res.status(200).json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    });
  } catch (error) {
    handleError(error, res, 'Health check failed');
  }
});

/**
 * Get users endpoint
 * Includes input validation and security considerations
 */
app.get('/users', (req, res, next) => {
  try {
    // Input validation
    const { limit, page } = req.query;

    // Validate limit parameter
    if (limit !== undefined) {
      if (!validator.isInt(limit, { min: 1, max: 100 })) {
        return res.status(400).json({
          error: 'Invalid limit parameter. Must be an integer between 1 and 100.',
          code: 'INVALID_INPUT',
        });
      }
    }

    // Validate page parameter
    if (page !== undefined) {
      if (!validator.isInt(page, { min: 1 })) {
        return res.status(400).json({
          error: 'Invalid page parameter. Must be a positive integer.',
          code: 'INVALID_INPUT',
        });
      }
    }

    // In production, fetch from database with pagination
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    res.status(200).json({
      success: true,
      data: users,
      count: users.length,
    });
  } catch (error) {
    next(error); // Pass to error handler
  }
});

// ============ 404 HANDLER ============
app.use((req, res) => {
  res.status(404).json({
    error: 'Resource not found',
    code: 'NOT_FOUND',
    path: req.path,
  });
});

// ============ ERROR HANDLING MIDDLEWARE ============
// Must be defined last and with 4 parameters (err, req, res, next)
app.use((err, req, res, next) => {
  handleError(err, res, 'Internal server error');
});

/**
 * Centralized error handling function
 * @param {Error} error - The error object
 * @param {Object} res - Express response object
 * @param {string} defaultMessage - Default error message
 */
function handleError(error, res, defaultMessage) {
  const timestamp = new Date().toISOString();
  const statusCode = error.statusCode || 500;
  const isDevelopment = NODE_ENV === 'development';

  // Log error details
  console.error(`[${timestamp}] Error:`, {
    message: error.message,
    statusCode,
    stack: isDevelopment ? error.stack : undefined,
  });

  // Don't expose error details in production
  const response = {
    error: defaultMessage,
    code: error.code || 'INTERNAL_ERROR',
    timestamp,
  };

  // Only include error details in development
  if (isDevelopment) {
    response.details = error.message;
    response.stack = error.stack;
  }

  res.status(statusCode).json(response);
}

// ============ SERVER STARTUP ============
const server = app.listen(PORT, () => {
  console.log(`[${new Date().toISOString()}] Server running on port ${PORT} (${NODE_ENV})`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received. Closing server gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  process.exit(1);
});

module.exports = app;

# Security Review & Recommendations for app.js

## Executive Summary
The original application lacks critical security controls for input validation, error handling, and protection against common vulnerabilities. This review provides specific improvements.

---

## Critical Issues Found

### 1. ❌ NO ERROR HANDLING
**Risk Level:** CRITICAL

**Issue:** No try-catch blocks or error middleware. Unhandled exceptions will crash the server or expose stack traces.

**Fix:**
```javascript
// Add global error handler
app.use((err, req, res, next) => {
  const isDevelopment = process.env.NODE_ENV === 'development';
  const statusCode = err.statusCode || 500;

  // Log error
  console.error(err);

  // Don't expose details in production
  res.status(statusCode).json({
    error: isDevelopment ? err.message : 'Internal Server Error',
    code: err.code || 'INTERNAL_ERROR'
  });
});
```

---

### 2. ❌ NO INPUT VALIDATION
**Risk Level:** HIGH

**Issue:** Query parameters are not validated. Attackers could send malicious input.

**Fix:**
```javascript
const validator = require('validator');

app.get('/users', (req, res) => {
  const { limit } = req.query;

  // Validate input
  if (limit && !validator.isInt(limit, { min: 1, max: 100 })) {
    return res.status(400).json({
      error: 'Invalid limit parameter',
      code: 'INVALID_INPUT'
    });
  }

  // Safe to proceed
});
```

---

### 3. ❌ MISSING SECURITY HEADERS
**Risk Level:** HIGH

**Issue:** No protection against XSS, clickjacking, or other header-based attacks.

**Fix:**
```javascript
const helmet = require('helmet');
app.use(helmet()); // Adds security headers automatically
```

**Headers Added:**
- `X-Frame-Options: DENY` - Prevents clickjacking
- `X-Content-Type-Options: nosniff` - Prevents MIME sniffing
- `Strict-Transport-Security` - Enforces HTTPS
- `Content-Security-Policy` - Prevents XSS

---

### 4. ❌ NO CORS CONFIGURATION
**Risk Level:** MEDIUM

**Issue:** Uncontrolled CORS allows any origin to access the API.

**Fix:**
```javascript
app.use((req, res, next) => {
  const allowedOrigins = process.env.CORS_ORIGIN || 'http://localhost:3000';
  res.header('Access-Control-Allow-Origin', allowedOrigins);
  res.header('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
  res.header('Access-Control-Allow-Headers', 'Content-Type, Authorization');
  next();
});

// Or use cors package:
const cors = require('cors');
app.use(cors({
  origin: process.env.CORS_ORIGIN || 'http://localhost:3000',
  credentials: true
}));
```

---

### 5. ❌ NO RATE LIMITING
**Risk Level:** HIGH

**Issue:** No protection against DoS/brute force attacks.

**Fix:**
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // 100 requests per IP
  message: 'Too many requests, please try again later'
});

app.use(limiter); // Apply globally, or to specific routes
```

---

### 6. ❌ NO REQUEST PARSING LIMITS
**Risk Level:** MEDIUM

**Issue:** No limit on request body size - vulnerable to payload-based attacks.

**Fix:**
```javascript
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));
```

---

### 7. ❌ NO REQUEST VALIDATION/SANITIZATION
**Risk Level:** MEDIUM

**Issue:** No protection against NoSQL injection or other injection attacks.

**Fix:**
```javascript
const mongoSanitize = require('express-mongo-sanitize');
app.use(mongoSanitize()); // Remove $ and . from keys
```

---

### 8. ❌ HARDCODED CONFIGURATION
**Risk Level:** MEDIUM

**Issue:** Port hardcoded, no environment configuration.

**Fix:**
```javascript
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
```

---

### 9. ❌ NO LOGGING
**Risk Level:** MEDIUM

**Issue:** No request logging makes debugging and security audits difficult.

**Fix:**
```javascript
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.path} - ${req.ip}`);
  next();
});
```

---

### 10. ❌ SENSITIVE DATA EXPOSURE
**Risk Level:** LOW (for this demo)

**Issue:** User emails are exposed without authentication or role-based access control.

**Fix:**
```javascript
// Add authentication middleware
const isAuthenticated = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];
  if (!token) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  // Verify token...
  next();
};

app.get('/users', isAuthenticated, (req, res) => {
  // Return user data only to authenticated users
});
```

---

## Recommended Dependencies

Add these to your `package.json`:

```json
{
  "dependencies": {
    "express": "^4.18.0",
    "helmet": "^7.0.0",
    "express-rate-limit": "^6.10.0",
    "express-mongo-sanitize": "^2.2.0",
    "validator": "^13.11.0",
    "cors": "^2.8.5"
  },
  "devDependencies": {
    "dotenv": "^16.3.1"
  }
}
```

---

## Environment Configuration

Create a `.env` file:

```env
NODE_ENV=development
PORT=3000
CORS_ORIGIN=http://localhost:3000
LOG_LEVEL=debug
```

---

## Testing Recommendations

### Test Cases:
1. **Invalid input:** `GET /users?limit=abc` → Should return 400
2. **Rate limiting:** Send 101 requests → Should return 429 on 101st
3. **Large payload:** POST with 15KB+ body → Should return 413
4. **NoSQL injection:** `GET /users?filter={"$ne":null}` → Should be sanitized
5. **CORS:** Request from unauthorized origin → Should be rejected

### Security Headers Check:
```bash
curl -I http://localhost:3000/health
```

Should include:
- `X-Frame-Options: DENY`
- `X-Content-Type-Options: nosniff`
- `Strict-Transport-Security`

---

## Additional Best Practices

1. **Use HTTPS in production** - Always use TLS/SSL
2. **Implement authentication** - Use JWT or sessions
3. **Add request ID tracking** - For debugging and auditing
4. **Implement proper logging** - Use a logging library like Winston
5. **Add API versioning** - `/api/v1/users`
6. **Implement health checks** - For load balancers
7. **Use environment variables** - Never hardcode secrets
8. **Implement graceful shutdown** - Handle signals properly
9. **Monitor and alert** - Set up error tracking (Sentry, etc.)
10. **Regular security audits** - Use tools like OWASP ZAP

---

## Summary of Changes

| Issue | Severity | Status |
|-------|----------|--------|
