// Improved application with security best practices
// Includes: error handling, input validation, security headers, rate limiting, logging

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const validator = require('validator');
const app = express();

// ============ CONFIGURATION ============
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// ============ MIDDLEWARE SETUP ============

// Security Headers
app.use(helmet());

// Body Parser with Size Limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// CORS Configuration
app.use((req, res, next) => {
  const allowedOrigins = process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'];
  const origin = req.headers.origin;

  if (allowedOrigins.includes(origin)) {
    res.header('Access-Control-Allow-Origin', origin);
  }
  res.header('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
  res.header('Access-Control-Allow-Headers', 'Content-Type, Authorization');

  if (req.method === 'OPTIONS') {
    return res.sendStatus(200);
  }
  next();
});

// Data Sanitization
app.use(mongoSanitize());

// Rate Limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // stricter limit for sensitive endpoints
  skipSuccessfulRequests: true,
});

app.use(limiter);

// Request Logging Middleware
app.use((req, res, next) => {
  const timestamp = new Date().toISOString();
  const method = req.method;
  const path = req.path;
  const ip = req.ip || req.connection.remoteAddress;

  console.log(`[${timestamp}] ${method} ${path} from ${ip}`);
  next();
});

// ============ ROUTES ============

/**
 * Health Check Endpoint
 * GET /health
 * Returns server status
 */
app.get('/health', (req, res, next) => {
  try {
    res.status(200).json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      environment: NODE_ENV,
    });
  } catch (error) {
    next(error);
  }
});

/**
 * Get Users Endpoint
 * GET /users
 * Query Parameters:
 *   - limit: number of results (1-100, default: 50)
 *   - offset: pagination offset (default: 0)
 */
app.get('/users', strictLimiter, (req, res, next) => {
  try {
    // Input Validation
    let limit = parseInt(req.query.limit) || 50;
    let offset = parseInt(req.query.offset) || 0;

    // Validate pagination parameters
    if (!Number.isInteger(limit) || limit < 1 || limit > 100) {
      return res.status(400).json({
        error: 'Invalid limit parameter. Must be an integer between 1 and 100.',
      });
    }

    if (!Number.isInteger(offset) || offset < 0) {
      return res.status(400).json({
        error: 'Invalid offset parameter. Must be a non-negative integer.',
      });
    }

    // Mock data - in production, this would query a database
    const allUsers = [
      { id: 1, name: 'Alice' }, // Removed email from response
      { id: 2, name: 'Bob' },
    ];

    // Apply pagination
    const paginatedUsers = allUsers.slice(offset, offset + limit);

    res.status(200).json({
      success: true,
      data: paginatedUsers,
      pagination: {
        total: allUsers.length,
        limit,
        offset,
        returned: paginatedUsers.length,
      },
    });
  } catch (error) {
    next(error);
  }
});

/**
 * Get User by ID Endpoint
 * GET /users/:id
 * Validates user ID parameter
 */
app.get('/users/:id', (req, res, next) => {
  try {
    const { id } = req.params;

    // Validate ID is a positive integer
    if (!validator.isInt(id, { min: 1 })) {
      return res.status(400).json({
        error: 'Invalid user ID. Must be a positive integer.',
      });
    }

    // Mock data
    const users = {
      1: { id: 1, name: 'Alice' },
      2: { id: 2, name: 'Bob' },
    };

    const user = users[id];
    if (!user) {
      return res.status(404).json({
        error: 'User not found.',
      });
    }

    res.status(200).json({
      success: true,
      data: user,
    });
  } catch (error) {
    next(error);
  }
});

// ============ ERROR HANDLING ============

// 404 Handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Route ${req.method} ${req.path} does not exist.`,
  });
});

// Global Error Handler
app.use((err, req, res, next) => {
  const timestamp = new Date().toISOString();
  const errorId = Math.random().toString(36).substring(7);

  // Log error details (but not sensitive data in production)
  console.error(`[${timestamp}] Error ID: ${errorId}`, {
    message: err.message,
    stack: NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method,
  });

  // Determine status code
  let statusCode = err.statusCode || 500;
  let message = err.message || 'Internal Server Error';

  // Handle specific error types
  if (err.name === 'SyntaxError' && 'body' in err) {
    statusCode = 400;
    message = 'Invalid JSON in request body';
  }

  // Don't expose internal error details to client in production
  const clientMessage = NODE_ENV === 'development' ? message : 'Internal Server Error';

  res.status(statusCode).json({
    error: {
      message: clientMessage,
      errorId: NODE_ENV === 'development' ? errorId : undefined,
      timestamp,
    },
  });
});

// ============ SERVER STARTUP ============

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} (${NODE_ENV})`);
  console.log(`Time: ${new Date().toISOString()}`);
});

// Graceful Shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received. Shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received. Shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

