// Enhanced application with security best practices
// Error handling, input validation, and security headers

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const validator = require('validator');

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// 1. Set security HTTP headers
app.use(helmet());

// 2. Body parser with size limits (prevent DoS)
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 3. Data sanitization against NoSQL injection
app.use(mongoSanitize());

// 4. Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// 5. Stricter rate limiting for auth endpoints (if added later)
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: 'Too many login attempts, please try again after 15 minutes',
  skipSuccessfulRequests: true,
});

// ============================================
// LOGGING & ERROR HANDLING MIDDLEWARE
// ============================================

// Request logging middleware
app.use((req, res, next) => {
  const timestamp = new Date().toISOString();
  console.log(`[${timestamp}] ${req.method} ${req.path} - IP: ${req.ip}`);
  next();
});

// ============================================
// ROUTES WITH VALIDATION & ERROR HANDLING
// ============================================

/**
 * Health check endpoint
 * GET /health
 */
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    });
  } catch (error) {
    logError('Health check failed', error);
    res.status(500).json({
      status: 'error',
      message: 'Health check failed',
    });
  }
});

/**
 * Get users endpoint with validation
 * GET /users?limit=10&skip=0
 */
app.get('/users', (req, res) => {
  try {
    // Input validation
    const limit = parseInt(req.query.limit) || 10;
    const skip = parseInt(req.query.skip) || 0;

    // Validate query parameters
    const validationErrors = [];

    if (!Number.isInteger(limit) || limit < 1 || limit > 100) {
      validationErrors.push('limit must be an integer between 1 and 100');
    }

    if (!Number.isInteger(skip) || skip < 0) {
      validationErrors.push('skip must be a non-negative integer');
    }

    // Return validation errors if any
    if (validationErrors.length > 0) {
      return res.status(400).json({
        status: 'error',
        message: 'Invalid input parameters',
        errors: validationErrors,
      });
    }

    // Mock user data
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination
    const users = allUsers.slice(skip, skip + limit);

    res.json({
      status: 'success',
      data: users,
      pagination: {
        total: allUsers.length,
        limit,
        skip,
        returned: users.length,
      },
    });
  } catch (error) {
    logError('Failed to retrieve users', error);
    res.status(500).json({
      status: 'error',
      message: 'Failed to retrieve users',
    });
  }
});

/**
 * Get user by ID with validation
 * GET /users/:id
 */
app.get('/users/:id', (req, res) => {
  try {
    const { id } = req.params;

    // Validate ID format (should be a positive integer)
    if (!validator.isNumeric(id) || parseInt(id) < 1) {
      return res.status(400).json({
        status: 'error',
        message: 'Invalid user ID format',
      });
    }

    // Mock data
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === parseInt(id));

    if (!user) {
      return res.status(404).json({
        status: 'error',
        message: 'User not found',
      });
    }

    res.json({
      status: 'success',
      data: user,
    });
  } catch (error) {
    logError('Failed to retrieve user by ID', error);
    res.status(500).json({
      status: 'error',
      message: 'Failed to retrieve user',
    });
  }
});

// ============================================
// ERROR HANDLING
// ============================================

// 404 Not Found handler
app.use((req, res) => {
  res.status(404).json({
    status: 'error',
    message: 'Endpoint not found',
    path: req.path,
  });
});

// Global error handling middleware
app.use((error, req, res, next) => {
  const statusCode = error.statusCode || 500;
  const message = process.env.NODE_ENV === 'production'
    ? 'Internal server error'
    : error.message;

  logError('Unhandled error', error);

  res.status(statusCode).json({
    status: 'error',
    message,
    ...(process.env.NODE_ENV !== 'production' && { stack: error.stack }),
  });
});

// ============================================
// UTILITY FUNCTIONS
// ============================================

/**
 * Log errors with timestamp
 */
function logError(context, error) {
  const timestamp = new Date().toISOString();
  console.error(`[${timestamp}] ERROR - ${context}:`, error.message);
  if (process.env.NODE_ENV !== 'production') {
    console.error(error.stack);
  }
}

// ============================================
// SERVER STARTUP
// ============================================

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${NODE_ENV} mode`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

