/**
 * Improved Express application with security best practices
 * Includes error handling, input validation, and security headers
 */

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const xss = require('xss-clean');
const validator = require('validator');
const morgan = require('morgan');
const app = express();

// ============================================================================
// MIDDLEWARE SETUP - Security & Logging
// ============================================================================

// Set security HTTP headers
app.use(helmet());

// CORS configuration - restrict to trusted origins
app.use((req, res, next) => {
  const allowedOrigins = process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'];
  const origin = req.headers.origin;

  if (allowedOrigins.includes(origin)) {
    res.header('Access-Control-Allow-Origin', origin);
  }
  res.header('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
  res.header('Access-Control-Allow-Headers', 'Content-Type, Authorization');

  if (req.method === 'OPTIONS') {
    return res.sendStatus(200);
  }
  next();
});

// Rate limiting - prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
});

app.use('/api/', limiter);

// Request size limiting - prevent payload bomb attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Data sanitization against NoSQL injection
app.use(mongoSanitize());

// Data sanitization against XSS
app.use(xss());

// HTTP request logger
app.use(morgan('combined'));

// ============================================================================
// VALIDATION UTILITIES
// ============================================================================

/**
 * Validate email format
 */
const isValidEmail = (email) => {
  return validator.isEmail(email);
};

/**
 * Validate numeric ID
 */
const isValidId = (id) => {
  return validator.isInt(String(id), { min: 1 });
};

/**
 * Validate string length
 */
const isValidString = (str, minLength = 1, maxLength = 255) => {
  if (typeof str !== 'string') return false;
  return str.length >= minLength && str.length <= maxLength;
};

/**
 * Validate query parameter
 */
const validateQueryParam = (value, type = 'string') => {
  if (type === 'int') {
    return validator.isInt(String(value), { min: 1 });
  }
  if (type === 'string') {
    return isValidString(value, 1, 100);
  }
  return false;
};

// ============================================================================
// ERROR HANDLING UTILITIES
// ============================================================================

/**
 * Custom error class for application errors
 */
class AppError extends Error {
  constructor(message, statusCode) {
    super(message);
    this.statusCode = statusCode;
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * Error response formatter
 */
const errorResponse = (error, req, res) => {
  const statusCode = error.statusCode || 500;
  const message = error.message || 'Internal Server Error';
  const isDevelopment = process.env.NODE_ENV === 'development';

  console.error({
    timestamp: new Date().toISOString(),
    method: req.method,
    url: req.url,
    statusCode,
    message,
    error: isDevelopment ? error : {},
  });

  res.status(statusCode).json({
    status: 'error',
    statusCode,
    message,
    ...(isDevelopment && { stack: error.stack }),
  });
};

// ============================================================================
// ROUTES
// ============================================================================

/**
 * Health check endpoint - no sensitive data
 */
app.get('/api/health', (req, res, next) => {
  try {
    res.status(200).json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    });
  } catch (error) {
    next(error);
  }
});

/**
 * Get users with optional filtering
 * Query params: limit (1-100), skip (>=0)
 */
app.get('/api/users', (req, res, next) => {
  try {
    // Input validation
    let limit = 10; // default
    let skip = 0; // default

    if (req.query.limit) {
      if (!validateQueryParam(req.query.limit, 'int')) {
        throw new AppError('Invalid limit parameter. Must be a positive integer.', 400);
      }
      limit = Math.min(parseInt(req.query.limit, 10), 100); // Cap at 100
    }

    if (req.query.skip) {
      if (!validateQueryParam(req.query.skip, 'int')) {
        throw new AppError('Invalid skip parameter. Must be a non-negative integer.', 400);
      }
      skip = parseInt(req.query.skip, 10);
    }

    // Mock database - in production, use actual database with parameterized queries
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
    ];

    const users = allUsers.slice(skip, skip + limit);

    res.status(200).json({
      status: 'success',
      data: {
        users,
        count: users.length,
        total: allUsers.length,
      },
    });
  } catch (error) {
    next(error);
  }
});

/**
 * Get user by ID
 */
app.get('/api/users/:id', (req, res, next) => {
  try {
    const { id } = req.params;

    // Input validation
    if (!isValidId(id)) {
      throw new AppError('Invalid user ID. Must be a positive integer.', 400);
    }

    // Mock database lookup
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
    ];

    const user = allUsers.find(u => u.id === parseInt(id, 10));

    if (!user) {
      throw new AppError('User not found', 404);
    }

    res.status(200).json({
      status: 'success',
      data: { user },
    });
  } catch (error) {
    next(error);
  }
});

/**
 * Create user (example POST endpoint)
 */
app.post('/api/users', (req, res, next) => {
  try {
    const { name, email } = req.body;

    // Input validation
    if (!name || !email) {
      throw new AppError('Name and email are required fields', 400);
    }

    if (!isValidString(name, 1, 100)) {
      throw new AppError('Name must be between 1 and 100 characters', 400);
    }

    if (!isValidEmail(email)) {
      throw new AppError('Invalid email format', 400);
    }

    // In production: check for duplicates in database
    // Hash sensitive data before storage
    // Use parameterized queries to prevent SQL injection

    const newUser = {
      id: Math.floor(Math.random() * 10000),
      name: name.trim(),
      email: email.toLowerCase().trim(),
      created_at: new Date().toISOString(),
    };

    res.status(201).json({
      status: 'success',
      data: { user: newUser },
      message: 'User created successfully',
    });
  } catch (error) {
    next(error);
  }
});

/**
 * 404 Not Found handler
 */
app.use('*', (req, res) => {
  res.status(404).json({
    status: 'error',
    statusCode: 404,
    message: `Route ${req.originalUrl} not found`,
  });
});

/**
 * Global error handling middleware
 * Must be defined after all other routes and middleware
 */
app.use((error, req, res, next) => {
  if (error instanceof AppError) {
    return errorResponse(error, req, res);
  }

  // Handle validation errors
  if (error.name === 'ValidationError') {
    return errorResponse(
      new AppError('Validation error', 400),
      req,
      res
    );
  }

  // Handle JSON parse errors
  if (error instanceof SyntaxError && error.status === 400 && 'body' in error) {
    return errorResponse(
      new AppError('Invalid JSON in request body', 400),
      req,
      res
    );
  }

  // Fallback to generic error
  errorResponse(
    new AppError('Internal server error', 500),
    req,
    res
  );
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${NODE_ENV} mode`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

# Security Review and Improvements for app.js

## Executive Summary
The original app.js had **10 critical security issues**. The improved version implements industry best practices for error handling, input validation, and security hardening.

---

## 🔴 Critical Issues in Original Code

### 1. **No Input Validation**
**Risk:** Injection attacks, unexpected behavior
```javascript
// ❌ VULNERABLE
app.get('/users', (req, res) => {
  // req.query not validated
  res.json([...]); 
});

// ✅ SECURE
if (!validateQueryParam(req.query.limit, 'int')) {
  throw new AppError('Invalid limit parameter', 400);
}
```

### 2. **Missing Error Handling**
**Risk:** Unhandled exceptions crash the app
```javascript
// ❌ VULNERABLE
app.get('/users', (req, res) => {
  res.json([...]); // No try-catch
});

// ✅ SECURE
app.get('/users', (req, res, next) => {
  try {
    // logic
  } catch (error) {
    next(error); // Pass to error middleware
  }
});
```

### 3. **No Security Headers**
**Risk:** CORS attacks, XSS, clickjacking, etc.
```javascript
// ✅ SECURE
app.use(helmet()); // Sets 15+ security headers
```

### 4. **Sensitive Data Exposure**
**Risk:** Email addresses exposed without authentication
```javascript
// ❌ VULNERABLE
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    // Exposed without authentication!
  ]);
});

// ✅ SECURE
// Add authentication middleware
// Implement role-based access control (RBAC)
// Use `.select('-email')` in database queries if not needed
```

### 5. **No Rate Limiting**
**Risk:** DoS attacks
```javascript
// ✅ SECURE
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100
});
app.use('/api/', limiter);
```

### 6. **No Request Size Limits**
**Risk:** Payload bomb attacks
```javascript
// ✅ SECURE
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb' }));
```

### 7. **Missing Logging & Monitoring**
**Risk:** Can't detect or investigate security incidents
```javascript
// ✅ SECURE
const morgan = require('morgan');
app.use(morgan('combined')); // HTTP request logging

console.error({ // Error logging with context
  timestamp: new Date().toISOString(),
  method: req.method,
  url: req.url,
  error: error.message
});
```

### 8. **Hardcoded Configuration**
**Risk:** Cannot adapt to different environments
```javascript
// ❌ VULNERABLE
app.listen(3000, () => { ... });

// ✅ SECURE
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${NODE_ENV} mode`);
});
```

### 9. **No NoSQL Injection Protection**
**Risk:** Database compromise
```javascript
// ✅ SECURE
const mongoSanitize = require('express-mongo-sanitize');
app.use(mongoSanitize()); // Removes $ and . from query
```

### 10. **No XSS Protection**
**Risk:** Malicious scripts executed in browsers
```javascript
// ✅ SECURE
const xss = require('xss-clean');
app.use(xss()); // Sanitizes user input
```

---

## ✅ Security Improvements Implemented

### A. Input Validation
- ✅ Validate all query parameters
- ✅ Validate all path parameters
- ✅ Validate request body fields
- ✅ Type checking (string, number, email)
- ✅ Length boundaries (min/max)
- ✅ Format validation (email, integers)

### B. Error Handling
