/**
 * Centralized configuration management
 * Loads and validates environment variables
 */

/**
 * Parse comma-separated string into array, filtering empty values
 */
const parseOrigins = (originsString = '') => {
  return originsString
    .split(',')
    .map(origin => origin.trim())
    .filter(origin => origin.length > 0);
};

/**
 * Validate environment variables
 */
const validateConfig = (config) => {
  const errors = [];

  // Validate NODE_ENV
  const validEnvs = ['development', 'test', 'production'];
  if (!validEnvs.includes(config.nodeEnv)) {
    errors.push(`NODE_ENV must be one of: ${validEnvs.join(', ')}`);
  }

  // Validate PORT
  if (config.port < 1 || config.port > 65535) {
    errors.push('PORT must be between 1 and 65535');
  }

  // Validate ALLOWED_ORIGINS
  if (config.allowedOrigins.length === 0) {
    errors.push('ALLOWED_ORIGINS must contain at least one valid origin');
  }

  // Production-specific validation
  if (config.nodeEnv === 'production') {
    if (!process.env.ALLOWED_ORIGINS) {
      errors.push('ALLOWED_ORIGINS is required in production');
    }
  }

  return errors;
};

/**
 * Load and parse configuration from environment
 */
const loadConfig = () => {
  const config = {
    nodeEnv: process.env.NODE_ENV || 'development',
    port: parseInt(process.env.PORT, 10) || 3000,
    allowedOrigins: parseOrigins(
      process.env.ALLOWED_ORIGINS || 'http://localhost:3000'
    ),
  };

  // Validate configuration
  const errors = validateConfig(config);
  if (errors.length > 0) {
    console.error('Configuration validation failed:');
    errors.forEach(error => console.error(`  - ${error}`));
    process.exit(1);
  }

  return config;
};

const config = loadConfig();

module.exports = config;

