// Improved application with security best practices
// Includes error handling, input validation, and security headers

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const validator = require('validator');
const app = express();

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// 1. Set Security Headers (Helmet)
app.use(helmet());

// 2. Rate Limiting - Prevent brute force and DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// 3. Stricter rate limit for auth endpoints (if added later)
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // More restrictive for auth
  skipSuccessfulRequests: true,
});

// 4. Body Parser with size limits
app.use(express.json({ limit: '10mb' }));
app.use(express.urlencoded({ limit: '10mb', extended: true }));

// 5. Data Sanitization (NoSQL Injection prevention)
app.use(mongoSanitize());

// 6. CORS Configuration (if needed)
// const cors = require('cors');
// app.use(cors({
//   origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
//   credentials: true
// }));

// ============================================================================
// REQUEST LOGGING
// ============================================================================

// Simple request logger (consider using winston/morgan for production)
app.use((req, res, next) => {
  const timestamp = new Date().toISOString();
  const requestInfo = `[${timestamp}] ${req.method} ${req.path}`;
  console.log(requestInfo);

  // Track response time
  res.on('finish', () => {
    console.log(`${requestInfo} - Status: ${res.statusCode}`);
  });

  next();
});

// ============================================================================
// HEALTH CHECK ENDPOINT
// ============================================================================

app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    res.status(500).json({ 
      status: 'error', 
      message: 'Health check failed' 
    });
  }
});

// ============================================================================
// USERS ENDPOINT WITH INPUT VALIDATION
// ============================================================================

app.get('/users', (req, res) => {
  try {
    // Input Validation
    const { id, limit, offset } = req.query;

    // Validate optional id parameter
    if (id !== undefined) {
      if (!validator.isNumeric(String(id))) {
        return res.status(400).json({ 
          error: 'Invalid id parameter - must be numeric',
          code: 'INVALID_INPUT'
        });
      }
    }

    // Validate pagination parameters
    if (limit !== undefined) {
      const parsedLimit = parseInt(limit, 10);
      if (!Number.isInteger(parsedLimit) || parsedLimit < 1 || parsedLimit > 100) {
        return res.status(400).json({ 
          error: 'Invalid limit parameter - must be integer between 1 and 100',
          code: 'INVALID_INPUT'
        });
      }
    }

    if (offset !== undefined) {
      const parsedOffset = parseInt(offset, 10);
      if (!Number.isInteger(parsedOffset) || parsedOffset < 0) {
        return res.status(400).json({ 
          error: 'Invalid offset parameter - must be non-negative integer',
          code: 'INVALID_INPUT'
        });
      }
    }

    // Mock data - in production, this would come from a database
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Filter by id if provided
    let users = allUsers;
    if (id !== undefined) {
      users = users.filter(user => user.id === parseInt(id, 10));
      if (users.length === 0) {
        return res.status(404).json({ 
          error: 'User not found',
          code: 'NOT_FOUND'
        });
      }
    }

    // Apply pagination
    const pageLimit = limit ? Math.min(parseInt(limit, 10), 100) : 10;
    const pageOffset = offset ? parseInt(offset, 10) : 0;
    const paginatedUsers = users.slice(pageOffset, pageOffset + pageLimit);

    res.json({
      data: paginatedUsers,
      total: users.length,
      limit: pageLimit,
      offset: pageOffset
    });

  } catch (error) {
    console.error('Error in /users endpoint:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      code: 'INTERNAL_ERROR'
    });
  }
});

// ============================================================================
// 404 AND ERROR HANDLING
// ============================================================================

// 404 Handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Endpoint not found',
    code: 'NOT_FOUND',
    path: req.path,
    method: req.method
  });
});

// Global Error Handler (must be last)
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Avoid leaking stack traces in production
  const isDevelopment = process.env.NODE_ENV !== 'production';

  res.status(err.status || 500).json({
    error: err.message || 'Internal server error',
    code: err.code || 'INTERNAL_ERROR',
    ...(isDevelopment && { stack: err.stack })
  });
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`✓ Server running on port ${PORT}`);
  console.log(`✓ Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

// Security Test Suite for app_improved.js
