  // ========================================================================
  // HEALTH ENDPOINT TESTS
  // ========================================================================

  describe('GET /health', () => {
    test('should return 200 with status ok', async () => {
      const res = await request(app).get('/health');
      expect(res.status).toBe(200);
      expect(res.body.status).toBe('ok');
      expect(res.body.timestamp).toBeDefined();
      expect(res.body.uptime).toBeDefined();
    });
  });

  // ========================================================================
  // USERS ENDPOINT - INPUT VALIDATION TESTS
  // ========================================================================

  describe('GET /users - Input Validation', () => {

    // ID Parameter Tests
    describe('id parameter validation', () => {
      test('should accept valid numeric id', async () => {
        const res = await request(app).get('/users?id=1');
        expect(res.status).toBe(200);
        expect(res.body.data).toBeDefined();
      });

      test('should reject non-numeric id', async () => {
        const res = await request(app).get('/users?id=abc');
        expect(res.status).toBe(400);
        expect(res.body.code).toBe('INVALID_INPUT');
        expect(res.body.error).toContain('Invalid id parameter');
      });

      test('should reject id with special characters', async () => {
        const res = await request(app).get('/users?id=1<script>');
        expect(res.status).toBe(400);
