// Improved version with security best practices
// Production-ready error handling and input validation

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const validator = require('validator');
const app = express();

// ============ SECURITY MIDDLEWARE ============

// Set security headers
app.use(helmet());

// Parse JSON with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Rate limiting - prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
});

app.use(limiter);

// ============ REQUEST LOGGING ============
// Simple request logging (consider using Winston/Morgan in production)
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.path}`);
  next();
});

// ============ VALIDATION HELPERS ============
const validateId = (id) => {
  const parsedId = parseInt(id, 10);
  if (isNaN(parsedId) || parsedId <= 0) {
    throw new Error('Invalid ID: must be a positive integer');
  }
  return parsedId;
};

const sanitizeQueryParams = (params) => {
  const sanitized = {};
  for (const [key, value] of Object.entries(params)) {
    if (typeof value === 'string') {
      sanitized[key] = validator.trim(value);
      sanitized[key] = validator.escape(sanitized[key]);
    }
  }
  return sanitized;
};

// ============ ROUTES ============

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    res.status(500).json({
      error: 'Failed to retrieve health status',
    });
  }
});

// Get users endpoint with optional filtering
app.get('/users', (req, res) => {
  try {
    // Validate and sanitize query parameters
    const sanitizedQuery = sanitizeQueryParams(req.query);

    // Mock user data (replace with database query in production)
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Filter by name if provided
    let users = allUsers;
    if (sanitizedQuery.name) {
      const nameFilter = sanitizedQuery.name.toLowerCase();
      users = users.filter((user) =>
        user.name.toLowerCase().includes(nameFilter)
      );
    }

    // Pagination support (prevent data exfiltration)
    const page = Math.max(1, parseInt(req.query.page || '1', 10));
    const limit = Math.min(50, Math.max(1, parseInt(req.query.limit || '10', 10))); // Cap at 50
    const start = (page - 1) * limit;
    const paginatedUsers = users.slice(start, start + limit);

    res.json({
      success: true,
      data: paginatedUsers,
      pagination: {
        page,
        limit,
        total: users.length,
      },
    });
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(400).json({
      success: false,
      error: 'Invalid request parameters',
    });
  }
});

// Get single user endpoint
app.get('/users/:id', (req, res) => {
  try {
    const userId = validateId(req.params.id);

    // Mock user data (replace with database query in production)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find((u) => u.id === userId);

    if (!user) {
      return res.status(404).json({
        success: false,
        error: 'User not found',
      });
    }

    res.json({
      success: true,
      data: user,
    });
  } catch (error) {
    console.error('Error fetching user:', error);
    res.status(400).json({
      success: false,
      error: 'Invalid user ID',
    });
  }
});

// ============ 404 HANDLER ============
app.use((req, res) => {
  res.status(404).json({
    success: false,
    error: 'Endpoint not found',
  });
});

// ============ GLOBAL ERROR HANDLER ============
// Must be defined last
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Don't expose internal error details in production
  const isDevelopment = process.env.NODE_ENV === 'development';
  const errorMessage = isDevelopment ? err.message : 'An error occurred';

  res.status(err.status || 500).json({
    success: false,
    error: errorMessage,
    ...(isDevelopment && { stack: err.stack }),
  });
});

// ============ STARTUP ============
const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`[${new Date().toISOString()}] Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

# Security Review: app.js

## Executive Summary
The original app.js has several security vulnerabilities and lacks proper error handling and input validation. This document outlines the issues and provides recommendations.

---

## 🔴 Critical Issues

### 1. **No Input Validation**
**Risk:** SQL Injection, NoSQL Injection, XSS attacks
- Query parameters are used directly without validation
- Path parameters are not validated
- No type checking

**Recommendations:**
```javascript
// ❌ Vulnerable
app.get('/users/:id', (req, res) => {
  res.json(users.find(u => u.id == req.params.id));
});

// ✅ Secure
app.get('/users/:id', (req, res) => {
  try {
    const userId = parseInt(req.params.id, 10);
    if (isNaN(userId) || userId <= 0) {
      return res.status(400).json({ error: 'Invalid ID' });
    }
    res.json(users.find(u => u.id === userId));
  } catch (error) {
    res.status(400).json({ error: 'Invalid request' });
  }
});
```

### 2. **Missing Error Handling Middleware**
**Risk:** Unhandled exceptions crash the server, exposing stack traces
- No try-catch blocks
- No error middleware
- No graceful error responses

**Recommendations:**
```javascript
// Add global error handler (must be last middleware)
app.use((err, req, res, next) => {
  console.error('Error:', err);
  const isDev = process.env.NODE_ENV === 'development';
  res.status(err.status || 500).json({
    error: isDev ? err.message : 'Internal server error'
  });
});

// Wrap async route handlers
app.get('/route', async (req, res, next) => {
  try {
    // your code
  } catch (error) {
    next(error); // Pass to error handler
  }
});
```

### 3. **No Security Headers**
**Risk:** Clickjacking, MIME type sniffing, XSS, Man-in-the-Middle attacks
- Missing Content-Security-Policy
- No X-Frame-Options
- No X-Content-Type-Options

**Recommendations:**
```javascript
const helmet = require('helmet');

app.use(helmet()); // Adds 15+ security headers automatically

// Or set headers manually:
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  next();
});
```

### 4. **No Rate Limiting**
**Risk:** Denial of Service (DoS), brute force attacks
- Endpoints are open to abuse
- No protection against automated attacks

**Recommendations:**
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // requests per IP
  message: 'Too many requests'
});

app.use(limiter);

// Or specific limiter for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 60 * 1000,
  max: 5
});
app.post('/login', strictLimiter, (req, res) => { /* ... */ });
```

### 5. **No Request Size Limiting**
**Risk:** Buffer overflow, memory exhaustion
- No payload size restrictions

**Recommendations:**
```javascript
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb' }));
```

### 6. **Sensitive Data Exposure**
**Risk:** Privacy violation, information disclosure
- Email addresses exposed directly in responses
- No data filtering or redaction

**Recommendations:**
```javascript
// Don't expose sensitive fields
const users = [
  { id: 1, name: 'Alice', email: 'alice@example.com' }
];

// Filter response
const sanitizedUser = {
  id: user.id,
  name: user.name
  // Don't include: email, password_hash, etc.
};

res.json(sanitizedUser);
```

---

## 🟡 Medium Priority Issues

### 7. **No Request Logging**
**Risk:** Cannot detect attacks or debug issues
- No audit trail
- No security monitoring

**Recommendations:**
```javascript
const morgan = require('morgan');
const winston = require('winston');

// Use Morgan for HTTP logging
app.use(morgan('combined'));

// Or Winston for structured logging
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});
```

### 8. **Missing Graceful Shutdown**
**Risk:** Data loss, corrupted state
- No cleanup on server shutdown

**Recommendations:**
```javascript
process.on('SIGTERM', () => {
  console.log('Shutting down...');
  server.close(() => {
    // Close database connections
    // Release resources
    process.exit(0);
  });
});
```

### 9. **Hardcoded Configuration**
**Risk:** Secrets exposed in code
- Port hardcoded
- No environment variable support

**Recommendations:**
```javascript
require('dotenv').config();

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
const DATABASE_URL = process.env.DATABASE_URL;

if (!DATABASE_URL) {
  throw new Error('DATABASE_URL environment variable is required');
}
```

### 10. **No Query Parameter Sanitization**
**Risk:** XSS if responses are rendered in HTML
- Query strings are echoed back without escaping

**Recommendations:**
```javascript
const validator = require('validator');

app.get('/search', (req, res) => {
  const query = validator.trim(req.query.q || '');
  const escaped = validator.escape(query);

  // Now safe to use in JSON or HTML
  res.json({ query: escaped });
});
```

---

## 🟢 Best Practices to Implement

### 11. **Use HTTPS in Production**
```javascript
const https = require('https');
const fs = require('fs');

if (process.env.NODE_ENV === 'production') {
  const options = {
    key: fs.readFileSync(process.env.KEY_PATH),
    cert: fs.readFileSync(process.env.CERT_PATH)
  };
  https.createServer(options, app).listen(443);
} else {
  app.listen(3000);
}
```

### 12. **Add CORS Protection**
```javascript
const cors = require('cors');

app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  methods: ['GET', 'POST'],
  credentials: true
}));
```

### 13. **Add Request Timeout**
```javascript
app.use((req, res, next) => {
  req.setTimeout(30000); // 30 seconds
  next();
});
```

### 14. **Add API Versioning**
```javascript
app.get('/api/v1/users', (req, res) => { /* ... */ });
app.get('/api/v2/users', (req, res) => { /* ... */ });
```

### 15. **Add Response Validation**
```javascript
const schema = {
  users: Joi.array().items(Joi.object({
    id: Joi.number().required(),
    name: Joi.string().required()
  }))
};

const { error, value } = schema.validate(response);
if (error) throw new Error('Invalid response schema');
```

---

## Dependencies to Add

```json
{
  "dependencies": {
    "express": "^4.18.0",
    "helmet": "^7.0.0",
    "express-rate-limit": "^6.0.0",
    "validator": "^13.9.0",
    "dotenv": "^16.0.0"
  },
  "devDependencies": {
    "morgan": "^1.10.0",
    "winston": "^3.8.0"
  }
}
```

---

## Environment Configuration

Create a `.env` file:
```env
NODE_ENV=development
PORT=3000
ALLOWED_ORIGINS=http://localhost:3000,http://localhost:5000
LOG_LEVEL=info
```

And `.env.production`:
```env
NODE_ENV=production
PORT=443
ALLOWED_ORIGINS=https://yourdomain.com
LOG_LEVEL=warn
KEY_PATH=/etc/ssl/private/key.pem
CERT_PATH=/etc/ssl/certs/cert.pem
```

---

## Testing Security

### Unit Tests for Input Validation
```javascript
describe('Input Validation', () => {
  it('should reject invalid user IDs', async () => {
    const res = await request(app).get('/users/invalid');
    expect(res.status).toBe(400);
  });

  it('should reject negative IDs', async () => {
    const res = await request(app).get('/users/-1');
    expect(res.status).toBe(400);
  });

  it('should accept valid IDs', async () => {
    const res = await request(app).get('/users/1');
    expect(res.status).toBe(200);
  });
});
```

### Security Headers Check
```javascript
describe('Security Headers', () => {
  it('should include helmet headers', async () => {
    const res = await request(app).get('/health');
    expect(res.header('x-content-type-options')).toBe('nosniff');
    expect(res.header('x-frame-options')).toBe('DENY');
  });
});
```

---

## Compliance Checklist

- [ ] All inputs validated and sanitized
- [ ] All errors caught and handled gracefully
- [ ] Security headers set (use helmet)
- [ ] Rate limiting implemented
- [ ] HTTPS enabled in production
- [ ] Sensitive data not exposed
- [ ] Logging and monitoring in place
- [ ] CORS properly configured
- [ ] SQL/NoSQL injection prevention
- [ ] XSS prevention (output encoding)
- [ ] CSRF protection (for state-changing operations)
- [ ] Authentication/Authorization implemented
- [ ] Secrets not hardcoded
- [ ] Dependencies kept up to date
- [ ] Graceful error handling
- [ ] Request timeouts set
- [ ] Payload size limits enforced

---

## References

- [OWASP Top 10](https://owasp.org/www-project-top-ten/)
- [Express.js Security Best Practices](https://expressjs.com/en/advanced/best-practice-security.html)
- [Node.js Security Checklist](https://nodejs.org/en/docs/guides/security/)
- [Helmet.js Documentation](https://helmetjs.github.io/)

