// Improved application with security best practices
// Includes error handling, input validation, and security headers

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const validator = require('validator');
const morgan = require('morgan');
require('dotenv').config();

const app = express();

// ============ MIDDLEWARE SETUP ============

// Security headers
app.use(helmet());

// CORS configuration
const cors = require('cors');
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
}));

// Request logging
app.use(morgan(process.env.LOG_LEVEL || 'combined'));

// Parse JSON with size limits to prevent payload attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Rate limiting middleware
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
  skip: (req) => process.env.NODE_ENV === 'development', // Skip in development
});

app.use('/api/', limiter);

// ============ ROUTES ============

/**
 * Health check endpoint
 * GET /health
 */
app.get('/health', (req, res) => {
  try {
    res.status(200).json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    });
  } catch (error) {
    res.status(500).json({ error: 'Internal server error' });
  }
});

/**
 * Get users endpoint
 * GET /api/users
 * Query parameters:
 *   - limit: number (1-100, default: 10) - limit results
 *   - offset: number (0+, default: 0) - pagination offset
 */
app.get('/api/users', (req, res) => {
  try {
    // Input validation
    const limit = validateLimit(req.query.limit);
    const offset = validateOffset(req.query.offset);

    if (limit.error || offset.error) {
      return res.status(400).json({
        error: 'Invalid input',
        details: limit.error || offset.error,
      });
    }

    // Mock user data (in production, this would be from a database)
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
    ];

    // Apply pagination
    const users = allUsers.slice(offset.value, offset.value + limit.value);

    res.status(200).json({
      data: users,
      pagination: {
        limit: limit.value,
        offset: offset.value,
        total: allUsers.length,
      },
    });
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

/**
 * Get single user endpoint
 * GET /api/users/:id
 */
app.get('/api/users/:id', (req, res) => {
  try {
    const userId = validateUserId(req.params.id);

    if (userId.error) {
      return res.status(400).json({
        error: 'Invalid user ID',
        details: userId.error,
      });
    }

    // Mock data lookup
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = allUsers.find(u => u.id === userId.value);

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    res.status(200).json({ data: user });
  } catch (error) {
    console.error('Error fetching user:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// ============ ERROR HANDLING ============

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    path: req.path,
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  const status = err.status || 500;
  const message = process.env.NODE_ENV === 'development'
    ? err.message
    : 'Internal server error';

  res.status(status).json({
    error: message,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack }),
  });
});

// ============ INPUT VALIDATION FUNCTIONS ============

/**
 * Validate and sanitize limit parameter
 */
function validateLimit(limit) {
  const DEFAULT_LIMIT = 10;
  const MAX_LIMIT = 100;

  if (!limit) {
    return { value: DEFAULT_LIMIT };
  }

  // Check if it's a valid integer
  if (!validator.isInt(String(limit))) {
    return { error: 'Limit must be an integer' };
  }

  const limitNum = parseInt(limit, 10);

  if (limitNum < 1) {
    return { error: 'Limit must be at least 1' };
  }

  if (limitNum > MAX_LIMIT) {
    return { error: `Limit must not exceed ${MAX_LIMIT}` };
  }

  return { value: limitNum };
}

/**
 * Validate and sanitize offset parameter
 */
function validateOffset(offset) {
  const DEFAULT_OFFSET = 0;

  if (!offset) {
    return { value: DEFAULT_OFFSET };
  }

  if (!validator.isInt(String(offset))) {
    return { error: 'Offset must be an integer' };
  }

  const offsetNum = parseInt(offset, 10);

  if (offsetNum < 0) {
    return { error: 'Offset must be non-negative' };
  }

  return { value: offsetNum };
}

/**
 * Validate user ID parameter
 */
function validateUserId(id) {
  // Check if it's a valid integer
  if (!validator.isInt(String(id))) {
    return { error: 'User ID must be an integer' };
  }

  const idNum = parseInt(id, 10);

  if (idNum < 1) {
    return { error: 'User ID must be positive' };
  }

  if (idNum > 999999) {
    return { error: 'User ID is out of valid range' };
  }

  return { value: idNum };
}

// ============ SERVER STARTUP ============

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${NODE_ENV} mode`);
});

module.exports = app;

# Security Review & Improvements for app.js

## Summary of Issues Found

### 🔴 CRITICAL

1. **No Input Validation**
   - Query parameters accepted without validation
   - Vulnerable to injection attacks
   - No type checking

2. **Missing Error Handling**
   - Unhandled exceptions could expose stack traces
   - No global error handler
   - No 404 handler

3. **No Security Headers**
   - Missing CORS configuration
   - No helmet.js protection
   - Vulnerable to common attacks (XSS, clickjacking, etc.)

### 🟡 HIGH

4. **No Rate Limiting**
   - Vulnerable to DoS attacks
   - No request throttling

5. **Hardcoded Configuration**
   - Port hardcoded to 3000
   - No environment-based configuration
   - Secrets potentially exposed in code

6. **No Request Logging**
   - Difficult to debug issues
   - No audit trail for security incidents

### 🟢 MEDIUM

7. **No Request Size Limits**
   - Vulnerable to payload attacks
   - Memory exhaustion risks

---

## Recommended Improvements

### 1. **Input Validation** ✅
```javascript
// BEFORE: No validation
app.get('/users', (req, res) => {
  res.json([...]);
});

// AFTER: With validation
function validateLimit(limit) {
  const DEFAULT_LIMIT = 10;
  const MAX_LIMIT = 100;

  if (!limit) return { value: DEFAULT_LIMIT };
  if (!validator.isInt(String(limit))) {
    return { error: 'Limit must be an integer' };
  }

  const limitNum = parseInt(limit, 10);
  if (limitNum < 1 || limitNum > MAX_LIMIT) {
    return { error: 'Invalid limit' };
  }

  return { value: limitNum };
}
```

**Why:** Prevents injection attacks, type confusion, and unexpected behavior.

---

### 2. **Error Handling** ✅
```javascript
// Add global error handler
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  const status = err.status || 500;
  const message = process.env.NODE_ENV === 'development'
    ? err.message
    : 'Internal server error';

  res.status(status).json({ error: message });
});
```

**Why:** 
- Prevents stack trace leaks in production
- Centralizes error handling
- Ensures consistent error responses

---

### 3. **Security Headers (Helmet.js)** ✅
```javascript
const helmet = require('helmet');
app.use(helmet());
```

**Protects against:**
- Content Security Policy (CSP) violations
- Cross-Site Scripting (XSS)
- Clickjacking
- MIME type sniffing

---

### 4. **CORS Configuration** ✅
```javascript
const cors = require('cors');
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
}));
```

**Why:** Restricts cross-origin requests, preventing unauthorized access.

---

### 5. **Rate Limiting** ✅
```javascript
const rateLimit = require('express-rate-limit');
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: 'Too many requests',
});
app.use('/api/', limiter);
```

**Why:** Prevents DoS attacks and abuse.

---

### 6. **Request Size Limits** ✅
```javascript
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));
```

**Why:** Prevents memory exhaustion and payload attacks.

---

### 7. **Environment Variables** ✅
```javascript
require('dotenv').config();
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
```

**Why:** Allows configuration without code changes. Never hardcode secrets.

---

### 8. **Request Logging** ✅
```javascript
const morgan = require('morgan');
app.use(morgan(process.env.LOG_LEVEL || 'combined'));
```

**Why:** Essential for debugging and audit trails.

---

## Required Dependencies

Add to `package.json`:
```json
{
  "dependencies": {
    "express": "^4.18.0",
    "helmet": "^7.0.0",
    "cors": "^2.8.5",
    "express-rate-limit": "^6.7.0",
    "validator": "^13.9.0",
    "morgan": "^1.10.0",
    "dotenv": "^16.0.3"
  }
}
```

Install:
```bash
npm install helmet cors express-rate-limit validator morgan dotenv
```

---

## .env Configuration Template

Create `.env` file:
```
PORT=3000
NODE_ENV=development
LOG_LEVEL=combined
ALLOWED_ORIGINS=http://localhost:3000,http://localhost:5173
```

---

## Additional Security Recommendations

### 1. **Use HTTPS in Production**
```javascript
if (process.env.NODE_ENV === 'production') {
  app.use((req, res, next) => {
    if (!req.secure && req.get('x-forwarded-proto') !== 'https') {
      return res.redirect('https://' + req.get('host') + req.url);
    }
    next();
  });
}
```

### 2. **Add Authentication/Authorization**
```javascript
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) return res.sendStatus(401);

  // Verify token (use JWT in production)
  next();
};

app.get('/api/users', authenticateToken, (req, res) => {
  // Protected route
});
```

### 3. **Input Sanitization**
```javascript
const sanitizer = require('xss');
const userInput = sanitizer(req.query.search);
```

### 4. **Database Parameterized Queries**
```javascript
// GOOD: Parameterized query
db.query('SELECT * FROM users WHERE id = ?', [userId]);

// BAD: String concatenation
db.query(`SELECT * FROM users WHERE id = ${userId}`);
```

### 5. **Secrets Management**
- Never commit `.env` files to version control
- Use `.env.example` template
- Rotate secrets regularly
- Use environment secrets in CI/CD pipelines

### 6. **Monitoring & Alerting**
- Log all errors
- Monitor response times
- Set up alerts for suspicious activities
- Use APM tools (e.g., New Relic, DataDog)

---

## Testing Recommendations

```javascript
// Install: npm install --save-dev jest supertest

const request = require('supertest');
const app = require('./app_improved');

describe('GET /api/users', () => {
  test('should return users with default pagination', async () => {
    const response = await request(app).get('/api/users');
    expect(response.status).toBe(200);
    expect(response.body.data).toBeInstanceOf(Array);
  });

  test('should reject invalid limit parameter', async () => {
    const response = await request(app).get('/api/users?limit=invalid');
    expect(response.status).toBe(400);
    expect(response.body.error).toBe('Invalid input');
  });

  test('should reject limit exceeding max', async () => {
    const response = await request(app).get('/api/users?limit=1000');
    expect(response.status).toBe(400);
  });

  test('should enforce rate limiting', async () => {
    // After 100 requests in 15 minutes, should get 429
    for (let i = 0; i < 101; i++) {
      const response = await request(app).get('/api/users');
      if (i === 100) {
        expect(response.status).toBe(429);
      }
    }
  });
});
```

---

## Summary

| Issue | Severity | Solution | Impact |
|-------|----------|----------|--------|
| No input validation | Critical | Add validator middleware | Prevents injection attacks |
| Missing error handling | Critical | Global error handler | Prevents information leaks |
| No security headers | Critical | Use helmet.js | Prevents XSS, clickjacking |
| No rate limiting | High | Use express-rate-limit | Prevents DoS |
| No CORS config | High | Configure CORS | Restricts unauthorized access |
| Hardcoded config | Medium | Use environment variables | Improves security & flexibility |
| No logging | Medium | Use morgan | Enables debugging & auditing |

---

## Reference Files

- ✅ **app_improved.js** - Fully secured version with all recommendations
- 📋 **This document** - Detailed security analysis and best practices

