const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const validator = require('validator');

const app = express();

// ============================================
// 1. SECURITY MIDDLEWARE
// ============================================

// Set security HTTP headers
app.use(helmet());

// Set request size limits to prevent large payload attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

// Apply rate limiting to all routes
app.use(limiter);

// ============================================
// 2. LOGGING (Simple version - use winston/morgan in production)
// ============================================

app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.path}`);
  next();
});

// ============================================
// 3. INPUT VALIDATION HELPER
// ============================================

const validateQueryParams = (schema) => {
  return (req, res, next) => {
    const errors = [];

    for (const [key, rules] of Object.entries(schema)) {
      const value = req.query[key];

      if (rules.required && !value) {
        errors.push(`Parameter '${key}' is required`);
        continue;
      }

      if (value) {
        if (rules.type === 'number' && isNaN(value)) {
          errors.push(`Parameter '${key}' must be a number`);
        }
        if (rules.type === 'email' && !validator.isEmail(value)) {
          errors.push(`Parameter '${key}' must be a valid email`);
        }
        if (rules.maxLength && value.length > rules.maxLength) {
          errors.push(`Parameter '${key}' exceeds maximum length of ${rules.maxLength}`);
        }
      }
    }

    if (errors.length > 0) {
      return res.status(400).json({
        error: 'Validation failed',
        details: errors,
      });
    }

    next();
  };
};

// ============================================
// 4. ENDPOINTS WITH ERROR HANDLING & VALIDATION
// ============================================

app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    console.error('Error in /health:', error);
    res.status(500).json({
      error: 'Internal server error',
      message: process.env.NODE_ENV === 'development' ? error.message : undefined,
    });
  }
});

app.get('/users', (req, res) => {
  try {
    // Validate optional query parameters
    if (req.query.id && (isNaN(req.query.id) || req.query.id < 1)) {
      return res.status(400).json({
        error: 'Validation failed',
        details: ['Parameter "id" must be a positive number'],
      });
    }

    // Mock database (in production, use actual database)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Filter by ID if provided
    let result = users;
    if (req.query.id) {
      const id = parseInt(req.query.id, 10);
      result = users.filter(user => user.id === id);

      if (result.length === 0) {
        return res.status(404).json({
          error: 'Not found',
          message: `User with ID ${id} not found`,
        });
      }
    }

    res.json(result);
  } catch (error) {
    console.error('Error in /users:', error);
    res.status(500).json({
      error: 'Internal server error',
      message: process.env.NODE_ENV === 'development' ? error.message : undefined,
    });
  }
});

// ============================================
// 5. 404 HANDLER
// ============================================

app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    message: `The requested endpoint ${req.method} ${req.path} does not exist`,
  });
});

// ============================================
// 6. GLOBAL ERROR HANDLER
// ============================================

app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Don't expose internal error details in production
  const isDevelopment = process.env.NODE_ENV === 'development';
  const message = isDevelopment ? err.message : 'Internal server error';

  res.status(err.status || 500).json({
    error: 'Internal server error',
    message,
    ...(isDevelopment && { stack: err.stack }),
  });
});

// ============================================
// 7. SERVER STARTUP
// ============================================

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

// Advanced validation patterns and helpers for production use

const validator = require('validator');

// ============================================
// VALIDATION SCHEMAS (using Joi style)
// ============================================

const validationSchemas = {
  // Query parameter validation
  queryParams: {
    userId: {
      required: false,
      type: 'number',
      min: 1,
      max: 999999,
    },
    email: {
      required: false,
      type: 'email',
      maxLength: 255,
    },
    page: {
      required: false,
      type: 'number',
      min: 1,
      max: 10000,
    },
    limit: {
      required: false,
      type: 'number',
      min: 1,
      max: 100,
    },
  },

  // Request body validation
  createUser: {
    name: {
      required: true,
      type: 'string',
      minLength: 1,
      maxLength: 255,
    },
    email: {
      required: true,
      type: 'email',
      maxLength: 255,
    },
    age: {
      required: false,
      type: 'number',
      min: 0,
      max: 150,
    },
  },
};

// ============================================
// CUSTOM VALIDATORS
// ============================================

const customValidators = {
  /**
   * Validate email format and prevent common injection patterns
   */
  validateEmail: (email) => {
    if (!validator.isEmail(email)) {
      return { valid: false, error: 'Invalid email format' };
    }
    if (email.length > 255) {
      return { valid: false, error: 'Email too long' };
    }
    // Prevent SQL injection patterns
    if (validator.contains(email, ';') || validator.contains(email, '--')) {
      return { valid: false, error: 'Invalid characters in email' };
    }
    return { valid: true };
  },

  /**
   * Validate username: alphanumeric, underscore, hyphen only
   */
  validateUsername: (username) => {
    if (!username || username.length < 3 || username.length > 32) {
      return { valid: false, error: 'Username must be 3-32 characters' };
    }
    if (!/^[a-zA-Z0-9_-]+$/.test(username)) {
      return { valid: false, error: 'Username can only contain letters, numbers, underscore, and hyphen' };
    }
    return { valid: true };
  },

  /**
   * Validate password strength
   */
  validatePassword: (password) => {
    const errors = [];

    if (!password || password.length < 8) {
      errors.push('Password must be at least 8 characters');
    }
    if (password.length > 128) {
      errors.push('Password must be less than 128 characters');
    }
    if (!/[A-Z]/.test(password)) {
      errors.push('Password must contain uppercase letter');
    }
    if (!/[a-z]/.test(password)) {
      errors.push('Password must contain lowercase letter');
    }
    if (!/[0-9]/.test(password)) {
      errors.push('Password must contain digit');
    }
    if (!/[!@#$%^&*]/.test(password)) {
      errors.push('Password must contain special character (!@#$%^&*)');
    }

    return errors.length === 0
      ? { valid: true }
      : { valid: false, error: errors };
  },

  /**
   * Sanitize and validate URL to prevent SSRF attacks
   */
  validateUrl: (url) => {
    try {
      const urlObj = new URL(url);

      // Whitelist protocols
      if (!['http:', 'https:'].includes(urlObj.protocol)) {
        return { valid: false, error: 'Only HTTP and HTTPS protocols allowed' };
      }

      // Block private IP ranges to prevent SSRF
      const hostname = urlObj.hostname;
      const privateIpPattern = /^(127\.|localhost|10\.|172\.(1[6-9]|2[0-9]|3[01])\.|192\.168\.|::1|fc00:|fe80:)/;
      if (privateIpPattern.test(hostname)) {
        return { valid: false, error: 'Private IP addresses not allowed' };
      }

      return { valid: true };
    } catch (error) {
      return { valid: false, error: 'Invalid URL format' };
    }
  },

  /**
   * Validate integer range
   */
  validateIntegerRange: (value, min, max) => {
    const num = parseInt(value, 10);

    if (isNaN(num)) {
      return { valid: false, error: 'Must be a number' };
    }
    if (num < min) {
      return { valid: false, error: `Must be at least ${min}` };
    }
    if (num > max) {
      return { valid: false, error: `Must not exceed ${max}` };
    }

    return { valid: true };
  },

  /**
   * Sanitize string input to prevent XSS
   */
  sanitizeString: (input) => {
    if (typeof input !== 'string') {
      return '';
    }

    // Remove HTML/script tags
    let sanitized = validator.escape(input);

    // Trim whitespace
    sanitized = sanitized.trim();

    // Remove null bytes
    sanitized = sanitized.replace(/\0/g, '');

    return sanitized;
  },

  /**
   * Validate JSON payload isn't too large
   */
  validateJsonSize: (payload, maxSizeKb = 10) => {
    const sizeInKb = Buffer.byteLength(JSON.stringify(payload)) / 1024;
    if (sizeInKb > maxSizeKb) {
      return { valid: false, error: `Payload exceeds maximum size of ${maxSizeKb}KB` };
    }
    return { valid: true };
  },
};

// ============================================
// MIDDLEWARE FACTORIES
// ============================================

/**
 * Create validation middleware for query parameters
 */
const validateQueryParams = (schema) => {
  return (req, res, next) => {
    const errors = [];

    for (const [key, rules] of Object.entries(schema)) {
      const value = req.query[key];

      // Check required
      if (rules.required && !value) {
        errors.push(`Parameter '${key}' is required`);
        continue;
      }

      // Skip validation if optional and not provided
      if (!rules.required && !value) {
        continue;
      }

      // Type validation
      if (rules.type === 'number') {
        const result = customValidators.validateIntegerRange(value, rules.min || 0, rules.max || Infinity);
        if (!result.valid) {
          errors.push(`Parameter '${key}': ${result.error}`);
        }
      }

      if (rules.type === 'email') {
        const result = customValidators.validateEmail(value);
        if (!result.valid) {
          errors.push(`Parameter '${key}': ${result.error}`);
        }
      }

      if (rules.type === 'string') {
        if (value.length < (rules.minLength || 0)) {
          errors.push(`Parameter '${key}' must be at least ${rules.minLength} characters`);
        }
        if (value.length > (rules.maxLength || 255)) {
          errors.push(`Parameter '${key}' must not exceed ${rules.maxLength} characters`);
        }
      }
    }

    if (errors.length > 0) {
      return res.status(400).json({
        error: 'Validation failed',
        details: errors,
      });
    }

    next();
  };
};

/**
 * Create validation middleware for request body
 */
const validateRequestBody = (schema) => {
  return (req, res, next) => {
    const errors = [];

    for (const [key, rules] of Object.entries(schema)) {
      const value = req.body[key];

      // Check required
      if (rules.required && (value === undefined || value === null || value === '')) {
        errors.push(`Field '${key}' is required`);
        continue;
      }

      // Skip validation if optional and not provided
      if (!rules.required && (value === undefined || value === null)) {
        continue;
      }

      // Type validation
      if (rules.type === 'string') {
        if (typeof value !== 'string') {
          errors.push(`Field '${key}' must be a string`);
          continue;
        }
        if (value.length < (rules.minLength || 0)) {
          errors.push(`Field '${key}' must be at least ${rules.minLength} characters`);
        }
        if (value.length > (rules.maxLength || 255)) {
          errors.push(`Field '${key}' must not exceed ${rules.maxLength} characters`);
        }
      }

      if (rules.type === 'email') {
        const result = customValidators.validateEmail(value);
        if (!result.valid) {
          errors.push(`Field '${key}': ${result.error}`);
        }
      }

      if (rules.type === 'number') {
        const result = customValidators.validateIntegerRange(value, rules.min || 0, rules.max || Infinity);
        if (!result.valid) {
          errors.push(`Field '${key}': ${result.error}`);
        }
      }
    }

    if (errors.length > 0) {
      return res.status(400).json({
        error: 'Validation failed',
        details: errors,
      });
    }

    next();
  };
};

/**
 * Sanitize request body
 */
const sanitizeRequestBody = (fieldsToSanitize = []) => {
  return (req, res, next) => {
    for (const field of fieldsToSanitize) {
      if (typeof req.body[field] === 'string') {
        req.body[field] = customValidators.sanitizeString(req.body[field]);
      }
    }
    next();
  };
};

// ============================================
// EXPORT
// ============================================

module.exports = {
  validationSchemas,
  customValidators,
  validateQueryParams,
  validateRequestBody,
  sanitizeRequestBody,
};

# Security Best Practices Quick Reference

## 🔐 Top 10 Security Priorities for Express.js

### 1. ✅ Use Helmet for Security Headers
```javascript
const helmet = require('helmet');
app.use(helmet());
```
**What it does:** Sets Content-Security-Policy, X-Frame-Options, X-Content-Type-Options, etc.

---

### 2. ✅ Implement Rate Limiting
```javascript
const rateLimit = require('express-rate-limit');
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
});
app.use(limiter);
```
**Prevents:** Brute force, DoS, abuse

---

### 3. ✅ Add Request Size Limits
```javascript
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));
```
**Prevents:** Memory exhaustion, large payload attacks

---

### 4. ✅ Validate All Input
```javascript
const validateEmail = (email) => {
  return validator.isEmail(email) && email.length <= 255;
};

app.post('/users', (req, res) => {
  if (!validateEmail(req.body.email)) {
    return res.status(400).json({ error: 'Invalid email' });
  }
  // Process request
});
```
**Prevents:** SQL injection, XSS, command injection

---

### 5. ✅ Handle All Errors
```javascript
try {
  // Your code
} catch (error) {
  console.error(error);
  res.status(500).json({
    error: 'Internal server error',
    // Never expose stack trace in production!
  });
}

// Global error handler
app.use((err, req, res, next) => {
  console.error(err);
  res.status(500).json({
    error: process.env.NODE_ENV === 'development' ? err.message : 'Internal error'
  });
});
```
**Prevents:** Information disclosure, crashes

---

### 6. ✅ Sanitize Output
```javascript
const sanitizeString = (str) => {
  return validator.escape(str).trim();
};

app.get('/users/:id', (req, res) => {
  const id = parseInt(req.params.id, 10);
  if (isNaN(id) || id < 1) {
    return res.status(400).json({ error: 'Invalid ID' });
  }
  // Get user...
});
```
**Prevents:** XSS, LDAP injection, command injection

---

### 7. ✅ Use Environment Variables
```javascript
// ❌ WRONG
const dbPassword = 'mypassword123';

// ✅ RIGHT
const dbPassword = process.env.DB_PASSWORD;
if (!dbPassword) throw new Error('DB_PASSWORD not set');
```
**Prevents:** Credential exposure

---

### 8. ✅ Implement CORS Properly
```javascript
const cors = require('cors');

app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(','),
  credentials: true,
  optionsSuccessStatus: 200,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
}));
```
**Prevents:** Unauthorized cross-origin requests

---

### 9. ✅ Add Authentication
```javascript
const verifyToken = (req, res, next) => {
  const token = req.headers['authorization']?.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'No token' });

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) return res.status(403).json({ error: 'Invalid token' });
    req.user = user;
    next();
  });
};

app.get('/protected', verifyToken, (req, res) => {
  res.json({ message: 'Authorized' });
});
```
**Prevents:** Unauthorized access

---

### 10. ✅ Log Security Events
```javascript
const winston = require('winston');

const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

// Log suspicious activity
logger.warn('Failed login attempt', { email, ip: req.ip });
logger.error('SQL injection attempt detected', { payload: req.body });
```
**Enables:** Audit trail, anomaly detection, incident response

---

## 🚫 Common Vulnerabilities to Avoid

### SQL Injection
```javascript
// ❌ VULNERABLE
const query = `SELECT * FROM users WHERE email = '${email}'`;

// ✅ SAFE (with parameterized queries)
const query = 'SELECT * FROM users WHERE email = ?';
db.query(query, [email]);
```

### XSS (Cross-Site Scripting)
```javascript
// ❌ VULNERABLE
res.send(`<h1>Welcome ${name}</h1>`);

// ✅ SAFE
const sanitized = validator.escape(name);
res.send(`<h1>Welcome ${sanitized}</h1>`);
```

### CSRF (Cross-Site Request Forgery)
```javascript
// ✅ Use CSRF tokens
const csrf = require('csurf');
app.use(csrf());

app.post('/user', csrf(), (req, res) => {
  // Only processes if valid CSRF token in request
});
```

### Sensitive Data Exposure
```javascript
// ❌ VULNERABLE
app.get('/users', (req, res) => {
  res.json(users); // Exposes all fields
});

// ✅ SAFE (only return necessary fields)
app.get('/users', (req, res) => {
  const filtered = users.map(u => ({
    id: u.id,
    name: u.name,
    // email omitted unless specifically requested
  }));
  res.json(filtered);
});
```

### Insecure Deserialization
```javascript
// ❌ VULNERABLE
const data = eval(jsonString); // NEVER use eval!

// ✅ SAFE
const data = JSON.parse(jsonString);
```

