## Specific Vulnerability Examples

### 1. SQL Injection Prevention

**Vulnerable:**
```javascript
// ❌ User input directly in query
app.get('/user/:id', (req, res) => {
  const id = req.params.id;
  db.query(`SELECT * FROM users WHERE id = ${id}`, (err, result) => {
    res.json(result);
  });
});

// Attack: /user/1 OR 1=1
// Query becomes: SELECT * FROM users WHERE id = 1 OR 1=1
// Returns ALL users!
```

**Secure:**
```javascript
// ✅ Parameterized query with validation
app.get('/user/:id', (req, res) => {
  const id = parseInt(req.params.id, 10);

  // Validate first
  if (isNaN(id) || id < 1) {
    return res.status(400).json({ error: 'Invalid ID' });
  }

  // Use parameterized query
  db.query('SELECT * FROM users WHERE id = ?', [id], (err, result) => {
    res.json(result);
  });
});
```

---

### 2. XSS Prevention

**Vulnerable:**
```javascript
// ❌ User input directly in response
app.post('/comment', (req, res) => {
  const comment = req.body.comment;
  res.send(`<h2>Comment:</h2><p>${comment}</p>`);
});

// Attack: comment = "<script>alert('xss')</script>"
// Response contains executable JavaScript!
```

**Secure:**
```javascript
// ✅ Escape user input
const validator = require('validator');

app.post('/comment', (req, res) => {
  const comment = req.body.comment;

  // Validate
  if (!comment || comment.length > 500) {
    return res.status(400).json({ error: 'Invalid comment' });
  }

  // Escape HTML
  const safe = validator.escape(comment);
  res.send(`<h2>Comment:</h2><p>${safe}</p>`);
});

// Even if comment = "<script>alert('xss')</script>"
// Response contains: &lt;script&gt;alert(&#x27;xss&#x27;)&lt;/script&gt;
// Rendered as plain text, not executed
```

---

### 3. DoS Prevention

**Vulnerable:**
```javascript
// ❌ No request size limit
app.use(express.json()); // Accepts unlimited size!

app.post('/data', (req, res) => {
  const data = req.body;
  res.json({ received: data });
});

// Attack: Send 1GB JSON payload
// Server runs out of memory and crashes
```

**Secure:**
```javascript
// ✅ Request size limit
app.use(express.json({ limit: '10kb' })); // Maximum 10KB

app.post('/data', (req, res) => {
  // If payload > 10KB, automatically rejected
  const data = req.body;
  res.json({ received: data });
});

// Attack attempt returns 413 Payload Too Large
// Server remains stable
```

---

### 4. Brute Force Prevention

**Vulnerable:**
```javascript
// ❌ No rate limiting
app.post('/login', (req, res) => {
  const { email, password } = req.body;
  // Check credentials...
  res.json({ token: '...' });
});

// Attack: Send 1000 login attempts per second
// Attacker can brute force passwords
```

**Secure:**
```javascript
// ✅ Rate limiting
const rateLimit = require('express-rate-limit');

const loginLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 5, // 5 attempts per IP
  message: 'Too many login attempts, try again later',
  skipSuccessfulRequests: true, // Don't count successful logins
});

app.post('/login', loginLimiter, (req, res) => {
  const { email, password } = req.body;
  // Check credentials...
  res.json({ token: '...' });
});

// Attack: After 5 failed attempts, IP is blocked for 15 minutes
```

---

### 5. Information Disclosure Prevention

**Vulnerable:**
```javascript
// ❌ Stack trace exposed
app.get('/user/:id', (req, res) => {
  try {
    const id = parseInt(req.params.id);
    const user = db.query('SELECT * FROM users WHERE id = ?', [id]);
    res.json(user);
  } catch (error) {
    res.status(500).json({
      error: error.message,
      stack: error.stack, // ❌ Exposes internal details!
    });
  }
});

// Error response includes:
// /app/db.js:45 (reveals file structure)
// SQL syntax (reveals database type)
// System paths (reveals hosting infrastructure)
```

**Secure:**
```javascript
// ✅ Generic error messages in production
app.get('/user/:id', (req, res) => {
  try {
    const id = parseInt(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: 'Invalid ID' });
    }
    const user = db.query('SELECT * FROM users WHERE id = ?', [id]);
    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }
    res.json(user);
  } catch (error) {
    console.error('Database error:', error); // Log internally
    res.status(500).json({
      error: 'Internal server error',
      // No details exposed to client
    });
  }
});

// Error response only shows:
// "Internal server error"
// No sensitive information leaks
```

