// Enhanced application with security best practices
// Error handling, input validation, and security hardening

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');
const app = express();

// ============================================
// 1. SECURITY MIDDLEWARE
// ============================================

// Helmet helps secure Express apps with various HTTP headers
app.use(helmet());

// CORS configuration - restrict to specific origins
app.use((req, res, next) => {
  const allowedOrigins = process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'];
  const origin = req.get('origin');

  if (allowedOrigins.includes(origin)) {
    res.header('Access-Control-Allow-Origin', origin);
    res.header('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
    res.header('Access-Control-Allow-Headers', 'Content-Type, Authorization');
  }
  next();
});

// Body parser with size limits to prevent payload attacks
app.use(express.json({ limit: '1mb' }));
app.use(express.urlencoded({ limit: '1mb', extended: false }));

// ============================================
// 2. RATE LIMITING
// ============================================

// General rate limiter: 100 requests per 15 minutes
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

// Strict rate limiter for sensitive endpoints: 10 requests per 15 minutes
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10,
  message: 'Too many requests to this endpoint, please try again later.',
});

app.use(limiter);

// ============================================
// 3. REQUEST VALIDATION MIDDLEWARE
// ============================================

// Middleware to handle validation errors
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.param,
        message: err.msg
      }))
    });
  }
  next();
};

// ============================================
// 4. HEALTH CHECK ENDPOINT
// ============================================

app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    res.status(500).json({
      status: 'error',
      message: 'Health check failed'
    });
  }
});

// ============================================
// 5. USERS ENDPOINT WITH VALIDATION
// ============================================

app.get(
  '/users',
  strictLimiter,
  [
    // Validate query parameters
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100'),
    query('offset')
      .optional()
      .isInt({ min: 0 })
      .withMessage('Offset must be a non-negative integer'),
    query('sort')
      .optional()
      .isIn(['id', 'name', 'email'])
      .withMessage('Invalid sort field'),
  ],
  handleValidationErrors,
  (req, res, next) => {
    try {
      const limit = Math.min(parseInt(req.query.limit) || 10, 100);
      const offset = parseInt(req.query.offset) || 0;
      const sort = req.query.sort || 'id';

      // Mock data - in production, fetch from database
      const allUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Apply sorting
      const sorted = allUsers.sort((a, b) => {
        const aVal = a[sort];
        const bVal = b[sort];
        return aVal < bVal ? -1 : aVal > bVal ? 1 : 0;
      });

      // Apply pagination
      const paginated = sorted.slice(offset, offset + limit);

      res.json({
        data: paginated,
        pagination: {
          limit,
          offset,
          total: allUsers.length,
          hasMore: offset + limit < allUsers.length
        }
      });
    } catch (error) {
      next(error);
    }
  }
);

// ============================================
// 6. ERROR HANDLING MIDDLEWARE
// ============================================

// 404 Not Found handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: 'The requested resource could not be found.',
    path: req.path
  });
});

// Global error handler (must be last)
app.use((error, req, res, next) => {
  const status = error.status || error.statusCode || 500;
  const message = error.message || 'Internal Server Error';

  // Log error (in production, use proper logging service)
  console.error({
    timestamp: new Date().toISOString(),
    status,
    message,
    path: req.path,
    method: req.method,
    stack: error.stack
  });

  // Don't expose internal error details to clients in production
  const isProduction = process.env.NODE_ENV === 'production';

  res.status(status).json({
    error: message,
    ...((!isProduction && error.details) && { details: error.details })
  });
});

// ============================================
// 7. UNHANDLED REJECTION HANDLERS
// ============================================

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // In production, send to error tracking service
});

process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  // In production, send to error tracking service and restart gracefully
  process.exit(1);
});

// ============================================
// 8. SERVER STARTUP
// ============================================

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

# Security Review & Improvements for app.js

## Executive Summary
The original `app.js` is a minimal Express server with **significant security gaps**. This document outlines vulnerabilities and provides implementation recommendations.

---

## 🔴 Critical Issues Found

### 1. **No Input Validation**
**Risk:** SQL Injection, NoSQL Injection, Parameter Pollution
```javascript
// ❌ VULNERABLE
app.get('/users', (req, res) => {
  // No validation of query parameters
});

// ✅ FIXED
app.get('/users', [
  query('limit').optional().isInt({ min: 1, max: 100 }),
  query('offset').optional().isInt({ min: 0 }),
  query('sort').optional().isIn(['id', 'name', 'email']),
], handleValidationErrors, ...);
```

### 2. **No Error Handling**
**Risk:** Information Disclosure, Server Crashes
```javascript
// ❌ VULNERABLE
app.get('/users', (req, res) => {
  res.json([...]); // No try-catch
});

// ✅ FIXED
try {
  // logic here
} catch (error) {
  next(error); // Pass to error handler
}
```

### 3. **Missing Security Headers**
**Risk:** XSS, Clickjacking, MIME-type sniffing attacks
```javascript
// ✅ FIXED
const helmet = require('helmet');
app.use(helmet()); // Sets secure headers automatically
```

### 4. **No CORS Configuration**
**Risk:** Cross-Site Request Forgery (CSRF), Unauthorized API Access
```javascript
// ✅ FIXED
app.use((req, res, next) => {
  const allowedOrigins = process.env.ALLOWED_ORIGINS?.split(',') || [];
  const origin = req.get('origin');
  if (allowedOrigins.includes(origin)) {
    res.header('Access-Control-Allow-Origin', origin);
  }
  next();
});
```

### 5. **No Rate Limiting**
**Risk:** Denial of Service (DoS), Brute Force Attacks
```javascript
// ✅ FIXED
const rateLimit = require('express-rate-limit');
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100
});
app.use(limiter);
```

### 6. **No Request Size Limits**
**Risk:** Memory exhaustion, Buffer overflow attacks
```javascript
// ✅ FIXED
app.use(express.json({ limit: '1mb' }));
app.use(express.urlencoded({ limit: '1mb', extended: false }));
```

### 7. **Sensitive Data Exposure**
**Risk:** Information Disclosure
```javascript
// ❌ VULNERABLE - Exposes emails without authentication
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
  ]);
});

// ✅ FIXED - Add authentication and authorization checks
```

### 8. **No 404 Handler**
**Risk:** Stack trace leakage in production
```javascript
// ✅ FIXED
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});
```

### 9. **No Unhandled Rejection Handlers**
**Risk:** Unexpected server crashes
```javascript
// ✅ FIXED
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection:', reason);
});
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  process.exit(1);
});
```

### 10. **No Logging**
**Risk:** Cannot audit security incidents
```javascript
// ✅ FIXED - Log all errors with context
app.use((error, req, res, next) => {
  console.error({
    timestamp: new Date().toISOString(),
    status: error.status || 500,
    path: req.path,
    method: req.method,
    stack: error.stack
  });
});
```

