# Practical Examples: Before & After

## Vulnerability 1: SQL Injection via Query Parameters

### ❌ BEFORE (Vulnerable)
```javascript
app.get('/users', (req, res) => {
  const userId = req.query.id;
  // If user passes: ?id=1 OR 1=1 --
  // Results in: SELECT * FROM users WHERE id = 1 OR 1=1 --
  db.query(`SELECT * FROM users WHERE id = ${userId}`, (err, results) => {
    res.json(results);
  });
});
```

**Attack Example:**
```
GET /users?id=1 OR 1=1 --
GET /users?id=1; DROP TABLE users; --
```

### ✅ AFTER (Secure)
```javascript
const { query, validationResult } = require('express-validator');

app.get('/users', [
  query('id')
    .isInt({ min: 1 })
    .withMessage('User ID must be a positive integer'),
], (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  const userId = req.query.id;
  // Parameterized query - SQL injection impossible
  db.query('SELECT * FROM users WHERE id = ?', [userId], (err, results) => {
    if (err) return next(err);
    res.json(results);
  });
});
```

---

## Vulnerability 2: Buffer Overflow / Memory Exhaustion

### ❌ BEFORE (Vulnerable)
```javascript
const express = require('express');
const app = express();

// No size limit - attacker can send 1GB of data
app.use(express.json());

app.post('/upload', (req, res) => {
  // Server could crash from memory exhaustion
  const data = req.body;
  res.json({ received: true });
});
```

**Attack:**
```bash
# Sends 100GB of JSON
yes '{"x":"'$(python3 -c "print('a'*1000000)")'""}' | \
  curl -X POST -H "Content-Type: application/json" -d @- http://localhost:3000/upload
```

### ✅ AFTER (Secure)
```javascript
const express = require('express');
const app = express();

// Set strict size limits
app.use(express.json({ limit: '1mb' }));
app.use(express.urlencoded({ limit: '1mb', extended: false }));

app.post('/upload', (req, res) => {
  // Maximum 1MB payload
  const data = req.body;
  res.json({ received: true });
});
```

---

## Vulnerability 3: Missing Error Handlers

### ❌ BEFORE (Vulnerable)
```javascript
app.get('/users/:id', (req, res) => {
  const userId = parseInt(req.params.id);

  db.query('SELECT * FROM users WHERE id = ?', [userId], (err, results) => {
    // No error handling!
    res.json(results[0]);
  });
});

// Server crashes if:
// - Database connection fails
// - Query times out
// - Results is undefined
```

**Consequences:**
- Server crashes and shows stack trace
- Stack trace reveals database schema, file paths
- DoS vulnerability (attacker crashes server)

### ✅ AFTER (Secure)
```javascript
app.get('/users/:id', (req, res, next) => {
  try {
    const userId = parseInt(req.params.id);

    if (isNaN(userId)) {
      return res.status(400).json({
        error: 'Invalid user ID',
        message: 'User ID must be a valid integer'
      });
    }

    db.query('SELECT * FROM users WHERE id = ?', [userId], (err, results) => {
      if (err) return next(err); // Pass to error handler

      if (!results || results.length === 0) {
        return res.status(404).json({
          error: 'Not Found',
          message: 'User not found'
        });
      }

      res.json(results[0]);
    });
  } catch (error) {
    next(error); // Pass to global error handler
  }
});

// Global error handler
app.use((error, req, res, next) => {
  const status = error.status || 500;
  const isDevelopment = process.env.NODE_ENV === 'development';

  console.error({
    timestamp: new Date().toISOString(),
    status,
    message: error.message,
    path: req.path,
    stack: error.stack
  });

  res.status(status).json({
    error: 'Internal Server Error',
    // Only show details in development
    ...(isDevelopment && { message: error.message })
  });
});
```

---

## Vulnerability 4: No Rate Limiting

### ❌ BEFORE (Vulnerable)
```javascript
app.post('/login', (req, res) => {
  const { username, password } = req.body;
  // No rate limiting - attacker can try unlimited passwords
  authenticateUser(username, password);
});
```

**Attack:**
```bash
# Brute force 1 million password attempts
for i in {1..1000000}; do
  curl -X POST http://localhost:3000/login \
    -d "{\"username\":\"admin\",\"password\":\"attempt$i\"}" \
    -H "Content-Type: application/json"
done
```

### ✅ AFTER (Secure)
```javascript
const rateLimit = require('express-rate-limit');

// Different limits for different endpoints
const loginLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 5, // 5 attempts per IP
  message: 'Too many login attempts, please try again later',
  standardHeaders: true, // Return rate limit info in headers
  legacyHeaders: false,
  // Skip rate limiting for internal IPs
  skip: (req) => req.ip === '127.0.0.1'
});

app.post('/login', loginLimiter, (req, res) => {
  const { username, password } = req.body;
  authenticateUser(username, password);
});
```

**Consequences of rate limiting:**
- Attacker can only try 5 passwords every 15 minutes
- Locks account or IP after failed attempts
- Protects against brute force and DoS

