## Vulnerability 5: Sensitive Data Exposure

### ❌ BEFORE (Vulnerable)
```javascript
app.get('/users', (req, res) => {
  // No authentication check
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com', ssn: '123-45-6789' },
    { id: 2, name: 'Bob', email: 'bob@example.com', ssn: '987-65-4321' }
  ]);
});

// Anyone can access: http://localhost:3000/users
// Exposes sensitive PII (personally identifiable information)
```

### ✅ AFTER (Secure)
```javascript
const jwt = require('jsonwebtoken');

// Authentication middleware
const authenticate = (req, res, next) => {
  const token = req.get('authorization')?.replace('Bearer ', '');

  if (!token) {
    return res.status(401).json({
      error: 'Unauthorized',
      message: 'Missing authentication token'
    });
  }

  try {
    req.user = jwt.verify(token, process.env.JWT_SECRET);
    next();
  } catch (error) {
    res.status(403).json({
      error: 'Forbidden',
      message: 'Invalid or expired token'
    });
  }
};

// Authorization middleware
const authorize = (roles = []) => (req, res, next) => {
  if (!roles.includes(req.user.role)) {
    return res.status(403).json({
      error: 'Forbidden',
      message: 'Insufficient permissions'
    });
  }
  next();
};

app.get('/users', 
  authenticate,
  authorize(['admin']),
  (req, res) => {
    // Only authenticated admins can access
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' }
      // SSN not included in response
    ]);
  }
);
```

