## Testing Security

### Unit Tests

Create `tests/security.test.js`:

```javascript
const request = require('supertest');
const app = require('../app');

describe('Security Tests', () => {

  describe('Input Validation', () => {
    test('should reject invalid limit parameter', async () => {
      const res = await request(app)
        .get('/users?limit=99999');

      expect(res.status).toBe(400);
      expect(res.body.error).toBe('Validation failed');
    });

    test('should reject invalid sort parameter', async () => {
      const res = await request(app)
        .get('/users?sort=malicious');

      expect(res.status).toBe(400);
    });

    test('should accept valid parameters', async () => {
      const res = await request(app)
        .get('/users?limit=10&offset=0&sort=name');

      expect(res.status).toBe(200);
      expect(res.body.data).toBeDefined();
    });
  });

  describe('Error Handling', () => {
    test('should return 404 for non-existent endpoint', async () => {
      const res = await request(app)
        .get('/nonexistent');

      expect(res.status).toBe(404);
      expect(res.body.error).toBe('Not Found');
    });

    test('should not expose stack trace in production', async () => {
      process.env.NODE_ENV = 'production';

      const res = await request(app)
        .get('/nonexistent');

      expect(res.body.stack).toBeUndefined();
    });
  });

  describe('Security Headers', () => {
    test('should set X-Content-Type-Options header', async () => {
      const res = await request(app)
        .get('/health');

      expect(res.headers['x-content-type-options']).toBe('nosniff');
    });

    test('should set X-Frame-Options header', async () => {
      const res = await request(app)
        .get('/health');

      expect(res.headers['x-frame-options']).toBeDefined();
    });

    test('should set CSP header', async () => {
      const res = await request(app)
        .get('/health');

      expect(res.headers['content-security-policy']).toBeDefined();
    });
  });

  describe('Request Size Limits', () => {
    test('should reject oversized JSON payload', async () => {
      const largePayload = { data: 'x'.repeat(2000000) };

      const res = await request(app)
        .post('/api/data')
        .send(largePayload);

      expect(res.status).toBe(413); // Payload Too Large
    });
  });

  describe('Rate Limiting', () => {
    test('should accept requests within rate limit', async () => {
      for (let i = 0; i < 5; i++) {
        const res = await request(app)
          .get('/health');
        expect(res.status).toBe(200);
      }
    });
  });

});
```

