// Improved application with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const { validateRequest, validateId } = require('./middleware/validators');

const app = express();

// ============= SECURITY MIDDLEWARE =============

// Set security HTTP headers
app.use(helmet());

// Parse JSON bodies with size limit
app.use(express.json({ limit: '10kb' }));

// Request logging
app.use(morgan('combined'));

// Rate limiting to prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
});

app.use(limiter);

// ============= ROUTES =============

/**
 * Health check endpoint
 * GET /health
 */
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    res.status(500).json({ error: 'Internal server error' });
  }
});

/**
 * Get all users endpoint
 * GET /users
 * Query params: limit (optional, max 100)
 */
app.get('/users', validateRequest, (req, res) => {
  try {
    const limit = Math.min(parseInt(req.query.limit) || 10, 100);

    // In production, fetch from database with proper query limits
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    res.json({
      data: users.slice(0, limit),
      total: users.length,
      limit: limit
    });
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

/**
 * Get specific user by ID
 * GET /users/:id
 */
app.get('/users/:id', validateId, (req, res) => {
  try {
    const userId = parseInt(req.params.id, 10);

    if (userId < 1) {
      return res.status(400).json({ error: 'Invalid user ID' });
    }

    // Mock data - in production, fetch from database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === userId);

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    res.json(user);
  } catch (error) {
    console.error('Error fetching user:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// ============= ERROR HANDLING =============

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Endpoint not found' });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Unhandled error:', {
    message: err.message,
    stack: err.stack,
    url: req.url,
    method: req.method
  });

  // Don't leak error details in production
  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal server error' 
    : err.message;

  res.status(statusCode).json({ error: message });
});

// ============= SERVER STARTUP =============

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';

app.listen(PORT, HOST, () => {
  console.log(`Server running on ${HOST}:${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

module.exports = app;

/**
 * Input validation middleware
 * Provides functions to validate request parameters and data
 */

/**
 * Validates query parameters
 */
const validateRequest = (req, res, next) => {
  try {
    // Validate limit parameter if provided
    if (req.query.limit !== undefined) {
      const limit = parseInt(req.query.limit, 10);

      if (isNaN(limit)) {
        return res.status(400).json({ 
          error: 'Invalid parameter: limit must be a number' 
        });
      }

      if (limit < 1 || limit > 100) {
        return res.status(400).json({ 
          error: 'Invalid parameter: limit must be between 1 and 100' 
        });
      }
    }

    next();
  } catch (error) {
    console.error('Validation error:', error);
    res.status(400).json({ error: 'Invalid request' });
  }
};

/**
 * Validates ID parameter is a positive integer
 */
const validateId = (req, res, next) => {
  try {
    const id = req.params.id;

    // Check if ID is provided
    if (!id) {
      return res.status(400).json({ error: 'ID parameter is required' });
    }

    // Check if ID is a valid positive integer
    const parsedId = parseInt(id, 10);
    if (isNaN(parsedId) || parsedId < 1) {
      return res.status(400).json({ 
        error: 'Invalid ID: must be a positive integer' 
      });
    }

    next();
  } catch (error) {
    console.error('ID validation error:', error);
    res.status(400).json({ error: 'Invalid ID format' });
  }
};

/**
 * Validates user object (for POST/PUT operations)
 */
const validateUserData = (userData) => {
  const errors = [];

  // Name validation
  if (!userData.name || typeof userData.name !== 'string') {
    errors.push('Name is required and must be a string');
  } else if (userData.name.trim().length < 2) {
    errors.push('Name must be at least 2 characters long');
  } else if (userData.name.length > 100) {
    errors.push('Name must not exceed 100 characters');
  }

  // Email validation
  if (!userData.email || typeof userData.email !== 'string') {
    errors.push('Email is required and must be a string');
  } else if (!isValidEmail(userData.email)) {
    errors.push('Invalid email format');
  }

  return errors;
};

