// Improved application with security best practices
// Error handling, input validation, and security hardening

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const validator = require('validator');
const app = express();

// =====================
// SECURITY MIDDLEWARE
// =====================

// 1. Set security HTTP headers
app.use(helmet());

// 2. Rate limiting - prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);

// 3. Stricter rate limit for login/sensitive endpoints (if added)
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: 'Too many login attempts, please try again later.',
});

// 4. Body parser with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 5. Data sanitization against NoSQL injection
app.use(mongoSanitize());

// =====================
// ERROR HANDLING
// =====================

// Global error handler for uncaught errors
process.on('uncaughtException', (err) => {
  console.error('UNCAUGHT EXCEPTION! 💥 Shutting down...');
  console.error(err.name, err.message);
  process.exit(1);
});

// =====================
// ROUTES
// =====================

// Health check endpoint
app.get('/health', (req, res, next) => {
  try {
    res.status(200).json({
      status: 'ok',
      timestamp: new Date().toISOString(),
    });
  } catch (err) {
    next(err);
  }
});

// Get users endpoint with validation and sanitization
app.get('/users', (req, res, next) => {
  try {
    // Input validation for query parameters
    const { page = 1, limit = 10, search = '' } = req.query;

    // Validate pagination parameters
    const pageNum = parseInt(page);
    const limitNum = parseInt(limit);

    if (!Number.isInteger(pageNum) || pageNum < 1) {
      return res.status(400).json({
        status: 'fail',
        message: 'Page must be a positive integer',
      });
    }

    if (!Number.isInteger(limitNum) || limitNum < 1 || limitNum > 100) {
      return res.status(400).json({
        status: 'fail',
        message: 'Limit must be an integer between 1 and 100',
      });
    }

    // Sanitize search parameter
    const sanitizedSearch = validator.trim(search);
    if (sanitizedSearch.length > 50) {
      return res.status(400).json({
        status: 'fail',
        message: 'Search query must not exceed 50 characters',
      });
    }

    // Mock user data (in real app, fetch from database)
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Filter users based on search (if provided)
    let filteredUsers = allUsers;
    if (sanitizedSearch) {
      filteredUsers = allUsers.filter(
        (user) =>
          user.name.toLowerCase().includes(sanitizedSearch.toLowerCase()) ||
          user.id.toString().includes(sanitizedSearch)
      );
    }

    // Apply pagination
    const startIdx = (pageNum - 1) * limitNum;
    const paginatedUsers = filteredUsers.slice(
      startIdx,
      startIdx + limitNum
    );

    // Remove sensitive data before sending (optional based on requirements)
    // const sanitizedUsers = paginatedUsers.map(user => ({
    //   id: user.id,
    //   name: user.name,
    //   // email removed
    // }));

    res.status(200).json({
      status: 'success',
      results: paginatedUsers.length,
      data: {
        users: paginatedUsers,
      },
    });
  } catch (err) {
    next(err);
  }
});

// =====================
// ERROR MIDDLEWARE
// =====================

// 404 handler for undefined routes
app.use((req, res) => {
  res.status(404).json({
    status: 'fail',
    message: `Cannot find ${req.originalUrl} on this server!`,
  });
});

// Global error handling middleware (MUST be last)
app.use((err, req, res, next) => {
  // Set default error properties
  err.statusCode = err.statusCode || 500;
  err.status = err.status || 'error';

  // Log error (in production, use proper logging service)
  console.error('ERROR:', err);

  // Send error response
  res.status(err.statusCode).json({
    status: err.status,
    message: err.message,
    // In production, don't leak error details
    ...(process.env.NODE_ENV === 'development' && { error: err }),
  });
});

// =====================
// SERVER STARTUP
// =====================

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (err) => {
  console.error('UNHANDLED REJECTION! 💥 Shutting down...');
  console.error(err.name, err.message);
  server.close(() => {
    process.exit(1);
  });
});

module.exports = app;

# Security Review: app.js - Detailed Recommendations

## Executive Summary
The current `app.js` lacks critical security features including input validation, error handling, and security middleware. This document outlines issues found and improvements implemented.

---

## 🔴 CRITICAL ISSUES

### 1. **No Input Validation**
**Risk:** Injection attacks, malformed data, DOS via large payloads

**Current Code:**
```javascript
app.get('/users', (req, res) => {
  // No validation of query parameters
  res.json([...]);
});
```

**Improvement:**
```javascript
app.use(express.json({ limit: '10kb' })); // Limit payload size
// Validate pagination
const pageNum = parseInt(page);
if (!Number.isInteger(pageNum) || pageNum < 1) {
  return res.status(400).json({ status: 'fail', message: '...' });
}
```

**Tools Recommended:**
- `validator.js` - String validation and sanitization
- `joi` or `yup` - Schema validation
- Built-in `Number.isInteger()` - Type checking

---

### 2. **Missing Error Handling**
**Risk:** Unhandled exceptions crash server, information leakage through stack traces

**Improvement:**
```javascript
// Wrap route handlers in try-catch
app.get('/users', (req, res, next) => {
  try {
    // route logic
  } catch (err) {
    next(err); // Pass to error middleware
  }
});

// Global error handler (must be last)
app.use((err, req, res, next) => {
  err.statusCode = err.statusCode || 500;
  console.error('ERROR:', err);

  // Don't leak stack traces in production
  res.status(err.statusCode).json({
    status: 'error',
    message: err.message,
    ...(process.env.NODE_ENV === 'development' && { error: err }),
  });
});
```

---

### 3. **No Security Headers**
**Risk:** XSS, Clickjacking, MIME-type sniffing attacks

**Solution:**
```javascript
const helmet = require('helmet');
app.use(helmet()); // Sets X-Frame-Options, X-Content-Type-Options, CSP, etc.
```

**Headers Added:**
- `Content-Security-Policy` - Prevents XSS
- `X-Frame-Options` - Prevents clickjacking
- `X-Content-Type-Options` - Prevents MIME sniffing
- `Strict-Transport-Security` - Enforces HTTPS

---

### 4. **No Rate Limiting**
**Risk:** Brute force attacks, DOS attacks, abuse

**Solution:**
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // 100 requests per IP
  message: 'Too many requests...',
});

app.use(limiter);

// Stricter limits for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
});
app.post('/login', strictLimiter, loginHandler);
```

---

### 5. **NoSQL Injection Vulnerability**
**Risk:** Database queries manipulated via user input

**Solution:**
```javascript
const mongoSanitize = require('express-mongo-sanitize');
app.use(mongoSanitize()); // Removes $, . from user input

// Additional layer: parametrized queries
db.collection.findOne({ name: sanitizedInput }); // Good
```

---

### 6. **Sensitive Data Exposure**
**Risk:** Email addresses, personal info exposed unnecessarily

**Current Issue:**
```javascript
{ id: 1, name: 'Alice', email: 'alice@example.com' } // Email exposed
```

**Recommendation:**
```javascript
// Option 1: Remove email field
const sanitizedUsers = paginatedUsers.map(user => ({
  id: user.id,
  name: user.name,
}));

// Option 2: Hash/mask sensitive data
email: user.email.substring(0, 3) + '***@example.com'
```

---

## 🟡 IMPORTANT IMPROVEMENTS

### 7. **No Request Size Limits**
**Risk:** Memory exhaustion, DOS attacks

```javascript
app.use(express.json({ limit: '10kb' })); // Set reasonable limits
app.use(express.urlencoded({ limit: '10kb', extended: true }));
```

---

### 8. **Missing Unhandled Error Handlers**
**Risk:** Server crashes silently

```javascript
// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('UNCAUGHT EXCEPTION! Shutting down...');
  console.error(err.name, err.message);
  process.exit(1);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (err) => {
  console.error('UNHANDLED REJECTION! Shutting down...');
  server.close(() => process.exit(1));
});
```

---

### 9. **No 404 Handler**
**Risk:** Inconsistent error responses, information leakage

```javascript
app.use((req, res) => {
  res.status(404).json({
    status: 'fail',
    message: `Cannot find ${req.originalUrl} on this server!`,
  });
});
```

---

### 10. **Environment-Based Error Details**
**Risk:** Stack traces reveal system details in production

```javascript
res.status(err.statusCode).json({
  status: 'error',
  message: err.message,
  // Only include error details in development
  ...(process.env.NODE_ENV === 'development' && { error: err }),
});
```

---

## 📋 IMPLEMENTATION CHECKLIST

### Required Dependencies
```bash
npm install express helmet express-rate-limit express-mongo-sanitize validator
```

### Recommended Dependencies (Future)
```bash
npm install joi cors dotenv morgan winston
```

---

## 🔐 Additional Security Recommendations

### 1. **Enable CORS Properly**
```javascript
const cors = require('cors');
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(','),
  credentials: true,
  methods: ['GET', 'POST'],
  maxAge: 3600,
}));
```

### 2. **Environment Variables**
```javascript
require('dotenv').config();
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
```

### 3. **Request Logging**
```javascript
const morgan = require('morgan');
app.use(morgan('combined')); // Log all requests
```

### 4. **Request Timeout**
```javascript
app.use((req, res, next) => {
  req.setTimeout(30000); // 30 seconds
  next();
});
```

### 5. **Require HTTPS in Production**
```javascript
if (process.env.NODE_ENV === 'production') {
  app.use((req, res, next) => {
    if (req.header('x-forwarded-proto') !== 'https') {
      res.redirect(`https://${req.header('host')}${req.url}`);
    } else {
      next();
    }
  });
}
```

### 6. **Input Schema Validation with Joi**
```javascript
const schema = joi.object({
  page: joi.number().integer().min(1).default(1),
  limit: joi.number().integer().min(1).max(100).default(10),
  search: joi.string().max(50).default(''),
});

const { error, value } = schema.validate(req.query);
if (error) return res.status(400).json({ error: error.details });
```

