// Improved application with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const { body, validationResult } = require('express-validator');

const app = express();

// ============ SECURITY MIDDLEWARE ============

// 1. Set security HTTP headers
app.use(helmet());

// 2. Rate limiting to prevent DOS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10, // stricter limit for sensitive endpoints
});

app.use(limiter);

// 3. Body parser with size limits
app.use(express.json({ limit: '10kb' })); // Limit request body size
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 4. Data sanitization against NoSQL injection
app.use(mongoSanitize());

// 5. Request logging middleware
app.use((req, res, next) => {
  const timestamp = new Date().toISOString();
  console.log(`[${timestamp}] ${req.method} ${req.path} - IP: ${req.ip}`);
  next();
});

// ============ ROUTES ============

/**
 * Health check endpoint
 * No user input required
 */
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ status: 'error', message: 'Internal server error' });
  }
});

/**
 * Get users endpoint
 * Safe endpoint - no external data source in this example
 */
app.get('/users', (req, res) => {
  try {
    // In production, validate any query parameters
    const limit = Math.min(parseInt(req.query.limit) || 10, 100);
    const offset = Math.max(parseInt(req.query.offset) || 0, 0);

    if (isNaN(limit) || isNaN(offset)) {
      return res.status(400).json({
        error: 'Invalid query parameters. limit and offset must be numbers.',
      });
    }

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination safely
    const paginatedUsers = users.slice(offset, offset + limit);

    res.json({
      data: paginatedUsers,
      pagination: { limit, offset, total: users.length },
    });
  } catch (error) {
    console.error('Get users error:', error);
    res.status(500).json({ error: 'Failed to retrieve users' });
  }
});

/**
 * Example POST endpoint with input validation
 * Demonstrates proper validation practices
 */
app.post('/users', [
  // Input validation middleware
  body('name')
    .trim()
    .notEmpty()
    .withMessage('Name is required')
    .isLength({ min: 1, max: 100 })
    .withMessage('Name must be between 1 and 100 characters')
    .escape(), // Escape HTML characters
  body('email')
    .trim()
    .isEmail()
    .withMessage('Valid email is required')
    .normalizeEmail(),
], (req, res) => {
  try {
    // Check validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const { name, email } = req.body;

    // Additional business logic validation
    if (typeof name !== 'string' || typeof email !== 'string') {
      return res.status(400).json({ error: 'Invalid input types' });
    }

    // Process user creation (placeholder)
    const newUser = { id: 3, name, email };

    res.status(201).json({
      message: 'User created successfully',
      data: newUser,
    });
  } catch (error) {
    console.error('Create user error:', error);
    res.status(500).json({ error: 'Failed to create user' });
  }
});

// ============ ERROR HANDLING ============

/**
 * 404 handler - must be last
 */
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    path: req.path,
    method: req.method,
  });
});

/**
 * Global error handler - must be last
 */
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Don't expose internal error details to clients
  const statusCode = err.statusCode || 500;
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(statusCode).json({
    error: 'Internal Server Error',
    ...(isDevelopment && { details: err.message }),
  });
});

// ============ SERVER STARTUP ============

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

