// Improved application with security best practices
// Enhanced error handling, input validation, and security headers

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const validator = require('validator');

const app = express();

// ==================== SECURITY MIDDLEWARE ====================

// Set security HTTP headers
app.use(helmet());

// Rate limiting - protect against brute force and DoS
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
});

// Apply rate limiting to all requests
app.use(limiter);

// Body parser middleware with size limits
app.use(express.json({ limit: '10kb' })); // Limit payload size
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Data sanitization against NoSQL injection
app.use(mongoSanitize());

// ==================== REQUEST VALIDATION HELPERS ====================

/**
 * Validates email format
 * @param {string} email - Email to validate
 * @returns {boolean} - True if valid
 */
function isValidEmail(email) {
  return validator.isEmail(email);
}

/**
 * Validates positive integer
 * @param {*} value - Value to validate
 * @returns {boolean} - True if valid positive integer
 */
function isValidId(value) {
  const id = parseInt(value, 10);
  return Number.isInteger(id) && id > 0;
}

/**
 * Sanitizes string input
 * @param {string} str - String to sanitize
 * @returns {string} - Sanitized string
 */
function sanitizeString(str) {
  if (typeof str !== 'string') return '';
  return validator.escape(str).trim();
}

// ==================== ROUTES ====================

/**
 * Health check endpoint
 * @route GET /health
 * @returns {Object} - Health status
 */
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({
      status: 'error',
      message: 'Internal server error',
    });
  }
});

/**
 * Get all users
 * @route GET /users
 * @query {number} limit - Optional: limit results (1-100, default: 50)
 * @query {number} offset - Optional: offset for pagination (default: 0)
 * @returns {Array} - Array of user objects
 */
app.get('/users', (req, res) => {
  try {
    // Input validation
    const limit = req.query.limit ? parseInt(req.query.limit, 10) : 50;
    const offset = req.query.offset ? parseInt(req.query.offset, 10) : 0;

    // Validate pagination parameters
    if (!Number.isInteger(limit) || limit < 1 || limit > 100) {
      return res.status(400).json({
        status: 'error',
        message: 'Invalid limit parameter. Must be between 1 and 100.',
      });
    }

    if (!Number.isInteger(offset) || offset < 0) {
      return res.status(400).json({
        status: 'error',
        message: 'Invalid offset parameter. Must be a positive integer.',
      });
    }

    // Mock database data
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination
    const paginatedUsers = users.slice(offset, offset + limit);

    res.json({
      status: 'success',
      data: paginatedUsers,
      pagination: {
        limit,
        offset,
        total: users.length,
      },
    });
  } catch (error) {
    console.error('Get users error:', error);
    res.status(500).json({
      status: 'error',
      message: 'Failed to retrieve users',
    });
  }
});

/**
 * Get user by ID
 * @route GET /users/:id
 * @param {number} id - User ID
 * @returns {Object} - User object
 */
app.get('/users/:id', (req, res) => {
  try {
    const { id } = req.params;

    // Validate ID parameter
    if (!isValidId(id)) {
      return res.status(400).json({
        status: 'error',
        message: 'Invalid user ID. Must be a positive integer.',
      });
    }

    // Mock database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === parseInt(id, 10));

    if (!user) {
      return res.status(404).json({
        status: 'error',
        message: 'User not found',
      });
    }

    res.json({
      status: 'success',
      data: user,
    });
  } catch (error) {
    console.error('Get user by ID error:', error);
    res.status(500).json({
      status: 'error',
      message: 'Failed to retrieve user',
    });
  }
});

/**
 * Create a new user
 * @route POST /users
 * @body {Object} user - User object with name and email
 * @returns {Object} - Created user object
 */
app.post('/users', (req, res) => {
  try {
    const { name, email } = req.body;

    // Input validation
    if (!name || !email) {
      return res.status(400).json({
        status: 'error',
        message: 'Missing required fields: name, email',
      });
    }

    // Validate and sanitize name
    const sanitizedName = sanitizeString(name);
    if (sanitizedName.length === 0 || sanitizedName.length > 100) {
      return res.status(400).json({
        status: 'error',
        message: 'Invalid name. Must be 1-100 characters.',
      });
    }

    // Validate email
    const sanitizedEmail = sanitizeString(email);
    if (!isValidEmail(sanitizedEmail)) {
      return res.status(400).json({
        status: 'error',
        message: 'Invalid email format',
      });
    }

    // In a real app, you'd check for duplicates and save to DB
    const newUser = {
      id: 3, // Generated ID in real scenario
      name: sanitizedName,
      email: sanitizedEmail,
    };

    res.status(201).json({
      status: 'success',
      message: 'User created successfully',
      data: newUser,
    });
  } catch (error) {
    console.error('Create user error:', error);
    res.status(500).json({
      status: 'error',
      message: 'Failed to create user',
    });
  }
});

// ==================== ERROR HANDLERS ====================

/**
 * 404 Not Found handler
 */
app.use((req, res) => {
  res.status(404).json({
    status: 'error',
    message: 'Endpoint not found',
  });
});

/**
 * Global error handler
 * Catches all errors and sends standardized error response
 */
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Don't expose internal error details in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    status: 'error',
    message: err.message || 'Internal server error',
    ...(isDevelopment && { stack: err.stack }), // Only include stack trace in dev
  });
});

// ==================== SERVER STARTUP ====================

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} (${process.env.NODE_ENV || 'development'} mode)`);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (err) => {
  console.error('Unhandled Rejection:', err);
  server.close(() => {
    process.exit(1);
  });
});

module.exports = app;

# Security Review: app.js - Detailed Recommendations

## Summary of Issues Found

### CRITICAL Issues
1. ❌ No error handling - unhandled errors expose stack traces
2. ❌ No input validation - vulnerable to injection attacks
3. ❌ No security headers - vulnerable to XSS, clickjacking
4. ❌ No rate limiting - vulnerable to DoS attacks

### HIGH Priority Issues
5. ⚠️ No request size limits - payload bomb vulnerability
6. ⚠️ No data sanitization - NoSQL injection risks
7. ⚠️ Missing 404 handler - information disclosure
8. ⚠️ Sensitive data exposed - no access control

### MEDIUM Priority Issues
9. ⚠️ No logging strategy - poor observability
10. ⚠️ No response validation - inconsistent API contracts

---

## Detailed Recommendations

### 1. **Error Handling**

**Problem:**
```javascript
app.get('/users', (req, res) => {
  res.json([...]); // No try-catch, unhandled errors crash server
});
```

**Solution:**
```javascript
app.get('/users', (req, res) => {
  try {
    // Logic here
    res.json({ status: 'success', data: [] });
  } catch (error) {
    console.error('Get users error:', error);
    res.status(500).json({
      status: 'error',
      message: 'Failed to retrieve users',
      // Never expose stack trace to clients
    });
  }
});

// Add global error handler
app.use((err, req, res, next) => {
  const isDevelopment = process.env.NODE_ENV === 'development';
  res.status(err.status || 500).json({
    status: 'error',
    message: err.message || 'Internal server error',
    ...(isDevelopment && { stack: err.stack }),
  });
});
```

**Security Benefit:** Prevents information disclosure and application crashes.

---

### 2. **Input Validation**

**Problem:**
```javascript
app.get('/users', (req, res) => {
  // No validation of query parameters
  res.json([...]); 
});
```

**Solution:**
```javascript
app.get('/users', (req, res) => {
  const limit = req.query.limit ? parseInt(req.query.limit, 10) : 50;
  const offset = req.query.offset ? parseInt(req.query.offset, 10) : 0;

  // Validate pagination parameters
  if (!Number.isInteger(limit) || limit < 1 || limit > 100) {
    return res.status(400).json({
      status: 'error',
      message: 'Invalid limit. Must be 1-100.',
    });
  }

  if (!Number.isInteger(offset) || offset < 0) {
    return res.status(400).json({
      status: 'error',
      message: 'Invalid offset. Must be >= 0.',
    });
  }

  res.json({ status: 'success', data: [...] });
});
```

**Security Benefit:** Prevents injection attacks, type confusion, and business logic bypass.

---

### 3. **Security Headers (Helmet.js)**

**Problem:**
```javascript
// No security headers - vulnerable to XSS, clickjacking, MIME sniffing
const app = express();
```

**Solution:**
```javascript
const helmet = require('helmet');
app.use(helmet()); // Adds 15+ security headers:
// - X-Frame-Options: DENY (prevents clickjacking)
// - X-Content-Type-Options: nosniff (prevents MIME sniffing)
// - Strict-Transport-Security (enforces HTTPS)
// - Content-Security-Policy (prevents XSS)
// - X-XSS-Protection
// - Referrer-Policy
// ... and more
```

**Security Benefit:** Protects against XSS, clickjacking, MIME sniffing attacks.

---

### 4. **Rate Limiting**

**Problem:**
```javascript
// No rate limiting - vulnerable to DoS and brute force attacks
app.get('/users', (req, res) => {
  res.json([...]);
});
```

**Solution:**
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // 100 requests per window per IP
  message: 'Too many requests, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter); // Apply to all routes

// Or for specific endpoints:
app.post('/users', limiter, (req, res) => { ... });
```

**Security Benefit:** Prevents DoS attacks and brute force attempts.

---

### 5. **Request Body Size Limits**

**Problem:**
```javascript
// No size limit - vulnerable to payload bomb attacks
app.use(express.json());
```

**Solution:**
```javascript
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));
```

**Security Benefit:** Prevents memory exhaustion and resource consumption attacks.

---

### 6. **Data Sanitization**

**Problem:**
```javascript
// No sanitization - vulnerable to NoSQL/XSS injection
app.post('/users', (req, res) => {
  const { name, email } = req.body; // Raw, unsanitized input
  res.json({ name, email });
});
```

**Solution:**
```javascript
const mongoSanitize = require('express-mongo-sanitize');
const validator = require('validator');

app.use(mongoSanitize()); // Sanitizes all inputs

// OR manually sanitize:
function sanitizeString(str) {
  if (typeof str !== 'string') return '';
  return validator.escape(str).trim();
}

// Validate email format
function isValidEmail(email) {
  return validator.isEmail(email);
}

app.post('/users', (req, res) => {
  const { name, email } = req.body;

  const sanitizedName = sanitizeString(name);
  const sanitizedEmail = sanitizeString(email);

  if (!isValidEmail(sanitizedEmail)) {
    return res.status(400).json({ error: 'Invalid email' });
  }

  // Safe to use now
});
```

**Security Benefit:** Prevents injection attacks (NoSQL, XSS, command injection).

---

### 7. **Parameter Type Validation**

**Problem:**
```javascript
app.get('/users/:id', (req, res) => {
  const { id } = req.params; // Could be "abc" or negative
  res.json(users.find(u => u.id === id)); // Type coercion issues
});
```

**Solution:**
```javascript
function isValidId(value) {
  const id = parseInt(value, 10);
  return Number.isInteger(id) && id > 0;
}

app.get('/users/:id', (req, res) => {
  const { id } = req.params;

  if (!isValidId(id)) {
    return res.status(400).json({
      status: 'error',
      message: 'Invalid user ID. Must be a positive integer.',
    });
  }

  res.json({ status: 'success', data: user });
});
```

**Security Benefit:** Prevents type confusion and logic bypass attacks.

---

### 8. **Sensitive Data Protection**

**Problem:**
```javascript
// Email addresses exposed without access control
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' }, // PII exposed
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Recommendations:**
```javascript
// Option 1: Implement authentication/authorization
app.get('/users', authenticateUser, (req, res) => {
  // Only authenticated users can see emails
  res.json([...]);
});

// Option 2: Hide sensitive data in public endpoints
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice' }, // Email removed
    { id: 2, name: 'Bob' },
  ]);
});

// Option 3: Use role-based access control
app.get('/users', (req, res) => {
  const users = [...]
  const filteredUsers = users.map(u => ({
    id: u.id,
    name: u.name,
    ...(req.user.isAdmin && { email: u.email }), // Only admins see email
  }));
  res.json(filteredUsers);
});
```

**Security Benefit:** Prevents unauthorized access to PII (Personal Identifiable Information).

---

### 9. **Consistent Error Responses**

**Problem:**
```javascript
// Inconsistent responses across endpoints
app.get('/health', (req, res) => {
  res.json({ status: 'ok' }); // Inconsistent structure
});

app.get('/users', (req, res) => {
  res.json([...]); // No status field
});
```

**Solution:**
```javascript
// Use consistent response format
app.get('/health', (req, res) => {
  res.json({ status: 'success', data: { health: 'ok' } });
});

app.get('/users', (req, res) => {
  res.json({ status: 'success', data: users });
});

// Errors also consistent
res.status(400).json({ status: 'error', message: 'Invalid input' });
```

**Security Benefit:** Easier to detect attacks, better API contract enforcement.

---

### 10. **Logging Strategy**

**Problem:**
```javascript
// No structured logging - poor for security monitoring
app.get('/users', (req, res) => {
  res.json([...]);
});
```

**Solution:**
```javascript
const logger = require('winston'); // or pino, bunyan

app.get('/users', (req, res) => {
  try {
    logger.info('Users endpoint accessed', {
      ip: req.ip,
      timestamp: new Date(),
      userId: req.user?.id,
    });
    res.json({ status: 'success', data: users });
  } catch (error) {
    logger.error('Users endpoint error', {
      error: error.message,
      ip: req.ip,
      timestamp: new Date(),
    });
    res.status(500).json({ status: 'error' });
  }
});
```

**Security Benefit:** Enables security monitoring, audit trails, and incident response.

---

## Dependencies to Add

