// Improved version with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { v4: uuidv4 } = require('uuid');
const app = express();

// ============= SECURITY MIDDLEWARE =============

// Set security HTTP headers
app.use(helmet());

// Body parser with size limits to prevent payload attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// Request ID tracking for logging
app.use((req, res, next) => {
  req.id = uuidv4();
  next();
});

// Request logging middleware
app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    const duration = Date.now() - start;
    console.log(`[${req.id}] ${req.method} ${req.path} - Status: ${res.statusCode} - ${duration}ms`);
  });
  next();
});

// Rate limiting - prevent brute force and DDoS
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
});

app.use(limiter);

// ============= REQUEST VALIDATION HELPERS =============

/**
 * Validate and sanitize input parameters
 */
const validateInput = (input, options = {}) => {
  const {
    type = 'string',
    maxLength = 255,
    minLength = 0,
    required = false,
    pattern = null,
  } = options;

  // Check if required
  if (required && (input === undefined || input === null || input === '')) {
    return { valid: false, error: 'This field is required' };
  }

  // If not required and empty, return valid
  if (!required && (input === undefined || input === null || input === '')) {
    return { valid: true, value: input };
  }

  // Type validation
  if (type === 'string' && typeof input !== 'string') {
    return { valid: false, error: 'Expected string' };
  }

  if (type === 'number' && isNaN(Number(input))) {
    return { valid: false, error: 'Expected number' };
  }

  // Length validation
  if (typeof input === 'string') {
    if (input.length > maxLength) {
      return { valid: false, error: `Maximum length is ${maxLength}` };
    }
    if (input.length < minLength) {
      return { valid: false, error: `Minimum length is ${minLength}` };
    }
  }

  // Pattern validation (regex)
  if (pattern && !pattern.test(input)) {
    return { valid: false, error: 'Invalid format' };
  }

  return { valid: true, value: input.trim ? input.trim() : input };
};

// ============= ERROR HANDLING MIDDLEWARE =============

/**
 * Custom error handler
 */
class AppError extends Error {
  constructor(message, statusCode) {
    super(message);
    this.statusCode = statusCode;
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * Global error handling middleware (must be last)
 */
app.use((err, req, res, next) => {
  const error = {
    id: req.id,
    status: err.statusCode || 500,
    message: err.message || 'Internal Server Error',
  };

  // Log errors
  console.error(`[${req.id}] Error:`, {
    status: error.status,
    message: error.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
  });

  // Don't expose internal error details to client in production
  if (process.env.NODE_ENV === 'production' && err.statusCode >= 500) {
    error.message = 'Internal Server Error';
  }

  res.status(error.status).json({ error });
});

// ============= ROUTES =============

/**
 * Health check endpoint
 */
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      requestId: req.id,
    });
  } catch (err) {
    const error = new AppError('Health check failed', 500);
    throw error;
  }
});

/**
 * Get users endpoint with validation
 * In production, add authentication middleware to protect this endpoint
 */
app.get('/users', (req, res, next) => {
  try {
    // Example: Validate optional query parameters
    const limit = req.query.limit || '10';
    const validation = validateInput(limit, {
      type: 'number',
      pattern: /^\d+$/,
      required: false,
    });

    if (!validation.valid) {
      return res.status(400).json({
        error: {
          message: 'Invalid query parameters',
          details: validation.error,
          requestId: req.id,
        },
      });
    }

    const parsedLimit = Math.min(parseInt(validation.value), 100); // Cap at 100

    // Mock user data (in production, would come from database with parameterized queries)
    const users = [
      { id: 1, name: 'Alice' }, // Remove sensitive email data
      { id: 2, name: 'Bob' },
    ].slice(0, parsedLimit);

    res.json({
      data: users,
      count: users.length,
      requestId: req.id,
    });
  } catch (err) {
    next(new AppError('Failed to fetch users', 500));
  }
});

/**
 * Example POST endpoint with input validation
 */
app.post('/users', (req, res, next) => {
  try {
    const { name, email } = req.body;

    // Validate name
    const nameValidation = validateInput(name, {
      type: 'string',
      minLength: 1,
      maxLength: 100,
      required: true,
    });

    if (!nameValidation.valid) {
      return res.status(400).json({
        error: {
          field: 'name',
          message: nameValidation.error,
          requestId: req.id,
        },
      });
    }

    // Validate email
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    const emailValidation = validateInput(email, {
      type: 'string',
      maxLength: 254,
      required: true,
      pattern: emailRegex,
    });

    if (!emailValidation.valid) {
      return res.status(400).json({
        error: {
          field: 'email',
          message: emailValidation.error,
          requestId: req.id,
        },
      });
    }

    // In production: Save to database with parameterized queries
    const newUser = {
      id: Math.floor(Math.random() * 10000),
      name: nameValidation.value,
      email: emailValidation.value,
    };

    res.status(201).json({
      data: newUser,
      message: 'User created successfully',
      requestId: req.id,
    });
  } catch (err) {
    next(new AppError('Failed to create user', 500));
  }
});

// ============= 404 HANDLER =============

app.use((req, res) => {
  res.status(404).json({
    error: {
      message: 'Not Found',
      path: req.path,
      requestId: req.id,
    },
  });
});

// ============= SERVER STARTUP =============

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`[${new Date().toISOString()}] Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

/**
 * Application Configuration Management
 * Centralizes all environment configuration with validation
 */

require('dotenv').config();

// Define all configuration with defaults and validation rules
const config = {
  // Core Application Settings
  app: {
    env: process.env.NODE_ENV || 'development',
    port: parseInt(process.env.PORT, 10) || 3000,
    log_level: process.env.LOG_LEVEL || 'info',
    isDevelopment: (process.env.NODE_ENV || 'development') === 'development',
    isProduction: process.env.NODE_ENV === 'production',
