  },

  // Rate Limiting Configuration
  rateLimiting: {
    windowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS, 10) || 15 * 60 * 1000, // 15 minutes
    maxRequests: parseInt(process.env.RATE_LIMIT_MAX_REQUESTS, 10) || 100,
    // Stricter limits for production
    maxRequestsProduction: parseInt(process.env.RATE_LIMIT_MAX_REQUESTS_PROD, 10) || 50,
  },

  // Request Handling Configuration
  request: {
    bodyLimit: process.env.REQUEST_SIZE_LIMIT || '10kb',
    urlEncodedLimit: process.env.REQUEST_SIZE_LIMIT || '10kb',
    timeout: parseInt(process.env.REQUEST_TIMEOUT_MS, 10) || 30000, // 30 seconds
  },

  // CORS Configuration
  cors: {
    enabled: process.env.CORS_ENABLED === 'true',
    origin: process.env.CORS_ORIGIN || 'http://localhost:3000',
    credentials: process.env.CORS_CREDENTIALS === 'true',
    methods: (process.env.CORS_METHODS || 'GET,POST,PUT,DELETE').split(','),
  },

  // Authentication Configuration
  auth: {
    enabled: process.env.AUTH_ENABLED === 'true',
    jwtSecret: process.env.JWT_SECRET,
    jwtExpiry: process.env.JWT_EXPIRY || '24h',
    hashRounds: parseInt(process.env.HASH_ROUNDS, 10) || 10,
  },

  // Database Configuration
  database: {
    url: process.env.DATABASE_URL,
    enabled: !!process.env.DATABASE_URL,
    poolSize: parseInt(process.env.DATABASE_POOL_SIZE, 10) || 10,
    connectionTimeout: parseInt(process.env.DATABASE_CONNECTION_TIMEOUT, 10) || 5000,
    idleTimeout: parseInt(process.env.DATABASE_IDLE_TIMEOUT, 10) || 30000,
    maxConnections: parseInt(process.env.DATABASE_MAX_CONNECTIONS, 10) || 20,
  },

  // AWS Configuration
  aws: {
