    accessKeyId: process.env.AWS_ACCESS_KEY_ID,
    secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
  },

  // Third-party API Configuration
  apis: {
    anthropic: {
      enabled: !!process.env.ANTHROPIC_API_KEY,
      key: process.env.ANTHROPIC_API_KEY,
    },
    stripe: {
      enabled: !!process.env.STRIPE_SECRET_KEY,
      key: process.env.STRIPE_SECRET_KEY,
      publishableKey: process.env.STRIPE_PUBLISHABLE_KEY,
    },
    logfire: {
      enabled: !!process.env.LOGFIRE_TOKEN,
      token: process.env.LOGFIRE_TOKEN,
    },
  },

  // Security Configuration
  security: {
    enableHSTS: process.env.ENABLE_HSTS !== 'false',
    hstsMaxAge: parseInt(process.env.HSTS_MAX_AGE, 10) || 31536000, // 1 year
    enableCSP: process.env.ENABLE_CSP !== 'false',
    enableXFrame: process.env.ENABLE_X_FRAME !== 'false',
    enableXContentTypeOptions: process.env.ENABLE_X_CONTENT_TYPE_OPTIONS !== 'false',
  },

  // Logging Configuration
  logging: {
    level: process.env.LOG_LEVEL || 'info',
    format: process.env.LOG_FORMAT || 'json',
    destination: process.env.LOG_DESTINATION || 'console',
  },
};

/**
 * Validate required configuration
 * Throws error on startup if critical config is missing
 */
const validateConfig = () => {
  const errors = [];

  // Authentication validation
  if (config.auth.enabled && !config.auth.jwtSecret) {
    errors.push('AUTH_ENABLED is true but JWT_SECRET is not set');
  }

  // Database validation
  if (config.database.enabled && !config.database.url) {
    errors.push('DATABASE_ENABLED is set but DATABASE_URL is not configured');
  }

  // Port validation
  if (config.app.port < 1 || config.app.port > 65535) {
    errors.push(`PORT must be between 1 and 65535, got ${config.app.port}`);
  }

  // Rate limiting validation
  if (config.rateLimiting.maxRequests < 1) {
    errors.push('RATE_LIMIT_MAX_REQUESTS must be at least 1');
  }

  // AWS validation (if partial config)
  if (!!process.env.AWS_ACCESS_KEY_ID !== !!process.env.AWS_SECRET_ACCESS_KEY) {
    errors.push('Both AWS_ACCESS_KEY_ID and AWS_SECRET_ACCESS_KEY must be provided together');
  }

  if (errors.length > 0) {
    const errorMessage = 'Configuration validation failed:\n' + errors.map(e => `  - ${e}`).join('\n');
    throw new Error(errorMessage);
  }
};

/**
 * Get environment-appropriate rate limit
 */
config.getRateLimit = function() {
  return this.app.isProduction ? this.rateLimiting.maxRequestsProduction : this.rateLimiting.maxRequests;
};

/**
 * Check if a service is enabled
 */
config.isServiceEnabled = function(serviceName) {
  const serviceConfig = this.apis[serviceName] || this[serviceName];
  return serviceConfig ? serviceConfig.enabled : false;
};

/**
 * Get formatted config for logging (without sensitive data)
 */
config.getPublicConfig = function() {
  return {
    app: {
      env: this.app.env,
      port: this.app.port,
      log_level: this.app.log_level,
    },
    database: {
      enabled: this.database.enabled,
    },
    auth: {
      enabled: this.auth.enabled,
    },
    cors: {
      enabled: this.cors.enabled,
      origin: this.cors.origin,
    },
    services: {
      aws: this.aws.enabled,
      anthropic: this.apis.anthropic.enabled,
      stripe: this.apis.stripe.enabled,
      logfire: this.apis.logfire.enabled,
    },
  };
};

// Validate on load
try {
  validateConfig();
} catch (error) {
  console.error(error.message);
  process.exit(1);
}

module.exports = config;

