// Improved application with security best practices
// Enhanced error handling, input validation, and security middleware

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const validator = require('validator');

const app = express();

// ==================== SECURITY MIDDLEWARE ====================

// 1. Helmet - Sets various HTTP headers for security
app.use(helmet());

// 2. Body Parser with Size Limits - Prevent payload attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 3. Data Sanitization - Prevent NoSQL injection
app.use(mongoSanitize());

// 4. Rate Limiting - Prevent brute force and DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply rate limiting to all routes
app.use(limiter);

// More aggressive rate limiting for sensitive endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: 'Too many failed attempts, please try again later.',
});

// ==================== REQUEST TIMEOUT ====================

// Set request timeout to prevent hanging connections
app.use((req, res, next) => {
  req.setTimeout(30000); // 30 seconds
  next();
});

// ==================== LOGGING MIDDLEWARE ====================

app.use((req, res, next) => {
  const timestamp = new Date().toISOString();
  const method = req.method;
  const path = req.path;
  const ip = req.ip;

  console.log(`[${timestamp}] ${method} ${path} - IP: ${ip}`);
  next();
});

// ==================== ROUTES ====================

/**
 * Health Check Endpoint
 * GET /health
 * No sensitive data returned
 */
app.get('/health', (req, res) => {
  try {
    res.status(200).json({
      status: 'ok',
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    res.status(500).json({
      status: 'error',
      message: 'Internal server error',
    });
  }
});

/**
 * Get Users Endpoint
 * GET /users
 * 
 * Query Parameters:
 * - page: number (optional, default: 1)
 * - limit: number (optional, default: 10, max: 50)
 * 
 * Returns: Array of user objects
 */
app.get('/users', (req, res) => {
  try {
    // Input Validation
    const { page = 1, limit = 10 } = req.query;

    // Validate page parameter
    if (!validator.isInt(String(page), { min: 1 })) {
      return res.status(400).json({
        status: 'error',
        message: 'Page must be a positive integer',
      });
    }

    // Validate limit parameter
    if (!validator.isInt(String(limit), { min: 1, max: 50 })) {
      return res.status(400).json({
        status: 'error',
        message: 'Limit must be between 1 and 50',
      });
    }

    // Convert to integers
    const pageNum = parseInt(page, 10);
    const limitNum = parseInt(limit, 10);

    // Mock user data
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Implement pagination
    const startIndex = (pageNum - 1) * limitNum;
    const paginatedUsers = allUsers.slice(
      startIndex,
      startIndex + limitNum
    );

    if (paginatedUsers.length === 0) {
      return res.status(404).json({
        status: 'error',
        message: 'No users found for the requested page',
      });
    }

    res.status(200).json({
      status: 'success',
      data: {
        users: paginatedUsers,
        page: pageNum,
        limit: limitNum,
        total: allUsers.length,
      },
    });
  } catch (error) {
    console.error('Error in /users endpoint:', error.message);
    res.status(500).json({
      status: 'error',
      message: 'Failed to retrieve users',
    });
  }
});

/**
 * Get User by ID Endpoint
 * GET /users/:id
 * 
 * Path Parameters:
 * - id: positive integer
 * 
 * Returns: Single user object
 */
app.get('/users/:id', (req, res) => {
  try {
    const { id } = req.params;

    // Validate ID parameter
    if (!validator.isInt(id, { min: 1 })) {
      return res.status(400).json({
        status: 'error',
        message: 'User ID must be a positive integer',
      });
    }

    const userId = parseInt(id, 10);

    // Mock user data
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === userId);

    if (!user) {
      return res.status(404).json({
        status: 'error',
        message: 'User not found',
      });
    }

    res.status(200).json({
      status: 'success',
      data: { user },
    });
  } catch (error) {
    console.error('Error in /users/:id endpoint:', error.message);
    res.status(500).json({
      status: 'error',
      message: 'Failed to retrieve user',
    });
  }
});

// ==================== 404 HANDLER ====================

app.use((req, res) => {
  res.status(404).json({
    status: 'error',
    message: 'Endpoint not found',
  });
});

// ==================== GLOBAL ERROR HANDLER ====================

app.use((err, req, res, next) => {
  const status = err.status || 500;
  const message = err.message || 'Internal server error';

  console.error(`[ERROR] ${status}: ${message}`, err);

  res.status(status).json({
    status: 'error',
    message: message,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack }),
  });
});

// ==================== SERVER START ====================

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (err) => {
  console.error('Unhandled Rejection:', err);
  server.close(() => process.exit(1));
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  process.exit(1);
});

module.exports = app;

