console.log(`   PORT: ${config.port}`);
console.log(`   LOG_LEVEL: ${config.logLevel}`);
console.log(`   RATE_LIMIT: ${config.rateLimitMax} requests per ${config.rateLimitWindow} minutes`);
console.log(`   REQUEST_TIMEOUT: ${config.requestTimeout}ms`);

// ==================== EXPRESS SETUP ====================

const app = express();

// ==================== SECURITY MIDDLEWARE ====================

// 1. Helmet - Sets various HTTP headers for security
app.use(helmet());

// 2. Body Parser with Size Limits - Prevent payload attacks
app.use(express.json({ limit: config.maxJsonSize }));
app.use(express.urlencoded({ limit: config.maxJsonSize, extended: true }));

// 3. Data Sanitization - Prevent NoSQL injection
app.use(mongoSanitize());

// 4. Rate Limiting - Prevent brute force and DoS attacks
const limiter = rateLimit({
  windowMs: config.rateLimitWindow * 60 * 1000,
