app.use(limiter);

// More aggressive rate limiting for sensitive endpoints
const authLimiter = rateLimit({
  windowMs: config.rateLimitWindow * 60 * 1000,
  max: 5,
  message: 'Too many failed attempts, please try again later.',
});

// ==================== REQUEST TIMEOUT ====================

// Set request timeout to prevent hanging connections
app.use((req, res, next) => {
  req.setTimeout(config.requestTimeout);
  res.setTimeout(config.requestTimeout);
  next();
});

// ==================== LOGGING MIDDLEWARE ====================

/**
 * Request logging middleware
 * Logs: timestamp, method, path, status, response time, client IP
 */
app.use((req, res, next) => {
  const startTime = Date.now();
  const timestamp = new Date().toISOString();
  const method = req.method;
  const path = req.path;
  const ip = req.ip || req.connection.remoteAddress;

  // Capture response status
  const originalSend = res.send;
  res.send = function(data) {
    const statusCode = res.statusCode;
    const duration = Date.now() - startTime;

    if (config.logLevel === 'debug' || statusCode >= 400) {
      console.log(
        `[${timestamp}] ${method} ${path} ${statusCode} ${duration}ms IP: ${ip}`
      );
    }

    return originalSend.call(this, data);
  };

  next();
});

// ==================== ROUTES ====================

/**
 * Health Check Endpoint
 * GET /health
 * No sensitive data returned
 */
app.get('/health', (req, res) => {
  try {
    res.status(200).json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      environment: config.nodeEnv,
    });
  } catch (error) {
    console.error('Error in /health endpoint:', error.message);
    res.status(500).json({
      status: 'error',
      message: 'Internal server error',
    });
  }
});

/**
 * Configuration Endpoint (Debug Only)
 * GET /config
 * Only available in development mode
 */
app.get('/config', (req, res) => {
  if (config.nodeEnv !== 'development') {
    return res.status(403).json({
      status: 'error',
      message: 'This endpoint is only available in development mode',
    });
  }

  res.status(200).json({
    status: 'success',
    data: {
      nodeEnv: config.nodeEnv,
      port: config.port,
      rateLimitWindow: `${config.rateLimitWindow} minutes`,
      rateLimitMax: config.rateLimitMax,
      requestTimeout: `${config.requestTimeout}ms`,
    },
  });
});

/**
 * Get Users Endpoint
 * GET /users
 * 
 * Query Parameters:
 * - page: number (optional, default: 1)
 * - limit: number (optional, default: 10, max: 50)
 * 
 * Returns: Array of user objects
 */
app.get('/users', (req, res) => {
  try {
    // Input Validation
    const { page = 1, limit = 10 } = req.query;

    // Validate page parameter
    if (!validator.isInt(String(page), { min: 1 })) {
      return res.status(400).json({
        status: 'error',
        message: 'Page must be a positive integer',
      });
    }

    // Validate limit parameter
    if (!validator.isInt(String(limit), { min: 1, max: 50 })) {
      return res.status(400).json({
        status: 'error',
        message: 'Limit must be between 1 and 50',
      });
    }

    // Convert to integers
    const pageNum = parseInt(page, 10);
    const limitNum = parseInt(limit, 10);

    // Mock user data
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Implement pagination
    const startIndex = (pageNum - 1) * limitNum;
    const paginatedUsers = allUsers.slice(
      startIndex,
      startIndex + limitNum
    );

    if (paginatedUsers.length === 0) {
      return res.status(404).json({
        status: 'error',
        message: 'No users found for the requested page',
      });
    }

    res.status(200).json({
      status: 'success',
      data: {
        users: paginatedUsers,
        page: pageNum,
        limit: limitNum,
        total: allUsers.length,
      },
    });
  } catch (error) {
    console.error('Error in /users endpoint:', error.message);
    res.status(500).json({
      status: 'error',
      message: 'Failed to retrieve users',
    });
  }
});

/**
 * Get User by ID Endpoint
 * GET /users/:id
 * 
 * Path Parameters:
 * - id: positive integer
 * 
 * Returns: Single user object
 */
app.get('/users/:id', (req, res) => {
  try {
    const { id } = req.params;

    // Validate ID parameter
    if (!validator.isInt(id, { min: 1 })) {
      return res.status(400).json({
        status: 'error',
        message: 'User ID must be a positive integer',
      });
    }

    const userId = parseInt(id, 10);

    // Mock user data
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === userId);

    if (!user) {
      return res.status(404).json({
        status: 'error',
        message: 'User not found',
      });
    }

    res.status(200).json({
      status: 'success',
      data: { user },
    });
  } catch (error) {
    console.error('Error in /users/:id endpoint:', error.message);
    res.status(500).json({
      status: 'error',
      message: 'Failed to retrieve user',
    });
  }
});

// ==================== 404 HANDLER ====================

app.use((req, res) => {
  res.status(404).json({
    status: 'error',
    message: 'Endpoint not found',
  });
});

// ==================== GLOBAL ERROR HANDLER ====================

app.use((err, req, res, next) => {
  const status = err.status || 500;
  const message = err.message || 'Internal server error';

  console.error(`[ERROR] ${status}: ${message}`, err);

  // In development, include stack trace; in production, don't
  const response = {
    status: 'error',
    message: message,
  };

  if (config.nodeEnv === 'development') {
    response.stack = err.stack;
  }

  res.status(status).json(response);
});

// ==================== SERVER START ====================

const server = app.listen(config.port, () => {
  console.log(`\n🚀 Server running on http://localhost:${config.port}`);
  console.log(`📊 Environment: ${config.nodeEnv}`);
  console.log(`🔒 Security: Helmet enabled, Rate limiting enabled\n`);
});

// ==================== PROCESS ERROR HANDLERS ====================

/**
 * Handle unhandled promise rejections
 * Prevents silent failures in async operations
 */
process.on('unhandledRejection', (err) => {
  console.error('❌ Unhandled Promise Rejection:', err);
  server.close(() => {
    console.log('Server closed due to unhandled rejection');
    process.exit(1);
  });
});

/**
 * Handle uncaught exceptions
 * Prevents silent failures in synchronous operations
 */
process.on('uncaughtException', (err) => {
  console.error('❌ Uncaught Exception:', err);
  server.close(() => {
    console.log('Server closed due to uncaught exception');
    process.exit(1);
  });
});

/**
 * Graceful shutdown on SIGTERM
 * Allows for clean shutdown in containerized environments
 */
process.on('SIGTERM', () => {
  console.log('📛 SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

