// Improved application with security best practices
// - Comprehensive error handling
// - Input validation
// - Security headers
// - Rate limiting
// - Logging

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');
const app = express();

// ===== Security Middleware =====

// Add security headers
app.use(helmet());

// Body parser with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// Rate limiting - prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);

// ===== Logging Middleware =====

// Simple request logging (consider using winston or morgan in production)
app.use((req, res, next) => {
  const start = Date.now();

  res.on('finish', () => {
    const duration = Date.now() - start;
    console.log(`[${new Date().toISOString()}] ${req.method} ${req.path} - ${res.statusCode} - ${duration}ms`);
  });

  next();
});

// ===== Input Validation Middleware =====

/**
 * Middleware to handle validation errors
 */
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.param,
        message: err.msg,
      })),
    });
  }
  next();
};

// ===== Routes =====

/**
 * Health check endpoint
 * No sensitive data, minimal validation needed
 */
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    console.error('[Health Check Error]', error);
    res.status(500).json({ error: 'Health check failed' });
  }
});

/**
 * Get users endpoint
 * Protected by validation and authentication (example)
 * 
 * Query parameters:
 * - limit: number (optional, 1-100, default: 10)
 * - offset: number (optional, 0+, default: 0)
 */
app.get(
  '/users',
  [
    // Validate query parameters
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100'),
    query('offset')
      .optional()
      .isInt({ min: 0 })
      .withMessage('Offset must be a non-negative integer'),
  ],
  handleValidationErrors,
  (req, res) => {
    try {
      // In a real application, verify authentication/authorization here
      // Example: const user = await authenticate(req);
      // if (!user) return res.status(401).json({ error: 'Unauthorized' });

      const limit = Math.min(parseInt(req.query.limit) || 10, 100);
      const offset = Math.max(parseInt(req.query.offset) || 0, 0);

      const allUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      const paginatedUsers = allUsers.slice(offset, offset + limit);

      res.json({
        data: paginatedUsers,
        pagination: {
          limit,
          offset,
          total: allUsers.length,
        },
      });
    } catch (error) {
      console.error('[Get Users Error]', error);
      res.status(500).json({ error: 'Failed to retrieve users' });
    }
  }
);

/**
 * Create user endpoint (example)
 * Demonstrates input validation for POST requests
 */
app.post(
  '/users',
  [
    body('name')
      .trim()
      .notEmpty()
      .withMessage('Name is required')
      .isLength({ min: 1, max: 100 })
      .withMessage('Name must be between 1 and 100 characters'),
    body('email')
      .trim()
      .isEmail()
      .withMessage('Valid email is required')
      .normalizeEmail(),
  ],
  handleValidationErrors,
  (req, res) => {
    try {
      // In production, save to database
      const newUser = {
        id: 3,
        name: req.body.name,
        email: req.body.email,
      };

      res.status(201).json({
        message: 'User created successfully',
        data: newUser,
      });
    } catch (error) {
      console.error('[Create User Error]', error);
      res.status(500).json({ error: 'Failed to create user' });
    }
  }
);

// ===== 404 Handler =====

app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    path: req.path,
    method: req.method,
  });
});

// ===== Global Error Handler =====

/**
 * Centralized error handling middleware
 * Should be last middleware registered
 */
app.use((err, req, res, next) => {
  const statusCode = err.statusCode || 500;
  const message = err.message || 'Internal Server Error';

  // Log error details (don't expose sensitive info to client)
  console.error('[Error]', {
    statusCode,
    message,
    path: req.path,
    method: req.method,
    stack: err.stack,
  });

  // Send safe error response to client
  res.status(statusCode).json({
    error: message,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack }),
  });
});

// ===== Server Startup =====

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// ===== Graceful Shutdown =====

process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

