# Side-by-Side Comparison: Before vs After

## INPUT VALIDATION

### ❌ BEFORE (Vulnerable)
```javascript
app.get('/users', (req, res) => {
  // No validation - accepts any input
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

### ✅ AFTER (Secure)
```javascript
app.get('/users',
  [
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100'),
    query('offset')
      .optional()
      .isInt({ min: 0 })
      .withMessage('Offset must be a non-negative integer'),
  ],
  handleValidationErrors,
  (req, res) => {
    const limit = Math.min(parseInt(req.query.limit) || 10, 100);
    const offset = Math.max(parseInt(req.query.offset) || 0, 0);
    // ... safely use validated inputs
  }
);
```

---

## ERROR HANDLING

### ❌ BEFORE (No Error Handling)
```javascript
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
  // If an error occurs, the app crashes or returns 500 with stack trace
});
```

### ✅ AFTER (With Error Handling)
```javascript
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    console.error('[Health Check Error]', error);
    res.status(500).json({ error: 'Health check failed' });
  }
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('[Error]', err);
  res.status(500).json({
    error: 'Internal Server Error',
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack }),
  });
});
```

---

## SECURITY HEADERS

### ❌ BEFORE (No Security Headers)
```javascript
const express = require('express');
const app = express();
// Vulnerable to XSS, Clickjacking, MIME-sniffing, etc.
```

### ✅ AFTER (With Helmet)
```javascript
const helmet = require('helmet');
app.use(helmet());

// Adds headers:
// - X-Frame-Options: DENY (prevents Clickjacking)
// - X-Content-Type-Options: nosniff (prevents MIME-sniffing)
// - Content-Security-Policy: default-src 'self' (prevents XSS)
// - Strict-Transport-Security: max-age=15552000 (forces HTTPS)
// And 11 more security headers...
```

---

## RATE LIMITING

### ❌ BEFORE (No Rate Limiting)
```javascript
app.get('/users', (req, res) => {
  res.json([...]);
  // Attackers can spam this endpoint infinitely
});
```

### ✅ AFTER (With Rate Limiting)
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // 100 requests per IP per 15 minutes
});

app.use(limiter);
app.get('/users', (req, res) => {
  res.json([...]);
  // Now limited to 100 requests per IP per 15 minutes
});
```

---

## REQUEST LOGGING

### ❌ BEFORE (No Logging)
```javascript
app.get('/users', (req, res) => {
  res.json([...]);
  // No way to track when/how the endpoint was accessed
});
```

### ✅ AFTER (With Logging)
```javascript
app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    const duration = Date.now() - start;
    console.log(`[${new Date().toISOString()}] ${req.method} ${req.path} - ${res.statusCode} - ${duration}ms`);
  });
  next();
});

// Output:
// [2024-01-15T10:30:45.123Z] GET /users - 200 - 12ms
// [2024-01-15T10:30:47.456Z] GET /health - 200 - 5ms
```

---

## 404 HANDLING

### ❌ BEFORE (No 404 Handler)
```javascript
app.listen(3000, () => {
  console.log('Server running on port 3000');
});

// Request to /unknown returns default Express 404 response
// May leak framework/version information
```

### ✅ AFTER (With 404 Handler)
```javascript
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    path: req.path,
    method: req.method,
  });
});

// Consistent JSON response for all 404s
```

---

## REQUEST SIZE LIMITS

### ❌ BEFORE (No Size Limits)
```javascript
const app = express();
// Accepts unlimited request sizes
// Vulnerable to DoS attacks via large payloads
```

### ✅ AFTER (With Size Limits)
```javascript
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// Requests larger than 10kb are rejected
// Prevents memory exhaustion attacks
```

---

## GRACEFUL SHUTDOWN

### ❌ BEFORE (Abrupt Shutdown)
```javascript
app.listen(3000, () => {
  console.log('Server running on port 3000');
});

// SIGTERM signal causes immediate crash
// May leave connections/transactions open
```

### ✅ AFTER (Graceful Shutdown)
```javascript
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

// Closes server, waits for connections to finish
```

