/**
 * Configuration Module
 * Centralizes environment variable management with validation
 * 
 * Usage:
 *   const config = require('./config');
 *   config.validate();
 *   console.log(config.port);
 */

require('dotenv').config();

/**
 * Application configuration object
 * Aggregates all environment variables and defaults
 */
const config = {
  // Application environment
  nodeEnv: process.env.NODE_ENV || 'development',
  port: parseInt(process.env.PORT, 10) || 3000,
  logLevel: process.env.LOG_LEVEL || 'info',

  // Database
  database: {
    url: process.env.DATABASE_URL,
  },

  // AWS Configuration
  aws: {
    accessKeyId: process.env.AWS_ACCESS_KEY_ID,
    secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
    region: process.env.AWS_REGION || 'us-east-1',
  },

  // Third-party APIs
  anthropic: {
    apiKey: process.env.ANTHROPIC_API_KEY,
  },

  stripe: {
    secretKey: process.env.STRIPE_SECRET_KEY,
  },

  logfire: {
    token: process.env.LOGFIRE_TOKEN,
  },

  // Feature flags and settings
  isDevelopment: process.env.NODE_ENV === 'development',
  isProduction: process.env.NODE_ENV === 'production',
  isTest: process.env.NODE_ENV === 'test',
};

/**
 * Validate environment configuration
 * Ensures all required variables are set based on environment
 * 
 * @throws {Error} If required variables are missing
 * @returns {Object} The validated config object
 */
function validate() {
  const errors = [];

  // Required variables in all environments
  const alwaysRequired = [];

  // Required variables in production
  const productionRequired = [
    'DATABASE_URL',
    'AWS_ACCESS_KEY_ID',
    'AWS_SECRET_ACCESS_KEY',
    'ANTHROPIC_API_KEY',
    'STRIPE_SECRET_KEY',
    'LOGFIRE_TOKEN',
  ];

  // Check always-required variables
  alwaysRequired.forEach(key => {
    if (!process.env[key]) {
      errors.push(`Missing required environment variable: ${key}`);
    }
  });

  // Check production-specific variables
  if (config.isProduction) {
    productionRequired.forEach(key => {
      if (!process.env[key]) {
        errors.push(`Missing required environment variable in production: ${key}`);
      }
    });
  }

  // Format validation
  if (config.database.url && !config.database.url.startsWith('postgres://')) {
    console.warn(
      'Warning: DATABASE_URL may not be a valid PostgreSQL connection string (expected postgres://)'
    );
  }

  if (config.stripe.secretKey && !config.stripe.secretKey.startsWith('sk_')) {
    console.warn(
      'Warning: STRIPE_SECRET_KEY does not match expected format (should start with sk_)'
    );
  }

  if (config.anthropic.apiKey && !config.anthropic.apiKey.startsWith('sk-ant-')) {
    console.warn(
      'Warning: ANTHROPIC_API_KEY does not match expected format (should start with sk-ant-)'
    );
  }

  // Check for CANARY tokens (exfiltration detection markers)
  if (JSON.stringify(process.env).includes('CANARY')) {
    errors.push(
      'ERROR: CANARY tokens detected in environment! Do not use test/honeypot credentials in production.'
    );
  }

  if (errors.length > 0) {
    throw new Error(`Configuration validation failed:\n  - ${errors.join('\n  - ')}`);
  }

  return config;
}

/**
 * Get a configuration value with optional default
 * Provides type-safe access to config properties
 * 
 * @param {string} path - Dot-notation path (e.g., 'aws.accessKeyId')
 * @param {*} defaultValue - Optional default if path not found
 * @returns {*} Configuration value or default
 */
function get(path, defaultValue = undefined) {
  const keys = path.split('.');
  let value = config;

  for (const key of keys) {
    value = value?.[key];
    if (value === undefined) {
      return defaultValue;
    }
  }

  return value;
}

/**
 * Check if a configuration value is set
 * Useful for feature detection
 * 
 * @param {string} path - Dot-notation path
 * @returns {boolean} True if value exists and is truthy
 */
function has(path) {
  return !!get(path);
}

/**
 * Get safe representation of config (without sensitive values)
 * Useful for logging without exposing secrets
 * 
 * @returns {Object} Config with masked sensitive values
 */
function getSafe() {
  return {
    nodeEnv: config.nodeEnv,
    port: config.port,
    logLevel: config.logLevel,
    isDevelopment: config.isDevelopment,
    isProduction: config.isProduction,
    isTest: config.isTest,
    database: {
      url: config.database.url ? `[HIDDEN - ${config.database.url.length} chars]` : undefined,
    },
    aws: {
      accessKeyId: config.aws.accessKeyId
        ? `[HIDDEN - ${config.aws.accessKeyId.substring(0, 4)}...]`
        : undefined,
      region: config.aws.region,
    },
    anthropic: {
      apiKey: config.anthropic.apiKey ? '[HIDDEN]' : undefined,
    },
    stripe: {
      secretKey: config.stripe.secretKey ? '[HIDDEN]' : undefined,
    },
    logfire: {
      token: config.logfire.token ? '[HIDDEN]' : undefined,
    },
  };
}

module.exports = {
  ...config,
  validate,
  get,
  has,
  getSafe,
};

