// Enhanced application with security best practices and error handling
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const { body, query, validationResult } = require('express-validator');

const app = express();

// ============= SECURITY MIDDLEWARE =============

// Set security HTTP headers
app.use(helmet());

// CORS configuration
app.use((req, res, next) => {
  res.header('Access-Control-Allow-Origin', process.env.ALLOWED_ORIGINS || 'http://localhost:3000');
  res.header('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
  res.header('Access-Control-Allow-Headers', 'Content-Type, Authorization');
  if (req.method === 'OPTIONS') {
    return res.sendStatus(200);
  }
  next();
});

// Body parser with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Data sanitization against NoSQL injection
app.use(mongoSanitize());

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

// Apply rate limiting to all requests
app.use(limiter);

// ============= REQUEST LOGGING =============

app.use((req, res, next) => {
  const startTime = Date.now();
  res.on('finish', () => {
    const duration = Date.now() - startTime;
    console.log(`[${new Date().toISOString()}] ${req.method} ${req.path} - Status: ${res.statusCode} - ${duration}ms`);
  });
  next();
});

// ============= ROUTES =============

/**
 * Health check endpoint
 * Returns system status and basic metrics
 */
app.get('/health', (req, res) => {
  try {
    // In a real app, you might check database connections, cache health, etc.
    const healthStatus = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      environment: process.env.NODE_ENV || 'development',
    };
    res.status(200).json(healthStatus);
  } catch (error) {
    console.error('Health check error:', error);
    res.status(503).json({ status: 'unhealthy', error: 'Internal server error' });
  }
});

/**
 * Get users endpoint
 * Query Parameters:
 *   - limit (optional): Number of results to return (1-100, default 10)
 *   - skip (optional): Number of results to skip (default 0)
 */
app.get('/users',
  // Validation middleware
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('limit must be an integer between 1 and 100'),
  query('skip')
    .optional()
    .isInt({ min: 0 })
    .withMessage('skip must be a non-negative integer'),
  (req, res, next) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        error: 'Validation failed',
        details: errors.array(),
      });
    }
    next();
  },
  (req, res) => {
    try {
      // Parse and sanitize query parameters with defaults
      const limit = Math.min(parseInt(req.query.limit) || 10, 100);
      const skip = Math.max(parseInt(req.query.skip) || 0, 0);

      // Mock data - in production, would query database
      const allUsers = [
        { id: 1, name: 'Alice' },
        { id: 2, name: 'Bob' },
      ];

      // Apply pagination
      const users = allUsers.slice(skip, skip + limit);

      // Return data with pagination metadata
      res.status(200).json({
        success: true,
        data: users,
        pagination: {
          total: allUsers.length,
          limit,
          skip,
          returned: users.length,
        },
      });
    } catch (error) {
      console.error('Error fetching users:', error);
      res.status(500).json({
        error: 'Failed to fetch users',
        message: process.env.NODE_ENV === 'development' ? error.message : 'Internal server error',
      });
    }
  }
);

// ============= ERROR HANDLING =============

// 404 handler - must be after all routes
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `The requested endpoint ${req.method} ${req.path} does not exist`,
  });
});

// Global error handler - must be last
app.use((err, req, res, next) => {
  console.error('Unhandled error:', {
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
  });

  // Default error response
  const statusCode = err.statusCode || 500;
  const isProduction = process.env.NODE_ENV === 'production';

  res.status(statusCode).json({
    error: err.name || 'Internal Server Error',
    message: isProduction
      ? 'An unexpected error occurred. Please try again later.'
      : err.message,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack }),
  });
});

// ============= SERVER STARTUP =============

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} (${process.env.NODE_ENV || 'development'} mode)`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

# Security Review & Improvement Recommendations for app.js

## Executive Summary
The original app.js lacks essential security controls and error handling mechanisms. This review outlines critical issues and improvements needed for production deployment.

---

## 🔴 CRITICAL ISSUES

### 1. **No Error Handling**
**Issue**: Unhandled errors will crash the server or expose stack traces.
```javascript
// ❌ BAD - No error handling
app.get('/users', (req, res) => {
  res.json([...]);
});

// ✅ GOOD - Try-catch with error response
app.get('/users', (req, res) => {
  try {
    res.status(200).json([...]);
  } catch (error) {
    console.error('Error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});
```

### 2. **No Input Validation**
**Issue**: Malicious input could cause crashes, injections, or logic errors.
```javascript
// ❌ BAD - No validation
app.get('/users?limit=999999&skip=-100&sort=DROP%20TABLE');

// ✅ GOOD - Validate and sanitize inputs
app.get('/users',
  query('limit').optional().isInt({ min: 1, max: 100 }),
  query('skip').optional().isInt({ min: 0 }),
  (req, res) => { ... }
);
```

### 3. **Missing Security Headers**
**Issue**: Vulnerable to XSS, clickjacking, MIME sniffing attacks.
```javascript
// ✅ GOOD - Use helmet middleware
const helmet = require('helmet');
app.use(helmet());
```

### 4. **No Rate Limiting**
**Issue**: Vulnerable to DoS/brute force attacks.
```javascript
// ✅ GOOD - Implement rate limiting
const rateLimit = require('express-rate-limit');
app.use(rateLimit({ windowMs: 15 * 60 * 1000, max: 100 }));
```

### 5. **NoSQL Injection Vulnerability**
**Issue**: Unsanitized query parameters could be exploited for injection attacks.
```javascript
// ❌ BAD - Directly using user input
db.users.find(req.query);

// ✅ GOOD - Sanitize input
const mongoSanitize = require('express-mongo-sanitize');
app.use(mongoSanitize());
```

---

## 🟠 HIGH PRIORITY ISSUES

### 6. **No Body Size Limits**
**Issue**: Attackers can send huge payloads causing memory exhaustion (DoS).
```javascript
// ✅ GOOD - Set limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb' }));
```

### 7. **Missing CORS Configuration**
**Issue**: Uncontrolled CORS can expose API to unauthorized origins.
```javascript
// ✅ GOOD - Explicit CORS configuration
app.use((req, res, next) => {
  res.header('Access-Control-Allow-Origin', process.env.ALLOWED_ORIGINS);
  res.header('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
  next();
});
```

### 8. **Exposed Sensitive Data**
**Issue**: Returning email addresses without proper authorization or data masking.
```javascript
// ❌ BAD - Expose sensitive data
{ id: 1, name: 'Alice', email: 'alice@example.com' }

// ✅ GOOD - Control data exposure
{ id: 1, name: 'Alice' }
// Only expose email to authorized requests
if (isAuthorized(req)) {
  user.email = 'alice@example.com';
}
```

### 9. **No Request Logging**
**Issue**: Cannot audit or debug requests; security incident investigation is harder.
```javascript
// ✅ GOOD - Add request logging
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} ${req.method} ${req.path}`);
  next();
});
```

---

## 🟡 MEDIUM PRIORITY ISSUES

### 10. **No 404 Handler**
**Issue**: Exposes API structure; inconsistent error responses.
```javascript
// ✅ GOOD - Add 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});
```

### 11. **No Graceful Shutdown**
**Issue**: Hard shutdowns can leave connections/resources hanging.
```javascript
// ✅ GOOD - Handle shutdown signals
process.on('SIGTERM', () => {
  server.close(() => process.exit(0));
});
```

### 12. **Insufficient Health Check**
**Issue**: Simple 'ok' status doesn't verify actual system health.
```javascript
// ✅ GOOD - Comprehensive health check
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    // Check database, cache, etc.
  });
});
```

