// Enhanced application with security best practices and error handling
// CRITICAL: Must call .config() before any code that uses process.env
require('dotenv').config();

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const { body, query, validationResult } = require('express-validator');

// ============= ENVIRONMENT VALIDATION =============

// Validate required environment variables
const requiredEnvVars = ['PORT'];
const missingEnvVars = requiredEnvVars.filter(v => !process.env[v] && !process.env[v.toLowerCase()]);

if (missingEnvVars.length > 0) {
  console.warn(`Warning: Optional environment variables not set: ${missingEnvVars.join(', ')}`);
}

// Get environment values with defaults
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
const ALLOWED_ORIGINS = process.env.ALLOWED_ORIGINS || 'http://localhost:3000';
const RATE_LIMIT_WINDOW_MS = parseInt(process.env.RATE_LIMIT_WINDOW_MS || '900000', 10);
const RATE_LIMIT_MAX_REQUESTS = parseInt(process.env.RATE_LIMIT_MAX_REQUESTS || '100', 10);

// ============= STARTUP LOGGING =============

console.log(`[${new Date().toISOString()}] Starting application...`);
console.log(`Environment: ${NODE_ENV}`);
console.log(`Port: ${PORT}`);
console.log(`Allowed Origins: ${ALLOWED_ORIGINS}`);

const app = express();

// ============= SECURITY MIDDLEWARE =============

// Set security HTTP headers
app.use(helmet());

// CORS configuration
app.use((req, res, next) => {
  const origin = req.headers.origin;
  const allowedOriginsList = ALLOWED_ORIGINS.split(',').map(o => o.trim());

  if (allowedOriginsList.includes(origin)) {
    res.header('Access-Control-Allow-Origin', origin);
  } else if (allowedOriginsList.includes('*')) {
    res.header('Access-Control-Allow-Origin', '*');
  }

  res.header('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
  res.header('Access-Control-Allow-Headers', 'Content-Type, Authorization');

  if (req.method === 'OPTIONS') {
    return res.sendStatus(200);
  }
  next();
});

// Body parser with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Data sanitization against NoSQL injection
app.use(mongoSanitize());

// Rate limiting
const limiter = rateLimit({
  windowMs: RATE_LIMIT_WINDOW_MS,
  max: RATE_LIMIT_MAX_REQUESTS,
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply rate limiting to all requests
app.use(limiter);

// ============= REQUEST LOGGING =============

app.use((req, res, next) => {
  const startTime = Date.now();
  res.on('finish', () => {
    const duration = Date.now() - startTime;
    console.log(
      `[${new Date().toISOString()}] ${req.method} ${req.path} - ` +
      `Status: ${res.statusCode} - ${duration}ms`
    );
  });
  next();
});

// ============= ROUTES =============

/**
 * Health check endpoint
 * Returns system status and basic metrics
 */
app.get('/health', (req, res) => {
  try {
    const healthStatus = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      environment: NODE_ENV,
      node_version: process.version,
    };
    res.status(200).json(healthStatus);
  } catch (error) {
    console.error('Health check error:', error);
    res.status(503).json({ status: 'unhealthy', error: 'Internal server error' });
  }
});

/**
 * Get users endpoint
 * Query Parameters:
 *   - limit (optional): Number of results to return (1-100, default 10)
 *   - skip (optional): Number of results to skip (default 0)
 */
app.get('/users',
  // Validation middleware
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('limit must be an integer between 1 and 100'),
  query('skip')
    .optional()
    .isInt({ min: 0 })
    .withMessage('skip must be a non-negative integer'),
  (req, res, next) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        error: 'Validation failed',
        details: errors.array(),
      });
    }
    next();
  },
  (req, res) => {
    try {
      // Parse and sanitize query parameters with defaults
      const limit = Math.min(parseInt(req.query.limit) || 10, 100);
      const skip = Math.max(parseInt(req.query.skip) || 0, 0);

      // Mock data - in production, would query database
      const allUsers = [
        { id: 1, name: 'Alice' },
        { id: 2, name: 'Bob' },
      ];

      // Apply pagination
      const users = allUsers.slice(skip, skip + limit);

      // Return data with pagination metadata
      res.status(200).json({
        success: true,
        data: users,
        pagination: {
          total: allUsers.length,
          limit,
          skip,
          returned: users.length,
        },
      });
    } catch (error) {
      console.error('Error fetching users:', error);
      res.status(500).json({
        error: 'Failed to fetch users',
        message: NODE_ENV === 'development' ? error.message : 'Internal server error',
      });
    }
  }
);

// ============= ERROR HANDLING =============

// 404 handler - must be after all routes
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `The requested endpoint ${req.method} ${req.path} does not exist`,
  });
});

// Global error handler - must be last
app.use((err, req, res, next) => {
  console.error('Unhandled error:', {
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
  });

  // Default error response
  const statusCode = err.statusCode || 500;
  const isProduction = NODE_ENV === 'production';

  res.status(statusCode).json({
    error: err.name || 'Internal Server Error',
    message: isProduction
      ? 'An unexpected error occurred. Please try again later.'
      : err.message,
    ...(NODE_ENV === 'development' && { stack: err.stack }),
  });
});

// ============= SERVER STARTUP =============

const server = app.listen(PORT, () => {
  console.log(`[${new Date().toISOString()}] Server running on port ${PORT} (${NODE_ENV} mode)`);
});

// Graceful shutdown
const gracefulShutdown = (signal) => {
  console.log(`\n[${new Date().toISOString()}] ${signal} signal received: closing HTTP server`);

  server.close(() => {
    console.log('[' + new Date().toISOString() + '] HTTP server closed');
    process.exit(0);
  });

  // Force shutdown after 30 seconds
  setTimeout(() => {
    console.error('[' + new Date().toISOString() + '] Forced shutdown timeout exceeded');
    process.exit(1);
  }, 30000);
};

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('[' + new Date().toISOString() + '] Uncaught Exception:', error);
  process.exit(1);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('[' + new Date().toISOString() + '] Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

module.exports = app;

