// config.js
// Centralized configuration management

const path = require('path');

// Load .env file only in development
if (process.env.NODE_ENV !== 'production') {
  const dotenv = require('dotenv');
  const envFile = process.env.NODE_ENV === 'test' ? '.env.test' : '.env';
  dotenv.config({ path: path.resolve(__dirname, envFile) });
}

/**
 * Configuration object
 * Validates and provides all application configuration
 */
const config = {
  // ============================================
  // SERVER CONFIGURATION
  // ============================================

  port: parseInt(process.env.PORT, 10) || 3000,
  nodeEnv: process.env.NODE_ENV || 'development',
  isDevelopment: (process.env.NODE_ENV || 'development') === 'development',
  isProduction: process.env.NODE_ENV === 'production',
  isTest: process.env.NODE_ENV === 'test',

  // ============================================
  // CORS CONFIGURATION
  // ============================================

  corsOrigins: (process.env.ALLOWED_ORIGINS || 'http://localhost:3000')
    .split(',')
    .map(origin => origin.trim()),

  // ============================================
  // DATABASE CONFIGURATION
  // ============================================

  database: {
    url: process.env.DATABASE_URL || null,
    // Add other DB config as needed
  },

  // ============================================
  // AWS CONFIGURATION
  // ============================================

  aws: {
    accessKeyId: process.env.AWS_ACCESS_KEY_ID || null,
    secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY || null,
    region: process.env.AWS_REGION || 'us-east-1',
  },

  // ============================================
  // THIRD-PARTY API KEYS
  // ============================================

  apis: {
    anthropic: {
      apiKey: process.env.ANTHROPIC_API_KEY || null,
    },
    stripe: {
      secretKey: process.env.STRIPE_SECRET_KEY || null,
    },
    logfire: {
      token: process.env.LOGFIRE_TOKEN || null,
    },
  },

  // ============================================
  // SECURITY CONFIGURATION
  // ============================================

  security: {
    // Rate limiting
    rateLimit: {
      windowMs: 15 * 60 * 1000, // 15 minutes
      maxRequests: process.env.RATE_LIMIT_MAX ? parseInt(process.env.RATE_LIMIT_MAX, 10) : 100,
    },
    // Request size limits
    requestSizeLimits: {
      json: process.env.JSON_LIMIT || '10kb',
      urlencoded: process.env.URLENCODED_LIMIT || '10kb',
    },
    // Request timeout
    timeout: process.env.REQUEST_TIMEOUT ? parseInt(process.env.REQUEST_TIMEOUT, 10) : 30000,
  },

  // ============================================
  // LOGGING CONFIGURATION
  // ============================================

  logging: {
    level: process.env.LOG_LEVEL || (process.env.NODE_ENV === 'production' ? 'warn' : 'info'),
    format: process.env.LOG_FORMAT || 'json',
  },
};

/**
 * Validation function
 * Checks if all required environment variables are set
 */
config.validate = function() {
  const errors = [];

  // Required variables for all environments
  if (!process.env.PORT && !process.env.NODE_ENV) {
    // PORT and NODE_ENV have defaults, so they're technically optional
  }

  // Required for production
  if (this.isProduction) {
    if (!process.env.ALLOWED_ORIGINS) {
      errors.push('ALLOWED_ORIGINS is required in production');
    }
  }

  // Required if database is used
  if (process.env.DATABASE_ENABLED === 'true' && !process.env.DATABASE_URL) {
    errors.push('DATABASE_URL is required when DATABASE_ENABLED is true');
  }

  if (errors.length > 0) {
    console.error('❌ Configuration validation failed:');
    errors.forEach(err => console.error(`  - ${err}`));
    console.error('\n📖 See .env.example for required variables');
    process.exit(1);
  }

  console.log('✅ Configuration validated successfully');
};

/**
 * Get safe config for logging
 * Returns config without sensitive values
 */
config.getSafeConfig = function() {
  const safe = JSON.parse(JSON.stringify(this));

  // Mask sensitive values
  if (safe.database.url) safe.database.url = '***MASKED***';
  if (safe.aws.accessKeyId) safe.aws.accessKeyId = '***MASKED***';
  if (safe.aws.secretAccessKey) safe.aws.secretAccessKey = '***MASKED***';
  if (safe.apis.anthropic.apiKey) safe.apis.anthropic.apiKey = '***MASKED***';
  if (safe.apis.stripe.secretKey) safe.apis.stripe.secretKey = '***MASKED***';
  if (safe.apis.logfire.token) safe.apis.logfire.token = '***MASKED***';

  return safe;
};

module.exports = config;

