// Improved application with security best practices
// Includes error handling, input validation, and security headers

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');
const app = express();

// ============================================================================
// MIDDLEWARE - Security & Configuration
// ============================================================================

// Apply security headers
app.use(helmet());

// CORS configuration (restrict as needed)
app.use((req, res, next) => {
  res.header('X-Content-Type-Options', 'nosniff');
  res.header('X-Frame-Options', 'DENY');
  res.header('X-XSS-Protection', '1; mode=block');
  next();
});

// Request size limiting
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api/', limiter);

// ============================================================================
// VALIDATION MIDDLEWARE
// ============================================================================

// Middleware to handle validation errors
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      success: false,
      errors: errors.array().map(err => ({
        field: err.param,
        message: err.msg
      }))
    });
  }
  next();
};

// ============================================================================
// ROUTES
// ============================================================================

app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString()
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ 
      success: false, 
      message: 'Internal server error' 
    });
  }
});

/**
 * GET /api/users
 * Retrieves list of users with optional filtering
 * Query Parameters:
 *   - limit: number (1-100, default: 10)
 *   - skip: number (0+, default: 0)
 */
app.get('/api/users',
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),
  query('skip')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Skip must be a non-negative integer'),
  handleValidationErrors,
  (req, res) => {
    try {
      const limit = Math.min(parseInt(req.query.limit) || 10, 100);
      const skip = Math.max(parseInt(req.query.skip) || 0, 0);

      // Mock data - in production, query from database with proper parameterized queries
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Apply pagination
      const paginatedUsers = users.slice(skip, skip + limit);

      res.json({
        success: true,
        data: paginatedUsers,
        pagination: {
          limit,
          skip,
          total: users.length
        }
      });
    } catch (error) {
      console.error('Error fetching users:', error);
      res.status(500).json({
        success: false,
        message: 'Failed to retrieve users'
      });
    }
  }
);

/**
 * POST /api/users
 * Creates a new user
 * Body Parameters:
 *   - name: string (required, 2-100 chars)
 *   - email: string (required, valid email)
 */
app.post('/api/users',
  body('name')
    .trim()
    .isLength({ min: 2, max: 100 })
    .withMessage('Name must be between 2 and 100 characters')
    .matches(/^[a-zA-Z\s'-]+$/)
    .withMessage('Name contains invalid characters'),
  body('email')
    .trim()
    .isEmail()
    .withMessage('Invalid email format')
    .normalizeEmail(),
  handleValidationErrors,
  (req, res) => {
    try {
      const { name, email } = req.body;

      // In production: check for duplicates, use prepared statements
      // Save to database here
      const newUser = {
        id: 3, // In production, generate proper ID
        name,
        email
      };

      res.status(201).json({
        success: true,
        message: 'User created successfully',
        data: newUser
      });
    } catch (error) {
      console.error('Error creating user:', error);
      res.status(500).json({
        success: false,
        message: 'Failed to create user'
      });
    }
  }
);

/**
 * GET /api/users/:id
 * Retrieves a specific user by ID
 * Path Parameters:
 *   - id: number (positive integer)
 */
app.get('/api/users/:id',
  (req, res, next) => {
    // Validate ID format
    if (!/^\d+$/.test(req.params.id)) {
      return res.status(400).json({
        success: false,
        message: 'Invalid user ID format'
      });
    }
    next();
  },
  (req, res) => {
    try {
      const userId = parseInt(req.params.id, 10);

      // Mock data - in production use parameterized queries
      const user = { id: userId, name: 'Alice', email: 'alice@example.com' };

      if (!user) {
        return res.status(404).json({
          success: false,
          message: 'User not found'
        });
      }

      res.json({
        success: true,
        data: user
      });
    } catch (error) {
      console.error('Error fetching user:', error);
      res.status(500).json({
        success: false,
        message: 'Failed to retrieve user'
      });
    }
  }
);

// ============================================================================
// ERROR HANDLING
// ============================================================================

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    success: false,
    message: 'Not found'
  });
});

// Global error handler (MUST be last)
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Don't expose internal error details to client
  const statusCode = err.statusCode || 500;
  const message = statusCode === 500 ? 'Internal server error' : err.message;

  res.status(statusCode).json({
    success: false,
    message,
    ...(process.env.NODE_ENV === 'development' && { error: err.message })
  });
});

// ============================================================================
// SERVER
// ============================================================================

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
  });
});

module.exports = app;

# Security Review: app.js - Detailed Recommendations

## 🔴 CRITICAL ISSUES

### 1. No Input Validation
**Issue:** Query parameters and body data are not validated, making the app vulnerable to:
- Type confusion attacks
- Buffer overflow attempts
- Injection attacks
- Data corruption

**Solution:** Use `express-validator` to validate all inputs
```javascript
const { body, query, validationResult } = require('express-validator');

app.get('/api/users',
  query('limit').optional().isInt({ min: 1, max: 100 }),
  query('skip').optional().isInt({ min: 0 }),
  (req, res) => { /* ... */ }
);
```

### 2. Missing Error Handling
**Issue:** Unhandled exceptions crash the server or expose stack traces
**Solution:** 
- Wrap routes in try-catch blocks
- Implement global error handler middleware
- Log errors securely (never log sensitive data)
- Return generic error messages to clients

### 3. No Rate Limiting
**Issue:** Vulnerable to Denial of Service (DoS) attacks
**Solution:** Use `express-rate-limit` middleware
```javascript
const rateLimit = require('express-rate-limit');
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100
});
app.use('/api/', limiter);
```

## 🟠 HIGH PRIORITY ISSUES

### 4. Missing Security Headers
**Issue:** No protection against common attacks (XSS, Clickjacking, etc.)
**Solution:** Use `helmet` package
```javascript
const helmet = require('helmet');
app.use(helmet());
```

Alternatively, manually add headers:
```javascript
app.use((req, res, next) => {
  res.header('X-Content-Type-Options', 'nosniff');
  res.header('X-Frame-Options', 'DENY');
  res.header('X-XSS-Protection', '1; mode=block');
  res.header('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
  next();
});
```

### 5. No Request Size Limits
**Issue:** Application accepts unlimited request sizes → memory exhaustion/DoS
**Solution:**
```javascript
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));
```

### 6. Exposed Sensitive Data
**Issue:** User emails returned without authentication check
**Solution:**
- Implement authentication (JWT, OAuth, etc.)
- Add authorization checks per endpoint
- Only return necessary fields
- Consider data classification/sensitivity levels

### 7. No Path Validation
**Issue:** Path parameters (e.g., `/users/:id`) not validated for format
**Solution:**
```javascript
app.get('/api/users/:id', (req, res, next) => {
  if (!/^\d+$/.test(req.params.id)) {
    return res.status(400).json({ message: 'Invalid ID format' });
  }
  next();
});
```

## 🟡 MEDIUM PRIORITY ISSUES

### 8. Insufficient Logging and Monitoring
**Issue:** Can't track security events or debug issues
**Solution:**
- Use structured logging (Winston, Pino)
- Log security-relevant events
- Monitor for suspicious patterns
- Never log sensitive data (passwords, tokens, PII)

### 9. No CORS Configuration
**Issue:** Unprotected endpoints accessible from any origin
**Solution:**
```javascript
const cors = require('cors');
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || 'http://localhost:3000',
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type']
}));
```

### 10. No Content-Type Validation
**Issue:** Application doesn't validate Content-Type headers
**Solution:**
```javascript
app.use((req, res, next) => {
  if (['POST', 'PUT', 'PATCH'].includes(req.method)) {
    const contentType = req.get('content-type');
    if (!contentType || !contentType.includes('application/json')) {
      return res.status(415).json({ message: 'Unsupported Media Type' });
    }
  }
  next();
});
```

### 11. Error Messages Reveal System Details
**Issue:** Stack traces and internal errors exposed to clients
**Solution:**
```javascript
app.use((err, req, res, next) => {
  console.error(err); // Log internally

  // Send generic response to client
  res.status(500).json({
    success: false,
    message: 'Internal server error'
    // Only in development:
    ...(process.env.NODE_ENV === 'development' && { error: err.message })
  });
});
```

## 🟢 BEST PRACTICES

### 12. Use Consistent Response Format
```javascript
// Success response
{ success: true, data: {...}, pagination: {...} }

// Error response
{ success: false, message: "...", errors: [...] }
```

### 13. Implement API Versioning
```javascript
app.get('/api/v1/users', ...);
app.get('/api/v2/users', ...);
```

### 14. Add Request ID for Tracing
```javascript
const { v4: uuidv4 } = require('uuid');
app.use((req, res, next) => {
  req.id = req.get('x-request-id') || uuidv4();
  res.set('X-Request-ID', req.id);
  next();
});
```

### 15. Implement Graceful Shutdown
```javascript
process.on('SIGTERM', () => {
  server.close(() => {
    console.log('Server closed');
  });
});
```

### 16. Environment-Specific Configuration
```javascript
require('dotenv').config();
const config = {
  PORT: process.env.PORT || 3000,
  NODE_ENV: process.env.NODE_ENV || 'development',
  LOG_LEVEL: process.env.LOG_LEVEL || 'info'
};
