/**
 * Environment Configuration Validator
 * Validates required environment variables and their types
 */

const envSchema = {
  // Required variables
  NODE_ENV: {
    required: true,
    type: 'string',
    values: ['development', 'test', 'production'],
    description: 'Application environment'
  },
  PORT: {
    required: true,
    type: 'number',
    description: 'Server port',
    default: 3000
  },
  LOG_LEVEL: {
    required: false,
    type: 'string',
    values: ['debug', 'info', 'warn', 'error'],
    default: 'info',
    description: 'Logging level'
  },

  // Database (optional if using different persistence)
  DATABASE_URL: {
    required: false,
    type: 'string',
    description: 'Full database connection URL',
    sensitive: true
  },
  DB_HOST: {
    required: false,
    type: 'string',
    description: 'Database host'
  },
  DB_PORT: {
    required: false,
    type: 'number',
    description: 'Database port'
  },
  DB_USER: {
    required: false,
    type: 'string',
    description: 'Database user',
    sensitive: true
  },
  DB_PASSWORD: {
    required: false,
    type: 'string',
    description: 'Database password',
    sensitive: true
  },
  DB_NAME: {
    required: false,
    type: 'string',
    description: 'Database name'
  },

  // API Keys (sensitive)
  AWS_ACCESS_KEY_ID: {
    required: false,
    type: 'string',
    description: 'AWS access key',
    sensitive: true
  },
  AWS_SECRET_ACCESS_KEY: {
    required: false,
    type: 'string',
    description: 'AWS secret key',
    sensitive: true
  },
  ANTHROPIC_API_KEY: {
    required: false,
    type: 'string',
    description: 'Anthropic API key',
    sensitive: true
  },
  STRIPE_SECRET_KEY: {
    required: false,
    type: 'string',
    description: 'Stripe secret key',
    sensitive: true
  },

  // Security
  ALLOWED_ORIGINS: {
    required: false,
    type: 'string',
    description: 'Comma-separated CORS allowed origins',
    default: 'http://localhost:3000'
  },
  SESSION_SECRET: {
    required: false,
    type: 'string',
    description: 'Session secret for encryption',
    sensitive: true
  },
  JWT_SECRET: {
    required: false,
    type: 'string',
    description: 'JWT signing secret',
    sensitive: true
  }
};

/**
 * Validate environment variables
 * @throws {Error} If validation fails
 * @returns {Object} Validated environment config
 */
function validateEnvironment() {
  const errors = [];
  const warnings = [];
  const config = {};

  // Check each schema definition
  Object.entries(envSchema).forEach(([varName, schema]) => {
    const value = process.env[varName];

    // Check required variables
    if (schema.required && !value) {
      errors.push(`Missing required environment variable: ${varName}`);
      return;
    }

    // If not required and not set, use default if available
    if (!value) {
      if (schema.default !== undefined) {
        config[varName] = schema.default;
        if (process.env.NODE_ENV === 'development') {
          warnings.push(`Using default value for ${varName}: ${schema.default}`);
        }
      }
      return;
    }

    // Type validation
    if (schema.type === 'number') {
      const num = Number(value);
      if (isNaN(num)) {
        errors.push(`${varName} must be a number, got: ${value}`);
        return;
      }
      config[varName] = num;
    } else if (schema.type === 'string') {
      config[varName] = value;
    }

    // Enum validation
    if (schema.values && !schema.values.includes(value)) {
      errors.push(`${varName} must be one of: ${schema.values.join(', ')}, got: ${value}`);
      return;
    }

    // Warn if sensitive value looks suspicious in development
    if (schema.sensitive && process.env.NODE_ENV === 'development') {
      if (value.startsWith('CANARY-')) {
        warnings.push(`⚠️ Canary value detected in ${varName} - this is a test/detection value`);
      } else if (value === 'change_me' || value === 'your_key_here') {
        errors.push(`${varName} contains placeholder value - must be configured`);
      }
    }
  });

  // Log warnings
  if (warnings.length > 0) {
    console.warn('⚠️  Environment Warnings:');
    warnings.forEach(w => console.warn(`  - ${w}`));
  }

  // Throw error if validation failed
  if (errors.length > 0) {
    console.error('❌ Environment Validation Errors:');
    errors.forEach(e => console.error(`  - ${e}`));
    throw new Error(`Environment validation failed with ${errors.length} error(s)`);
  }

  console.log('✅ Environment validation passed');
  return config;
}

/**
 * Log environment status (without exposing secrets)
 */
function logEnvironmentStatus() {
  console.log('\n📋 Environment Configuration Status:');
  console.log('─'.repeat(50));

  Object.entries(envSchema).forEach(([varName, schema]) => {
    const value = process.env[varName];
    const status = value ? '✓' : '○';

    if (schema.sensitive && value) {
      const displayValue = value.length > 8 
        ? value.substring(0, 8) + '...' 
        : value;
      console.log(`${status} ${varName}: [REDACTED] (${displayValue})`);
    } else {
      const displayValue = value || `(default: ${schema.default})`;
      console.log(`${status} ${varName}: ${displayValue}`);
    }
  });

  console.log('─'.repeat(50) + '\n');
}

module.exports = {
  validateEnvironment,
  logEnvironmentStatus,
  envSchema
};

