// Improved Express application with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('mongo-sanitize');
const xss = require('xss-clean');
const compression = require('compression');
const validator = require('validator');

const app = express();

// ============================================
// 1. SECURITY MIDDLEWARE
// ============================================

// Helmet helps secure Express apps by setting various HTTP headers
app.use(helmet());

// Rate limiting middleware to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
});

app.use(limiter);

// ============================================
// 2. DATA PARSING & SANITIZATION MIDDLEWARE
// ============================================

// Compression middleware
app.use(compression());

// Body parser middleware with size limits
app.use(express.json({ limit: '10kb' })); // Limit request body size
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Data sanitization against NoSQL injection
app.use(mongoSanitize());

// Data sanitization against XSS attacks
app.use(xss());

// ============================================
// 3. VALIDATION UTILITIES
// ============================================

/**
 * Validates if a value is a valid positive integer
 * @param {string|number} value - The value to validate
 * @returns {boolean} True if valid
 */
const isValidId = (value) => {
  const id = parseInt(value, 10);
  return !isNaN(id) && id > 0;
};

/**
 * Validates if a value is a valid email
 * @param {string} email - The email to validate
 * @returns {boolean} True if valid
 */
const isValidEmail = (email) => {
  if (!email || typeof email !== 'string') return false;
  return validator.isEmail(email);
};

/**
 * Validates if a value is a valid name (alphanumeric and basic punctuation)
 * @param {string} name - The name to validate
 * @returns {boolean} True if valid
 */
const isValidName = (name) => {
  if (!name || typeof name !== 'string') return false;
  return /^[a-zA-Z\s'-]{1,100}$/.test(name.trim());
};

// ============================================
// 4. ROUTES WITH ERROR HANDLING
// ============================================

/**
 * Health check endpoint
 * GET /health
 */
app.get('/health', (req, res, next) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    });
  } catch (error) {
    next(error);
  }
});

/**
 * Get all users endpoint
 * GET /users
 */
app.get('/users', (req, res, next) => {
  try {
    // Mock data - in real apps, this would come from a database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Remove sensitive fields if needed
    const sanitizedUsers = users.map(({ id, name, email }) => ({
      id,
      name,
      email,
    }));

    res.json({
      success: true,
      data: sanitizedUsers,
      count: sanitizedUsers.length,
    });
  } catch (error) {
    next(error);
  }
});

/**
 * Get user by ID endpoint
 * GET /users/:id
 */
app.get('/users/:id', (req, res, next) => {
  try {
    const { id } = req.params;

    // Validate ID parameter
    if (!isValidId(id)) {
      return res.status(400).json({
        success: false,
        error: 'Invalid user ID format',
      });
    }

    // Mock data lookup
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find((u) => u.id === parseInt(id, 10));

    if (!user) {
      return res.status(404).json({
        success: false,
        error: 'User not found',
      });
    }

    res.json({
      success: true,
      data: user,
    });
  } catch (error) {
    next(error);
  }
});

/**
 * Create user endpoint
 * POST /users
 */
app.post('/users', (req, res, next) => {
  try {
    const { name, email } = req.body;

    // Input validation
    const errors = {};

    if (!name) {
      errors.name = 'Name is required';
    } else if (!isValidName(name)) {
      errors.name = 'Name must be 1-100 characters and contain only letters, spaces, hyphens, and apostrophes';
    }

    if (!email) {
      errors.email = 'Email is required';
    } else if (!isValidEmail(email)) {
      errors.email = 'Invalid email format';
    }

    if (Object.keys(errors).length > 0) {
      return res.status(400).json({
        success: false,
        error: 'Validation failed',
        details: errors,
      });
    }

    // Mock user creation
    const newUser = {
      id: Math.floor(Math.random() * 10000),
      name: name.trim(),
      email: email.toLowerCase().trim(),
    };

    res.status(201).json({
      success: true,
      message: 'User created successfully',
      data: newUser,
    });
  } catch (error) {
    next(error);
  }
});

// ============================================
// 5. ROUTE NOT FOUND HANDLER
// ============================================

app.use((req, res) => {
  res.status(404).json({
    success: false,
    error: 'Route not found',
  });
});

// ============================================
// 6. GLOBAL ERROR HANDLER MIDDLEWARE
// ============================================

/**
 * Central error handling middleware
 * Must be defined AFTER all other routes and middleware
 */
app.use((err, req, res, next) => {
  // Log error (in production, use proper logging service)
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method,
  });

  // Determine status code
  const statusCode = err.statusCode || 500;
  const isProduction = process.env.NODE_ENV === 'production';

  // Send error response (don't leak sensitive info in production)
  res.status(statusCode).json({
    success: false,
    error: isProduction ? 'Internal server error' : err.message,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack }),
  });
});

// ============================================
// 7. SERVER STARTUP
// ============================================

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} (Environment: ${process.env.NODE_ENV || 'development'})`);
});

// ============================================
// 8. GRACEFUL SHUTDOWN
// ============================================

// Handle unhandled promise rejections
process.on('unhandledRejection', (err) => {
  console.error('Unhandled Rejection:', err);
  // In production, you should shut down the server
  process.exit(1);
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  process.exit(1);
});

module.exports = app;

