});

// Global error handler
app.use((err, req, res, next) => {
  const status = err.status || 500;
  const message = NODE_ENV === 'production' 
    ? 'Internal Server Error' 
    : err.message;

  console.error(err);
  res.status(status).json({ error: message });
});

// Start server
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} (${NODE_ENV})`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => process.exit(0));
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection:', reason);
  process.exit(1);
});

module.exports = app;
```

### Required Dependencies
Add to `package.json`:
```json
{
  "dependencies": {
    "express": "^4.18.0",
    "helmet": "^7.0.0",
    "express-rate-limit": "^6.7.0",
    "express-validator": "^7.0.0"
  }
}
```

### Summary of Security Improvements
| Issue | Severity | Fix |
|-------|----------|-----|
| No error handling | **High** | Add try-catch + error middleware |
| No input validation | **High** | Use express-validator |
| No rate limiting | **High** | Add express-rate-limit |
| No security headers | **Medium** | Use helmet |
| No request size limits | **Medium** | Configure middleware limits |
| Hardcoded config | **Low** | Use environment variables |

