// Improved application with security best practices and error handling
// Enhanced with input validation, error handling, and security middleware

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');
const app = express();

// ============================================
// 1. SECURITY MIDDLEWARE
// ============================================

// Helmet helps secure Express apps by setting various HTTP headers
app.use(helmet());

// Rate limiting to prevent brute force and DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

// Apply rate limiting to all requests
app.use(limiter);

// ============================================
// 2. BODY PARSER & REQUEST PARSING
// ============================================

// Parse JSON bodies with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// ============================================
// 3. REQUEST LOGGING MIDDLEWARE
// ============================================

app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.path}`);
  next();
});

// ============================================
// 4. ROUTE HANDLERS WITH VALIDATION
// ============================================

// Health check endpoint (no sensitive data)
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString()
    });
  } catch (error) {
    res.status(500).json({ 
      error: 'Internal server error',
      message: process.env.NODE_ENV === 'development' ? error.message : undefined
    });
  }
});

// Get users with query parameter validation
app.get('/users', 
  // Validate query parameters
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be an integer between 1 and 100'),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Offset must be a non-negative integer'),
  (req, res) => {
    try {
      // Check for validation errors
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({ 
          error: 'Validation failed',
          details: errors.array() 
        });
      }

      // Extract and validate query parameters with defaults
      const limit = Math.min(parseInt(req.query.limit, 10) || 10, 100);
      const offset = Math.max(parseInt(req.query.offset, 10) || 0, 0);

      // Sample data - in production, this would come from a database
      const users = [
        { id: 1, name: 'Alice' },
        { id: 2, name: 'Bob' },
      ];

      // Apply pagination
      const paginatedUsers = users.slice(offset, offset + limit);

      res.json({
        data: paginatedUsers,
        pagination: {
          offset,
          limit,
          total: users.length
        }
      });
    } catch (error) {
      console.error('Error in /users endpoint:', error);
      res.status(500).json({ 
        error: 'Internal server error',
        message: process.env.NODE_ENV === 'development' ? error.message : undefined
      });
    }
  }
);

// Example POST endpoint with body validation
app.post('/users',
  // Validate request body
  body('name')
    .trim()
    .notEmpty()
    .withMessage('Name is required')
    .isLength({ min: 2, max: 100 })
    .withMessage('Name must be between 2 and 100 characters')
    .matches(/^[a-zA-Z\s'-]+$/)
    .withMessage('Name contains invalid characters'),
  body('email')
    .trim()
    .isEmail()
    .withMessage('Valid email is required')
    .normalizeEmail(),
  (req, res) => {
    try {
      // Check for validation errors
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({ 
          error: 'Validation failed',
          details: errors.array() 
        });
      }

      // If validation passed, process the request
      const { name, email } = req.body;

      // In production, save to database
      const newUser = {
        id: 3, // Would be generated by database
        name,
        email
      };

      res.status(201).json({
        message: 'User created successfully',
        data: newUser
      });
    } catch (error) {
      console.error('Error in POST /users endpoint:', error);
      res.status(500).json({ 
        error: 'Internal server error',
        message: process.env.NODE_ENV === 'development' ? error.message : undefined
      });
    }
  }
);

// ============================================
// 5. ERROR HANDLING MIDDLEWARE
// ============================================

// 404 handler for undefined routes
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    message: `${req.method} ${req.path} does not exist`,
    timestamp: new Date().toISOString()
  });
});

// Global error handling middleware (must be last)
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Don't leak error details in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  const statusCode = err.statusCode || 500;
  const response = {
    error: err.message || 'Internal server error',
    timestamp: new Date().toISOString()
  };

  // Include stack trace only in development
  if (isDevelopment) {
    response.stack = err.stack;
  }

  res.status(statusCode).json(response);
});

// ============================================
// 6. SERVER STARTUP
// ============================================

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // In production, you might want to log this and exit gracefully
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

