// Improved application with security best practices
// Includes error handling, input validation, and security headers

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const validator = require('validator');
const morgan = require('morgan');

const app = express();

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// 1. Security Headers - Use Helmet.js
app.use(helmet());

// 2. CORS Configuration - Be explicit about trusted origins
const cors = require('cors');
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  optionsSuccessStatus: 200,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
};
app.use(cors(corsOptions));

// 3. Request Logging - Use Morgan for security audit trail
app.use(morgan('combined'));

// 4. Rate Limiting - Prevent abuse and DDoS
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
  skip: (req) => process.env.NODE_ENV === 'test', // Skip rate limiting in tests
});
app.use(limiter);

// 5. Request Size Limits - Prevent payload bomb attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// 6. Input Sanitization - Prevent NoSQL injection and XSS
app.use(mongoSanitize()); // Removes $ and . from keys

// ============================================================================
// INPUT VALIDATION HELPERS
// ============================================================================

/**
 * Validates email format
 * @param {string} email - Email to validate
 * @returns {boolean} - True if valid
 */
const isValidEmail = (email) => {
  return validator.isEmail(email) && email.length <= 255;
};

/**
 * Validates user name
 * @param {string} name - Name to validate
 * @returns {boolean} - True if valid
 */
const isValidName = (name) => {
  return (
    typeof name === 'string' &&
    name.length >= 1 &&
    name.length <= 100 &&
    /^[a-zA-Z\s'-]+$/.test(name) // Only letters, spaces, hyphens, and apostrophes
  );
};

/**
 * Validates positive integer ID
 * @param {any} id - ID to validate
 * @returns {boolean} - True if valid
 */
const isValidId = (id) => {
  const numId = parseInt(id, 10);
  return Number.isInteger(numId) && numId > 0;
};

// ============================================================================
// ROUTES
// ============================================================================

/**
 * Health check endpoint
 */
app.get('/health', (req, res) => {
  try {
    const response = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      environment: process.env.NODE_ENV || 'development',
    };
    res.status(200).json(response);
  } catch (error) {
    res.status(500).json({ error: 'Internal server error' });
  }
});

/**
 * Get all users endpoint
 * Query parameters: limit (optional)
 */
app.get('/users', (req, res, next) => {
  try {
    const limit = req.query.limit ? parseInt(req.query.limit, 10) : 10;

    // Input validation
    if (!Number.isInteger(limit) || limit < 1 || limit > 100) {
      return res.status(400).json({
        error: 'Invalid limit parameter',
        details: 'limit must be an integer between 1 and 100',
      });
    }

    // Mock data - in production, this would come from a database
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const users = allUsers.slice(0, limit);

    res.status(200).json({
      data: users,
      count: users.length,
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    next(error);
  }
});

/**
 * Get specific user by ID
 */
app.get('/users/:id', (req, res, next) => {
  try {
    const { id } = req.params;

    // Input validation
    if (!isValidId(id)) {
      return res.status(400).json({
        error: 'Invalid user ID',
        details: 'ID must be a positive integer',
      });
    }

    // Mock data
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find((u) => u.id === parseInt(id, 10));

    if (!user) {
      return res.status(404).json({
        error: 'Not found',
        details: `User with ID ${id} not found`,
      });
    }

    res.status(200).json({
      data: user,
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    next(error);
  }
});

/**
 * Create new user
 */
app.post('/users', (req, res, next) => {
  try {
    const { name, email } = req.body;

    // Validate required fields
    if (!name || !email) {
      return res.status(400).json({
        error: 'Validation error',
        details: 'name and email are required fields',
      });
    }

    // Validate field formats
    if (!isValidName(name)) {
      return res.status(400).json({
        error: 'Validation error',
        details: 'name must be 1-100 characters and contain only letters, spaces, hyphens, and apostrophes',
      });
    }

    if (!isValidEmail(email)) {
      return res.status(400).json({
        error: 'Validation error',
        details: 'email must be a valid email address (max 255 characters)',
      });
    }

    // In production, check for duplicate emails, save to DB, etc.
    const newUser = {
      id: 3, // This would be generated by the database
      name,
      email,
    };

    res.status(201).json({
      data: newUser,
      message: 'User created successfully',
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    next(error);
  }
});

// ============================================================================
// 404 HANDLER
// ============================================================================

app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    details: `Route ${req.method} ${req.path} does not exist`,
  });
});

// ============================================================================
// GLOBAL ERROR HANDLER (Must be last)
// ============================================================================

app.use((err, req, res, next) => {
  // Log error (in production, use proper logging service)
  console.error('[ERROR]', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method,
    timestamp: new Date().toISOString(),
  });

  // Determine status code
  const statusCode = err.statusCode || 500;

  // Send error response (don't leak internal details in production)
  const isProduction = process.env.NODE_ENV === 'production';
  res.status(statusCode).json({
    error: err.message || 'Internal server error',
    ...(isProduction && statusCode === 500 ? {} : { details: err.details }),
    timestamp: new Date().toISOString(),
  });
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`[SERVER] Running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('[SERVER] SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('[SERVER] Process terminated');
    process.exit(0);
  });
});

module.exports = app;

