## Validation Examples

### Email Validation
```javascript
const validator = require('validator');

// Good - comprehensive validation
const validateEmail = (email) => {
  return (
    typeof email === 'string' &&
    validator.isEmail(email) &&
    email.length <= 255 &&
    !email.includes('..')
  );
};

// Bad - too lenient
const isBadEmail = (email) => {
  return email.includes('@');
};
```

### Name Validation
```javascript
// Good - whitelist allowed characters
const validateName = (name) => {
  return (
    typeof name === 'string' &&
    name.length >= 1 &&
    name.length <= 100 &&
    /^[a-zA-Z\s'-]+$/.test(name)
  );
};

// Test cases
validateName('John Doe');           // ✅ true
validateName("O'Connor");           // ✅ true
validateName('Mary-Jane');          // ✅ true
validateName('John123');            // ❌ false (numbers)
validateName('John@Doe');           // ❌ false (special chars)
validateName('');                   // ❌ false (empty)
```

### Number Validation
```javascript
// Good - explicit type checking
const validateId = (id) => {
  const num = parseInt(id, 10);
  return Number.isInteger(num) && num > 0 && num < 1000000;
};

// Bad - assumes input is valid
const isBadId = (id) => {
  return id > 0;
};

validateId('123');                  // ✅ true
validateId('123abc');               // ❌ false
validateId('-1');                   // ❌ false
validateId('0');                    // ❌ false
```

### Password Validation (When Needed)
```javascript
const validatePassword = (password) => {
  const hasMinLength = password.length >= 12;
  const hasUppercase = /[A-Z]/.test(password);
  const hasLowercase = /[a-z]/.test(password);
  const hasNumbers = /\d/.test(password);
  const hasSpecialChar = /[!@#$%^&*]/.test(password);

  return (
    hasMinLength &&
    hasUppercase &&
    hasLowercase &&
    hasNumbers &&
    hasSpecialChar
  );
};

validatePassword('Pass123!@#');     // ✅ true
validatePassword('password');       // ❌ false (no uppercase, numbers, special)
validatePassword('Pass123');        // ❌ false (no special char)
```

