## Common Mistakes to Avoid

### ❌ Mistake #1: Logging Sensitive Data
```javascript
// BAD
console.log('User registered:', user); // password exposed!

// GOOD
console.log('User registered:', { id: user.id, email: user.email });
```

### ❌ Mistake #2: Trusting Client Input
```javascript
// BAD
app.post('/users', (req, res) => {
  const user = req.body; // No validation
  db.save(user);
});

// GOOD
app.post('/users', (req, res) => {
  const { error, value } = userSchema.validate(req.body);
  if (error) return res.status(400).json({ error });
  db.save(value);
});
```

### ❌ Mistake #3: Generic Error Messages
```javascript
// BAD
res.status(500).json({ error: `Database error: ${err.message}` });

// GOOD
res.status(500).json({ error: 'Internal server error' });
console.error(err); // Log details separately
```

### ❌ Mistake #4: Not Validating IDs
```javascript
// BAD
app.get('/users/:id', (req, res) => {
  db.findById(req.params.id); // Could be anything
});

// GOOD
app.get('/users/:id', (req, res) => {
  if (!isValidId(req.params.id)) {
    return res.status(400).json({ error: 'Invalid ID' });
  }
  db.findById(req.params.id);
});
```

### ❌ Mistake #5: Hardcoding Secrets
```javascript
// BAD
const JWT_SECRET = 'my-secret-key-12345';

// GOOD
const JWT_SECRET = process.env.JWT_SECRET;
```

