## Performance & Security Balance

```javascript
// Trade-off: Security vs Performance
const config = {
  // Strict (slower, more secure)
  strict: {
    rateLimitMax: 10,
    requestSizeLimit: '1kb',
    requestTimeout: 5000
  },

  // Balanced (recommended)
  balanced: {
    rateLimitMax: 100,
    requestSizeLimit: '10kb',
    requestTimeout: 30000
  },

  // Relaxed (faster, less secure)
  relaxed: {
    rateLimitMax: 1000,
    requestSizeLimit: '50kb',
    requestTimeout: 60000
  }
};

// Apply based on endpoint sensitivity
const strictLimiter = rateLimit({ max: config.strict.rateLimitMax });
const balancedLimiter = rateLimit({ max: config.balanced.rateLimitMax });

app.post('/login', strictLimiter, loginHandler);      // Strict
app.get('/users', balancedLimiter, usersHandler);     // Balanced
app.get('/public', balancedLimiter, publicHandler);   // Balanced
```

