// Improved version with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const validator = require('express-validator');
const morgan = require('morgan');
require('dotenv').config();

const app = express();

// ===== SECURITY MIDDLEWARE =====

// Set security HTTP headers
app.use(helmet());

// Request logging for security audit trails
app.use(morgan('combined'));

// Rate limiting - prevent brute force and DDoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
});

app.use(limiter);

// Body parser with size limits - prevent large payload attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// ===== VALIDATION MIDDLEWARE =====

// Custom validation helper
const validateQuery = (req, res, next) => {
  try {
    // Sanitize query parameters
    Object.keys(req.query).forEach(key => {
      if (typeof req.query[key] === 'string') {
        req.query[key] = req.query[key].trim();
      }
    });
    next();
  } catch (error) {
    res.status(400).json({ error: 'Invalid query parameters' });
  }
};

// ===== ERROR HANDLING MIDDLEWARE =====

// Global error handler
const errorHandler = (err, req, res, next) => {
  console.error('Error:', {
    message: err.message,
    status: err.status || 500,
    timestamp: new Date().toISOString(),
    path: req.path,
  });

  const statusCode = err.status || 500;
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(statusCode).json({
    error: {
      message: isDevelopment ? err.message : 'Internal Server Error',
      status: statusCode,
      ...(isDevelopment && { stack: err.stack }),
    },
  });
};

// ===== ROUTES =====

// Health check endpoint - no sensitive data
app.get('/health', (req, res, next) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    });
  } catch (error) {
    next(error);
  }
});

// Users endpoint with validation and error handling
app.get(
  '/users',
  validateQuery,
  [
    validator.query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('limit must be between 1 and 100'),
    validator.query('offset')
      .optional()
      .isInt({ min: 0 })
      .withMessage('offset must be a non-negative integer'),
  ],
  (req, res, next) => {
    try {
      // Check for validation errors
      const errors = validator.validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({ errors: errors.array() });
      }

      const limit = Math.min(parseInt(req.query.limit || 10, 10), 100);
      const offset = parseInt(req.query.offset || 0, 10);

      // Sample data - in production, this would come from a database
      const allUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Implement pagination safely
      const users = allUsers.slice(offset, offset + limit);

      // Only return necessary fields - avoid exposing sensitive data
      const safeUsers = users.map(user => ({
        id: user.id,
        name: user.name,
        // Don't expose email to unauthenticated users in production
      }));

      res.json({
        data: safeUsers,
        pagination: {
          limit,
          offset,
          total: allUsers.length,
        },
      });
    } catch (error) {
      next(error);
    }
  }
);

// Handle 404 errors
app.use((req, res) => {
  res.status(404).json({
    error: {
      message: 'Endpoint not found',
      status: 404,
    },
  });
});

// Error handling middleware (must be last)
app.use(errorHandler);

// ===== SERVER STARTUP =====

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${NODE_ENV} mode`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

