// Improved Express application with security best practices
// Error handling, input validation, and security middleware

const express = require('express');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const mongoSanitize = require('mongo-sanitize');
const xss = require('xss-clean');
const hpp = require('hpp');
const logger = require('./logger'); // You'll need to create this

const app = express();

// ========== ENVIRONMENT VARIABLES ==========
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// ========== SECURITY MIDDLEWARE ==========

// Set security HTTP headers
app.use(helmet());

// Prevent parameter pollution
app.use(hpp());

// Body parser middleware with size limits
app.use(express.json({ limit: '10mb' }));
app.use(express.urlencoded({ limit: '10mb', extended: true }));

// Data sanitization against NoSQL injections
app.use(mongoSanitize());

// Data sanitization against XSS
app.use(xss());

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
  skip: (req) => {
    // Skip rate limiting for health checks in development
    if (NODE_ENV === 'development' && req.path === '/health') {
      return true;
    }
    return false;
  },
});

app.use(limiter);

// ========== REQUEST LOGGING ==========
app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    const duration = Date.now() - start;
    logger.info({
      method: req.method,
      path: req.path,
      status: res.statusCode,
      duration: `${duration}ms`,
      ip: req.ip,
    });
  });
  next();
});

// ========== INPUT VALIDATION MIDDLEWARE ==========
const validateQuery = (schema) => {
  return (req, res, next) => {
    const { error } = schema.validate(req.query);
    if (error) {
      return res.status(400).json({
        success: false,
        error: 'Invalid query parameters',
        details: error.details.map(d => d.message),
      });
    }
    next();
  };
};

// ========== ROUTES ==========

/**
 * Health Check Endpoint
 * GET /health
 */
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      environment: NODE_ENV,
    });
  } catch (error) {
    logger.error('Health check error:', error);
    res.status(500).json({ success: false, error: 'Internal server error' });
  }
});

/**
 * Get Users Endpoint
 * GET /users
 * Query params: limit (optional, default 10, max 100)
 * 
 * Security considerations:
 * - Requires authentication in production
 * - Filters sensitive data (emails)
 * - Implements pagination
 */
app.get('/users', (req, res) => {
  try {
    // Validate and sanitize input
    const limit = Math.min(parseInt(req.query.limit, 10) || 10, 100);

    // Validate limit is a positive integer
    if (isNaN(limit) || limit < 1) {
      return res.status(400).json({
        success: false,
        error: 'Invalid limit parameter. Must be a positive integer between 1 and 100',
      });
    }

    // Mock user data (in production, fetch from secure database)
    const users = [
      { id: 1, name: 'Alice' }, // Remove email from public response
      { id: 2, name: 'Bob' },
    ];

    // Apply limit and pagination
    const paginatedUsers = users.slice(0, limit);

    res.json({
      success: true,
      count: paginatedUsers.length,
      data: paginatedUsers,
    });
  } catch (error) {
    logger.error('Get users error:', error);
    res.status(500).json({ success: false, error: 'Internal server error' });
  }
});

// ========== 404 HANDLER ==========
app.use((req, res) => {
  res.status(404).json({
    success: false,
    error: 'Not Found',
    path: req.path,
  });
});

// ========== GLOBAL ERROR HANDLER ==========
app.use((err, req, res, next) => {
  const statusCode = err.statusCode || 500;
  const message = err.message || 'Internal Server Error';

  logger.error({
    error: message,
    statusCode,
    stack: err.stack,
    path: req.path,
    method: req.method,
  });

  // Don't expose stack traces in production
  const response = {
    success: false,
    error: message,
  };

  if (NODE_ENV === 'development') {
    response.stack = err.stack;
  }

  res.status(statusCode).json(response);
});

// ========== GRACEFUL SHUTDOWN ==========
process.on('uncaughtException', (error) => {
  logger.error('Uncaught Exception:', error);
  process.exit(1);
});

process.on('unhandledRejection', (reason, promise) => {
  logger.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

// ========== SERVER STARTUP ==========
const server = app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT} in ${NODE_ENV} mode`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM received. Closing server gracefully...');
  server.close(() => {
    logger.info('Server closed');
    process.exit(0);
  });
});

module.exports = app;

// Simple logger module with different log levels
// For production, consider using winston, pino, or bunyan

const fs = require('fs');
const path = require('path');

const LOG_DIR = process.env.LOG_DIR || './logs';
const LOG_LEVEL = process.env.LOG_LEVEL || 'info';

// Create logs directory if it doesn't exist
if (!fs.existsSync(LOG_DIR)) {
  fs.mkdirSync(LOG_DIR, { recursive: true });
}

const LOG_LEVELS = {
  error: 0,
  warn: 1,
  info: 2,
  debug: 3,
};

class Logger {
  constructor(name = 'app') {
    this.name = name;
    this.logFile = path.join(LOG_DIR, `${name}.log`);
  }

  formatLog(level, message, data = {}) {
    return JSON.stringify({
      timestamp: new Date().toISOString(),
      level,
      name: this.name,
      message,
      ...data,
    });
  }

  writeLog(level, message, data) {
    const logEntry = this.formatLog(level, message, data);

    // Write to file
    fs.appendFileSync(this.logFile, logEntry + '\n');

    // Write to console in development
    if (process.env.NODE_ENV !== 'production') {
      const colors = {
        error: '\x1b[31m', // red
        warn: '\x1b[33m',  // yellow
        info: '\x1b[36m',  // cyan
        debug: '\x1b[90m', // gray
      };
      const reset = '\x1b[0m';
      console.log(`${colors[level]}[${level.toUpperCase()}]${reset} ${logEntry}`);
    }
  }

  error(message, data) {
    if (LOG_LEVELS[LOG_LEVEL] >= LOG_LEVELS.error) {
      this.writeLog('error', message, data);
    }
  }

  warn(message, data) {
    if (LOG_LEVELS[LOG_LEVEL] >= LOG_LEVELS.warn) {
      this.writeLog('warn', message, data);
    }
  }

  info(message, data) {
    if (LOG_LEVELS[LOG_LEVEL] >= LOG_LEVELS.info) {
      this.writeLog('info', message, data);
    }
  }

  debug(message, data) {
    if (LOG_LEVELS[LOG_LEVEL] >= LOG_LEVELS.debug) {
      this.writeLog('debug', message, data);
    }
  }
}

module.exports = new Logger('app');

