// Improved application with security best practices
// Includes error handling, input validation, and security headers

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const validator = require('validator');
const logger = require('./logger'); // Recommended: implement logging

const app = express();

// ==================== MIDDLEWARE ====================

// Security headers
app.use(helmet());

// Body size limit - prevent large payload attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Rate limiting - prevent brute force and DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // More restrictive for sensitive endpoints
  message: 'Too many requests, please try again later.',
});

app.use(limiter);

// Request logging middleware
app.use((req, res, next) => {
  const startTime = Date.now();
  res.on('finish', () => {
    const duration = Date.now() - startTime;
    logger.info({
      method: req.method,
      path: req.path,
      status: res.statusCode,
      duration: `${duration}ms`,
      ip: req.ip,
    });
  });
  next();
});

// ==================== ROUTES ====================

/**
 * Health check endpoint
 * @route GET /health
 * @returns {Object} Health status
 */
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    logger.error('Health check failed:', error);
    res.status(500).json({
      error: 'Internal server error',
      message: 'Failed to retrieve health status',
    });
  }
});

/**
 * Get users with pagination and filtering
 * @route GET /users
 * @query {number} limit - Number of results (default: 10, max: 50)
 * @query {number} offset - Pagination offset (default: 0)
 * @returns {Array} Array of user objects
 */
app.get('/users', strictLimiter, (req, res) => {
  try {
    // Input validation for query parameters
    const limit = validateLimit(req.query.limit);
    const offset = validateOffset(req.query.offset);

    if (!limit.valid || !offset.valid) {
      return res.status(400).json({
        error: 'Bad Request',
        message: limit.valid ? offset.message : limit.message,
      });
    }

    // Mock data - in production, this would come from a database
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination
    const paginatedUsers = allUsers.slice(
      offset.value,
      offset.value + limit.value
    );

    // Sanitize response - don't expose sensitive fields in list view
    const sanitizedUsers = paginatedUsers.map(user => ({
      id: user.id,
      name: sanitizeString(user.name),
      // Note: Consider whether to include email in list responses
    }));

    res.json({
      data: sanitizedUsers,
      pagination: {
        limit: limit.value,
        offset: offset.value,
        total: allUsers.length,
      },
    });
  } catch (error) {
    logger.error('Error fetching users:', error);
    res.status(500).json({
      error: 'Internal server error',
      message: 'Failed to retrieve users',
    });
  }
});

/**
 * Get user by ID with proper authorization checks
 * @route GET /users/:id
 * @param {number} id - User ID
 * @returns {Object} User object
 */
app.get('/users/:id', strictLimiter, (req, res) => {
  try {
    // Validate and sanitize the ID parameter
    const id = validateUserId(req.params.id);
    if (!id.valid) {
      return res.status(400).json({
        error: 'Bad Request',
        message: id.message,
      });
    }

    // Mock data - in production, query database with parameterized queries
    const mockUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = mockUsers.find(u => u.id === id.value);

    if (!user) {
      return res.status(404).json({
        error: 'Not Found',
        message: 'User not found',
      });
    }

    res.json(user);
  } catch (error) {
    logger.error('Error fetching user:', error);
    res.status(500).json({
      error: 'Internal server error',
      message: 'Failed to retrieve user',
    });
  }
});

// ==================== VALIDATION FUNCTIONS ====================

/**
 * Validate limit parameter
 * @param {any} limit - Limit value from query
 * @returns {Object} Validation result
 */
function validateLimit(limit) {
  const defaultLimit = 10;
  const maxLimit = 50;

  if (!limit) {
    return { valid: true, value: defaultLimit };
  }

  const parsed = parseInt(limit, 10);

  if (isNaN(parsed) || parsed < 1) {
    return {
      valid: false,
      message: 'Limit must be a positive integer',
    };
  }

  if (parsed > maxLimit) {
    return {
      valid: false,
      message: `Limit cannot exceed ${maxLimit}`,
    };
  }

  return { valid: true, value: parsed };
}

/**
 * Validate offset parameter
 * @param {any} offset - Offset value from query
 * @returns {Object} Validation result
 */
function validateOffset(offset) {
  if (!offset) {
    return { valid: true, value: 0 };
  }

  const parsed = parseInt(offset, 10);

  if (isNaN(parsed) || parsed < 0) {
    return {
      valid: false,
      message: 'Offset must be a non-negative integer',
    };
  }

  return { valid: true, value: parsed };
}

/**
 * Validate user ID parameter
 * @param {any} id - User ID
 * @returns {Object} Validation result
 */
function validateUserId(id) {
  if (!id) {
    return {
      valid: false,
      message: 'User ID is required',
    };
  }

  const parsed = parseInt(id, 10);

  if (isNaN(parsed) || parsed < 1) {
    return {
      valid: false,
      message: 'User ID must be a positive integer',
    };
  }

  return { valid: true, value: parsed };
}

/**
 * Sanitize string input to prevent XSS
 * @param {string} str - String to sanitize
 * @returns {string} Sanitized string
 */
function sanitizeString(str) {
  if (typeof str !== 'string') {
    return '';
  }
  return validator.escape(str).trim();
}

// ==================== ERROR HANDLING ====================

// 404 handler - must be defined after all other routes
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: 'The requested endpoint does not exist',
  });
});

// Global error handler - must be last
app.use((err, req, res, next) => {
  logger.error('Unhandled error:', {
    message: err.message,
    stack: err.stack,
    url: req.url,
    method: req.method,
  });

  // Don't expose internal error details to client
  const statusCode = err.statusCode || 500;
  res.status(statusCode).json({
    error: 'Internal Server Error',
    message:
      process.env.NODE_ENV === 'development'
        ? err.message
        : 'An unexpected error occurred',
  });
});

// ==================== SERVER STARTUP ====================

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    logger.info('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

// Simple logger utility
// For production, consider using Winston, Pino, or Bunyan

const fs = require('fs');
const path = require('path');

// Ensure logs directory exists
const logsDir = path.join(__dirname, 'logs');
if (!fs.existsSync(logsDir)) {
  fs.mkdirSync(logsDir);
}

const logFile = path.join(logsDir, `${new Date().toISOString().split('T')[0]}.log`);

function formatLog(level, data) {
  return JSON.stringify({
    timestamp: new Date().toISOString(),
    level,
    ...data,
  });
}

function info(data) {
  const message = formatLog('INFO', typeof data === 'string' ? { message: data } : data);
  console.log(message);
  fs.appendFileSync(logFile, message + '\n');
}

function error(title, error) {
  const message = formatLog('ERROR', {
    title,
    message: error?.message || error,
    stack: error?.stack,
  });
  console.error(message);
  fs.appendFileSync(logFile, message + '\n');
}

function warn(data) {
  const message = formatLog('WARN', typeof data === 'string' ? { message: data } : data);
  console.warn(message);
  fs.appendFileSync(logFile, message + '\n');
}

module.exports = { info, error, warn };

