// Improved application with security best practices
// Includes error handling, input validation, and security measures

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, validationResult, query } = require('express-validator');
const morgan = require('morgan');

const app = express();

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// 1. Set security HTTP headers
app.use(helmet());

// 2. Request logging (non-error requests only)
app.use(morgan('combined'));

// 3. Request size limits - prevent large payload attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 4. Rate limiting - prevent DoS and brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // stricter limit for auth endpoints
  skipSuccessfulRequests: true, // don't count successful requests
});

app.use('/health', limiter);
app.use('/users', limiter);

// ============================================================================
// ERROR HANDLING MIDDLEWARE (must come before routes)
// ============================================================================

// Global error handler for uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('UNCAUGHT EXCEPTION:', error);
  process.exit(1);
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('UNHANDLED REJECTION at:', promise, 'reason:', reason);
  process.exit(1);
});

// ============================================================================
// ROUTES WITH VALIDATION AND ERROR HANDLING
// ============================================================================

/**
 * Health check endpoint - No sensitive data
 * GET /health
 */
app.get('/health', (req, res, next) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    next(error);
  }
});

/**
 * Get users endpoint - With input validation
 * GET /users
 * Query Parameters:
 *   - skip (optional): number of records to skip (default: 0)
 *   - limit (optional): number of records to return (default: 10, max: 100)
 *   - email (optional): filter by email (basic security concern - see notes)
 */
app.get(
  '/users',
  [
    // Input validation middleware
    query('skip')
      .optional()
      .isInt({ min: 0, max: 10000 })
      .withMessage('skip must be a non-negative integer up to 10000'),
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('limit must be between 1 and 100'),
    query('email')
      .optional()
      .isEmail()
      .normalizeEmail()
      .withMessage('email must be a valid email address'),
  ],
  (req, res, next) => {
    try {
      // Check for validation errors
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({
          success: false,
          errors: errors.array().map(err => ({
            field: err.param,
            message: err.msg
          }))
        });
      }

      // Extract and sanitize query parameters
      const skip = Math.min(parseInt(req.query.skip || 0), 10000);
      const limit = Math.min(parseInt(req.query.limit || 10), 100);
      const emailFilter = req.query.email ? req.query.email.toLowerCase() : null;

      // Mock database - replace with actual database query
      const allUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Apply filters
      let filteredUsers = allUsers;
      if (emailFilter) {
        filteredUsers = allUsers.filter(u => u.email === emailFilter);
      }

      // Apply pagination
      const paginatedUsers = filteredUsers.slice(skip, skip + limit);

      // Return sanitized response (consider if email should be public)
      res.json({
        success: true,
        data: paginatedUsers.map(u => ({
          id: u.id,
          name: u.name,
          // SECURITY NOTE: Consider if email should be exposed publicly
          // Remove in production if not needed
          email: u.email
        })),
        pagination: {
          skip,
          limit,
          total: filteredUsers.length
        }
      });
    } catch (error) {
      next(error);
    }
  }
);

// ============================================================================
// 404 AND ERROR HANDLING
// ============================================================================

// 404 handler - must come after all routes
app.use((req, res) => {
  res.status(404).json({
    success: false,
    error: 'Not Found',
    message: `The requested endpoint ${req.method} ${req.path} does not exist`
  });
});

// Global error handler middleware - must be last
app.use((error, req, res, next) => {
  // Log error details for debugging (don't expose to client)
  console.error('ERROR:', {
    message: error.message,
    stack: error.stack,
    url: req.originalUrl,
    method: req.method,
    ip: req.ip
  });

  // Determine status code
  const status = error.status || error.statusCode || 500;

  // Prepare error response (don't expose stack traces in production)
  const response = {
    success: false,
    error: error.name || 'Internal Server Error',
    message: process.env.NODE_ENV === 'production' 
      ? 'An internal server error occurred' 
      : error.message
  };

  // Add stack trace only in development
  if (process.env.NODE_ENV !== 'production') {
    response.stack = error.stack;
  }

  res.status(status).json(response);
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;

if (require.main === module) {
  const server = app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  });

  // Graceful shutdown
  process.on('SIGTERM', () => {
    console.log('SIGTERM received, shutting down gracefully...');
    server.close(() => {
      console.log('Server closed');
      process.exit(0);
    });
  });
}

module.exports = app;

# Security Review & Improvements for app.js

## Executive Summary
The original application lacks critical security measures for production use, including input validation, error handling, rate limiting, and security headers.

---

## Critical Issues & Recommendations

### 1. ❌ NO INPUT VALIDATION
**Issue:** Query and request parameters are not validated
```javascript
// VULNERABLE
app.get('/users', (req, res) => {
  // No validation of req.query parameters
});
```

**Risk Level:** HIGH
- Integer overflow attacks
- NoSQL injection (if using NoSQL)
- Type confusion vulnerabilities

**Fix:**
```javascript
// SECURE
app.get('/users', [
  query('skip').optional().isInt({ min: 0, max: 10000 }),
  query('limit').optional().isInt({ min: 1, max: 100 }),
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  // Safe to use validated parameters
});
```

---

### 2. ❌ MISSING ERROR HANDLING
**Issue:** No try-catch blocks or global error handler
```javascript
// VULNERABLE - unhandled exceptions crash the app
app.get('/users', (req, res) => {
  res.json([...]); // If this throws, no error handler
});
```

**Risk Level:** HIGH
- Application crashes on errors
- Stack traces exposed to clients
- Information leakage (database errors, file paths, etc.)

**Fix:** Implement comprehensive error handling:
- Try-catch blocks in route handlers
- Global error middleware
- Separate error handling for development vs production
- Error logging for debugging

---

### 3. ❌ NO RATE LIMITING
**Issue:** Endpoints are unprotected against DoS and brute force attacks

**Risk Level:** HIGH
- Distributed Denial of Service (DDoS) attacks
- Account enumeration attacks
- Resource exhaustion

**Fix:**
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // 100 requests per IP
});

app.get('/users', limiter, (req, res) => { ... });
```

---

### 4. ❌ MISSING SECURITY HEADERS
**Issue:** No HTTP security headers configured

**Risk Level:** MEDIUM
- Clickjacking attacks (X-Frame-Options missing)
- XSS attacks (X-Content-Type-Options missing)
- MIME sniffing attacks
- Insufficient CORS protection

**Fix:**
```javascript
const helmet = require('helmet');
app.use(helmet()); // Sets 15+ security headers

// Additional configuration if needed:
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
  },
}));
```

---

### 5. ❌ NO REQUEST SIZE LIMITS
**Issue:** Unlimited request body size

**Risk Level:** MEDIUM
- Memory exhaustion attacks
- Large payload DOS attacks
- File upload bombs

**Fix:**
```javascript
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));
```

---

### 6. ❌ NO AUTHENTICATION/AUTHORIZATION
**Issue:** Sensitive user data exposed without access control

**Risk Level:** CRITICAL
- Unauthorized access to user information
- Potential privacy violations
- Data breach exposure

**Fix:**
```javascript
// Add authentication middleware
const authenticateToken = (req, res, next) => {
  const token = req.headers['authorization']?.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'Unauthorized' });

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (error) {
    res.status(403).json({ error: 'Forbidden' });
  }
};

app.get('/users', authenticateToken, (req, res) => { ... });
```

---

### 7. ❌ NO LOGGING/MONITORING
**Issue:** No request logging for security auditing

**Risk Level:** MEDIUM
- Cannot detect suspicious activity
- No audit trail for compliance
- Difficult to investigate security incidents

**Fix:**
```javascript
const morgan = require('morgan');
app.use(morgan('combined')); // Log all requests
```

---

### 8. ❌ EXPOSED SENSITIVE DATA
**Issue:** Email addresses returned without protection consideration

**Risk Level:** MEDIUM
- Privacy concerns
- Information useful for targeted attacks
- Potential GDPR/privacy law violations

**Recommendation:**
```javascript
// Evaluate if email needs to be public
res.json({
  data: users.map(u => ({
    id: u.id,
    name: u.name,
    // Remove email if not essential
    email: u.email
  }))
});
```

---

### 9. ❌ NO GRACEFUL SHUTDOWN
**Issue:** Server doesn't handle graceful termination

**Risk Level:** LOW
- Data loss on pending requests
- Incomplete database operations

**Fix:**
```javascript
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

process.on('SIGTERM', () => {
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});
```

---

## Dependencies to Install

```bash
npm install express helmet express-rate-limit express-validator morgan
```

**Package Purposes:**
- **helmet**: Sets 15+ security headers
- **express-rate-limit**: Prevents DoS and brute force attacks
- **express-validator**: Input validation and sanitization
- **morgan**: HTTP request logging

