// Improved application with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, validationResult, query } = require('express-validator');
const cors = require('cors');
const morgan = require('morgan');
const app = express();

// ============================================
// 1. SECURITY MIDDLEWARE
// ============================================

// Set security HTTP headers
app.use(helmet());

// CORS configuration - restrict to trusted origins
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST'],
  maxAge: 600
};
app.use(cors(corsOptions));

// Body parser with size limits to prevent payload attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// Request logging
app.use(morgan('combined'));

// ============================================
// 2. RATE LIMITING
// ============================================

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
});

// Stricter rate limiter for public endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10,
  message: 'Too many requests, please try again later.',
});

app.use('/health', limiter);
app.use('/users', strictLimiter);

// ============================================
// 3. INPUT VALIDATION MIDDLEWARE
// ============================================

// Validation for /users endpoint query parameters
const validateUserQuery = [
  query('id')
    .optional()
    .isInt({ min: 1 })
    .withMessage('ID must be a positive integer'),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Offset must be a non-negative integer'),
];

// ============================================
// 4. ERROR HANDLING MIDDLEWARE
// ============================================

// Middleware to handle validation errors
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      success: false,
      errors: errors.array().map(err => ({
        field: err.param,
        message: err.msg
      }))
    });
  }
  next();
};

// ============================================
// 5. ROUTES
// ============================================

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({
      success: true,
      status: 'ok',
      timestamp: new Date().toISOString()
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({
      success: false,
      message: 'Internal server error'
    });
  }
});

// Mock user database (in production, use a real database)
const mockUsers = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
];

// Get users endpoint with validation
app.get('/users', validateUserQuery, handleValidationErrors, (req, res) => {
  try {
    const { id, limit = 10, offset = 0 } = req.query;

    let users = mockUsers;

    // Filter by ID if provided
    if (id) {
      const userId = parseInt(id, 10);
      users = users.filter(user => user.id === userId);

      if (users.length === 0) {
        return res.status(404).json({
          success: false,
          message: 'User not found'
        });
      }
    }

    // Apply pagination
    const paginatedUsers = users.slice(offset, offset + limit);

    res.json({
      success: true,
      data: paginatedUsers,
      total: users.length,
      limit: parseInt(limit, 10),
      offset: parseInt(offset, 10)
    });
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({
      success: false,
      message: 'Internal server error'
    });
  }
});

// ============================================
// 6. 404 HANDLER
// ============================================

app.use((req, res) => {
  res.status(404).json({
    success: false,
    message: 'Endpoint not found'
  });
});

// ============================================
// 7. GLOBAL ERROR HANDLER
// ============================================

app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Don't expose error details in production
  const isDevelopment = process.env.NODE_ENV !== 'production';

  res.status(err.status || 500).json({
    success: false,
    message: isDevelopment ? err.message : 'Internal server error',
    ...(isDevelopment && { stack: err.stack })
  });
});

// ============================================
// 8. SERVER STARTUP
// ============================================

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

# Security Review: app.js - Detailed Analysis & Recommendations

## Executive Summary
The original `app.js` is a minimal Express server lacking critical security controls. It has no input validation, error handling, rate limiting, or security headers. These gaps expose the application to common vulnerabilities including injection attacks, DoS, information disclosure, and unhandled exceptions.

---

## 1. ERROR HANDLING

### Current Issues
```javascript
// ❌ NO ERROR HANDLING
app.get('/users', (req, res) => {
  res.json([...]);
});
```

### Risks
- Unhandled exceptions crash the server
- No way to debug issues
- Poor user experience
- Security vulnerabilities may not be detected

### Improvements
✅ Add try-catch blocks in route handlers
✅ Implement global error handling middleware
✅ Add 404 handler for undefined routes
✅ Graceful shutdown handling
✅ Structured logging with winston or morgan

**Example:**
```javascript
app.get('/users', (req, res) => {
  try {
    // logic here
  } catch (error) {
    console.error('Error:', error);
    res.status(500).json({ success: false, message: 'Internal server error' });
  }
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);
  res.status(err.status || 500).json({
    success: false,
    message: process.env.NODE_ENV === 'production' ? 'Internal server error' : err.message
  });
});
```

---

## 2. INPUT VALIDATION

### Current Issues
```javascript
// ❌ NO INPUT VALIDATION
app.get('/users', (req, res) => {
  res.json([...]); // No validation of query parameters
});
```

### Risks
- **Injection Attacks**: Malicious payloads could be passed through query parameters
- **Type Confusion**: Unexpected data types cause errors
- **Business Logic Bypass**: Invalid data affects application behavior
- **NoSQL/SQL Injection**: In databases (future)

### Improvements
✅ Validate all input (query params, body, headers)
✅ Use established libraries: `express-validator` or `joi`
✅ Sanitize input to remove malicious content
✅ Enforce strict data types
✅ Set reasonable limits (string length, number ranges)

**Example:**
```javascript
const { query, validationResult } = require('express-validator');

const validateUserQuery = [
  query('id')
    .optional()
    .isInt({ min: 1 })
    .withMessage('ID must be a positive integer'),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),
];

app.get('/users', validateUserQuery, (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  // Process request
});
```

---

## 3. SECURITY HEADERS

### Current Issues
```javascript
// ❌ NO SECURITY HEADERS
app.get('/users', (req, res) => {
  res.json([...]); // Missing: X-Content-Type-Options, X-Frame-Options, etc.
});
```

### Risks
- **XSS Attacks**: No Content-Security-Policy header
- **Clickjacking**: No X-Frame-Options
- **MIME Sniffing**: No X-Content-Type-Options
- **Insufficient Transport Security**: No HSTS

### Improvements
✅ Use `helmet.js` middleware to set security headers automatically

**Example:**
```javascript
const helmet = require('helmet');
app.use(helmet()); // Sets ~15 security headers

// Custom headers if needed
app.use((req, res, next) => {
  res.setHeader('X-Custom-Header', 'value');
  next();
});
```

**Headers set by Helmet:**
- `Content-Security-Policy`
- `X-Content-Type-Options: nosniff`
- `X-Frame-Options: DENY`
- `X-XSS-Protection: 1; mode=block`
- `Strict-Transport-Security`
- And more...

---

## 4. RATE LIMITING

### Current Issues
```javascript
// ❌ NO RATE LIMITING
app.get('/users', (req, res) => {
  res.json([...]); // Endpoint can be called unlimited times
});
```

### Risks
- **Brute Force Attacks**: Attackers can try unlimited password/token combinations
- **Denial of Service (DoS)**: Overwhelming the server with requests
- **Resource Exhaustion**: Database overload, memory issues
- **Economic Impact**: Expensive operations without limits

### Improvements
✅ Use `express-rate-limit` middleware
✅ Different rate limits for different endpoints
✅ Implement based on IP, user ID, or API key
✅ Return standard rate limit headers

**Example:**
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                   // 100 requests per window
  message: 'Too many requests',
  standardHeaders: true,      // Return info in RateLimit-* headers
  legacyHeaders: false,       // Disable X-RateLimit-* headers
});

app.use('/users', limiter);
```

---

## 5. SENSITIVE DATA EXPOSURE

### Current Issues
```javascript
// ❌ EXPOSING SENSITIVE DATA
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' }, // Email exposed!
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

### Risks
- **Information Disclosure**: Email addresses can be harvested
- **Privacy Violations**: GDPR/CCPA non-compliance
- **Targeted Attacks**: Attackers have personal information
- **No Access Control**: Endpoint is completely public

### Improvements
✅ Implement authentication (JWT, OAuth, sessions)
✅ Implement authorization (role-based access)
✅ Don't expose sensitive fields unnecessarily
✅ Use database-level access controls

**Example:**
```javascript
const authenticate = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];
  if (!token) {
    return res.status(401).json({ success: false, message: 'Unauthorized' });
  }
  // Verify token
  next();
};

app.get('/users', authenticate, (req, res) => {
  const users = mockUsers.map(u => ({
    id: u.id,
    name: u.name
    // Don't include email unless necessary
  }));
  res.json({ success: true, data: users });
});
```

---

## 6. CORS (Cross-Origin Resource Sharing)

### Current Issues
```javascript
// ❌ NO CORS CONFIGURATION
// All origins can access the API
```

### Risks
- **Cross-Site Attacks**: Malicious websites can make requests
- **Credential Theft**: Cookies/tokens sent to unauthorized origins
- **Data Leakage**: Sensitive data accessible to cross-origin requests

### Improvements
✅ Use `cors` middleware
✅ Restrict to trusted origins
✅ Limit allowed methods
✅ Control credential sharing

**Example:**
```javascript
const cors = require('cors');

const corsOptions = {
  origin: ['https://trusted-domain.com', 'http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST'],
  maxAge: 600 // 10 minutes
};

app.use(cors(corsOptions));
```

---

## 7. PAYLOAD SIZE LIMITS

### Current Issues
```javascript
// ❌ NO PAYLOAD SIZE LIMIT
app.use(express.json()); // Can accept unlimited data
```

### Risks
- **Memory Exhaustion**: Large payloads exhaust server memory
- **DoS Attacks**: Attacker sends huge requests to crash server
- **Slow Client Attacks**: Gradually send large payloads

### Improvements
✅ Set reasonable limits on request size
✅ Set timeout limits

**Example:**
```javascript
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));
app.use(express.text({ limit: '10kb' }));
```

---

## 8. LOGGING & MONITORING

### Current Issues
```javascript
// ❌ MINIMAL LOGGING
app.listen(3000, () => {
  console.log('Server running on port 3000');
});
```

### Risks
- **No Audit Trail**: Cannot track what happened
- **Security Blind**: Can't detect attacks
- **Debugging Impossible**: Hard to diagnose issues
- **Compliance Issues**: No evidence for audits

### Improvements
✅ Use structured logging (Winston, Bunyan, Pino)
✅ Log all requests (use Morgan)
✅ Log errors with context
✅ Implement log rotation
✅ Centralize logs (ELK, CloudWatch, etc.)

**Example:**
```javascript
const morgan = require('morgan');
const winston = require('winston');

// Request logging
app.use(morgan('combined'));

// Error logging
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

app.use((err, req, res, next) => {
  logger.error({
    message: err.message,
    stack: err.stack,
    url: req.url,
    method: req.method,
  });
  res.status(500).json({ success: false, message: 'Internal server error' });
});
```

