// Improved application with security best practices and error handling
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const { body, query, validationResult } = require('express-validator');

const app = express();

// ============ SECURITY MIDDLEWARE ============

// Set security HTTP headers
app.use(helmet());

// CORS configuration - be explicit about allowed origins
app.use((req, res, next) => {
  res.header('Access-Control-Allow-Origin', process.env.ALLOWED_ORIGINS || 'http://localhost:3000');
  res.header('Access-Control-Allow-Methods', 'GET, OPTIONS');
  res.header('Access-Control-Allow-Headers', 'Content-Type, Authorization');
  next();
});

// Rate limiting - prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

app.use(limiter);

// Request logging
app.use(morgan(process.env.LOG_FORMAT || 'combined'));

// Body parser middleware
app.use(express.json({ limit: '10kb' })); // Limit payload size
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// ============ INPUT VALIDATION MIDDLEWARE ============

/**
 * Middleware to validate and sanitize request data
 */
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation Error',
      details: errors.array().map(err => ({
        field: err.param,
        message: err.msg
      }))
    });
  }
  next();
};

// ============ ROUTES ============

/**
 * Health check endpoint
 * GET /health
 */
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    res.status(500).json({
      error: 'Failed to generate health check response'
    });
  }
});

/**
 * Get users endpoint with optional filtering
 * GET /users?role=admin&limit=10
 * NOTE: In production, implement proper authentication and authorization
 */
app.get(
  '/users',
  [
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('limit must be an integer between 1 and 100'),
    query('offset')
      .optional()
      .isInt({ min: 0 })
      .withMessage('offset must be a non-negative integer'),
    query('role')
      .optional()
      .isIn(['user', 'admin'])
      .withMessage('role must be either "user" or "admin"')
  ],
  validateRequest,
  (req, res) => {
    try {
      const limit = parseInt(req.query.limit, 10) || 10;
      const offset = parseInt(req.query.offset, 10) || 0;

      // Sample data - in production use a database
      const allUsers = [
        { id: 1, name: 'Alice', role: 'admin' },
        { id: 2, name: 'Bob', role: 'user' },
      ];

      // Filter by role if provided
      let users = allUsers;
      if (req.query.role) {
        users = users.filter(u => u.role === req.query.role);
      }

      // Apply pagination
      const paginatedUsers = users.slice(offset, offset + limit);

      res.json({
        data: paginatedUsers,
        total: users.length,
        limit,
        offset
      });
    } catch (error) {
      console.error('Error retrieving users:', error);
      res.status(500).json({
        error: 'Internal Server Error',
        requestId: req.id // Add unique request ID for debugging
      });
    }
  }
);

// ============ ERROR HANDLING ============

/**
 * 404 Not Found handler
 */
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    path: req.path,
    method: req.method
  });
});

/**
 * Global error handler middleware
 * Must be defined last
 */
app.use((err, req, res, next) => {
  // Don't expose error details in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  console.error('Unhandled error:', {
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    timestamp: new Date().toISOString()
  });

  const statusCode = err.statusCode || err.status || 500;
  const message = isDevelopment ? err.message : 'Internal Server Error';

  res.status(statusCode).json({
    error: err.name || 'Error',
    message,
    ...(isDevelopment && { stack: err.stack })
  });
});

// ============ SERVER STARTUP ============

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';

const server = app.listen(PORT, HOST, () => {
  console.log(`Server running on http://${HOST}:${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // In production, might want to exit or alert monitoring
});

module.exports = app;

