# Security Review: app.js

## Overview
This document provides a comprehensive security review of app.js with focus on error handling, input validation, and security best practices.

---

## Current Issues & Recommendations

### 🔴 CRITICAL ISSUES

#### 1. **No Input Validation**
**Issue:** Query parameters and request bodies are not validated or sanitized.
```javascript
// Current code has no validation
app.get('/users', (req, res) => {
  res.json([...]);
});
```

**Risk:** Attackers could exploit unvalidated inputs for injection attacks.

**Recommendation:** Implement schema validation
```javascript
const { query, validationResult } = require('express-validator');

app.get('/users', 
  query('id').optional().isInt().withMessage('ID must be an integer'),
  query('email').optional().isEmail().withMessage('Invalid email format'),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    res.json([...]);
  }
);
```

---

#### 2. **No Error Handling Middleware**
**Issue:** The application has no centralized error handling.
- Unhandled exceptions will crash the server
- No error logging
- No standardized error responses

**Recommendation:** Add comprehensive error handling
```javascript
// Error handling middleware (add at the end, before listen)
app.use((err, req, res, next) => {
  console.error(err.stack);

  const status = err.status || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal Server Error' 
    : err.message;

  res.status(status).json({
    error: {
      message,
      status,
      requestId: req.id
    }
  });
});
```

---

### 🟡 HIGH PRIORITY ISSUES

#### 3. **Missing Security Headers**
**Issue:** No security headers configured (CORS, HSTS, CSP, etc.)

**Recommendation:** Add security headers using helmet middleware
```javascript
const helmet = require('helmet');

app.use(helmet());  // Sets multiple security headers
app.use(express.json({ limit: '10kb' }));  // Limit payload size

// CORS configuration
const cors = require('cors');
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || 'localhost',
  credentials: true,
  optionsSuccessStatus: 200
}));
```

---

#### 4. **No Request Rate Limiting**
**Issue:** Application is vulnerable to DoS attacks.

**Recommendation:** Implement rate limiting
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,  // 15 minutes
  max: 100,                   // 100 requests per window
  message: 'Too many requests, please try again later.',
  standardHeaders: true,      // Return rate limit info in headers
  legacyHeaders: false,
});

app.use(limiter);

// Stricter limit for auth endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: 'Too many login attempts',
});

app.post('/login', authLimiter, (req, res) => {
  // ...
});
```

---

#### 5. **No Logging System**
**Issue:** No structured logging for security audits and debugging.

**Recommendation:** Implement structured logging
```javascript
const winston = require('winston');

const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.json(),
  defaultMeta: { service: 'app' },
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple()
  }));
}
```

---

#### 6. **Hardcoded Sensitive Data**
**Issue:** Port number and potential future secrets hardcoded in source.

**Recommendation:** Use environment variables
```javascript
require('dotenv').config();

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${NODE_ENV} mode`);
});
```

---

### 🟢 MEDIUM PRIORITY ISSUES

#### 7. **No Request ID/Tracing**
**Issue:** Difficult to trace requests for debugging and security investigations.

**Recommendation:** Add request ID middleware
```javascript
const { v4: uuidv4 } = require('uuid');

app.use((req, res, next) => {
  req.id = req.headers['x-request-id'] || uuidv4();
  res.setHeader('X-Request-ID', req.id);
  next();
});
```

---

#### 8. **No Authentication/Authorization**
**Issue:** `/users` endpoint is publicly accessible without authentication.

**Recommendation:** Add authentication middleware
```javascript
const jwt = require('jsonwebtoken');

const authenticate = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'No token provided' });
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (err) {
    return res.status(403).json({ error: 'Invalid token' });
  }
};

app.get('/users', authenticate, (req, res) => {
  // Only authenticated users can access
  res.json([...]);
});
```

---

#### 9. **No Input Size Limits**
**Issue:** Attackers could send extremely large payloads.

**Recommendation:** Set limits
```javascript
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));
```

---

#### 10. **No Health Check Validation**
**Issue:** Health endpoint doesn't validate dependencies.

**Recommendation:** Enhanced health check
```javascript
app.get('/health', (req, res) => {
  try {
    // Validate database connection, cache, etc.
    const health = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      environment: process.env.NODE_ENV,
      version: require('./package.json').version
    };

    res.status(200).json(health);
  } catch (error) {
    logger.error('Health check failed', error);
    res.status(503).json({ status: 'error', message: 'Service unavailable' });
  }
});
```

---

## Improved app.js Implementation

Here's a refactored version incorporating security best practices:

```javascript
require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { v4: uuidv4 } = require('uuid');
const winston = require('winston');
const { query, validationResult } = require('express-validator');

// Logger setup
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.json(),
  defaultMeta: { service: 'app' },
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple()
  }));
}

const app = express();

// Security Middleware
app.use(helmet());

app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || 'localhost',
  credentials: true,
  optionsSuccessStatus: 200
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: 'Too many requests, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);

// Body parser with limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Request ID middleware
app.use((req, res, next) => {
  req.id = req.headers['x-request-id'] || uuidv4();
  res.setHeader('X-Request-ID', req.id);

  logger.info('Incoming request', {
    method: req.method,
    path: req.path,
    requestId: req.id
  });

  next();
});

// Health endpoint
app.get('/health', (req, res) => {
  try {
    const health = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      environment: process.env.NODE_ENV
    };

    res.status(200).json(health);
  } catch (error) {
    logger.error('Health check failed', { error, requestId: req.id });
    res.status(503).json({ 
      status: 'error', 
      message: 'Service unavailable',
      requestId: req.id
    });
  }
});

// Users endpoint with validation
app.get('/users', 
  query('id').optional().isInt().withMessage('ID must be an integer'),
  query('email').optional().isEmail().withMessage('Invalid email format'),
  (req, res, next) => {
    try {
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        logger.warn('Validation error', { 
          errors: errors.array(), 
          requestId: req.id 
        });
        return res.status(400).json({ 
          errors: errors.array(),
          requestId: req.id
        });
      }

      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Filter by query params if provided
      let result = users;
      if (req.query.id) {
        result = result.filter(u => u.id === parseInt(req.query.id));
      }
      if (req.query.email) {
        result = result.filter(u => u.email === req.query.email);
      }

      res.json(result);
    } catch (error) {
      next(error);
    }
  }
);

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    path: req.path,
    requestId: req.id
  });
});

// Error handling middleware (must be last)
app.use((err, req, res, next) => {
  logger.error('Unhandled error', {
    error: err.message,
    stack: err.stack,
    requestId: req.id
  });

  const status = err.status || err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal Server Error' 
    : err.message;

  res.status(status).json({
    error: {
      message,
      status,
      requestId: req.id
    }
  });
});

// Server startup
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

const server = app.listen(PORT, () => {
  logger.info(`Server started`, {
    port: PORT,
    environment: NODE_ENV,
    nodeVersion: process.version
  });
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM received, shutting down gracefully');
  server.close(() => {
    logger.info('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  logger.info('SIGINT received, shutting down gracefully');
  server.close(() => {
    logger.info('Server closed');
    process.exit(0);
  });
});

module.exports = app;
