// Enhanced application with security best practices
// Error handling, input validation, and security hardening

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');
const morgan = require('morgan');
const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// Security headers
app.use(helmet());

// Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

app.use(limiter);

// Logging middleware (use 'combined' for more details in production)
app.use(morgan('dev'));

// Body parser with size limits to prevent large payload attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// ============================================
// CUSTOM ERROR HANDLING MIDDLEWARE
// ============================================

// Validation error handler
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      success: false,
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.param,
        message: err.msg
      }))
    });
  }
  next();
};

// ============================================
// ROUTES WITH INPUT VALIDATION
// ============================================

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({
      success: false,
      error: 'Internal server error'
    });
  }
});

// Users endpoint with validation
app.get('/users',
  // Input validation
  query('filter').optional().trim().isLength({ min: 1, max: 50 })
    .withMessage('Filter must be between 1 and 50 characters'),
  query('limit').optional().isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),
  handleValidationErrors,
  (req, res) => {
    try {
      const { filter, limit = 10 } = req.query;

      // Mock user data (in production, this would come from a database)
      let users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Apply filter if provided
      if (filter) {
        users = users.filter(user =>
          user.name.toLowerCase().includes(filter.toLowerCase()) ||
          user.email.toLowerCase().includes(filter.toLowerCase())
        );
      }

      // Apply limit
      users = users.slice(0, Math.min(parseInt(limit), 100));

      res.json({
        success: true,
        data: users,
        count: users.length
      });
    } catch (error) {
      console.error('Error fetching users:', error);
      res.status(500).json({
        success: false,
        error: 'Failed to retrieve users'
      });
    }
  }
);

// POST endpoint example with validation
app.post('/users',
  // Input validation
  body('name')
    .trim()
    .notEmpty().withMessage('Name is required')
    .isLength({ min: 2, max: 100 }).withMessage('Name must be between 2 and 100 characters')
    .matches(/^[a-zA-Z\s'-]+$/).withMessage('Name contains invalid characters'),
  body('email')
    .trim()
    .notEmpty().withMessage('Email is required')
    .isEmail().withMessage('Invalid email format')
    .normalizeEmail(),
  handleValidationErrors,
  (req, res) => {
    try {
      const { name, email } = req.body;

      // Additional server-side validation
      if (!name || !email) {
        return res.status(400).json({
          success: false,
          error: 'Missing required fields: name, email'
        });
      }

      // In production, save to database with error handling
      const newUser = {
        id: 3,
        name,
        email,
        createdAt: new Date().toISOString()
      };

      res.status(201).json({
        success: true,
        message: 'User created successfully',
        data: newUser
      });
    } catch (error) {
      console.error('Error creating user:', error);
      res.status(500).json({
        success: false,
        error: 'Failed to create user'
      });
    }
  }
);

// ============================================
// 404 AND GLOBAL ERROR HANDLING
// ============================================

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    success: false,
    error: 'Route not found',
    path: req.path,
    method: req.method
  });
});

// Global error handling middleware (must be last)
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Don't expose sensitive error details in production
  const isDevelopment = process.env.NODE_ENV !== 'production';
  const errorDetails = isDevelopment ? err.message : 'Internal server error';

  res.status(err.status || 500).json({
    success: false,
    error: errorDetails,
    ...(isDevelopment && { stack: err.stack })
  });
});

// ============================================
// SERVER STARTUP
// ============================================

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, closing server gracefully');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

/**
 * Example test cases for improved app.js
 * Uses Jest and Supertest
