describe('Security & Input Validation Tests', () => {

  // ============================================
  // HEALTH CHECK ENDPOINT TESTS
  // ============================================

  describe('GET /health', () => {
    test('should return health status', async () => {
      const res = await request(app).get('/health');
      expect(res.status).toBe(200);
      expect(res.body).toHaveProperty('status', 'ok');
      expect(res.body).toHaveProperty('timestamp');
      expect(res.body).toHaveProperty('uptime');
    });

    test('should have valid timestamp format', async () => {
      const res = await request(app).get('/health');
      expect(new Date(res.body.timestamp)).toBeInstanceOf(Date);
    });
  });

  // ============================================
  // GET /users ENDPOINT TESTS
  // ============================================

  describe('GET /users', () => {
    test('should return array of users', async () => {
      const res = await request(app).get('/users');
      expect(res.status).toBe(200);
      expect(res.body.success).toBe(true);
      expect(Array.isArray(res.body.data)).toBe(true);
    });

    test('should not expose sensitive fields', async () => {
      const res = await request(app).get('/users');
      const user = res.body.data[0];
      // Depending on your security policy
      expect(user).toHaveProperty('id');
      expect(user).toHaveProperty('name');
    });

    // INPUT VALIDATION TESTS
    test('should reject invalid limit (too high)', async () => {
      const res = await request(app).get('/users?limit=101');
      expect(res.status).toBe(400);
      expect(res.body.success).toBe(false);
    });

    test('should reject invalid limit (negative)', async () => {
      const res = await request(app).get('/users?limit=0');
      expect(res.status).toBe(400);
      expect(res.body.success).toBe(false);
    });

    test('should reject invalid limit (non-numeric)', async () => {
      const res = await request(app).get('/users?limit=abc');
      expect(res.status).toBe(400);
      expect(res.body.success).toBe(false);
    });

    test('should reject overly long filter', async () => {
      const longFilter = 'a'.repeat(51);
      const res = await request(app).get(`/users?filter=${longFilter}`);
      expect(res.status).toBe(400);
      expect(res.body.success).toBe(false);
    });

    test('should accept valid filter', async () => {
      const res = await request(app).get('/users?filter=alice');
      expect(res.status).toBe(200);
      expect(res.body.success).toBe(true);
    });

    test('should limit results correctly', async () => {
      const res = await request(app).get('/users?limit=1');
      expect(res.status).toBe(200);
      expect(res.body.data.length).toBeLessThanOrEqual(1);
    });

    // SQL/INJECTION ATTACK TESTS
    test('should safely handle SQL injection attempt in filter', async () => {
      const res = await request(app).get("/users?filter='; DROP TABLE users; --");
      expect(res.status).toBe(200); // Should safely handle or reject
      expect(res.body.data).toBeDefined();
    });

    test('should safely handle NoSQL injection attempt', async () => {
      const res = await request(app).get('/users?filter={"$ne":null}');
      expect(res.status).toBe(200);
      expect(Array.isArray(res.body.data)).toBe(true);
    });

    // XSS PREVENTION TESTS
    test('should safely handle XSS attempt in filter', async () => {
      const res = await request(app).get('/users?filter=<script>alert("xss")</script>');
      expect(res.status).toBe(200);
      // Data should be safe to render
      expect(res.body.data).toBeDefined();
    });
  });

  // ============================================
  // POST /users ENDPOINT TESTS
  // ============================================

  describe('POST /users', () => {
    const validUser = {
      name: 'John Doe',
      email: 'john@example.com'
    };

    test('should create user with valid data', async () => {
      const res = await request(app)
        .post('/users')
        .send(validUser);
      expect(res.status).toBe(201);
      expect(res.body.success).toBe(true);
      expect(res.body.data).toHaveProperty('name', 'John Doe');
      expect(res.body.data).toHaveProperty('email', 'john@example.com');
    });

    // NAME VALIDATION
    test('should reject empty name', async () => {
      const res = await request(app)
        .post('/users')
        .send({ name: '', email: 'test@example.com' });
      expect(res.status).toBe(400);
      expect(res.body.success).toBe(false);
    });

    test('should reject name shorter than 2 characters', async () => {
      const res = await request(app)
        .post('/users')
        .send({ name: 'A', email: 'test@example.com' });
      expect(res.status).toBe(400);
      expect(res.body.success).toBe(false);
    });

    test('should reject name longer than 100 characters', async () => {
      const res = await request(app)
        .post('/users')
        .send({ 
          name: 'A'.repeat(101), 
          email: 'test@example.com' 
        });
      expect(res.status).toBe(400);
      expect(res.body.success).toBe(false);
    });

    test('should reject name with invalid characters', async () => {
      const res = await request(app)
        .post('/users')
        .send({ name: 'John@123!', email: 'test@example.com' });
      expect(res.status).toBe(400);
      expect(res.body.success).toBe(false);
    });

    test('should accept name with apostrophe', async () => {
      const res = await request(app)
        .post('/users')
        .send({ name: "O'Brien", email: 'test@example.com' });
      expect(res.status).toBe(201);
    });

    test('should accept name with hyphen', async () => {
      const res = await request(app)
        .post('/users')
        .send({ name: 'Mary-Jane', email: 'test@example.com' });
      expect(res.status).toBe(201);
    });

    // EMAIL VALIDATION
    test('should reject invalid email format', async () => {
      const res = await request(app)
        .post('/users')
        .send({ name: 'John Doe', email: 'invalid-email' });
      expect(res.status).toBe(400);
      expect(res.body.success).toBe(false);
    });

    test('should reject email without domain', async () => {
      const res = await request(app)
        .post('/users')
        .send({ name: 'John Doe', email: 'john@' });
      expect(res.status).toBe(400);
      expect(res.body.success).toBe(false);
    });

    test('should normalize email addresses', async () => {
      const res = await request(app)
        .post('/users')
        .send({ name: 'John Doe', email: 'JOHN@EXAMPLE.COM' });
      expect(res.status).toBe(201);
      expect(res.body.data.email).toMatch(/^[^A-Z]+@[^A-Z]+\.com$/);
    });

    test('should reject empty email', async () => {
      const res = await request(app)
        .post('/users')
        .send({ name: 'John Doe', email: '' });
      expect(res.status).toBe(400);
      expect(res.body.success).toBe(false);
    });

    // MISSING FIELDS
    test('should reject missing name', async () => {
      const res = await request(app)
        .post('/users')
        .send({ email: 'test@example.com' });
      expect(res.status).toBe(400);
      expect(res.body.success).toBe(false);
