const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('mongo-sanitize');
const validator = require('validator');
const logger = require('./middleware/logger');
const errorHandler = require('./middleware/errorHandler');

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// 1. Set security HTTP headers
app.use(helmet());

// 2. Body parser with size limits (prevent large payloads)
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 3. Data sanitization against NoSQL injection
app.use(mongoSanitize());

// 4. Request logging middleware
app.use(logger.requestLogger);

// 5. Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
});
app.use(limiter);

// Stricter limit for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 20,
  skipSuccessfulRequests: true, // Don't count successful requests
});

// ============================================
// INPUT VALIDATION HELPERS
// ============================================

/**
 * Validate query parameters
 */
const validateQueryParams = (req, res, next) => {
  const { limit, offset, sort } = req.query;

  try {
    // Validate limit
    if (limit) {
      const limitNum = parseInt(limit, 10);
      if (isNaN(limitNum) || limitNum < 1 || limitNum > 100) {
        return res.status(400).json({
          error: 'Invalid limit parameter. Must be between 1 and 100.',
        });
      }
      req.validatedQuery = req.validatedQuery || {};
      req.validatedQuery.limit = limitNum;
    }

    // Validate offset
    if (offset) {
      const offsetNum = parseInt(offset, 10);
      if (isNaN(offsetNum) || offsetNum < 0) {
        return res.status(400).json({
          error: 'Invalid offset parameter. Must be a non-negative integer.',
        });
      }
      req.validatedQuery = req.validatedQuery || {};
      req.validatedQuery.offset = offsetNum;
    }

    // Validate sort - whitelist allowed fields
    if (sort) {
      const allowedSortFields = ['id', 'name', 'email', 'createdAt'];
      const sortField = sort.replace(/^-/, ''); // Remove leading '-' for descending

      if (!allowedSortFields.includes(sortField)) {
        return res.status(400).json({
          error: `Invalid sort field. Allowed fields: ${allowedSortFields.join(', ')}`,
        });
      }
      req.validatedQuery = req.validatedQuery || {};
      req.validatedQuery.sort = sort;
    }

    next();
  } catch (error) {
    logger.error('Query validation error:', error);
    res.status(400).json({ error: 'Invalid query parameters' });
  }
};

/**
 * Validate user ID from URL parameters
 */
const validateUserId = (req, res, next) => {
  const { id } = req.params;

  try {
    // Validate ID is a positive integer
    const userId = parseInt(id, 10);
    if (isNaN(userId) || userId < 1) {
      return res.status(400).json({ error: 'Invalid user ID format.' });
    }

    req.validatedParams = { userId };
    next();
  } catch (error) {
    logger.error('Param validation error:', error);
    res.status(400).json({ error: 'Invalid parameters' });
  }
};

/**
 * Validate email format
 */
const validateEmail = (email) => {
  return validator.isEmail(email);
};

// ============================================
// ROUTES
// ============================================

/**
 * GET /health - Health check endpoint
 */
app.get('/health', (req, res) => {
  try {
    res.status(200).json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    });
  } catch (error) {
    logger.error('Health check error:', error);
    res.status(500).json({ error: 'Health check failed' });
  }
});

/**
 * GET /users - Get list of users with pagination
 */
app.get('/users', strictLimiter, validateQueryParams, (req, res) => {
  try {
    // Mock user data (in production, this would query a database)
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com', createdAt: '2024-01-01' },
      { id: 2, name: 'Bob', email: 'bob@example.com', createdAt: '2024-01-02' },
    ];

    // Apply pagination defaults
    const limit = (req.validatedQuery && req.validatedQuery.limit) || 10;
    const offset = (req.validatedQuery && req.validatedQuery.offset) || 0;

    // Apply pagination
    const paginatedUsers = allUsers.slice(offset, offset + limit);

    // Return sanitized response
    const response = {
      data: paginatedUsers,
      pagination: {
        limit,
        offset,
        total: allUsers.length,
        hasMore: offset + limit < allUsers.length,
      },
    };

    res.status(200).json(response);
  } catch (error) {
    logger.error('Error fetching users:', error);
    res.status(500).json({ error: 'Failed to fetch users' });
  }
});

/**
 * GET /users/:id - Get specific user by ID
 */
app.get('/users/:id', validateUserId, (req, res) => {
  try {
    const { userId } = req.validatedParams;

    // Mock data lookup
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com', createdAt: '2024-01-01' },
      { id: 2, name: 'Bob', email: 'bob@example.com', createdAt: '2024-01-02' },
    ];

    const user = users.find((u) => u.id === userId);

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    res.status(200).json({ data: user });
  } catch (error) {
    logger.error('Error fetching user:', error);
    res.status(500).json({ error: 'Failed to fetch user' });
  }
});

// ============================================
// 404 HANDLER
// ============================================

app.use((req, res) => {
  res.status(404).json({
    error: 'Route not found',
    path: req.path,
  });
});

// ============================================
// CENTRALIZED ERROR HANDLER (Must be last)
// ============================================

app.use(errorHandler.handle);

// ============================================
// SERVER STARTUP
// ============================================

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

/**
 * Logging middleware for request/response tracking
 */

const requestLogger = (req, res, next) => {
  const startTime = Date.now();

  // Log request
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.path}`);

  // Log response when finished
  res.on('finish', () => {
    const duration = Date.now() - startTime;
    const statusCode = res.statusCode;
    const statusMessage = statusCode >= 400 ? '❌' : '✅';

    console.log(
      `${statusMessage} ${statusCode} - ${req.method} ${req.path} (${duration}ms)`
    );
  });

  next();
};

const error = (message, error) => {
  console.error(`[ERROR] ${new Date().toISOString()} - ${message}`, error);
};

module.exports = {
  requestLogger,
  error,
};

