const requestLogger = (req, res, next) => {
  const startTime = Date.now();

  // Log request
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.path}`);

  // Log response when finished
  res.on('finish', () => {
    const duration = Date.now() - startTime;
    const statusCode = res.statusCode;
    const statusMessage = statusCode >= 400 ? '❌' : '✅';

    console.log(
      `${statusMessage} ${statusCode} - ${req.method} ${req.path} (${duration}ms)`
    );
  });

  next();
};

const error = (message, error) => {
  console.error(`[ERROR] ${new Date().toISOString()} - ${message}`, error);
};

module.exports = {
  requestLogger,
  error,
};

/**
 * Centralized error handler middleware
 */

const logger = require('./logger');

const handle = (err, req, res, next) => {
  // Log the error
  logger.error('Unhandled Error:', err);

  // Default error details
  let statusCode = err.statusCode || 500;
  let message = err.message || 'Internal Server Error';

  // Don't expose sensitive error details in production
  const isProduction = process.env.NODE_ENV === 'production';
  const errorResponse = {
    error: message,
    ...(
      !isProduction && {
        stack: err.stack,
        details: err,
      }
    ),
  };

  // Handle specific error types
  if (err.name === 'ValidationError') {
    statusCode = 400;
    errorResponse.error = 'Validation Error';
  } else if (err.name === 'CastError') {
    statusCode = 400;
    errorResponse.error = 'Invalid ID format';
  } else if (err.name === 'JsonWebTokenError') {
    statusCode = 401;
    errorResponse.error = 'Invalid token';
  }

  res.status(statusCode).json(errorResponse);
};

module.exports = {
  handle,
};

# Security Review & Improvement Guide for app.js

## Executive Summary

The original `app.js` had **7 critical and medium-priority security issues** that could expose the application to various attacks. A hardened version has been provided with security best practices implemented.

---

## 🔴 Critical Issues (Original Code)

### 1. **No Input Validation**
**Risk:** Injection attacks, unexpected behavior, crashes

**Original:**
```javascript
app.get('/users', (req, res) => {
  res.json([...]);  // No validation of query parameters
});
```

**Fixed:**
```javascript
// Validate and whitelist parameters
const validateQueryParams = (req, res, next) => {
  const { limit, offset, sort } = req.query;

  // Validate limit is numeric and within bounds
  if (limit) {
    const limitNum = parseInt(limit, 10);
    if (isNaN(limitNum) || limitNum < 1 || limitNum > 100) {
      return res.status(400).json({
        error: 'Invalid limit parameter. Must be between 1 and 100.',
      });
    }
  }
  next();
};
```

---

### 2. **No Error Handling**
**Risk:** Information disclosure, unhandled crashes, poor debugging

**Original:**
```javascript
app.get('/users', (req, res) => {
  res.json([...]); // No try-catch, unhandled errors expose stack traces
});
```

**Fixed:**
```javascript
app.get('/users', (req, res) => {
  try {
    // ... code ...
    res.status(200).json(response);
  } catch (error) {
    logger.error('Error fetching users:', error);
    res.status(500).json({ error: 'Failed to fetch users' });
  }
});

// Centralized error handler middleware
app.use(errorHandler.handle);
```

---

### 3. **Missing Security Headers**
**Risk:** XSS, Clickjacking, MIME-sniffing, other header-based attacks

**Original:** No security headers configured

**Fixed:**
```javascript
const helmet = require('helmet');
app.use(helmet()); // Automatically sets multiple security headers:
// - Content-Security-Policy
// - X-Frame-Options
// - X-Content-Type-Options
// - Strict-Transport-Security
// - etc.
```

---

### 4. **No Rate Limiting**
**Risk:** Brute force attacks, DoS attacks, resource exhaustion

**Original:** No rate limiting

**Fixed:**
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // 100 requests per IP
  message: 'Too many requests',
});
app.use(limiter);

// Stricter limit for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 20,
  skipSuccessfulRequests: true,
});
app.get('/users', strictLimiter, (req, res) => {...});
```

---

## 🟡 Medium Priority Issues

### 5. **Sensitive Data Exposure**
**Risk:** Privacy violations, data leakage

**Original:**
```javascript
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]); // Direct email exposure, no filtering
});
```

**Recommendations:**
```javascript
// 1. Add pagination to limit data exposure
const response = {
  data: paginatedUsers.slice(offset, offset + limit),
  pagination: { limit, offset, total: allUsers.length },
};

// 2. Filter sensitive fields (in production)
const filteredUsers = users.map(u => ({
  id: u.id,
  name: u.name,
  // email: u.email (only if user is authenticated)
}));

// 3. Require authentication for sensitive endpoints
app.get('/users/:id/email', authenticate, (req, res) => {...});

// 4. Add rate limiting to prevent scraping
app.use(strictLimiter);
```

---

### 6. **No Request Body Size Limit**
**Risk:** Large payload attacks causing memory exhaustion

**Original:** Unlimited request body size

**Fixed:**
```javascript
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));
```

---

### 7. **No NoSQL Injection Protection**
**Risk:** Database injection attacks (if using MongoDB)

**Fixed:**
```javascript
const mongoSanitize = require('mongo-sanitize');
app.use(mongoSanitize()); // Removes $ and . from keys
```

---

### 8. **Missing Logging & Monitoring**
**Risk:** Unable to detect or investigate security incidents

**Fixed:**
```javascript
// Request logging middleware
app.use(logger.requestLogger);

// Centralized error logging
catch (error) {
  logger.error('Error fetching users:', error);
  res.status(500).json({ error: 'Failed to fetch users' });
}
```

---

## ✅ Best Practices Implemented

### 1. **Proper HTTP Status Codes**
- `200` for successful GET
- `400` for bad request (validation errors)
- `401` for unauthorized
- `404` for not found
- `500` for server errors

### 2. **Input Validation Whitelist**
```javascript
const allowedSortFields = ['id', 'name', 'email', 'createdAt'];
if (!allowedSortFields.includes(sortField)) {
  return res.status(400).json({ error: 'Invalid sort field' });
}
```

### 3. **Secure Response Format**
- Consistent error/success response structure
- No stack traces in production
- Sanitized error messages

### 4. **Graceful Shutdown**
```javascript
process.on('SIGTERM', () => {
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});
```

