## Vulnerability Fixes Explained

### Fix #1: Security Headers
```javascript
// BEFORE: No headers
app.get('/users', (req, res) => {
  res.json([...]);
});
// VULNERABLE TO: XSS, Clickjacking, MIME-sniffing

// AFTER: Security headers
app.use(helmet()); // Sets 8+ security headers
app.get('/users', (req, res) => {
  res.json([...]);
});
// PROTECTED BY: CSP, X-Frame-Options, X-Content-Type-Options, etc.
```

### Fix #2: Input Validation
```javascript
// BEFORE: No validation
app.get('/users?limit=999999999&sort=$ne%3Anull', (req, res) => {
  const limit = req.query.limit; // "999999999" - could cause DoS
  const sort = req.query.sort;   // "$ne:null" - NoSQL injection
});

// AFTER: Strict validation
const validateQueryParams = (req, res, next) => {
  if (req.query.limit) {
    const limitNum = parseInt(req.query.limit, 10);
    if (isNaN(limitNum) || limitNum < 1 || limitNum > 100) {
      return res.status(400).json({ error: 'Invalid limit' });
    }
  }
  if (req.query.sort) {
    const allowed = ['id', 'name', 'email'];
    if (!allowed.includes(req.query.sort)) {
      return res.status(400).json({ error: 'Invalid sort' });
    }
  }
  next();
};
app.get('/users', validateQueryParams, (req, res) => {...});
```

### Fix #3: Rate Limiting
```javascript
// BEFORE: No rate limiting
app.get('/users', (req, res) => {
  // Attacker can make unlimited requests
  // DoS attack: 1000 req/sec = server crash
});

// AFTER: Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100, // Max 100 requests per 15 minutes per IP
});
app.get('/users', limiter, (req, res) => {
  // Attacker limited to 100 req/15min
  // Can't perform effective DoS
});
```

### Fix #4: Error Handling
```javascript
// BEFORE: No error handling
app.get('/users/:id', (req, res) => {
  const user = users.find(u => u.id === req.params.id);
  res.json(user); // If crash: Stack trace exposed!
});

// AFTER: Proper error handling
app.get('/users/:id', validateUserId, (req, res) => {
  try {
    const user = users.find(u => u.id === req.validatedParams.userId);
    if (!user) return res.status(404).json({ error: 'Not found' });
    res.status(200).json({ data: user });
  } catch (error) {
    logger.error('Error:', error); // Log internally
    res.status(500).json({ error: 'Internal Server Error' });
    // No stack trace exposed!
  }
});
```

### Fix #5: Request Body Size Limit
```javascript
// BEFORE: Unlimited body size
app.use(express.json());
// Attacker sends 1GB JSON payload
// Server runs out of memory -> crash

// AFTER: Limited body size
app.use(express.json({ limit: '10kb' }));
// Attacker sends 1GB JSON payload
// Server rejects: 413 Payload Too Large
```

### Fix #6: NoSQL Injection Protection
```javascript
// BEFORE: No sanitization
app.post('/users', (req, res) => {
  // Attacker sends: { name: {$ne: null} }
  // Query becomes: db.find({ name: {$ne: null} })
  // Returns ALL users instead of creating one
});

// AFTER: Sanitized
const mongoSanitize = require('mongo-sanitize');
app.use(mongoSanitize()); // Removes $ and . from input keys
app.post('/users', (req, res) => {
  // Attacker sends: { name: {$ne: null} }
  // Becomes: { name: {$ne null} } - safely rejected
});
```

### Fix #7: Response Consistency
```javascript
// BEFORE: Inconsistent responses
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});
app.get('/users', (req, res) => {
  res.json([...]);
});
// Different response formats = harder to parse, more errors

// AFTER: Consistent responses
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
  });
});
app.get('/users', (req, res) => {
  res.json({
    data: [...],
    pagination: { limit, offset, total },
  });
});
// Predictable format = better client implementation
```

