// Improved application with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const validator = require('validator');

const app = express();

// ============ SECURITY MIDDLEWARE ============

// Set HTTP security headers
app.use(helmet());

// Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);

// Body size limiting
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// ============ LOGGING SETUP ============

const logger = {
  error: (message, error) => console.error(`[ERROR] ${new Date().toISOString()}: ${message}`, error),
  info: (message) => console.log(`[INFO] ${new Date().toISOString()}: ${message}`),
  warn: (message) => console.warn(`[WARN] ${new Date().toISOString()}: ${message}`),
};

// ============ INPUT VALIDATION ============

/**
 * Validates and sanitizes user ID parameter
 * @param {string|number} id - The ID to validate
 * @returns {number|null} - Valid ID or null
 */
const validateUserId = (id) => {
  if (!id) return null;
  const sanitized = validator.escape(String(id).trim());
  const parsed = parseInt(sanitized, 10);

  if (isNaN(parsed) || parsed < 1) {
    return null;
  }
  return parsed;
};

/**
 * Validates email format
 * @param {string} email - Email to validate
 * @returns {boolean}
 */
const validateEmail = (email) => {
  if (typeof email !== 'string') return false;
  return validator.isEmail(email.trim());
};

// ============ ROUTES ============

/**
 * Health check endpoint
 */
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    logger.error('Health check failed', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

/**
 * Get all users (consider adding authentication/authorization)
 * TODO: Add authentication middleware before exposing real user data
 */
app.get('/users', (req, res) => {
  try {
    // Validate optional query parameters
    const { limit, offset } = req.query;

    let limitVal = 10; // default
    let offsetVal = 0; // default

    if (limit !== undefined) {
      const parsed = parseInt(limit, 10);
      if (isNaN(parsed) || parsed < 1 || parsed > 100) {
        return res.status(400).json({ 
          error: 'Invalid limit parameter. Must be between 1 and 100.' 
        });
      }
      limitVal = parsed;
    }

    if (offset !== undefined) {
      const parsed = parseInt(offset, 10);
      if (isNaN(parsed) || parsed < 0) {
        return res.status(400).json({ 
          error: 'Invalid offset parameter. Must be non-negative.' 
        });
      }
      offsetVal = parsed;
    }

    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const paginatedUsers = allUsers.slice(offsetVal, offsetVal + limitVal);

    res.json({
      data: paginatedUsers,
      total: allUsers.length,
      limit: limitVal,
      offset: offsetVal,
    });
  } catch (error) {
    logger.error('Failed to retrieve users', error);
    res.status(500).json({ error: 'Failed to retrieve users' });
  }
});

/**
 * Get specific user by ID with validation
 */
app.get('/users/:id', (req, res) => {
  try {
    const userId = validateUserId(req.params.id);

    if (userId === null) {
      return res.status(400).json({ error: 'Invalid user ID format' });
    }

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === userId);

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    res.json(user);
  } catch (error) {
    logger.error(`Failed to retrieve user ${req.params.id}`, error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// ============ ERROR HANDLING ============

/**
 * 404 Not Found handler
 */
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not found',
    path: req.path 
  });
});

/**
 * Global error handler (must be last)
 */
app.use((err, req, res, next) => {
  logger.error(`Unhandled error: ${err.message}`, err);

  // Don't expose internal error details to clients
  const statusCode = err.statusCode || 500;
  const message = statusCode === 500 ? 'Internal server error' : err.message;

  res.status(statusCode).json({
    error: message,
    ...(process.env.NODE_ENV === 'development' && { details: err.message }),
  });
});

// ============ SERVER STARTUP ============

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    logger.info('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

# Before & After Comparison

## Input Validation

### ❌ BEFORE: No Validation
```javascript
app.get('/users/:id', (req, res) => {
  // req.params.id could be anything: "abc", "", null, malicious input
  const user = users.find(u => u.id == req.params.id); // Type coercion!
});
```

**Issues**:
- No type checking
- Loose equality comparison (`==`) causes type coercion
- No sanitization
- Attacks: SQL injection (if connected to DB), injection attacks

### ✅ AFTER: With Validation
```javascript
const validateUserId = (id) => {
  if (!id) return null;
  const sanitized = validator.escape(String(id).trim());
  const parsed = parseInt(sanitized, 10);

  if (isNaN(parsed) || parsed < 1) return null;
  return parsed;
};

app.get('/users/:id', (req, res) => {
  const userId = validateUserId(req.params.id);
  if (userId === null) {
    return res.status(400).json({ error: 'Invalid user ID' });
  }
  // Safe to use userId
});
```

**Benefits**:
- Explicit type conversion with validation
- Range checking (must be > 0)
- Sanitization against injection
- Clear error messages

---

## Error Handling

### ❌ BEFORE: No Error Handling
```javascript
app.get('/users', (req, res) => {
  // If anything throws, server crashes or hangs
  res.json([...]);
});

// No error middleware at all
```

**Issues**:
- Unhandled exceptions crash the server
- No logging of errors
- No graceful error responses

### ✅ AFTER: Comprehensive Error Handling
```javascript
app.get('/users', (req, res) => {
  try {
    // Validate inputs
    // ... business logic ...
    res.json({ data: paginatedUsers });
  } catch (error) {
    logger.error('Failed to retrieve users', error);
    res.status(500).json({ error: 'Failed to retrieve users' });
  }
});

// Global error handler (must be last middleware)
app.use((err, req, res, next) => {
  logger.error(`Unhandled error: ${err.message}`, err);

  const statusCode = err.statusCode || 500;
  const message = statusCode === 500 ? 'Internal server error' : err.message;

  res.status(statusCode).json({ error: message });
});
```

**Benefits**:
- Graceful error handling prevents crashes
- Errors are logged for debugging
- Generic error messages prevent information leakage
- Proper HTTP status codes

---

## Security Headers

### ❌ BEFORE: No Security Headers
```javascript
app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});
// Missing: X-Content-Type-Options, X-Frame-Options, CSP, etc.
```

**Risks**:
- XSS (Cross-Site Scripting) attacks
- Clickjacking attacks
- MIME-type sniffing
- Information disclosure

### ✅ AFTER: Security Headers with Helmet
```javascript
const helmet = require('helmet');
app.use(helmet());

app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});
```

**Headers Added**:
- `X-Content-Type-Options: nosniff` - Prevents MIME sniffing
- `X-Frame-Options: DENY` - Prevents clickjacking
- `X-XSS-Protection: 1; mode=block` - Enables browser XSS filtering
- `Content-Security-Policy` - Restricts resource loading
- `Strict-Transport-Security` - Enforces HTTPS

