## Validation Patterns

### Email Validation
```javascript
const validateEmail = (email) => {
  if (typeof email !== 'string') return false;
  return validator.isEmail(email.trim());
};

// Usage
if (!validateEmail(req.body.email)) {
  return res.status(400).json({ error: 'Invalid email format' });
}
```

### Number Validation
```javascript
const validateNumber = (value, min = -Infinity, max = Infinity) => {
  const parsed = parseInt(String(value).trim(), 10);
  if (isNaN(parsed) || parsed < min || parsed > max) {
    return null;
  }
  return parsed;
};

// Usage
const age = validateNumber(req.body.age, 0, 150);
if (age === null) {
  return res.status(400).json({ error: 'Age must be 0-150' });
}
```

### String Validation
```javascript
const validateString = (str, minLength = 1, maxLength = 255) => {
  if (typeof str !== 'string') return null;
  const trimmed = str.trim();
  if (trimmed.length < minLength || trimmed.length > maxLength) {
    return null;
  }
  return validator.escape(trimmed); // Sanitize
};

// Usage
const name = validateString(req.body.name, 1, 100);
if (!name) {
  return res.status(400).json({ error: 'Name must be 1-100 characters' });
}
```

### URL Validation
```javascript
const validateUrl = (url) => {
  if (typeof url !== 'string') return null;
  if (!validator.isURL(url)) return null;
  return validator.escape(url);
};

// Usage
const website = validateUrl(req.body.website);
if (!website) {
  return res.status(400).json({ error: 'Invalid URL' });
}
```

### Phone Number Validation
```javascript
const validatePhone = (phone) => {
  if (typeof phone !== 'string') return null;
  const sanitized = phone.replace(/[^\d+\-()]/g, ''); // Keep only digits and phone chars
  if (!validator.isMobilePhone(sanitized)) return null;
  return sanitized;
};

// Usage
const mobile = validatePhone(req.body.phone);
if (!mobile) {
  return res.status(400).json({ error: 'Invalid phone number' });
}
```

