## Error Handling Patterns

### Validation Error Response
```javascript
const sendValidationError = (res, message, details = null) => {
  res.status(400).json({
    error: message,
    ...(details && { details }),
  });
};

// Usage
if (!email) {
  return sendValidationError(res, 'Invalid email format');
}
```

### Authentication Error Response
```javascript
const sendAuthError = (res, message = 'Unauthorized') => {
  res.status(401).json({ error: message });
};

// Usage
if (!token) {
  return sendAuthError(res, 'Missing authentication token');
}
```

### Permission Error Response
```javascript
const sendForbiddenError = (res, message = 'Forbidden') => {
  res.status(403).json({ error: message });
};

// Usage
if (user.role !== 'admin') {
  return sendForbiddenError(res, 'Admin access required');
}
```

### Not Found Response
```javascript
const sendNotFoundError = (res, resource = 'Resource') => {
  res.status(404).json({ error: `${resource} not found` });
};

// Usage
if (!user) {
  return sendNotFoundError(res, 'User');
}
```

### Internal Error Response
```javascript
const sendInternalError = (res, logger, error, message = 'Internal server error') => {
  logger.error(message, error);
  res.status(500).json({ error: message });
};

// Usage
catch (error) {
  return sendInternalError(res, logger, error, 'Failed to create user');
}
```

