## Testing Security

### Unit Tests for Validation
```javascript
// validation.test.js
const { validateEmail, validateUserId, validateString } = require('./validation');

describe('Input Validation', () => {
  describe('validateEmail', () => {
    test('accepts valid emails', () => {
      expect(validateEmail('test@example.com')).toBe(true);
      expect(validateEmail('user+tag@domain.co.uk')).toBe(true);
    });

    test('rejects invalid emails', () => {
      expect(validateEmail('not-an-email')).toBe(false);
      expect(validateEmail('')).toBe(false);
      expect(validateEmail(123)).toBe(false);
      expect(validateEmail(null)).toBe(false);
    });
  });

  describe('validateUserId', () => {
    test('accepts valid IDs', () => {
      expect(validateUserId('1')).toBe(1);
      expect(validateUserId(42)).toBe(42);
      expect(validateUserId('999')).toBe(999);
    });

    test('rejects invalid IDs', () => {
      expect(validateUserId('abc')).toBe(null);
      expect(validateUserId('0')).toBe(null);
      expect(validateUserId('-1')).toBe(null);
      expect(validateUserId('')).toBe(null);
    });
  });

  describe('validateString', () => {
    test('sanitizes HTML', () => {
      const result = validateString('<script>alert("xss")</script>');
      expect(result).not.toContain('<script>');
    });

    test('enforces length limits', () => {
      expect(validateString('a', 2, 10)).toBe(null);
      expect(validateString('a'.repeat(100), 1, 10)).toBe(null);
    });
  });
});
```

