## 🚨 Common Mistakes to Avoid

```javascript
// ❌ DON'T: Use loose equality
app.get('/users/:id', (req, res) => {
  const user = users.find(u => u.id == req.params.id); // Type coercion!
});

// ✅ DO: Use strict equality and validation
app.get('/users/:id', (req, res) => {
  const id = validateUserId(req.params.id);
  if (!id) return res.status(400).json({ error: 'Invalid ID' });
  const user = users.find(u => u.id === id); // Strict equality
});
```

```javascript
// ❌ DON'T: Expose stack traces
app.use((err, req, res, next) => {
  res.status(500).json({ error: err.stack }); // Leaks internals!
});

// ✅ DO: Log error, return generic message
app.use((err, req, res, next) => {
  logger.error(err.message, err);
  res.status(500).json({ error: 'Internal server error' });
});
```

```javascript
// ❌ DON'T: No input validation
app.post('/users', (req, res) => {
  const user = { name: req.body.name, email: req.body.email };
  saveUser(user);
});

// ✅ DO: Validate all inputs
app.post('/users', (req, res) => {
  const name = validateString(req.body.name, 1, 100);
  const email = validateEmail(req.body.email);

  if (!name || !email) {
    return res.status(400).json({ error: 'Invalid input' });
  }

  const user = { name, email };
  saveUser(user);
});
```

