// Improved application with security best practices
// Includes error handling, input validation, and security headers

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const { body, query, validationResult } = require('express-validator');
const morgan = require('morgan');
const logger = require('./logger'); // Assuming logger utility exists

const app = express();

// ============================================
// MIDDLEWARE - Security & Logging
// ============================================

// Security headers
app.use(helmet());

// Parse JSON with size limit to prevent large payload attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Data sanitization against NoSQL query injection
app.use(mongoSanitize());

// Request logging
app.use(morgan('combined', { stream: logger.stream }));

// Rate limiting - Apply globally
const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
  skip: (req) => {
    // Skip rate limiting for health checks (optional)
    return req.path === '/health';
  },
});

app.use(globalLimiter);

// Stricter rate limiting for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10,
  message: 'Too many requests to this endpoint, please try again later.',
});

// ============================================
// MIDDLEWARE - Request Validation
// ============================================

// Middleware to handle validation errors
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      success: false,
      message: 'Validation failed',
      errors: errors.array().map(err => ({
        field: err.param,
        message: err.msg,
      })),
    });
  }
  next();
};

// ============================================
// ROUTES
// ============================================

/**
 * Health Check Endpoint
 * No authentication required
 */
app.get('/health', (req, res) => {
  try {
    res.json({
      success: true,
      status: 'ok',
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    logger.error('Health check error:', error);
    res.status(500).json({
      success: false,
      message: 'Internal server error',
    });
  }
});

/**
 * Get Users Endpoint
 * Supports optional filtering and pagination
 */
app.get(
  '/users',
  strictLimiter,
  query('page')
    .optional()
    .isInt({ min: 1, max: 1000 })
    .withMessage('Page must be an integer between 1 and 1000'),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be an integer between 1 and 100'),
  query('search')
    .optional()
    .trim()
    .isLength({ max: 100 })
    .withMessage('Search term must not exceed 100 characters')
    .matches(/^[a-zA-Z0-9\s@\.\-_]*$/)
    .withMessage('Search term contains invalid characters'),
  handleValidationErrors,
  (req, res) => {
    try {
      const { page = 1, limit = 10, search = '' } = req.query;

      // Mock user data
      const allUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
        { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      ];

      // Filter users if search is provided
      let filteredUsers = allUsers;
      if (search) {
        const searchLower = search.toLowerCase();
        filteredUsers = allUsers.filter(
          user =>
            user.name.toLowerCase().includes(searchLower) ||
            user.email.toLowerCase().includes(searchLower)
        );
      }

      // Pagination
      const startIndex = (parseInt(page) - 1) * parseInt(limit);
      const endIndex = startIndex + parseInt(limit);
      const paginatedUsers = filteredUsers.slice(startIndex, endIndex);

      res.json({
        success: true,
        data: paginatedUsers,
        pagination: {
          page: parseInt(page),
          limit: parseInt(limit),
          total: filteredUsers.length,
          totalPages: Math.ceil(filteredUsers.length / parseInt(limit)),
        },
      });
    } catch (error) {
      logger.error('Get users error:', error);
      res.status(500).json({
        success: false,
        message: 'Internal server error',
      });
    }
  }
);

/**
 * Get User by ID
 * Validate that ID is a valid integer
 */
app.get(
  '/users/:id',
  strictLimiter,
  query('fields')
    .optional()
    .trim()
    .matches(/^[a-zA-Z0-9,\s]*$/)
    .withMessage('Invalid fields parameter'),
  handleValidationErrors,
  (req, res) => {
    try {
      const { id } = req.params;

      // Validate ID is a positive integer
      if (!Number.isInteger(Number(id)) || Number(id) <= 0) {
        return res.status(400).json({
          success: false,
          message: 'Invalid user ID',
        });
      }

      // Mock user data
      const allUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      const user = allUsers.find(u => u.id === Number(id));

      if (!user) {
        return res.status(404).json({
          success: false,
          message: 'User not found',
        });
      }

      res.json({
        success: true,
        data: user,
      });
    } catch (error) {
      logger.error('Get user by ID error:', error);
      res.status(500).json({
        success: false,
        message: 'Internal server error',
      });
    }
  }
);

// ============================================
// ERROR HANDLING
// ============================================

// 404 Handler
app.use((req, res) => {
  res.status(404).json({
    success: false,
    message: 'Endpoint not found',
    path: req.path,
  });
});

// Global Error Handler (must be last)
app.use((err, req, res, next) => {
  logger.error('Global error handler:', {
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
  });

  // Don't expose internal error details in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    success: false,
    message: err.message || 'Internal server error',
    ...(isDevelopment && { stack: err.stack }),
  });
});

// ============================================
// SERVER STARTUP
// ============================================

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

const server = app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT} in ${NODE_ENV} mode`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM received, shutting down gracefully');
  server.close(() => {
    logger.info('Server closed');
    process.exit(0);
  });
});

module.exports = app;

// Simple logging utility with morgan stream support
const fs = require('fs');
const path = require('path');

// Create logs directory if it doesn't exist
const logsDir = path.join(__dirname, 'logs');
if (!fs.existsSync(logsDir)) {
  fs.mkdirSync(logsDir);
}

const logFile = path.join(logsDir, 'app.log');
const errorLogFile = path.join(logsDir, 'error.log');

const logger = {
  info: (message, data = '') => {
    const timestamp = new Date().toISOString();
    const logMessage = `[${timestamp}] INFO: ${message} ${typeof data === 'string' ? data : JSON.stringify(data)}\n`;
    fs.appendFileSync(logFile, logMessage);
    if (process.env.NODE_ENV === 'development') {
      console.log(logMessage);
    }
  },

  error: (message, data = '') => {
    const timestamp = new Date().toISOString();
    const logMessage = `[${timestamp}] ERROR: ${message} ${typeof data === 'string' ? data : JSON.stringify(data)}\n`;
    fs.appendFileSync(errorLogFile, logMessage);
    console.error(logMessage);
  },

  warn: (message, data = '') => {
    const timestamp = new Date().toISOString();
    const logMessage = `[${timestamp}] WARN: ${message} ${typeof data === 'string' ? data : JSON.stringify(data)}\n`;
    fs.appendFileSync(logFile, logMessage);
    if (process.env.NODE_ENV === 'development') {
      console.warn(logMessage);
    }
  },

  // Stream for morgan
  stream: {
    write: (message) => {
      fs.appendFileSync(logFile, message);
    },
  },
};

module.exports = logger;

