## 12. Unvalidated Redirects

### ❌ Vulnerable Code (Original)
```javascript
app.get('/redirect', (req, res) => {
  const url = req.query.url;
  res.redirect(url);
});

// Attacker crafts: /redirect?url=http://evil.com
// User clicks link, gets redirected to malicious site
// Appears trusted because it came from your domain
```

### ✅ Protected Code (Improved)
```javascript
const url = require('url');

app.get('/redirect',
  query('url')
    .notEmpty()
    .custom(value => {
      try {
        const parsed = new url.URL(value);
        // Only allow same-origin or whitelist domains
        if (parsed.origin !== req.get('host')) {
          throw new Error('Redirects only allowed to same origin');
        }
        return true;
      } catch (e) {
        throw new Error('Invalid URL');
      }
    }),
  handleValidationErrors,
  (req, res) => {
    res.redirect(req.query.url);
  }
);

// Attacker URL rejected at validation stage
// User stays safe
```

