// Improved application with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const validator = require('validator');
const logger = require('./logger'); // You'll need to implement this

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// Security headers with Helmet
app.use(helmet());

// Rate limiting - protect against DoS
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
});

// Apply rate limiting to all requests
app.use(limiter);

// Body parser with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Data sanitization against NoSQL injection
app.use(mongoSanitize());

// ============================================
// REQUEST LOGGING & VALIDATION
// ============================================

// Request logging middleware
app.use((req, res, next) => {
  logger.info({
    method: req.method,
    path: req.path,
    ip: req.ip,
    timestamp: new Date().toISOString(),
  });
  next();
});

// ============================================
// ROUTES
// ============================================

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    });
  } catch (error) {
    logger.error('Health check failed:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Users endpoint with input validation
app.get('/users', (req, res, next) => {
  try {
    // Validate query parameters
    const { page = 1, limit = 10, sort = 'id' } = req.query;

    // Input validation
    const pageNum = parseInt(page, 10);
    const limitNum = parseInt(limit, 10);

    if (!Number.isInteger(pageNum) || pageNum < 1) {
      return res.status(400).json({
        error: 'Invalid page parameter. Must be a positive integer.',
      });
    }

    if (!Number.isInteger(limitNum) || limitNum < 1 || limitNum > 100) {
      return res.status(400).json({
        error: 'Invalid limit parameter. Must be between 1 and 100.',
      });
    }

    // Whitelist allowed sort fields
    const allowedSortFields = ['id', 'name'];
    if (!allowedSortFields.includes(sort)) {
      return res.status(400).json({
        error: `Invalid sort field. Allowed: ${allowedSortFields.join(', ')}`,
      });
    }

    // Mock data (in production, fetch from database with pagination)
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply sorting and pagination
    const startIdx = (pageNum - 1) * limitNum;
    const paginatedUsers = allUsers.slice(startIdx, startIdx + limitNum);

    res.json({
      data: paginatedUsers,
      page: pageNum,
      limit: limitNum,
      total: allUsers.length,
    });
  } catch (error) {
    next(error); // Pass to error handler
  }
});

// ============================================
// 404 HANDLER
// ============================================

app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    path: req.path,
  });
});

// ============================================
// GLOBAL ERROR HANDLER (MUST BE LAST)
// ============================================

app.use((err, req, res, next) => {
  logger.error({
    message: err.message,
    stack: err.stack,
    method: req.method,
    path: req.path,
    timestamp: new Date().toISOString(),
  });

  // Don't leak error details in production
  const isDevelopment = process.env.NODE_ENV === 'development';
  const errorResponse = {
    error: isDevelopment ? err.message : 'Internal server error',
  };

  if (isDevelopment) {
    errorResponse.stack = err.stack;
  }

  const statusCode = err.statusCode || 500;
  res.status(statusCode).json(errorResponse);
});

// ============================================
// SERVER STARTUP
// ============================================

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT}`);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (err) => {
  logger.error('Unhandled Rejection:', err);
  server.close(() => {
    process.exit(1);
  });
});

module.exports = app;

// logger.js - Simple logging utility
const fs = require('fs');
const path = require('path');

const logsDir = path.join(__dirname, 'logs');

// Ensure logs directory exists
if (!fs.existsSync(logsDir)) {
  fs.mkdirSync(logsDir, { recursive: true });
}

const getLogFile = () => {
  const date = new Date().toISOString().split('T')[0];
  return path.join(logsDir, `app-${date}.log`);
};

const formatLog = (level, data) => {
  return `[${new Date().toISOString()}] [${level}] ${JSON.stringify(data)}\n`;
};

const logger = {
  info: (data) => {
    const logEntry = formatLog('INFO', data);
    process.stdout.write(logEntry);
    fs.appendFileSync(getLogFile(), logEntry);
  },

  warn: (data) => {
    const logEntry = formatLog('WARN', data);
    process.stderr.write(logEntry);
    fs.appendFileSync(getLogFile(), logEntry);
  },

  error: (data) => {
    const logEntry = formatLog('ERROR', data);
    process.stderr.write(logEntry);
    fs.appendFileSync(getLogFile(), logEntry);
  },
};

module.exports = logger;

