// config.js - Centralized configuration management
require('dotenv').config({
  path: process.env.NODE_ENV === 'test' ? '.env.test' : '.env'
});

/**
 * Environment variable schema with validation
 * Defines all configuration options and their requirements
 */
const config = {
  // Core application config
  app: {
    name: process.env.APP_NAME || 'Secure App',
    env: process.env.NODE_ENV || 'development',
    port: parseInt(process.env.PORT, 10) || 3000,
    isDevelopment: (process.env.NODE_ENV || 'development') === 'development',
    isProduction: process.env.NODE_ENV === 'production',
    isTest: process.env.NODE_ENV === 'test',
  },

  // Security config
  security: {
    rateLimitWindowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS, 10) || 15 * 60 * 1000,
    rateLimitMax: parseInt(process.env.RATE_LIMIT_MAX, 10) || 100,
    bodyLimit: process.env.BODY_LIMIT || '10kb',
    corsOrigins: process.env.CORS_ORIGINS?.split(',') || ['http://localhost:3000'],
    trustProxy: process.env.TRUST_PROXY === 'true',
  },

  // Database config (if needed)
  database: {
    url: process.env.DATABASE_URL || null,
    useSSL: process.env.DATABASE_SSL === 'true',
  },

  // External services config
  services: {
    aws: {
      accessKeyId: process.env.AWS_ACCESS_KEY_ID || null,
      secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY || null,
      region: process.env.AWS_REGION || 'us-east-1',
    },
    anthropic: {
      apiKey: process.env.ANTHROPIC_API_KEY || null,
    },
    stripe: {
      secretKey: process.env.STRIPE_SECRET_KEY || null,
    },
    logfire: {
      token: process.env.LOGFIRE_TOKEN || null,
    },
  },

  // Logging config
  logging: {
    level: process.env.LOG_LEVEL || 'info',
    format: process.env.LOG_FORMAT || 'json',
    output: process.env.LOG_OUTPUT || 'both', // console, file, both
  },
};

/**
 * Validate required environment variables based on environment
 */
function validateConfig() {
  const errors = [];

  // Always required
  // (none for this minimal app)

  // Production requirements
  if (config.app.isProduction) {
    if (!process.env.PORT) {
      errors.push('PORT must be specified in production');
    }
  }

  // Database integration (if DATABASE_URL is set, validate it)
  if (config.database.url && !isValidPostgresUrl(config.database.url)) {
    errors.push('DATABASE_URL must be a valid PostgreSQL connection string');
  }

  // External services validation
  if (config.services.aws.accessKeyId && !config.services.aws.secretAccessKey) {
    errors.push('AWS_SECRET_ACCESS_KEY required when AWS_ACCESS_KEY_ID is set');
  }
  if (config.services.stripe.secretKey && !isValidStripeKey(config.services.stripe.secretKey)) {
    errors.push('STRIPE_SECRET_KEY appears to be invalid');
  }

  if (errors.length > 0) {
    const errorMessage = `Configuration validation failed:\n${errors.join('\n')}`;
    if (config.app.isProduction) {
      throw new Error(errorMessage);
    } else {
      console.warn('⚠️ Configuration warnings:\n', errorMessage);
    }
  }
}

/**
 * Validation helpers
 */
function isValidPostgresUrl(url) {
  try {
    const urlObj = new URL(url);
    return urlObj.protocol === 'postgresql:' || urlObj.protocol === 'postgres:';
  } catch {
    return false;
  }
}

function isValidStripeKey(key) {
  return key.startsWith('sk_live_') || key.startsWith('sk_test_');
}

// Validate on load
try {
  validateConfig();
} catch (error) {
  console.error('❌ Configuration Error:', error.message);
  process.exit(1);
}

/**
 * Export configuration
 */
module.exports = config;

/**
 * Export validation function for testing
 */
module.exports.validateConfig = validateConfig;

/**
 * Get safe config for logging (strips secrets)
 */
module.exports.getSafeConfig = () => {
  const safe = JSON.parse(JSON.stringify(config));

  // Redact sensitive values
  if (safe.services.aws.accessKeyId) {
    safe.services.aws.accessKeyId = '***REDACTED***';
    safe.services.aws.secretAccessKey = '***REDACTED***';
  }
  if (safe.services.stripe.secretKey) {
    safe.services.stripe.secretKey = '***REDACTED***';
  }
  if (safe.services.anthropic.apiKey) {
    safe.services.anthropic.apiKey = '***REDACTED***';
  }
  if (safe.services.logfire.token) {
    safe.services.logfire.token = '***REDACTED***';
  }
  if (safe.database.url) {
    safe.database.url = '***REDACTED***';
  }

  return safe;
};

// app-with-config.js - Using centralized configuration
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const config = require('./config');
const logger = require('./logger');

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// Security headers with Helmet
app.use(helmet());

// Rate limiting - protect against DoS
const limiter = rateLimit({
  windowMs: config.security.rateLimitWindowMs,
  max: config.security.rateLimitMax,
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);

// Body parser with size limits from config
app.use(express.json({ limit: config.security.bodyLimit }));
app.use(express.urlencoded({ limit: config.security.bodyLimit, extended: true }));

// Data sanitization against NoSQL injection
app.use(mongoSanitize());

// ============================================
// REQUEST LOGGING & VALIDATION
// ============================================

// Request logging middleware
app.use((req, res, next) => {
  logger.info({
    method: req.method,
    path: req.path,
    ip: req.ip,
    timestamp: new Date().toISOString(),
  });
  next();
});

// ============================================
// ROUTES
// ============================================

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    // Return safe config info in development
    const healthData = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      environment: config.app.env,
    };

    if (config.app.isDevelopment) {
      healthData.config = config.getSafeConfig();
    }

    res.json(healthData);
  } catch (error) {
    logger.error('Health check failed:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Users endpoint with input validation
app.get('/users', (req, res, next) => {
  try {
    const { page = 1, limit = 10, sort = 'id' } = req.query;

    // Input validation
    const pageNum = parseInt(page, 10);
    const limitNum = parseInt(limit, 10);

    if (!Number.isInteger(pageNum) || pageNum < 1) {
      return res.status(400).json({
        error: 'Invalid page parameter. Must be a positive integer.',
      });
    }

    if (!Number.isInteger(limitNum) || limitNum < 1 || limitNum > 100) {
      return res.status(400).json({
        error: 'Invalid limit parameter. Must be between 1 and 100.',
      });
    }

    // Whitelist allowed sort fields
    const allowedSortFields = ['id', 'name'];
    if (!allowedSortFields.includes(sort)) {
      return res.status(400).json({
        error: `Invalid sort field. Allowed: ${allowedSortFields.join(', ')}`,
      });
    }

    // Mock data
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply sorting and pagination
    const startIdx = (pageNum - 1) * limitNum;
    const paginatedUsers = allUsers.slice(startIdx, startIdx + limitNum);

    res.json({
      data: paginatedUsers,
      page: pageNum,
      limit: limitNum,
      total: allUsers.length,
    });
  } catch (error) {
    next(error);
  }
});

// ============================================
// 404 HANDLER
// ============================================

app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    path: req.path,
  });
});

// ============================================
// GLOBAL ERROR HANDLER (MUST BE LAST)
// ============================================

app.use((err, req, res, next) => {
  logger.error({
    message: err.message,
    stack: err.stack,
    method: req.method,
    path: req.path,
    timestamp: new Date().toISOString(),
  });

  // Don't leak error details in production
  const errorResponse = {
    error: config.app.isDevelopment ? err.message : 'Internal server error',
  };

  if (config.app.isDevelopment) {
    errorResponse.stack = err.stack;
  }

  const statusCode = err.statusCode || 500;
  res.status(statusCode).json(errorResponse);
});

// ============================================
// SERVER STARTUP
// ============================================

const server = app.listen(config.app.port, () => {
  logger.info(`Server running on port ${config.app.port} (${config.app.env})`);
  if (config.app.isDevelopment) {
    logger.info('Configuration loaded:', config.getSafeConfig());
  }
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (err) => {
  logger.error('Unhandled Rejection:', err);
  server.close(() => {
    process.exit(1);
  });
});

module.exports = app;

