# Security Review: app.js

## Current Issues & Recommendations

### 1. **Missing Error Handling** (Critical)
**Issue:** No try-catch blocks or error middleware to handle unexpected errors.
- Routes don't validate requests or handle errors gracefully
- Unhandled promise rejections could crash the server

**Recommendation:**
```javascript
// Add global error handling middleware
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);
  res.status(500).json({ 
    error: 'Internal Server Error',
    message: process.env.NODE_ENV === 'production' ? undefined : err.message
  });
});

// Handle 404s
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});
```

---

### 2. **No Input Validation** (High)
**Issue:** The `/users` endpoint accepts query parameters but doesn't validate them.
- Could be exploited for NoSQL injection, parameter pollution, or DoS attacks
- No rate limiting on endpoints

**Recommendation:**
```javascript
const { query, validationResult } = require('express-validator');

app.get('/users', 
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  query('offset').optional().isInt({ min: 0 }).toInt(),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const limit = req.query.limit || 10;
    const offset = req.query.offset || 0;

    // Return paginated results
    res.json({ users: [...], total: 2, limit, offset });
  }
);
```

---

### 3. **No Security Headers** (High)
**Issue:** Application doesn't set security headers (HSTS, CSP, X-Frame-Options, etc.)

**Recommendation:**
```javascript
const helmet = require('helmet');
app.use(helmet()); // Adds 15+ security headers automatically
```

**Headers set by helmet:**
- `Strict-Transport-Security` (HSTS)
- `X-Frame-Options` (clickjacking protection)
- `X-Content-Type-Options` (MIME sniffing prevention)
- `Content-Security-Policy`
- And more...

---

### 4. **No Input Sanitization** (High)
**Issue:** User data is returned as-is without sanitization.
- XSS vulnerability if user data includes HTML/JavaScript
- Sensitive data exposure

**Recommendation:**
```javascript
const mongoSanitize = require('mongo-sanitize');
app.use(mongoSanitize()); // Prevents NoSQL injection

// Also sanitize before sending to client
app.get('/users', (req, res) => {
  const sanitizedUsers = users.map(user => ({
    id: user.id,
    name: sanitizeHtml(user.name, { allowedTags: [] }),
    email: user.email // Already validated format
  }));
  res.json(sanitizedUsers);
});
```

---

### 5. **No Rate Limiting** (Medium)
**Issue:** Endpoints are vulnerable to DoS/brute force attacks

**Recommendation:**
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.'
});

app.use(limiter);

// Stricter limit for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5
});
```

---

### 6. **Missing CORS Configuration** (Medium)
**Issue:** CORS not explicitly configured - allows any origin by default in browser context

**Recommendation:**
```javascript
const cors = require('cors');

app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || 'http://localhost:3000',
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));
```

---

### 7. **No Logging/Monitoring** (Medium)
**Issue:** No request logging for security auditing

**Recommendation:**
```javascript
const morgan = require('morgan');

// Log all requests (except sensitive data)
app.use(morgan(':remote-addr - :remote-user [:date[clf]] ":method :url HTTP/:http-version" :status :res[content-length]'));

// Custom error logging
app.use((err, req, res, next) => {
  console.error({
    timestamp: new Date().toISOString(),
    method: req.method,
    url: req.url,
    ip: req.ip,
    status: res.statusCode,
    error: err.message
  });
  // ... error response
});
```

---

### 8. **No Authentication/Authorization** (Medium)
**Issue:** All endpoints are publicly accessible without authentication

**Recommendation:**
```javascript
const jwt = require('jsonwebtoken');

const verifyToken = (req, res, next) => {
  const token = req.headers['authorization']?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Missing token' });
  }

  try {
    req.user = jwt.verify(token, process.env.JWT_SECRET);
    next();
  } catch (err) {
    return res.status(403).json({ error: 'Invalid token' });
  }
};

app.get('/users', verifyToken, (req, res) => {
  // Protected endpoint
});
```

---

### 9. **No Input Size Limits** (Medium)
**Issue:** No protection against large payload attacks

**Recommendation:**
```javascript
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));
```

---

### 10. **Exposed Sensitive Information** (Low)
**Issue:** Error messages and timestamps could leak information

**Recommendation:**
```javascript
// Don't expose stack traces in production
app.use((err, req, res, next) => {
  const isDevelopment = process.env.NODE_ENV !== 'production';

  res.status(err.status || 500).json({
    error: 'An error occurred',
    ...(isDevelopment && { message: err.message, stack: err.stack })
  });
});
```

---

## Recommended Dependencies

```json
{
  "dependencies": {
    "express": "^4.18.0",
    "helmet": "^7.0.0",
    "express-validator": "^7.0.0",
    "express-rate-limit": "^6.10.0",
    "cors": "^2.8.5",
    "mongo-sanitize": "^2.1.0",
    "sanitize-html": "^2.7.0",
    "morgan": "^1.10.0",
    "jsonwebtoken": "^9.0.0",
    "dotenv": "^16.0.0"
  }
}
```

---

## Quick Start: Secure app.js

See `app.secure.js` for a refactored version implementing these recommendations.

---

## Summary

| Priority | Issue | Impact |
|----------|-------|--------|
| 🔴 Critical | No error handling | App crashes, data exposure |
| 🔴 Critical | No input validation | Injection attacks, DoS |
| 🟠 High | No security headers | XSS, clickjacking, MIME attacks |
| 🟠 High | No sanitization | XSS, data corruption |
| 🟡 Medium | No rate limiting | DoS attacks |
| 🟡 Medium | No CORS config | Cross-origin exploits |
| 🟡 Medium | No authentication | Unauthorized access |
| 🟢 Low | Exposed stack traces | Information disclosure |

// Secure version of app.js with best practices
// Implements error handling, input validation, and security measures

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');
const mongoSanitize = require('mongo-sanitize');
const morgan = require('morgan');
require('dotenv').config();

const app = express();

// ===== SECURITY MIDDLEWARE =====

// 1. Helmet: Set security headers
app.use(helmet());

// 2. Body size limits (prevent large payload attacks)
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 3. CORS: Only allow specified origins
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

// 4. NoSQL Injection prevention
app.use(mongoSanitize());

// 5. Request logging
app.use(morgan('combined'));

// 6. Rate limiting: Global
const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false // Disable the `X-RateLimit-*` headers
});
app.use(globalLimiter);

// 7. Stricter rate limit for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  skipSuccessfulRequests: true
});

// ===== ROUTES =====

/**
 * Health check endpoint
 * No authentication required
 */
app.get('/health', (req, res, next) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString()
    });
  } catch (err) {
    next(err);
  }
});

/**
 * Get users endpoint
 * Query parameters: limit (1-100), offset (≥0)
 */
app.get('/users',
  // Input validation
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .toInt()
    .withMessage('Limit must be between 1 and 100'),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .toInt()
    .withMessage('Offset must be a non-negative integer'),
  (req, res, next) => {
    try {
      // Check validation errors
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({ 
          error: 'Validation failed',
          details: errors.array() 
        });
      }

      // Safe defaults
      const limit = req.query.limit || 10;
      const offset = req.query.offset || 0;

      // Mock data (in production, fetch from database)
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Validate offset
      if (offset >= users.length) {
        return res.json({ 
          users: [],
          total: users.length,
          limit,
          offset
        });
      }

      // Paginate results
      const paginatedUsers = users.slice(offset, offset + limit);

      res.json({
        users: paginatedUsers,
        total: users.length,
        limit,
        offset
      });
    } catch (err) {
      next(err);
    }
  }
);

// ===== ERROR HANDLING =====

/**
 * 404 Not Found handler
 */
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not Found',
    path: req.path
  });
});

/**
 * Global error handler
 * Must be defined last
 */
app.use((err, req, res, next) => {
  // Log error details (in production, use proper logging service)
  console.error({
    timestamp: new Date().toISOString(),
    method: req.method,
    url: req.url,
    ip: req.ip,
    error: {
      message: err.message,
      stack: process.env.NODE_ENV === 'development' ? err.stack : undefined
    }
  });

  // Don't leak error details in production
  const isDevelopment = process.env.NODE_ENV !== 'production';
  const statusCode = err.statusCode || err.status || 500;

  res.status(statusCode).json({
    error: 'Internal Server Error',
    ...(isDevelopment && { 
      message: err.message,
      stack: err.stack
    })
  });
});

// ===== SERVER STARTUP =====

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

module.exports = app;

