    test('should track rate limits', async () => {
      const res = await request(app).get('/health');
      const limit = parseInt(res.headers['ratelimit-limit']);
      const remaining = parseInt(res.headers['ratelimit-remaining']);

      expect(limit).toBeGreaterThan(0);
      expect(remaining).toBeLessThan(limit);
    });
  });

  describe('CORS', () => {
    test('should set CORS headers for allowed origins', async () => {
      const res = await request(app)
        .get('/health')
        .set('Origin', 'http://localhost:3000');

      // CORS headers may or may not be set depending on implementation
