      const largePayload = 'x'.repeat(11 * 1024); // 11KB > 10KB limit

      const res = await request(app)
        .post('/users')
        .send({ data: largePayload });

      // Should reject or handle gracefully
      expect([413, 400, 404]).toContain(res.status);
    });
  });

});

