// Improved application with security best practices
// - Error handling
// - Input validation
// - Security middleware
// - Access control

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const validator = require('validator');

const app = express();

// ============================================
// 1. SECURITY MIDDLEWARE
// ============================================

// Set security HTTP headers
app.use(helmet());

// Rate limiting to prevent DoS/Brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);

// Body parsing with size limits
app.use(express.json({ limit: '10mb' }));
app.use(express.urlencoded({ limit: '10mb', extended: true }));

// Data sanitization against NoSQL injection
app.use(mongoSanitize());

// ============================================
// 2. LOGGING & ERROR HANDLING
// ============================================

// Request logging middleware
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.path}`);
  next();
});

// ============================================
// 3. VALIDATION UTILITIES
// ============================================

// Sanitize and validate email
const validateEmail = (email) => {
  if (!email || typeof email !== 'string') {
    return false;
  }
  return validator.isEmail(email);
};

// Sanitize string input
const sanitizeString = (str) => {
  if (typeof str !== 'string') return '';
  return str.trim().substring(0, 255); // Limit length to prevent DoS
};

// Validate positive integer
const validatePositiveInteger = (value) => {
  const num = parseInt(value, 10);
  return Number.isInteger(num) && num > 0;
};

// ============================================
// 4. ROUTES WITH SECURITY
// ============================================

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString() 
    });
  } catch (error) {
    console.error('Error in /health endpoint:', error);
    res.status(500).json({ 
      error: 'Internal server error' 
    });
  }
});

// Users endpoint with validation and error handling
app.get('/users', (req, res) => {
  try {
    // Validate optional query parameters
    const { limit = '10', offset = '0' } = req.query;

    // Validate limit parameter
    if (!validatePositiveInteger(limit) || parseInt(limit, 10) > 100) {
      return res.status(400).json({ 
        error: 'Invalid limit parameter. Must be a positive integer <= 100' 
      });
    }

    // Validate offset parameter
    if (!validatePositiveInteger(offset) || parseInt(offset, 10) > 10000) {
      return res.status(400).json({ 
        error: 'Invalid offset parameter. Must be a positive integer <= 10000' 
      });
    }

    const limitNum = parseInt(limit, 10);
    const offsetNum = parseInt(offset, 10);

    // Mock database query with pagination
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Implement pagination
    const paginatedUsers = allUsers.slice(offsetNum, offsetNum + limitNum);

    res.json({
      data: paginatedUsers,
      total: allUsers.length,
      limit: limitNum,
      offset: offsetNum,
    });
  } catch (error) {
    console.error('Error in /users endpoint:', error);
    res.status(500).json({ 
      error: 'Internal server error' 
    });
  }
});

// Example: Search endpoint with input validation
app.get('/users/search', (req, res) => {
  try {
    const { q } = req.query;

    // Input validation
    if (!q) {
      return res.status(400).json({ 
        error: 'Search query (q) is required' 
      });
    }

    if (typeof q !== 'string') {
      return res.status(400).json({ 
        error: 'Search query must be a string' 
      });
    }

    const sanitizedQuery = sanitizeString(q);

    if (sanitizedQuery.length < 2) {
      return res.status(400).json({ 
        error: 'Search query must be at least 2 characters long' 
      });
    }

    // Perform search (mock implementation)
    const mockUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const results = mockUsers.filter(user =>
      user.name.toLowerCase().includes(sanitizedQuery.toLowerCase())
    );

    res.json({ 
      query: sanitizedQuery, 
      results 
    });
  } catch (error) {
    console.error('Error in /users/search endpoint:', error);
    res.status(500).json({ 
      error: 'Internal server error' 
    });
  }
});

// Example: POST endpoint with input validation
app.post('/users', (req, res) => {
  try {
    const { name, email } = req.body;

    // Validate required fields
    if (!name || !email) {
      return res.status(400).json({ 
        error: 'Both name and email are required' 
      });
    }

    // Validate data types
    if (typeof name !== 'string' || typeof email !== 'string') {
      return res.status(400).json({ 
        error: 'Name and email must be strings' 
      });
    }

    // Validate email format
    if (!validateEmail(email)) {
      return res.status(400).json({ 
        error: 'Invalid email format' 
      });
    }

    // Sanitize inputs
    const sanitizedName = sanitizeString(name);

    if (sanitizedName.length < 2) {
      return res.status(400).json({ 
        error: 'Name must be at least 2 characters long' 
      });
    }

    // Mock user creation
    const newUser = {
      id: 3,
      name: sanitizedName,
      email: email.toLowerCase(),
    };

    res.status(201).json({
      message: 'User created successfully',
      user: newUser,
    });
  } catch (error) {
    console.error('Error in POST /users endpoint:', error);
    res.status(500).json({ 
      error: 'Internal server error' 
    });
  }
});

// ============================================
// 5. 404 ERROR HANDLER
// ============================================

app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not found' 
  });
});

// ============================================
// 6. CENTRALIZED ERROR HANDLER
// ============================================

// Global error handling middleware
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Don't expose internal error details to client
  const status = err.status || 500;
  const message = status === 500 ? 'Internal server error' : err.message;

  res.status(status).json({ 
    error: message 
  });
});

// ============================================
// 7. START SERVER
// ============================================

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (err) => {
  console.error('Unhandled Rejection:', err);
  process.exit(1);
});

module.exports = app;

# Security Review: app.js - Detailed Recommendations

## Executive Summary
The current `app.js` has **critical security gaps** in error handling, input validation, and security middleware. This document outlines issues and provides best practices for remediation.

---

## 🔴 CRITICAL ISSUES

### 1. **No Input Validation**
**Risk Level:** HIGH

**Current Problem:**
- Query parameters are accepted without any validation
- User input is directly used without sanitization
- Vulnerable to injection attacks, DoS, and malformed requests

**Example Vulnerability:**
```javascript
// Current: Unsafe
app.get('/users', (req, res) => {
  res.json(users); // No parameter validation
});
```

**Recommendation:**
```javascript
// Improved: Validate all inputs
const { limit = '10', offset = '0' } = req.query;

if (!validatePositiveInteger(limit)) {
  return res.status(400).json({ error: 'Invalid limit' });
}
```

---

### 2. **No Error Handling**
**Risk Level:** HIGH

**Current Problem:**
- No try-catch blocks
- Unhandled exceptions will crash the server or leak details to clients
- No centralized error handler
- Stack traces may expose sensitive information

**Example Vulnerability:**
```javascript
// Current: Unsafe - errors leak to client
app.get('/users', (req, res) => {
  const users = getUsersFromDb(); // If throws, client sees stack trace
  res.json(users);
});
```

**Recommendation:**
```javascript
// Improved: Proper error handling
app.get('/users', (req, res) => {
  try {
    const users = getUsersFromDb();
    res.json(users);
  } catch (error) {
    console.error('Database error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});
```

---

### 3. **Missing Security Middleware**
**Risk Level:** HIGH

**Current Problem:**
- No `helmet.js` for security headers
- No CORS configuration
- No rate limiting (vulnerable to DoS/brute force)
- No request body size limits
- No NoSQL injection protection

**Recommendation:**
```javascript
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');

app.use(helmet()); // Security headers
app.use(express.json({ limit: '10mb' })); // Size limits
app.use(mongoSanitize()); // NoSQL injection protection
app.use(rateLimit({ windowMs: 15 * 60 * 1000, max: 100 })); // Rate limit
```

---

### 4. **Sensitive Data Exposure**
**Risk Level:** MEDIUM

**Current Problem:**
- `/users` endpoint exposes email addresses without authentication
- No access control (anyone can read all user data)
- No encryption or data protection

**Recommendation:**
```javascript
// Add authentication middleware
app.get('/users', authMiddleware, (req, res) => {
  // Only authenticated users can access
  res.json(users);
});

// Or, don't expose sensitive data
app.get('/users', (req, res) => {
  const publicData = users.map(u => ({ id: u.id, name: u.name }));
  res.json(publicData);
});
```

---

### 5. **No Logging/Auditing**
**Risk Level:** MEDIUM

**Current Problem:**
- No request logging for debugging or security audits
- Can't track suspicious activity
- Difficult to diagnose issues in production

**Recommendation:**
```javascript
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.path}`);
  next();
});
```

---

## 🟡 MODERATE ISSUES

### 6. **No Input Length Limits**
**Risk Level:** MEDIUM

**Problem:** Large inputs can cause DoS or buffer overflow attacks

**Solution:**
```javascript
app.use(express.json({ limit: '10mb' }));
app.use(express.urlencoded({ limit: '10mb', extended: true }));

// Manual validation
const sanitizeString = (str) => {
  if (typeof str !== 'string') return '';
  return str.trim().substring(0, 255); // Max 255 chars
};
```

### 7. **No Type Validation**
**Risk Level:** MEDIUM

**Problem:** Requests with unexpected types can bypass logic

**Solution:**
```javascript
if (typeof email !== 'string' || typeof name !== 'string') {
  return res.status(400).json({ error: 'Invalid input types' });
}
```

### 8. **No HTTP Status Code Consistency**
**Risk Level:** LOW

**Problem:** Inconsistent status codes make error handling harder for clients

**Recommendation:**
```javascript
// Consistent error responses
400 - Bad Request (validation errors)
401 - Unauthorized (missing auth)
403 - Forbidden (insufficient permissions)
404 - Not Found
500 - Internal Server Error
```

---

## ✅ BEST PRACTICES IMPLEMENTATION

### A. **Request Validation Library**
Use a validation library like `validator.js`:

```javascript
const validator = require('validator');

const validateEmail = (email) => {
  return validator.isEmail(email);
};

const validateURL = (url) => {
  return validator.isURL(url);
};
```

### B. **Input Sanitization**
```javascript
const sanitizeString = (str) => {
  if (typeof str !== 'string') return '';
  return str.trim().substring(0, 255);
};

const sanitizeInt = (str) => {
  const num = parseInt(str, 10);
  return Number.isInteger(num) ? num : null;
};
```

### C. **Centralized Error Handler**
```javascript
app.use((err, req, res, next) => {
  console.error('Error:', err);

  // Don't expose internal errors
  const message = err.status === 500 ? 'Internal server error' : err.message;
  const status = err.status || 500;

  res.status(status).json({ error: message });
});
```

### D. **Environment-based Configuration**
```javascript
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// Log errors in development, hide in production
if (NODE_ENV === 'production') {
  app.use((err, req, res, next) => {
    // Only log, don't expose
    console.error('Error:', err);
  });
}
```

### E. **Rate Limiting Configuration**
```javascript
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // 100 requests per window
  message: 'Too many requests',
  standardHeaders: true, // RateLimit-* headers
  legacyHeaders: false,
  skip: (req) => req.path === '/health', // Skip health checks
});

app.use(limiter);
```

---

## 📋 REQUIRED DEPENDENCIES

Add these to `package.json`:

```json
{
  "dependencies": {
    "express": "^4.18.0",
    "helmet": "^7.0.0",
    "express-rate-limit": "^6.0.0",
    "express-mongo-sanitize": "^2.2.0",
    "validator": "^13.0.0",
    "cors": "^2.8.5"
  }
}
```

---

## 🔐 SECURITY CHECKLIST

- [ ] All endpoints have input validation
- [ ] All endpoints have try-catch error handling
- [ ] Security middleware is configured (helmet, rate-limit, sanitize)
- [ ] Request body size limits are set
- [ ] Sensitive data is not exposed in responses
- [ ] Authentication/authorization is implemented
- [ ] Logging is in place for audit trails
- [ ] Error messages don't expose stack traces
- [ ] CORS is properly configured
- [ ] HTTPS/TLS is enforced in production
- [ ] Database queries use parameterized statements
- [ ] Secrets are stored in environment variables
- [ ] Regular security audits are scheduled

---

## 🚀 QUICK START: Minimal Secure Version

```javascript
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();

// Security first
app.use(helmet());
app.use(rateLimit({ windowMs: 15 * 60 * 1000, max: 100 }));
app.use(express.json({ limit: '10mb' }));

// Error handling
app.use((err, req, res, next) => {
  console.error(err);
  res.status(err.status || 500).json({ error: 'Internal server error' });
});

// Graceful shutdown
process.on('unhandledRejection', (err) => {
  console.error('Unhandled:', err);
  process.exit(1);
});

module.exports = app;
```

---

## References
- [OWASP Top 10](https://owasp.org/www-project-top-ten/)
- [Express Security Best Practices](https://expressjs.com/en/advanced/best-practice-security.html)
- [Node.js Security Best Practices](https://nodejs.org/en/docs/guides/nodejs-security/)

