// app.js with proper environment variable configuration and validation

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const validator = require('validator');

// ============================================
// 1. ENVIRONMENT CONFIGURATION & VALIDATION
// ============================================

// Load environment variables (in development only - use secrets manager in production)
if (process.env.NODE_ENV !== 'production') {
  try {
    require('dotenv').config();
  } catch (err) {
    console.warn('dotenv not available - using system environment variables');
  }
}

// Define required and optional environment variables
const CONFIG = {
  // Application
  PORT: parseInt(process.env.PORT || '3000', 10),
  NODE_ENV: process.env.NODE_ENV || 'development',

  // Database (optional for current app, but documented)
  DATABASE_URL: process.env.DATABASE_URL || null,

  // AWS (optional for current app, but documented)
  AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID || null,
  AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY || null,
  AWS_REGION: process.env.AWS_REGION || 'us-east-1',

  // APIs (optional for current app, but documented)
  ANTHROPIC_API_KEY: process.env.ANTHROPIC_API_KEY || null,
  STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY || null,
  LOGFIRE_TOKEN: process.env.LOGFIRE_TOKEN || null,

  // Security
  CORS_ORIGIN: process.env.CORS_ORIGIN || 'http://localhost:3000',
  SESSION_SECRET: process.env.SESSION_SECRET || null,
  RATE_LIMIT_MAX: parseInt(process.env.RATE_LIMIT_MAX || '100', 10),

  // Logging
  LOG_LEVEL: process.env.LOG_LEVEL || 'info',
  DEBUG: process.env.DEBUG === 'true',
};

// Validate critical configuration
const validateConfig = () => {
  const errors = [];

  // Validate PORT is a valid number
  if (!Number.isInteger(CONFIG.PORT) || CONFIG.PORT <= 0 || CONFIG.PORT > 65535) {
    errors.push('PORT must be a valid port number (1-65535)');
  }

  // Validate NODE_ENV
  const validEnv = ['development', 'staging', 'production'];
  if (!validEnv.includes(CONFIG.NODE_ENV)) {
    errors.push(`NODE_ENV must be one of: ${validEnv.join(', ')}`);
  }

  // Validate RATE_LIMIT_MAX
  if (!Number.isInteger(CONFIG.RATE_LIMIT_MAX) || CONFIG.RATE_LIMIT_MAX <= 0) {
    errors.push('RATE_LIMIT_MAX must be a positive integer');
  }

  // In production, warn about using secrets manager
  if (CONFIG.NODE_ENV === 'production') {
    if (!CONFIG.SESSION_SECRET && CONFIG.SESSION_SECRET === process.env.SESSION_SECRET) {
      console.warn('⚠️  WARNING: SESSION_SECRET not set in production. Using secrets manager recommended.');
    }
  }

  if (errors.length > 0) {
    console.error('❌ Configuration Validation Errors:');
    errors.forEach(err => console.error(`   - ${err}`));
    throw new Error('Invalid configuration');
  }

  console.log('✅ Configuration validated successfully');
};

// Run validation on startup
validateConfig();

// ============================================
// 2. LOGGING UTILITIES
// ============================================

const logger = {
  info: (msg) => {
    if (['info', 'debug', 'trace'].includes(CONFIG.LOG_LEVEL)) {
      console.log(`[INFO] [${new Date().toISOString()}] ${msg}`);
    }
  },
  warn: (msg) => {
    if (['warn', 'info', 'debug', 'trace'].includes(CONFIG.LOG_LEVEL)) {
      console.warn(`[WARN] [${new Date().toISOString()}] ${msg}`);
    }
  },
  error: (msg, err = null) => {
    console.error(`[ERROR] [${new Date().toISOString()}] ${msg}`);
    if (err && CONFIG.DEBUG) {
      console.error(err.stack);
    }
  },
  debug: (msg) => {
    if (['debug', 'trace'].includes(CONFIG.LOG_LEVEL)) {
      console.log(`[DEBUG] [${new Date().toISOString()}] ${msg}`);
    }
  },
};

// ============================================
// 3. EXPRESS APP INITIALIZATION
// ============================================

const app = express();

// ============================================
// 4. SECURITY MIDDLEWARE
// ============================================

// Set security HTTP headers
app.use(helmet());

// Rate limiting with configurable limit
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: CONFIG.RATE_LIMIT_MAX,
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  skip: (req) => req.path === '/health', // Skip health checks
});

app.use(limiter);

// Body parsing with size limits
app.use(express.json({ limit: '10mb' }));
app.use(express.urlencoded({ limit: '10mb', extended: true }));

// Data sanitization against NoSQL injection
app.use(mongoSanitize());

// ============================================
// 5. REQUEST LOGGING MIDDLEWARE
// ============================================

app.use((req, res, next) => {
  logger.info(`${req.method} ${req.path} from ${req.ip}`);
  next();
});

// ============================================
// 6. VALIDATION UTILITIES
// ============================================

const validateEmail = (email) => {
  if (!email || typeof email !== 'string') {
    return false;
  }
  return validator.isEmail(email);
};

const sanitizeString = (str) => {
  if (typeof str !== 'string') return '';
  return str.trim().substring(0, 255);
};

const validatePositiveInteger = (value) => {
  const num = parseInt(value, 10);
  return Number.isInteger(num) && num > 0;
};

// ============================================
// 7. ROUTES
// ============================================

// Health check endpoint (not rate limited)
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      environment: CONFIG.NODE_ENV,
      uptime: process.uptime(),
    });
  } catch (error) {
    logger.error('Error in /health endpoint', error);
    res.status(500).json({
      error: 'Internal server error',
    });
  }
});

// Users endpoint with validation
app.get('/users', (req, res) => {
  try {
    const { limit = '10', offset = '0' } = req.query;

    // Validate limit parameter
    if (!validatePositiveInteger(limit) || parseInt(limit, 10) > 100) {
      return res.status(400).json({
        error: 'Invalid limit parameter. Must be a positive integer <= 100',
      });
    }

    // Validate offset parameter
    if (!validatePositiveInteger(offset) || parseInt(offset, 10) > 10000) {
      return res.status(400).json({
        error: 'Invalid offset parameter. Must be a positive integer <= 10000',
      });
    }

    const limitNum = parseInt(limit, 10);
    const offsetNum = parseInt(offset, 10);

    // Mock database query
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const paginatedUsers = allUsers.slice(offsetNum, offsetNum + limitNum);

    logger.debug(`Retrieved ${paginatedUsers.length} users`);

    res.json({
      data: paginatedUsers,
      total: allUsers.length,
      limit: limitNum,
      offset: offsetNum,
    });
  } catch (error) {
    logger.error('Error in /users endpoint', error);
    res.status(500).json({
      error: 'Internal server error',
    });
  }
});

// Search endpoint with input validation
app.get('/users/search', (req, res) => {
  try {
    const { q } = req.query;

    if (!q) {
      return res.status(400).json({
        error: 'Search query (q) is required',
      });
    }

    if (typeof q !== 'string') {
      return res.status(400).json({
        error: 'Search query must be a string',
      });
    }

    const sanitizedQuery = sanitizeString(q);

    if (sanitizedQuery.length < 2) {
      return res.status(400).json({
        error: 'Search query must be at least 2 characters long',
      });
    }

    const mockUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const results = mockUsers.filter((user) =>
      user.name.toLowerCase().includes(sanitizedQuery.toLowerCase())
    );

    logger.debug(`Search for "${sanitizedQuery}" returned ${results.length} results`);

    res.json({
      query: sanitizedQuery,
      results,
    });
  } catch (error) {
    logger.error('Error in /users/search endpoint', error);
    res.status(500).json({
      error: 'Internal server error',
    });
  }
});

// POST endpoint for creating users
app.post('/users', (req, res) => {
  try {
    const { name, email } = req.body;

    if (!name || !email) {
      return res.status(400).json({
        error: 'Both name and email are required',
      });
    }

    if (typeof name !== 'string' || typeof email !== 'string') {
      return res.status(400).json({
        error: 'Name and email must be strings',
      });
    }

    if (!validateEmail(email)) {
      return res.status(400).json({
        error: 'Invalid email format',
      });
    }

    const sanitizedName = sanitizeString(name);

    if (sanitizedName.length < 2) {
      return res.status(400).json({
        error: 'Name must be at least 2 characters long',
      });
    }

    const newUser = {
      id: 3,
      name: sanitizedName,
      email: email.toLowerCase(),
    };

    logger.info(`User created: ${sanitizedName} (${email})`);

    res.status(201).json({
      message: 'User created successfully',
      user: newUser,
    });
  } catch (error) {
    logger.error('Error in POST /users endpoint', error);
    res.status(500).json({
      error: 'Internal server error',
    });
  }
});

// ============================================
// 8. 404 ERROR HANDLER
// ============================================

app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
  });
});

// ============================================
// 9. CENTRALIZED ERROR HANDLER
// ============================================

app.use((err, req, res, next) => {
  logger.error('Unhandled error', err);

  // Determine status code
  const status = err.status || err.statusCode || 500;

  // Don't expose internal error details in production
  const message = CONFIG.NODE_ENV === 'production' 
    ? 'Internal server error'
    : err.message;

  res.status(status).json({
    error: message,
    ...(CONFIG.DEBUG && { details: err.stack }),
  });
});

// ============================================
// 10. SERVER STARTUP
// ============================================

const startServer = () => {
  const server = app.listen(CONFIG.PORT, () => {
    logger.info(`🚀 Server running on http://localhost:${CONFIG.PORT}`);
    logger.info(`📝 Environment: ${CONFIG.NODE_ENV}`);
    logger.info(`📊 Log Level: ${CONFIG.LOG_LEVEL}`);
    logger.info(`🔒 Rate Limit: ${CONFIG.RATE_LIMIT_MAX} requests per 15 minutes`);
  });

  // Handle unhandled promise rejections
  process.on('unhandledRejection', (err) => {
    logger.error('Unhandled Rejection', err);
    process.exit(1);
  });

  // Handle uncaught exceptions
  process.on('uncaughtException', (err) => {
    logger.error('Uncaught Exception', err);
    process.exit(1);
  });

  // Graceful shutdown
  process.on('SIGTERM', () => {
    logger.info('SIGTERM signal received: closing HTTP server');
    server.close(() => {
      logger.info('HTTP server closed');
      process.exit(0);
    });
  });

  return server;
};

// Start server if this file is run directly
if (require.main === module) {
  startServer();
}

module.exports = app;

