// Improved application with security best practices
// Includes error handling, input validation, and security hardening

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const xss = require('xss-clean');
const cors = require('cors');
const morgan = require('morgan');

const app = express();

// ============ SECURITY MIDDLEWARE ============

// 1. Set security HTTP headers
app.use(helmet());

// 2. Enable CORS with strict configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 3600
}));

// 3. Body parser with size limits to prevent large payload attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 4. Data sanitization against NoSQL injection
app.use(mongoSanitize());

// 5. Data sanitization against XSS
app.use(xss());

// 6. Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // stricter limit for sensitive endpoints
  skipSuccessfulRequests: true,
});

app.use('/api/', limiter);

// 7. Request logging
app.use(morgan('combined'));

// ============ UTILITY FUNCTIONS ============

/**
 * Validate input string
 * @param {string} input - Input to validate
 * @param {object} options - Validation options
 * @returns {boolean}
 */
const validateInput = (input, options = {}) => {
  const { maxLength = 255, pattern = null } = options;

  if (typeof input !== 'string') return false;
  if (input.length > maxLength) return false;
  if (input.trim().length === 0) return false;
  if (pattern && !pattern.test(input)) return false;

  return true;
};

/**
 * Global error handler wrapper
 */
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// ============ ROUTES ============

/**
 * Health check endpoint
 */
app.get('/health', asyncHandler(async (req, res) => {
  try {
    res.status(200).json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      environment: process.env.NODE_ENV || 'development'
    });
  } catch (error) {
    throw new AppError('Health check failed', 500);
  }
}));

/**
 * Get users endpoint
 * @query {string} filter - Optional filter parameter
 * @query {number} limit - Optional limit (max 100)
 */
app.get('/api/users', strictLimiter, asyncHandler(async (req, res) => {
  try {
    // Input validation for query parameters
    const { filter, limit } = req.query;

    if (filter && !validateInput(filter, { maxLength: 50 })) {
      return res.status(400).json({
        success: false,
        message: 'Invalid filter parameter'
      });
    }

    if (limit) {
      const parsedLimit = parseInt(limit, 10);
      if (isNaN(parsedLimit) || parsedLimit < 1 || parsedLimit > 100) {
        return res.status(400).json({
          success: false,
          message: 'Limit must be a number between 1 and 100'
        });
      }
    }

    // Simulated data (in production, this would be a database query)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply filter if provided
    let filteredUsers = users;
    if (filter) {
      filteredUsers = users.filter(user =>
        user.name.toLowerCase().includes(filter.toLowerCase())
      );
    }

    // Apply limit
    const limitNum = Math.min(parseInt(limit, 10) || 10, 100);
    filteredUsers = filteredUsers.slice(0, limitNum);

    res.status(200).json({
      success: true,
      count: filteredUsers.length,
      data: filteredUsers
    });
  } catch (error) {
    throw new AppError('Failed to retrieve users', 500);
  }
}));

/**
 * Get user by ID
 * @param {number} id - User ID
 */
app.get('/api/users/:id', asyncHandler(async (req, res) => {
  try {
    const { id } = req.params;

    // Validate ID is a positive integer
    const userId = parseInt(id, 10);
    if (isNaN(userId) || userId < 1) {
      return res.status(400).json({
        success: false,
        message: 'Invalid user ID'
      });
    }

    // Simulated database lookup
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === userId);

    if (!user) {
      return res.status(404).json({
        success: false,
        message: 'User not found'
      });
    }

    res.status(200).json({
      success: true,
      data: user
    });
  } catch (error) {
    throw new AppError('Failed to retrieve user', 500);
  }
}));

// ============ ERROR HANDLING ============

/**
 * Custom error class
 */
class AppError extends Error {
  constructor(message, statusCode) {
    super(message);
    this.statusCode = statusCode;
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * 404 handler
 */
app.use((req, res) => {
  res.status(404).json({
    success: false,
    message: 'Route not found'
  });
});

/**
 * Global error handling middleware
 */
app.use((err, req, res, next) => {
  err.statusCode = err.statusCode || 500;
  err.message = err.message || 'Internal Server Error';

  // Log error (in production, use a proper logging service)
  console.error({
    timestamp: new Date().toISOString(),
    status: err.statusCode,
    message: err.message,
    path: req.path,
    method: req.method,
    ip: req.ip
  });

  // Don't leak error details to client in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.statusCode).json({
    success: false,
    message: err.message,
    ...(isDevelopment && { stack: err.stack })
  });
});

// ============ SERVER START ============

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (err) => {
  console.error('UNHANDLED REJECTION:', err);
  server.close(() => {
    process.exit(1);
  });
});

module.exports = app;

# Security Review & Improvements for app.js

## Executive Summary
The original app.js lacks critical security measures including error handling, input validation, and protection against common attacks. The improved version implements industry best practices.

---

## Critical Issues Found

### 1. ❌ NO ERROR HANDLING
**Risk Level:** HIGH

**Problem:**
- No try-catch blocks
- No error handling middleware
- Unhandled promise rejections will crash the server
- No logging of errors

**Solution:**
```javascript
// Global error handler
app.use((err, req, res, next) => {
  err.statusCode = err.statusCode || 500;
  console.error({ timestamp: new Date(), error: err.message });
  res.status(err.statusCode).json({ 
    success: false, 
    message: err.message 
  });
});

// Async handler wrapper
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};
```

---

### 2. ❌ NO INPUT VALIDATION
**Risk Level:** CRITICAL

**Problem:**
- Query parameters not validated
- No protection against injection attacks
- No type checking
- No length limits

**Solution:**
```javascript
app.get('/api/users', (req, res) => {
  const { filter, limit } = req.query;

  // Validate filter
  if (filter && typeof filter !== 'string' || filter.length > 50) {
    return res.status(400).json({ error: 'Invalid filter' });
  }

  // Validate limit
  const parsedLimit = parseInt(limit, 10);
  if (isNaN(parsedLimit) || parsedLimit < 1 || parsedLimit > 100) {
    return res.status(400).json({ error: 'Invalid limit' });
  }
});
```

---

### 3. ❌ NO SECURITY HEADERS
**Risk Level:** HIGH

**Problem:**
- Vulnerable to XSS attacks
- No CSRF protection
- No clickjacking protection
- Missing content security policy

**Solution:**
```javascript
const helmet = require('helmet');
app.use(helmet()); // Sets multiple security headers
// - X-Frame-Options: DENY (prevents clickjacking)
// - X-Content-Type-Options: nosniff
// - Content-Security-Policy
// - Strict-Transport-Security
```

---

### 4. ❌ NO RATE LIMITING
**Risk Level:** HIGH

**Problem:**
- Vulnerable to DDoS attacks
- No brute force protection
- Sensitive endpoints exposed

**Solution:**
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // 100 requests per window
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // stricter for sensitive endpoints
});

app.use('/api/', limiter);
app.get('/api/users', strictLimiter, handler);
```

---

### 5. ❌ NO CORS PROTECTION
**Risk Level:** MEDIUM

**Problem:**
- Allows any origin to access the API
- Missing credential controls
- No method restrictions

**Solution:**
```javascript
const cors = require('cors');

app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || 
          ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 3600
}));
```

---

### 6. ❌ NO REQUEST SANITIZATION
**Risk Level:** CRITICAL

**Problem:**
- Vulnerable to NoSQL injection
- Vulnerable to XSS attacks
- No size limits on payloads

**Solution:**
```javascript
const mongoSanitize = require('express-mongo-sanitize');
const xss = require('xss-clean');

// Prevent large payload attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Sanitize NoSQL injection
app.use(mongoSanitize());

// Sanitize XSS
app.use(xss());
```

---

### 7. ❌ EXPOSED SENSITIVE DATA
**Risk Level:** MEDIUM

**Problem:**
- Email addresses visible to any user
- No access control
- No data filtering

**Solution:**
```javascript
// Filter sensitive data based on user role
const filterUserData = (users, userRole) => {
  return users.map(user => {
    const userData = { id: user.id, name: user.name };

    // Only include email if admin
    if (userRole === 'admin') {
      userData.email = user.email;
    }

    return userData;
  });
};
```

---

### 8. ❌ NO LOGGING/AUDITING
**Risk Level:** MEDIUM

**Problem:**
- No security event tracking
- No debugging capability
- No audit trail

**Solution:**
```javascript
const morgan = require('morgan');

// Request logging
app.use(morgan('combined'));

// Error logging
app.use((err, req, res, next) => {
  console.error({
    timestamp: new Date().toISOString(),
    status: err.statusCode,
    message: err.message,
    path: req.path,
    ip: req.ip // Track source IP
  });
});
```

---

## Required Dependencies

Add to `package.json`:

```json
{
  "dependencies": {
    "express": "^4.18.0",
    "helmet": "^7.0.0",
    "express-rate-limit": "^6.7.0",
    "express-mongo-sanitize": "^2.2.0",
    "xss-clean": "^0.1.1",
    "cors": "^2.8.5",
    "morgan": "^1.10.0",
    "dotenv": "^16.0.3"
  },
  "devDependencies": {
    "jest": "^29.0.0",
    "supertest": "^6.3.0"
  }
}
```

Install with:
```bash
npm install helmet express-rate-limit express-mongo-sanitize xss-clean cors morgan dotenv
```

---

## Environment Configuration

Create `.env` file:
```
NODE_ENV=production
PORT=3000
ALLOWED_ORIGINS=https://example.com,https://app.example.com
LOG_LEVEL=info
```

---

## Additional Security Recommendations

### 1. **Authentication & Authorization**
- Implement JWT or OAuth2
- Add role-based access control (RBAC)
- Verify user permissions before data access

### 2. **HTTPS/TLS**
- Always use HTTPS in production
- Enable HSTS headers
- Use valid SSL certificates

### 3. **Database Security**
- Use prepared statements to prevent SQL injection
- Implement database connection pooling
- Use environment variables for credentials

### 4. **Secrets Management**
- Never commit `.env` files
- Use a secrets manager (AWS Secrets Manager, HashiCorp Vault)
- Rotate secrets regularly

### 5. **Monitoring & Alerts**
- Implement centralized logging (ELK, DataDog)
- Set up alerts for security events
- Monitor for suspicious patterns

### 6. **Testing**
```javascript
// Example test with security checks
describe('GET /api/users', () => {
  it('should reject requests with invalid limit parameter', async () => {
    const res = await request(app)
      .get('/api/users')
      .query({ limit: 'invalid' });

    expect(res.statusCode).toBe(400);
  });

  it('should enforce rate limiting', async () => {
    for (let i = 0; i < 6; i++) {
      const res = await request(app).get('/api/users');
      if (i === 5) {
        expect(res.statusCode).toBe(429); // Too Many Requests
      }
    }
  });
});
```

---

## Security Checklist

- ✅ Error handling (global middleware + async wrappers)
- ✅ Input validation (type, length, format checking)
- ✅ Security headers (Helmet)
- ✅ Rate limiting (express-rate-limit)
- ✅ CORS protection
- ✅ Request sanitization (XSS, NoSQL injection)
- ✅ Request logging (Morgan)
- ✅ Payload size limits
- ✅ 404 handling
- ✅ Unhandled rejection handling

---

## References

- [OWASP Top 10](https://owasp.org/www-project-top-ten/)
- [Express Security Best Practices](https://expressjs.com/en/advanced/best-practice-security.html)
- [Node.js Security Checklist](https://blog.risingstack.com/node-js-security-checklist/)
- [CWE-434: Unrestricted Upload](https://cwe.mitre.org/data/definitions/434.html)

// Example test suite demonstrating security testing
// Run with: npm test

const request = require('supertest');
const app = require('./app-improved');

describe('Security Tests', () => {

  describe('Input Validation', () => {

