// Secure application with error handling, input validation, and security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const validator = require('validator');

const app = express();

// ============================================================================
// MIDDLEWARE - Security Headers & Protection
// ============================================================================

// Set security HTTP headers
app.use(helmet());

// Body parser middleware with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Data sanitization against NoSQL injection
app.use(mongoSanitize());

// Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
  skip: (req) => {
    // Skip rate limiting for health checks
    return req.path === '/health';
  },
});

app.use(limiter);

// CORS configuration (adjust as needed)
const cors = require('cors');
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  optionsSuccessStatus: 200,
}));

// Request logging middleware
app.use((req, res, next) => {
  const timestamp = new Date().toISOString();
  const method = req.method;
  const path = req.path;

  console.log(`[${timestamp}] ${method} ${path}`);

  // Log response
  res.on('finish', () => {
    console.log(`[${timestamp}] ${method} ${path} - Status: ${res.statusCode}`);
  });

  next();
});

// ============================================================================
// INPUT VALIDATION HELPERS
// ============================================================================

/**
 * Validate and sanitize user ID
 * @param {string} id - User ID to validate
 * @returns {boolean} - True if valid
 */
function isValidUserId(id) {
  return /^[0-9]+$/.test(id) && parseInt(id, 10) > 0;
}

/**
 * Validate query parameters for /users endpoint
 * @param {object} query - Query parameters
 * @returns {object} - { valid: boolean, errors: array }
 */
function validateUsersQuery(query) {
  const errors = [];

  // Optional: limit parameter
  if (query.limit !== undefined) {
    const limit = parseInt(query.limit, 10);
    if (isNaN(limit) || limit < 1 || limit > 100) {
      errors.push('Limit must be a number between 1 and 100');
    }
  }

  // Optional: offset parameter
  if (query.offset !== undefined) {
    const offset = parseInt(query.offset, 10);
    if (isNaN(offset) || offset < 0) {
      errors.push('Offset must be a non-negative number');
    }
  }

  // Optional: search parameter
  if (query.search !== undefined) {
    if (typeof query.search !== 'string' || query.search.length > 100) {
      errors.push('Search must be a string of 100 characters or less');
    }
  }

  return {
    valid: errors.length === 0,
    errors,
  };
}

// ============================================================================
// ROUTES
// ============================================================================

/**
 * Health check endpoint
 * No authentication required for health checks (common pattern)
 */
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    });
  } catch (error) {
    // Even health checks should handle errors
    console.error('Health check error:', error);
    res.status(500).json({
      status: 'error',
      message: 'Internal server error',
    });
  }
});

/**
 * Get users endpoint with validation
 * In production, add authentication/authorization middleware
 */
app.get('/users', (req, res) => {
  try {
    // Validate query parameters
    const validation = validateUsersQuery(req.query);

    if (!validation.valid) {
      return res.status(400).json({
        status: 'error',
        message: 'Invalid query parameters',
        errors: validation.errors,
      });
    }

    // Mock database of users
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply limit and offset
    const limit = Math.min(parseInt(req.query.limit || 10, 10), 100);
    const offset = Math.max(parseInt(req.query.offset || 0, 10), 0);

    const users = allUsers.slice(offset, offset + limit);

    // Remove sensitive data if needed (e.g., for non-admin users)
    // For now, we're returning email, but in production consider:
    // const sanitizedUsers = users.map(u => ({ id: u.id, name: u.name }));

    res.json({
      status: 'success',
      data: users,
      pagination: {
        total: allUsers.length,
        limit,
        offset,
        returned: users.length,
      },
    });
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({
      status: 'error',
      message: 'Internal server error',
    });
  }
});

/**
 * Get user by ID endpoint with validation
 */
app.get('/users/:id', (req, res) => {
  try {
    // Validate user ID
    if (!isValidUserId(req.params.id)) {
      return res.status(400).json({
        status: 'error',
        message: 'Invalid user ID format',
      });
    }

    const userId = parseInt(req.params.id, 10);

    // Mock database lookup
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = allUsers.find(u => u.id === userId);

    if (!user) {
      return res.status(404).json({
        status: 'error',
        message: 'User not found',
      });
    }

    res.json({
      status: 'success',
      data: user,
    });
  } catch (error) {
    console.error('Error fetching user:', error);
    res.status(500).json({
      status: 'error',
      message: 'Internal server error',
    });
  }
});

// ============================================================================
// ERROR HANDLING MIDDLEWARE
// ============================================================================

/**
 * 404 Not Found handler
 */
app.use((req, res) => {
  res.status(404).json({
    status: 'error',
    message: 'Endpoint not found',
    path: req.path,
  });
});

/**
 * Global error handling middleware
 * Must be defined last and with 4 parameters (err, req, res, next)
 */
app.use((err, req, res, next) => {
  const status = err.status || err.statusCode || 500;
  const message = err.message || 'Internal server error';

  // Log error with context
  console.error({
    timestamp: new Date().toISOString(),
    status,
    message,
    path: req.path,
    method: req.method,
    error: process.env.NODE_ENV === 'development' ? err : {},
  });

  // Send error response (don't expose internal details in production)
  res.status(status).json({
    status: 'error',
    message: process.env.NODE_ENV === 'production' 
      ? 'Internal server error' 
      : message,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack }),
  });
});

// ============================================================================
// SERVER SETUP
// ============================================================================

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${NODE_ENV} mode`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

# Security Review & Improvements for app.js

## Summary of Issues Found

### 🔴 Critical Issues
1. **No error handling** - Application will crash on unexpected errors
2. **No input validation** - Vulnerable to injection attacks and bad data
3. **Missing security headers** - Exposed to common web attacks
4. **No rate limiting** - Vulnerable to brute force and DoS attacks

### 🟡 Important Issues
5. **No authentication/authorization** - All endpoints publicly accessible
6. **Hardcoded configuration** - No environment variable support
7. **No request logging** - Cannot audit or debug issues
8. **Uncontrolled data exposure** - Sensitive information returned without filtering

---

## Detailed Recommendations

### 1. ERROR HANDLING

**Problem:**
```javascript
app.get('/users', (req, res) => {
  res.json([...]); // No error handling
});
```

**Solution:**
```javascript
app.get('/users', (req, res) => {
  try {
    // Logic here
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({
      status: 'error',
      message: 'Internal server error',
    });
  }
});
```

**Best Practices:**
- Wrap all async operations in try-catch blocks
- Use a centralized error handler middleware
- Never expose stack traces in production
- Log errors with full context (timestamp, path, method, user, etc.)
- Implement graceful shutdown handlers for SIGTERM/SIGINT

### 2. INPUT VALIDATION

**Problem:**
```javascript
app.get('/users', (req, res) => {
  // No validation of req.query
  res.json([...]);
});
```

**Solution:**
```javascript
function validateUsersQuery(query) {
  const errors = [];

  if (query.limit !== undefined) {
    const limit = parseInt(query.limit, 10);
    if (isNaN(limit) || limit < 1 || limit > 100) {
      errors.push('Limit must be between 1 and 100');
    }
  }

  return { valid: errors.length === 0, errors };
}

app.get('/users', (req, res) => {
  const validation = validateUsersQuery(req.query);
  if (!validation.valid) {
    return res.status(400).json({
      status: 'error',
      errors: validation.errors,
    });
  }
  // Process request
});
```

**Best Practices:**
- Validate all user inputs (path params, query strings, body)
- Check data types, lengths, and formats
- Use whitelist approach (allow specific formats)
- Sanitize inputs to prevent injection attacks
- Return clear validation error messages

### 3. SECURITY HEADERS & PROTECTION

**Problem:**
- No helmet middleware for security headers
- No rate limiting
- No CORS configuration
- No body size limits

**Solution:**
```javascript
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

// Security headers
app.use(helmet());

// Body size limit
app.use(express.json({ limit: '10kb' }));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
});
app.use(limiter);

// CORS
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(','),
  credentials: true,
}));
```

**What Each Does:**
- **Helmet** - Sets security headers (X-Frame-Options, X-Content-Type-Options, etc.)
- **Rate Limiting** - Prevents brute force and DoS attacks
- **Body limits** - Prevents large payload attacks
- **CORS** - Controls cross-origin requests
- **NoSQL Sanitization** - Prevents injection attacks

### 4. AUTHENTICATION & AUTHORIZATION

**Current Problem:**
```javascript
app.get('/users', (req, res) => {
  // Anyone can access this
  res.json([...]);
});
```

**Solution:**
```javascript
// Middleware for authentication
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) return res.status(401).json({ error: 'Unauthorized' });

  // Verify token
  jwt.verify(token, process.env.ACCESS_TOKEN_SECRET, (err, user) => {
    if (err) return res.status(403).json({ error: 'Forbidden' });
    req.user = user;
    next();
  });
}

app.get('/users', authenticateToken, (req, res) => {
  // Protected endpoint
  res.json([...]);
});
```

**Best Practices:**
- Implement JWT or session-based authentication
- Add authorization checks based on user roles
- Use HTTPS only in production
- Implement token expiration and refresh mechanisms
- Validate tokens on every request

### 5. DATA SENSITIVITY & LOGGING

**Problem:**
```javascript
app.get('/users', (req, res) => {
  // Exposing all user data without filtering
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
  ]);
});
```

**Solution:**
```javascript
// For non-admin users, filter sensitive data
const sanitizedUsers = users.map(u => ({
  id: u.id,
  name: u.name,
  // Omit email, phone, etc. unless authorized
}));

res.json({
  status: 'success',
  data: sanitizedUsers,
});
```

**Best Practices:**
- Only return necessary data
- Filter based on user permissions
- Use separate endpoints for different data needs
- Consider PII (Personally Identifiable Information) regulations
- Implement audit logging for sensitive operations

### 6. CONFIGURATION MANAGEMENT

**Problem:**
```javascript
app.listen(3000, () => {
  console.log('Server running on port 3000');
});
```

**Solution:**
```javascript
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${NODE_ENV} mode`);
});
```

**Environment Variables to Use:**
```
PORT=3000
NODE_ENV=production
ALLOWED_ORIGINS=https://example.com,https://app.example.com
ACCESS_TOKEN_SECRET=your-secret-key
DATABASE_URL=mongodb://...
LOG_LEVEL=info
```

**Best Practices:**
- Use `.env` files (with `.env.example` for reference)
- Never commit secrets to version control
- Use different configs per environment
- Validate required environment variables on startup

### 7. LOGGING & MONITORING

**Problem:**
- No request logging
- No error logging
- No performance monitoring

**Solution:**
```javascript
// Request logging middleware
app.use((req, res, next) => {
  const timestamp = new Date().toISOString();
  console.log(`[${timestamp}] ${req.method} ${req.path}`);

  res.on('finish', () => {
    console.log(`[${timestamp}] ${req.method} ${req.path} - ${res.statusCode}`);
  });

  next();
});

// Error logging in error handler
app.use((err, req, res, next) => {
  console.error({
    timestamp: new Date().toISOString(),
    status: err.status,
    message: err.message,
    path: req.path,
    method: req.method,
    error: err,
  });
  res.status(500).json({ error: 'Internal server error' });
});
```

**Best Practices:**
- Log all requests with method, path, status, duration
- Log errors with full stack traces (in development)
- Use structured logging (JSON format for parsing)
- Implement centralized logging (e.g., ELK stack, Datadog)
- Set up alerts for errors and anomalies

---

## Dependencies Required

```json
{
  "dependencies": {
    "express": "^4.18.0",
    "helmet": "^7.0.0",
    "express-rate-limit": "^6.7.0",
    "express-mongo-sanitize": "^2.2.0",
    "cors": "^2.8.5",
    "validator": "^13.9.0"
  },
  "devDependencies": {
    "dotenv": "^16.0.0"
  }
}
```

Install with:
```bash
npm install express helmet express-rate-limit express-mongo-sanitize cors validator
npm install --save-dev dotenv
```

---

## Additional Security Checklist

- [ ] Use HTTPS/TLS in production
- [ ] Implement CSRF protection for state-changing requests
- [ ] Add HSTS headers (via helmet)
- [ ] Set up Content Security Policy (CSP)
- [ ] Validate file uploads if applicable
- [ ] Implement proper JWT/session management
- [ ] Use parameterized queries for database operations
- [ ] Implement SQL/NoSQL injection prevention
- [ ] Add security headers (X-Frame-Options, X-Content-Type-Options)
- [ ] Implement request signing for APIs
- [ ] Monitor and log suspicious activities
- [ ] Implement account lockout after failed login attempts
- [ ] Use strong password hashing (bcrypt, argon2)
- [ ] Keep dependencies updated
- [ ] Run security audits (npm audit, OWASP ZAP)
- [ ] Implement proper access control (RBAC/ABAC)

---

## Testing Recommendations

```javascript
// Example: Testing input validation
describe('GET /users', () => {
  it('should reject invalid limit parameter', async () => {
    const res = await request(app)
      .get('/users?limit=999')
      .expect(400);

    expect(res.body.status).toBe('error');
  });

  it('should validate positive integers only', async () => {
    const res = await request(app)
      .get('/users?limit=-5')
      .expect(400);
  });
});
```

---

## References

- [OWASP Top 10](https://owasp.org/www-project-top-ten/)
- [Express Security Best Practices](https://expressjs.com/en/advanced/best-practice-security.html)
- [OWASP API Security](https://owasp.org/www-project-api-security/)
- [Node.js Security Best Practices](https://nodejs.org/en/docs/guides/security/)
- [Helmet.js Documentation](https://helmetjs.github.io/)

