# Security Best Practices Quick Reference

## 🚨 Critical Security Issues to Always Avoid

### 1. **SQL/NoSQL Injection**
```javascript
// ❌ BAD - Direct concatenation
db.users.find({ name: req.query.name });

// ✅ GOOD - Parameterized queries
db.users.find({ name: validator.escape(req.query.name) });
```

### 2. **Unvalidated Input**
```javascript
// ❌ BAD - No validation
app.get('/users/:id', (req, res) => {
  const user = db.findById(req.params.id);
});

// ✅ GOOD - Validated input
app.get('/users/:id', (req, res) => {
  if (!isValidUserId(req.params.id)) {
    return res.status(400).json({ error: 'Invalid ID' });
  }
  const user = db.findById(req.params.id);
});
```

### 3. **Unhandled Errors**
```javascript
// ❌ BAD - No error handling
app.get('/users', async (req, res) => {
  const users = await db.getUsers(); // Could crash!
  res.json(users);
});

// ✅ GOOD - Error handling
app.get('/users', async (req, res) => {
  try {
    const users = await db.getUsers();
    res.json(users);
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: 'Server error' });
  }
});
```

### 4. **Hardcoded Secrets**
```javascript
// ❌ BAD - Secrets in code
const dbPassword = 'mySecurePassword123';

// ✅ GOOD - Environment variables
const dbPassword = process.env.DB_PASSWORD;
if (!dbPassword) {
  throw new Error('DB_PASSWORD environment variable not set');
}
```

### 5. **Exposing Sensitive Data**
```javascript
// ❌ BAD - Returning all data
res.json(user); // Includes password hash, internal IDs, etc.

// ✅ GOOD - Filter sensitive fields
res.json({
  id: user.id,
  name: user.name,
  email: user.email,
  // Omit: password, passwordHash, internalNotes, etc.
});
```

### 6. **Missing Authentication**
```javascript
// ❌ BAD - No authentication check
app.post('/users', (req, res) => {
  // Anyone can create users!
  db.createUser(req.body);
});

// ✅ GOOD - Authenticate first
app.post('/users', authenticateToken, (req, res) => {
  // Only authenticated users can proceed
  db.createUser(req.body);
});
```

### 7. **CSRF Without Protection**
```javascript
// ❌ BAD - No CSRF token validation
app.post('/transfer-money', (req, res) => {
  // Vulnerable to CSRF!
  transferMoney(req.body);
});

// ✅ GOOD - CSRF protection
const csrf = require('csurf');
const csrfProtection = csrf({ cookie: true });

app.post('/transfer-money', csrfProtection, (req, res) => {
  // Protected against CSRF
  transferMoney(req.body);
});
```

