## ✅ Input Validation Patterns

### Email Validation
```javascript
const validator = require('validator');

function validateEmail(email) {
  if (!email || typeof email !== 'string') {
    return { valid: false, error: 'Email must be a string' };
  }
  if (!validator.isEmail(email)) {
    return { valid: false, error: 'Invalid email format' };
  }
  return { valid: true };
}

// Usage
const validation = validateEmail(req.body.email);
if (!validation.valid) {
  return res.status(400).json({ error: validation.error });
}
```

### Number Validation
```javascript
function validateNumber(value, min = 0, max = 100) {
  const num = parseInt(value, 10);
  if (isNaN(num)) {
    return { valid: false, error: 'Must be a number' };
  }
  if (num < min || num > max) {
    return { valid: false, error: `Must be between ${min} and ${max}` };
  }
  return { valid: true, value: num };
}

// Usage
const validation = validateNumber(req.query.limit, 1, 100);
if (!validation.valid) {
  return res.status(400).json({ error: validation.error });
}
```

### String Validation
```javascript
function validateString(value, minLength = 1, maxLength = 100) {
  if (typeof value !== 'string') {
    return { valid: false, error: 'Must be a string' };
  }
  if (value.length < minLength || value.length > maxLength) {
    return { 
      valid: false, 
      error: `Length must be between ${minLength} and ${maxLength}` 
    };
  }
  return { valid: true, value: value.trim() };
}

// Usage
const validation = validateString(req.body.name, 1, 50);
if (!validation.valid) {
  return res.status(400).json({ error: validation.error });
}
```

### UUID Validation
```javascript
function validateUUID(id) {
  const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
  if (!uuidRegex.test(id)) {
    return { valid: false, error: 'Invalid UUID format' };
  }
  return { valid: true };
}
```

