## 🔄 Step-by-Step Migration

### Step 1: Backup Your Current Application (5 minutes)

```bash
# Create a backup branch
git checkout -b backup/original-app
git push origin backup/original-app

# Switch back to main
git checkout main
```

### Step 2: Install Required Dependencies (5 minutes)

```bash
npm install express helmet express-rate-limit express-mongo-sanitize cors validator
npm install --save-dev dotenv
```

**What each does:**
- `helmet` - Security headers
- `express-rate-limit` - Rate limiting
- `express-mongo-sanitize` - NoSQL injection prevention
- `cors` - CORS handling
- `validator` - Input validation

### Step 3: Create Environment Configuration (10 minutes)

```bash
# Create .env file
cp .env.example .env

# Create .gitignore entry for .env
echo ".env" >> .gitignore
```

Edit `.env` with your configuration:
```env
PORT=3000
NODE_ENV=development
ALLOWED_ORIGINS=http://localhost:3000,http://localhost:3001
```

### Step 4: Add Middleware to Your App (20 minutes)

Update your existing `app.js`:

```javascript
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const cors = require('cors');

const app = express();

// ============================================================================
// ADD: Security Middleware
// ============================================================================

// Security headers
app.use(helmet());

// Body parser with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Data sanitization
app.use(mongoSanitize());

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
});
app.use(limiter);

// CORS
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(','),
  credentials: true,
}));

// Request logging
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.path}`);
  next();
});

// ============================================================================
// Your existing routes go here
// ============================================================================

app.get('/users', (req, res) => {
  res.json([...]);
});
```

### Step 5: Add Input Validation (30 minutes)

Create a new file `src/validators.js`:

```javascript
// src/validators.js

function isValidUserId(id) {
  return /^[0-9]+$/.test(id) && parseInt(id, 10) > 0;
}

function validateUsersQuery(query) {
  const errors = [];

  if (query.limit !== undefined) {
    const limit = parseInt(query.limit, 10);
    if (isNaN(limit) || limit < 1 || limit > 100) {
      errors.push('Limit must be between 1 and 100');
    }
  }

  if (query.offset !== undefined) {
    const offset = parseInt(query.offset, 10);
    if (isNaN(offset) || offset < 0) {
      errors.push('Offset must be non-negative');
    }
  }

  return {
    valid: errors.length === 0,
    errors,
  };
}

module.exports = {
  isValidUserId,
  validateUsersQuery,
};
```

Update your routes:

```javascript
const { isValidUserId, validateUsersQuery } = require('./src/validators');

app.get('/users', (req, res) => {
  const validation = validateUsersQuery(req.query);

  if (!validation.valid) {
    return res.status(400).json({
      status: 'error',
      message: 'Invalid parameters',
      errors: validation.errors,
    });
  }

  // Your existing logic
  res.json([...]);
});

app.get('/users/:id', (req, res) => {
  if (!isValidUserId(req.params.id)) {
    return res.status(400).json({
      error: 'Invalid user ID',
    });
  }

  // Your existing logic
  res.json({...});
});
```

### Step 6: Add Error Handling (30 minutes)

Wrap your routes in try-catch:

```javascript
app.get('/users', (req, res) => {
  try {
    // Validation
    const validation = validateUsersQuery(req.query);
    if (!validation.valid) {
      return res.status(400).json({ errors: validation.errors });
    }

    // Your existing logic
    const users = [...];
    res.json({ status: 'success', data: users });
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({
      status: 'error',
      message: 'Internal server error',
    });
  }
});
```

Add global error handler:

```javascript
// 404 handler
app.use((req, res) => {
  res.status(404).json({
    status: 'error',
    message: 'Endpoint not found',
  });
});

// Global error handler (must be last)
app.use((err, req, res, next) => {
  console.error({
    timestamp: new Date().toISOString(),
    error: err.message,
    path: req.path,
    method: req.method,
  });

  const status = err.status || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal server error' 
    : err.message;

  res.status(status).json({
    status: 'error',
    message,
  });
});
```

