// Improved application with security best practices
// Error handling, input validation, and security headers

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const validator = require('validator');

const app = express();

// ============================================================
// 1. SECURITY MIDDLEWARE
// ============================================================

// Set security HTTP headers
app.use(helmet());

// Body parsing with size limits to prevent payload attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// CORS configuration (restrict if possible)
const cors = require('cors');
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || 'http://localhost:3000',
  credentials: true,
  methods: ['GET', 'POST'],
  allowedHeaders: ['Content-Type', 'Authorization']
};
app.use(cors(corsOptions));

// ============================================================
// 2. RATE LIMITING
// ============================================================

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10, // Stricter limit for sensitive endpoints
  skipSuccessfulRequests: true, // Don't count successful requests
});

app.use(limiter);

// ============================================================
// 3. REQUEST LOGGING MIDDLEWARE
// ============================================================

app.use((req, res, next) => {
  const startTime = Date.now();

  res.on('finish', () => {
    const duration = Date.now() - startTime;
    console.log(`[${new Date().toISOString()}] ${req.method} ${req.path} - ${res.statusCode} - ${duration}ms`);
  });

  next();
});

// ============================================================
// 4. ROUTES WITH VALIDATION & ERROR HANDLING
// ============================================================

/**
 * Health check endpoint
 */
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ error: 'Health check failed' });
  }
});

/**
 * Get users endpoint with validation
 * Query parameters: limit, offset
 */
app.get('/users', strictLimiter, (req, res) => {
  try {
    // Input validation
    const { limit = '10', offset = '0' } = req.query;

    // Validate and sanitize input
    if (!validator.isInt(String(limit), { min: 1, max: 100 })) {
      return res.status(400).json({
        error: 'Invalid limit parameter. Must be an integer between 1 and 100.'
      });
    }

    if (!validator.isInt(String(offset), { min: 0 })) {
      return res.status(400).json({
        error: 'Invalid offset parameter. Must be a non-negative integer.'
      });
    }

    const parsedLimit = parseInt(limit, 10);
    const parsedOffset = parseInt(offset, 10);

    // Mock data - in production, this would come from a database
    const allUsers = [
      { id: 1, name: 'Alice' }, // Remove sensitive email from default response
      { id: 2, name: 'Bob' },
    ];

    // Apply pagination
    const paginatedUsers = allUsers.slice(parsedOffset, parsedOffset + parsedLimit);

    res.json({
      data: paginatedUsers,
      total: allUsers.length,
      limit: parsedLimit,
      offset: parsedOffset
    });
  } catch (error) {
    console.error('Get users error:', error);
    res.status(500).json({ error: 'Failed to retrieve users' });
  }
});

/**
 * Get user by ID endpoint with validation
 */
app.get('/users/:id', (req, res) => {
  try {
    const { id } = req.params;

    // Validate ID format
    if (!validator.isInt(id, { min: 1 })) {
      return res.status(400).json({
        error: 'Invalid user ID. Must be a positive integer.'
      });
    }

    const userId = parseInt(id, 10);

    // Mock data
    const users = {
      1: { id: 1, name: 'Alice' },
      2: { id: 2, name: 'Bob' },
    };

    const user = users[userId];

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    res.json(user);
  } catch (error) {
    console.error('Get user error:', error);
    res.status(500).json({ error: 'Failed to retrieve user' });
  }
});

// ============================================================
// 5. 404 HANDLER
// ============================================================

app.use((req, res) => {
  res.status(404).json({
    error: 'Endpoint not found',
    path: req.path,
    method: req.method
  });
});

// ============================================================
// 6. GLOBAL ERROR HANDLER (Must be last)
// ============================================================

app.use((err, req, res, next) => {
  console.error('Unhandled error:', {
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    timestamp: new Date().toISOString()
  });

  // Don't expose error details in production
  const isDevelopment = process.env.NODE_ENV !== 'production';
  const errorMessage = isDevelopment ? err.message : 'Internal server error';

  res.status(err.status || 500).json({
    error: errorMessage,
    ...(isDevelopment && { stack: err.stack })
  });
});

// ============================================================
// 7. SERVER STARTUP
// ============================================================

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`[${new Date().toISOString()}] Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

# Security & Error Handling Review - app.js

## Summary of Issues Found

### 🔴 **Critical Issues**

1. **No Global Error Handler**
   - Unhandled exceptions can crash the server
   - No centralized error logging
   - Client receives no meaningful error responses

2. **No Input Validation**
   - Query parameters not validated
   - Vulnerable to injection attacks and malformed data
   - No type checking or bounds validation

3. **Exposed Sensitive Data**
   - Email addresses returned without authorization checks
   - No data filtering or access control

4. **No Security Headers**
   - Missing CORS configuration
   - No helmet middleware
   - Vulnerable to common web attacks (XSS, clickjacking, etc.)

### 🟡 **High Priority Issues**

5. **No Rate Limiting**
   - Application vulnerable to DoS attacks
   - No protection against brute force

6. **Missing Request Logging**
   - No audit trail
   - Difficult to debug production issues
   - No visibility into attacks

7. **No 404 Handler**
   - Default Express error page exposed
   - Inconsistent API responses

8. **No Graceful Shutdown**
   - No cleanup on process termination
   - Potential data loss or corruption

---

## Detailed Recommendations

### 1. **Error Handling**

**Problem:**
```javascript
app.get('/users', (req, res) => {
  res.json([...]); // No try-catch, crashes on error
});
```

**Solution:**
```javascript
app.get('/users', (req, res) => {
  try {
    // Route logic
  } catch (error) {
    console.error('Get users error:', error);
    res.status(500).json({ error: 'Failed to retrieve users' });
  }
});

// Global error handler at end
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);
  const statusCode = err.status || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal server error' 
    : err.message;

  res.status(statusCode).json({ error: message });
});
```

**Benefits:**
- Prevents server crashes
- Consistent error responses
- Hides sensitive error details in production
- Centralized error logging

---

### 2. **Input Validation**

**Problem:**
```javascript
app.get('/users', (req, res) => {
  // No validation - could receive malicious data
  res.json([...]);
});
```

**Solution:**
```javascript
const validator = require('validator');

app.get('/users', (req, res) => {
  try {
    const { limit = '10', offset = '0' } = req.query;

    // Validate input
    if (!validator.isInt(String(limit), { min: 1, max: 100 })) {
      return res.status(400).json({
        error: 'Invalid limit. Must be 1-100.'
      });
    }

    if (!validator.isInt(String(offset), { min: 0 })) {
      return res.status(400).json({
        error: 'Invalid offset. Must be non-negative.'
      });
    }

    const parsedLimit = parseInt(limit, 10);
    const parsedOffset = parseInt(offset, 10);

    // Safe to use validated values
    res.json([...]);
  } catch (error) {
    res.status(500).json({ error: 'Internal server error' });
  }
});
```

**Best Practices:**
- Whitelist allowed values
- Use type-safe parsing (parseInt, etc.)
- Set reasonable limits (max 100 records, etc.)
- Return descriptive validation errors

---

### 3. **Security Headers & CORS**

**Problem:**
```javascript
const app = express();
app.get('/users', ...); // No security headers
```

**Solution:**
```javascript
const helmet = require('helmet');
const cors = require('cors');

// Add security headers
app.use(helmet());

// Configure CORS
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || 'http://localhost:3000',
  methods: ['GET', 'POST'],
  allowedHeaders: ['Content-Type', 'Authorization']
};
app.use(cors(corsOptions));

// Limit payload size
app.use(express.json({ limit: '10kb' }));
```

**Protection Against:**
- XSS attacks
- Clickjacking
- MIME type sniffing
- Unauthorized CORS requests
- Large payload attacks

---

### 4. **Rate Limiting**

**Problem:**
```javascript
// No protection against abuse
app.get('/users', (req, res) => { ... });
```

**Solution:**
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // 100 requests per window
  message: 'Too many requests, please try again later.'
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10, // Stricter for sensitive endpoints
  skipSuccessfulRequests: true
});

app.use(limiter); // Apply to all routes
app.get('/users', strictLimiter, (req, res) => { ... });
```

**Benefits:**
- Prevents DoS attacks
- Protects against brute force
- Configurable per endpoint

---

### 5. **Data Sensitivity**

**Problem:**
```javascript
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' }, // Exposed!
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Solution:**
```javascript
app.get('/users', (req, res) => {
  try {
    // Only return public data
    const users = [
      { id: 1, name: 'Alice' },
      { id: 2, name: 'Bob' },
    ];

    res.json({
      data: users,
      total: users.length
    });
  } catch (error) {
    res.status(500).json({ error: 'Internal server error' });
  }
});

// For authorized endpoints that need email:
app.get('/users/:id', authenticateUser, (req, res) => {
  try {
    // Return full data only when authenticated
    const user = getUserFromDB(req.params.id);

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    res.json(user);
  } catch (error) {
    res.status(500).json({ error: 'Internal server error' });
  }
});
```

---

### 6. **Request Logging**

**Problem:**
- No visibility into requests
- Difficult to debug

**Solution:**
```javascript
app.use((req, res, next) => {
