// Improved application with security best practices and error handling
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const xss = require('xss-clean');
const { body, query, validationResult } = require('express-validator');

const app = express();
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// ============================================================
// SECURITY MIDDLEWARE
// ============================================================

// Set security HTTP headers
app.use(helmet());

// Rate limiting to prevent DDoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
  skip: (req) => NODE_ENV === 'test', // Skip rate limiting in test environment
});

// Apply rate limiting to all requests
app.use(limiter);

// Body parser with size limits
app.use(express.json({ limit: '10kb' })); // Limit payload size
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Data sanitization against NoSQL injection attacks
app.use(mongoSanitize());

// Data sanitization against XSS attacks
app.use(xss());

// CORS configuration
app.use((req, res, next) => {
  res.setHeader('Access-Control-Allow-Origin', process.env.ALLOWED_ORIGIN || 'http://localhost:3000');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type, Authorization');
  next();
});

// ============================================================
// REQUEST LOGGING MIDDLEWARE
// ============================================================

app.use((req, res, next) => {
  const timestamp = new Date().toISOString();
  console.log(`[${timestamp}] ${req.method} ${req.path}`);
  next();
});

// ============================================================
// ROUTES
// ============================================================

/**
 * Health check endpoint
 * GET /health
 */
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      environment: NODE_ENV,
    });
  } catch (error) {
    handleError(res, error, 500, 'Health check failed');
  }
});

/**
 * Get users with optional filtering
 * GET /users
 * Query parameters:
 *   - limit: number (1-100)
 *   - offset: number (0+)
 */
app.get('/users',
  // Input validation middleware
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be a number between 1 and 100'),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Offset must be a non-negative number'),
  (req, res) => {
    try {
      // Check for validation errors
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({ errors: errors.array() });
      }

      // Parse query parameters with defaults
      const limit = Math.min(parseInt(req.query.limit) || 10, 100);
      const offset = Math.max(parseInt(req.query.offset) || 0, 0);

      // Mock user database
      const allUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Apply pagination
      const paginatedUsers = allUsers.slice(offset, offset + limit);

      res.json({
        data: paginatedUsers,
        pagination: {
          limit,
          offset,
          total: allUsers.length,
        },
      });
    } catch (error) {
      handleError(res, error, 500, 'Failed to retrieve users');
    }
  }
);

/**
 * Get a specific user by ID
 * GET /users/:id
 */
app.get('/users/:id',
  // Validate ID format
  (req, res, next) => {
    if (!/^\d+$/.test(req.params.id)) {
      return res.status(400).json({ error: 'Invalid user ID format' });
    }
    next();
  },
  (req, res) => {
    try {
      const userId = parseInt(req.params.id, 10);

      // Mock user database
      const user = { id: userId, name: 'John Doe', email: 'john@example.com' };

      if (!user) {
        return res.status(404).json({ error: 'User not found' });
      }

      res.json(user);
    } catch (error) {
      handleError(res, error, 500, 'Failed to retrieve user');
    }
  }
);

// ============================================================
// ERROR HANDLING
// ============================================================

/**
 * 404 Not Found handler
 */
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `The requested resource '${req.method} ${req.path}' was not found.`,
  });
});

/**
 * Global error handling middleware
 */
app.use((err, req, res, next) => {
  const timestamp = new Date().toISOString();
  const status = err.status || 500;
  const message = err.message || 'Internal Server Error';

  // Log error (don't expose stack trace to client in production)
  console.error(`[${timestamp}] ERROR:`, err);

  res.status(status).json({
    error: {
      status,
      message,
      ...(NODE_ENV === 'development' && { stack: err.stack }),
    },
  });
});

// ============================================================
// UTILITIES
// ============================================================

/**
 * Centralized error handling utility
 */
function handleError(res, error, statusCode = 500, message = 'An error occurred') {
  console.error('[ERROR]', error);

  const response = {
    error: message,
    ...(NODE_ENV === 'development' && { details: error.message }),
  };

  res.status(statusCode).json(response);
}

// ============================================================
// SERVER STARTUP
// ============================================================

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${NODE_ENV} mode`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  process.exit(1);
});

module.exports = app;

