// Improved application with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');
const app = express();

// ============ SECURITY MIDDLEWARE ============

// Apply security headers
app.use(helmet());

// Body parser with size limits to prevent large payload attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// Rate limiting middleware
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

// Apply rate limiting to all routes
app.use(limiter);

// ============ LOGGING & ERROR TRACKING ============

// Request logging middleware
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.path}`);
  next();
});

// ============ ROUTE HANDLERS ============

app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString() 
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

app.get('/users', 
  // Input validation for query parameters
  query('filter')
    .optional()
    .isString()
    .trim()
    .isLength({ max: 50 })
    .withMessage('Filter must be a string with max 50 characters'),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),

  // Handler function with validation error checking
  (req, res) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        error: 'Validation failed',
        details: errors.array() 
      });
    }

    try {
      const { filter, limit } = req.query;
      const pageLimit = limit ? parseInt(limit) : 10;

      // Mock user data - in production, this would be from a database
      let users = [
        { id: 1, name: 'Alice' }, // Email removed for security
        { id: 2, name: 'Bob' },
      ];

      // Apply filter if provided
      if (filter) {
        users = users.filter(user => 
          user.name.toLowerCase().includes(filter.toLowerCase())
        );
      }

      // Apply limit
      users = users.slice(0, pageLimit);

      res.json({ 
        data: users,
        count: users.length,
        limit: pageLimit
      });
    } catch (error) {
      console.error('Users endpoint error:', error);
      res.status(500).json({ error: 'Internal server error' });
    }
  }
);

// ============ ERROR HANDLING ============

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// Global error handling middleware (must be last)
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Don't leak error details in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: 'Internal server error',
    ...(isDevelopment && { details: err.message })
  });
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
