});

module.exports = app;

# Security Review: app.js - Detailed Analysis

## 1. ERROR HANDLING ISSUES

### Problem: No Error Handling
```javascript
// VULNERABLE: No try-catch, server crashes on error
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});
```

### Solution: Wrap with try-catch and error middleware
```javascript
app.get('/health', (req, res) => {
  try {
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});
```

### Additional Improvements:
- Add global error handling middleware as the last middleware
- Handle unhandled promise rejections
- Implement proper HTTP status codes
- Add 404 handler for undefined routes

---

## 2. INPUT VALIDATION ISSUES

### Problem: No Validation
```javascript
// VULNERABLE: Query parameters accepted without validation
app.get('/users', (req, res) => {
  res.json([...]);
});
```

### Risks:
- **Injection attacks** - malicious input passed to database queries
- **NoSQL injection** - if used with MongoDB/etc
- **ReDoS (Regular Expression Denial of Service)** - malicious patterns
- **Parameter pollution** - unexpected parameter combinations

### Solution: Use express-validator
```javascript
app.get('/users',
  query('filter')
    .optional()
    .isString()
    .trim()
    .isLength({ max: 50 })
    .withMessage('Filter must be max 50 characters'),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be 1-100'),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ error: 'Validation failed' });
    }
    // ... rest of handler
  }
);
```

---

## 3. MISSING SECURITY MIDDLEWARE

### Problem: No Security Headers
```javascript
// VULNERABLE: Exposed to various attacks
const app = express();
app.listen(3000);
```

### Solutions:

#### A. Add Helmet.js for security headers
```javascript
const helmet = require('helmet');
app.use(helmet());
```

Headers provided:
- `Strict-Transport-Security` - Force HTTPS
- `X-Content-Type-Options` - Prevent MIME sniffing
- `X-Frame-Options` - Prevent clickjacking
- `Content-Security-Policy` - Prevent XSS/injection
- And more...

#### B. Configure CORS
```javascript
const cors = require('cors');
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || 'http://localhost:3000',
  credentials: true,
  optionsSuccessStatus: 200
}));
```

#### C. Implement Rate Limiting
```javascript
const rateLimit = require('express-rate-limit');
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // 100 requests per 15 minutes
  message: 'Too many requests, try again later'
});
app.use(limiter);
```

#### D. Body Size Limits
```javascript
app.use(express.json({ limit: '10kb' })); // Prevent large payload attacks
app.use(express.urlencoded({ limit: '10kb', extended: false }));
```

---

## 4. DATA EXPOSURE ISSUES

### Problem: Sensitive Data Leaked
```javascript
// VULNERABLE: Exposing email addresses
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

### Risks:
- **Information disclosure** - unnecessary PII exposure
- **Email harvesting** - can be scraped for spam/phishing campaigns
- **Privacy violations** - potential GDPR/legal issues

### Solution: Remove unnecessary fields
```javascript
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' }
  ]);
});
```

---

## 5. MISSING LOGGING & MONITORING

### Problem: No audit trail
```javascript
// VULNERABLE: No way to track requests or security events
app.listen(3000, () => {
  console.log('Server running on port 3000');
});
```

### Solution: Add request logging
```javascript
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.path}`);
  next();
});
```

### Recommendations for Production:
- Use structured logging (Winston, Bunyan, Pino)
- Log security events (failed validations, rate limits hit)
- Monitor for suspicious patterns
- Use centralized log management

---

## 6. NO AUTHENTICATION/AUTHORIZATION

### Problem: Completely open API
```javascript
// VULNERABLE: Anyone can access any endpoint
app.get('/users', (req, res) => {
  res.json([...]);
});
```

### Solution Options:

#### A. API Key Authentication
```javascript
const apiKeyMiddleware = (req, res, next) => {
  const apiKey = req.headers['x-api-key'];
  if (!apiKey || apiKey !== process.env.API_KEY) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  next();
};
app.use(apiKeyMiddleware);
```

#### B. JWT Authentication
```javascript
const jwt = require('jsonwebtoken');
const authMiddleware = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];
  if (!token) {
    return res.status(401).json({ error: 'No token' });
  }
  try {
    req.user = jwt.verify(token, process.env.JWT_SECRET);
    next();
  } catch (err) {
    res.status(403).json({ error: 'Invalid token' });
  }
};
app.use(authMiddleware);
```

---

