// Enhanced application with security best practices
// Error handling, input validation, and security middleware

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const xss = require('xss-clean');
const logger = require('morgan');
const { body, query, validationResult } = require('express-validator');

const app = express();

// ============ SECURITY MIDDLEWARE ============

// 1. Set security HTTP headers
app.use(helmet());

// 2. Body parser with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 3. Data sanitization against NoSQL injection
app.use(mongoSanitize());

// 4. Data sanitization against XSS
app.use(xss());

// 5. Request logging
app.use(logger('combined'));

// 6. Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api/', limiter);

// 7. CORS configuration (adjust as needed for your use case)
const cors = require('cors');
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type'],
};
app.use(cors(corsOptions));

// ============ ROUTES ============

/**
 * Health check endpoint
 */
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    });
  } catch (error) {
    handleError(error, res);
  }
});

/**
 * Get users with optional filtering
 * Query parameters: limit (1-100), offset (0+)
 */
app.get(
  '/api/users',
  // Input validation
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Offset must be 0 or greater'),
  (req, res) => {
    try {
      // Check for validation errors
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({
          error: 'Validation failed',
          details: errors.array(),
        });
      }

      const limit = Math.min(parseInt(req.query.limit) || 20, 100);
      const offset = Math.max(parseInt(req.query.offset) || 0, 0);

      const allUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      const users = allUsers.slice(offset, offset + limit);

      res.json({
        data: users,
        pagination: {
          limit,
          offset,
          total: allUsers.length,
        },
      });
    } catch (error) {
      handleError(error, res);
    }
  }
);

/**
 * Create a new user with validation
 */
app.post(
  '/api/users',
  // Input validation
  body('name')
    .trim()
    .isLength({ min: 1, max: 100 })
    .withMessage('Name must be between 1 and 100 characters')
    .escape(),
  body('email')
    .isEmail()
    .withMessage('Invalid email format')
    .normalizeEmail(),
  (req, res) => {
    try {
      // Check for validation errors
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({
          error: 'Validation failed',
          details: errors.array(),
        });
      }

      // Simulate creating a user
      const newUser = {
        id: Math.random(), // In production, use a proper ID generation method
        name: req.body.name,
        email: req.body.email,
      };

      res.status(201).json({
        message: 'User created successfully',
        data: newUser,
      });
    } catch (error) {
      handleError(error, res);
    }
  }
);

// ============ ERROR HANDLING ============

/**
 * 404 Not Found handler
 */
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: 'The requested resource was not found',
    path: req.path,
  });
});

/**
 * Global error handler
 */
app.use((err, req, res, next) => {
  handleError(err, res);
});

/**
 * Centralized error handling function
 */
function handleError(error, res) {
  console.error('Error:', error.message);

  // Don't expose stack traces in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(error.status || 500).json({
    error: error.message || 'Internal Server Error',
    ...(isDevelopment && { stack: error.stack }),
  });
}

// ============ SERVER STARTUP ============

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

# Before & After Comparison

## Issue #1: No Error Handling

### ❌ BEFORE (Vulnerable)
```javascript
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
  ]);
});
// If an error occurs, the entire server crashes!
// Stack traces are exposed to the client!
```

### ✅ AFTER (Secure)
```javascript
app.get('/api/users', (req, res) => {
  try {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
    ];
    res.json({ data: users });
  } catch (error) {
    handleError(error, res);
  }
});

// Centralized error handler
function handleError(error, res) {
  console.error('Error:', error.message);
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(error.status || 500).json({
    error: error.message || 'Internal Server Error',
    ...(isDevelopment && { stack: error.stack }),
  });
}

// Global error middleware
app.use((err, req, res, next) => {
  handleError(err, res);
});
```

**Benefits:**
- Server doesn't crash
- Stack traces hidden in production
- Consistent error responses
- Easy to debug with logs

