# Security Best Practices Cheat Sheet

## Express.js Security Quick Reference

### 1. Essential Middleware (Copy & Paste)

```javascript
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const xss = require('xss-clean');
const cors = require('cors');
const morgan = require('morgan');

const app = express();

// Security middleware (order matters!)
app.use(helmet()); // 1. Security headers
app.use(express.json({ limit: '10kb' })); // 2. Request size limit
app.use(express.urlencoded({ limit: '10kb' })); // 2b. Form data limit
app.use(mongoSanitize()); // 3. NoSQL injection prevention
app.use(xss()); // 4. XSS prevention
app.use(cors({ origin: ['https://yourdomain.com'] })); // 5. CORS
app.use(morgan('combined')); // 6. Logging
app.use('/api', rateLimit({ windowMs: 15*60*1000, max: 100 })); // 7. Rate limit
```

### 2. Input Validation Template

```javascript
const { body, query, param, validationResult } = require('express-validator');

// GET with query validation
app.get('/users',
  query('limit').optional().isInt({ min: 1, max: 100 }),
  query('offset').optional().isInt({ min: 0 }),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    // Safe to use req.query
    res.json({ data: [] });
  }
);

// POST with body validation
app.post('/users',
  body('name').trim().isLength({ min: 1, max: 100 }).escape(),
  body('email').isEmail().normalizeEmail(),
  body('age').optional().isInt({ min: 0, max: 150 }),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    // Safe to use req.body
    res.status(201).json({ success: true });
  }
);

// PUT with param validation
app.put('/users/:id',
  param('id').isUUID(),
  body('name').optional().trim().escape(),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    res.json({ success: true });
  }
);
```

### 3. Error Handling Template

```javascript
// Wrap all route handlers in try-catch
app.get('/users', async (req, res) => {
  try {
    // Your code here
    const users = await db.users.find();
    res.json({ data: users });
  } catch (error) {
    handleError(error, res);
  }
});

// Centralized error handler
function handleError(error, res) {
  console.error('Error:', error.message);

  const statusCode = error.status || 500;
  const isDev = process.env.NODE_ENV === 'development';

  res.status(statusCode).json({
    error: error.message || 'Internal Server Error',
    ...(isDev && { stack: error.stack }),
  });
}

// Global error handler (last middleware)
app.use((err, req, res, next) => {
  handleError(err, res);
});

// 404 handler (before error handler)
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});
```

### 4. Environment Variables Template

```javascript
// Load from .env file using dotenv
require('dotenv').config();

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
const DB_URL = process.env.DB_URL || 'mongodb://localhost';
