## Common Attack Patterns & Fixes

### SQL/NoSQL Injection
```javascript
// ❌ VULNERABLE
db.query(`SELECT * FROM users WHERE id = ${req.query.id}`);
db.collection.find({ id: req.query.id });

// ✅ SAFE
db.query('SELECT * FROM users WHERE id = ?', [req.query.id]);
db.collection.find({ id: new ObjectId(req.query.id) }); // with validation
```

### XSS (Cross-Site Scripting)
```javascript
// ❌ VULNERABLE
res.send(`<h1>${req.body.title}</h1>`);

// ✅ SAFE
// Use template escaping
res.render('page', { title: req.body.title }); // auto-escaped in most engines
// Or manually escape
body('title').escape()
```

### CSRF (Cross-Site Request Forgery)
```javascript
// ✅ SAFE
const csrf = require('csurf');
app.use(csrf());

app.post('/users', csrf(), (req, res) => {
  // CSRF token must be present and valid
  res.json({ ok: true });
});
```

### DoS (Denial of Service)
```javascript
// ✅ SAFE
app.use(rateLimit(/* ... */));
app.use(express.json({ limit: '10kb' })); // Size limit
app.use(require('helmet')()); // Various protections
```

